def _local_git_commit() -> str:
    try:
        result = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=str(ROOT_DIR),
            capture_output=True,
            text=True,
            timeout=3,
            check=False,
        )
        value = result.stdout.strip()
        return value if re.fullmatch(r"[0-9a-f]{40}", value) else ""
    except Exception:
        return ""


def _remote_git_commit() -> str:
    # Prefer the Git remote ref over the GitHub REST API. The API can be
    # temporarily stale, which could otherwise make a newer production
    # checkout look like it needs a downgrade. Keep the whole check inside
    # the browser timeout: ls-remote first, API only if that fails.
    try:
        result = subprocess.run(
            ["git", "ls-remote", "origin", f"refs/heads/{GITHUB_BRANCH}"],
            cwd=str(ROOT_DIR),
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
        if result.returncode == 0:
            for line in result.stdout.splitlines():
                parts = line.strip().split()
                if len(parts) >= 2 and parts[1] == f"refs/heads/{GITHUB_BRANCH}":
                    value = parts[0].strip().lower()
                    if re.fullmatch(r"[0-9a-f]{40}", value):
                        return value
    except Exception:
        pass

    request = urllib.request.Request(
        GITHUB_API_COMMIT_URL,
        headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "AimiliVPN-Updater",
            "X-GitHub-Api-Version": "2022-11-28",
        },
    )
    with urllib.request.urlopen(request, timeout=3) as response:
        data = json.loads(response.read().decode("utf-8"))
    value = str(data.get("sha") or "").strip().lower()
    return value if re.fullmatch(r"[0-9a-f]{40}", value) else ""


def _git_is_ancestor(ancestor: str, descendant: str) -> bool:
    ancestor = str(ancestor or "").strip().lower()
    descendant = str(descendant or "").strip().lower()
    if not ancestor or not descendant:
        return False
    try:
        result = subprocess.run(
            ["git", "merge-base", "--is-ancestor", ancestor, descendant],
            cwd=str(ROOT_DIR),
            capture_output=True,
            text=True,
            timeout=3,
            check=False,
        )
        return result.returncode == 0
    except Exception:
        return False


def current_github_version() -> dict[str, Any]:
    local = _local_git_commit()
    return {
        "ok": bool(local),
        "repository": GITHUB_REPOSITORY,
        "branch": GITHUB_BRANCH,
        "current_version": _version_label(local) if local else APP_VERSION,
        "current_commit": local,
        "source": "git",
    }


def check_github_update() -> dict[str, Any]:
    local = _local_git_commit()
    if not local:
        return {
            "ok": False,
            "error": "当前安装目录不是有效 Git 仓库，无法检查正式版更新。",
            "repository": GITHUB_REPOSITORY,
            "branch": GITHUB_BRANCH,
        }

    try:
        remote = _remote_git_commit()
    except Exception as exc:
        return {
            "ok": False,
            "error": f"无法访问 GitHub 正式版：{exc}",
            "repository": GITHUB_REPOSITORY,
            "branch": GITHUB_BRANCH,
            "current_version": _version_label(local),
        }

    if not remote:
        return {
            "ok": False,
            "error": "GitHub 未返回有效的 main 分支版本。",
            "repository": GITHUB_REPOSITORY,
            "branch": GITHUB_BRANCH,
            "current_version": _version_label(local),
        }

    if remote == local:
        relation = "same"
    elif _git_is_ancestor(remote, local):
        relation = "local_ahead"
    else:
        relation = "remote_ahead"
    # Checking must not git-fetch. A fetch blocks this request for the whole
    # network round trip and the browser aborts at 10s while probes are busy.
    has_update = relation == "remote_ahead"
    result = {
        "ok": True,
        "repository": GITHUB_REPOSITORY,
        "branch": GITHUB_BRANCH,
        "current_version": _version_label(local),
        "current_commit": local,
        "latest_version": _version_label(remote),
        "latest_commit": remote,
        "has_update": has_update,
        "relation": relation,
        "checked_at": time.time(),
    }
    if relation == "local_ahead":
        result["message"] = "当前服务器版本高于 GitHub 正式版，不执行降级更新。"
    elif relation == "remote_ahead":
        result["message"] = "已获取 GitHub 正式版，将以 GitHub main 为准同步。"
    return result


def start_github_update() -> dict[str, Any]:
    global github_update_running, github_update_last_result
    with github_update_lock:
        if github_update_running:
            return {"ok": False, "error": "正在更新正式版，请稍候。", "running": True}

        check = check_github_update()
        if not check.get("ok"):
            return check
        if not check.get("has_update"):
            status = str(check.get("relation") or "latest")
            message = str(check.get("message") or "当前已经是 GitHub 正式版最新版本。")
            github_update_last_result = {
                "ok": True,
                "status": status,
                "current_version": check.get("current_version"),
                "latest_version": check.get("latest_version"),
                "checked_at": time.time(),
            }
            return {
                "ok": True,
                "status": status,
                "message": message,
                "current_version": check.get("current_version"),
                "latest_version": check.get("latest_version"),
            }

        github_update_running = True
        github_update_last_result = {
            "ok": True,
            "status": "starting",
            "from_version": check.get("current_version"),
            "to_version": check.get("latest_version"),
            "started_at": time.time(),
        }

        # Do not restart the current service from a child in its own
        # KillMode=control-group. That can terminate the updater before the
        # git reset happens. A dedicated systemd oneshot unit owns the update
        # process and can safely restart aimilivpn after the new checkout is ready.
        try:
            completed = subprocess.run(
                ["systemctl", "start", "--no-block", "aimilivpn-github-update.service"],
                cwd=str(ROOT_DIR),
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            if completed.returncode != 0:
                github_update_running = False
                error = (completed.stderr or completed.stdout or "无法启动 GitHub 更新服务。").strip()
                github_update_last_result = {
                    "ok": False,
                    "status": "failed",
                    "error": error,
                    "checked_at": time.time(),
                }
                return {"ok": False, "error": error}
        except Exception as exc:
            github_update_running = False
            github_update_last_result = {
                "ok": False,
                "status": "failed",
                "error": str(exc),
                "checked_at": time.time(),
            }
            return {"ok": False, "error": str(exc)}

        threading.Timer(30.0, _clear_github_update_running).start()
        return {
            "ok": True,
            "status": "starting",
            "message": f"已发现新版本 {check.get('latest_version')}，正在从 GitHub 更新并重启服务。",
            "current_version": check.get("current_version"),
            "latest_version": check.get("latest_version"),
        }

def _clear_github_update_running() -> None:
    global github_update_running
    github_update_running = False

def ensure_dirs() -> None:
    DATA_DIR.mkdir(exist_ok=True, parents=True)
    CONFIG_DIR.mkdir(exist_ok=True, parents=True)
    if not AUTH_FILE.exists():
        AUTH_FILE.write_text(f"{OPENVPN_AUTH_USER}\n{OPENVPN_AUTH_PASS}\n", encoding="utf-8")
        try:
            AUTH_FILE.chmod(0o600)
        except OSError:
            pass

def upstream_proxy_auth_file() -> str | None:
    username, password = vpn_utils.get_upstream_proxy_auth()
    if username is None:
        return None
    try:
        DATA_DIR.mkdir(exist_ok=True, parents=True)
        UPSTREAM_PROXY_AUTH_FILE.write_text(f"{username}\n{password or ''}\n", encoding="utf-8")
        try:
            UPSTREAM_PROXY_AUTH_FILE.chmod(0o600)
        except OSError:
            pass
        return str(UPSTREAM_PROXY_AUTH_FILE)
    except Exception as exc:
        print(f"[上游代理认证] 写入认证文件失败: {exc}", flush=True)
        return None

_json_file_locks_guard = threading.Lock()
_json_file_locks: dict[str, threading.Lock] = {}


def _json_file_lock(path: Path) -> threading.Lock:
    key = str(path)
    with _json_file_locks_guard:
        found = _json_file_locks.get(key)
        if found is None:
            found = threading.Lock()
            _json_file_locks[key] = found
        return found


def write_json(path: Path, data: Any) -> None:
    # nodes.json is ~11MB. Parsing and dumping it takes seconds and holds the
    # GIL. Keep that work off the process-wide lock, and do not make a state
    # read wait behind a node-library rewrite.
    if path == NODES_FILE and isinstance(data, list) and not data and path.exists():
        try:
            with _json_file_lock(path):
                existing_text = path.read_text(encoding="utf-8")
        except OSError:
            existing_text = ""
        try:
            existing = json.loads(existing_text) if existing_text else None
        except Exception:
            existing = None
        if isinstance(existing, list) and existing:
            log_to_json("WARNING", "Main", "拒绝用临时空节点快照覆盖已有节点库")
            return
    payload = json.dumps(data, ensure_ascii=False, indent=2)
    with _json_file_lock(path):
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(payload, encoding="utf-8")
        tmp.replace(path)
    if path == NODES_FILE:
        _invalidate_nodes_index()


def read_json(path: Path, default: Any) -> Any:
    try:
        with _json_file_lock(path):
            text = path.read_text(encoding="utf-8")
    except OSError:
        return default
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return default

import hashlib
import random

def generate_random_password() -> str:
    import string
    chars = string.ascii_letters + string.digits
    while True:
        pwd = "".join(random.choices(chars, k=12))
        # Ensure it contains at least one lowercase, one uppercase, and one digit
        has_lower = any(c.islower() for c in pwd)
        has_upper = any(c.isupper() for c in pwd)
        has_digit = any(c.isdigit() for c in pwd)
        if has_lower and has_upper and has_digit:
            return pwd

def generate_random_username() -> str:
    import string
    chars = string.ascii_letters + string.digits
    while True:
        uname = "".join(random.choices(chars, k=12))
        # Ensure it starts with a letter and contains at least one lowercase, one uppercase, and one digit
        if uname[0].isalpha():
            has_lower = any(c.islower() for c in uname)
            has_upper = any(c.isupper() for c in uname)
            has_digit = any(c.isdigit() for c in uname)
            if has_lower and has_upper and has_digit:
                return uname

def publish_proxy_auth(user: str, password: str) -> None:
    """8500 reads this file on each login, so a saved password does not need a restart."""
    user = str(user or "").strip() or "socks5"
    password = str(password or "")
    if not password:
        password = "ilovestudy"
    payload = {"user": user[:64], "password": password[:64]}
    path = DATA_DIR / "proxy_auth.json"
    try:
        DATA_DIR.mkdir(exist_ok=True, parents=True)
        text = json.dumps(payload, ensure_ascii=False)
        current = path.read_text(encoding="utf-8") if path.exists() else ""
        if current != text:
            tmp = path.with_suffix(".tmp")
            tmp.write_text(text, encoding="utf-8")
            tmp.replace(path)
    except OSError:
        pass
    os.environ["LOCAL_PROXY_USER"] = payload["user"]
    os.environ["LOCAL_PROXY_PASS"] = payload["password"]


def load_ui_config() -> dict[str, Any]:
    global ui_config_cache, ui_config_cache_at
    now_mono = time.monotonic()
    with ui_config_cache_lock:
        if ui_config_cache is not None and now_mono - ui_config_cache_at < 1.0:
            cached = dict(ui_config_cache)
            cached["favorite_node_ids"] = list(cached.get("favorite_node_ids") or [])
            return cached
    with lock:
        auth_file = DATA_DIR / "ui_auth.json"
        config = {
            "username": "",
            "secret_path": "EJsW2EeBo9lY",
            "password": "",
            "host": "127.0.0.1",
            "port": UI_PORT,
            "proxy_port": env_int("LOCAL_PROXY_PORT", 8500, 1, 65535),
            "routing_mode": "auto",
            "force_country": "",
            "routing_ip_type": "all",
            "routing_protocol": "",
            "routing_min_speed_bps": 0,
            "routing_latency": "",
            "connection_enabled": True,
            "fixed_node_id": "",
            "favorite_node_ids": [],
            "fav_fail_fallback": True,
            "web_domain": "",
            "routing_blocklist": "",
            "proxy_user": "socks5",
            "proxy_pass": "ilovestudy",
            "log_auto_cleanup": True,
        }
        updated = False
        if auth_file.exists():
            try:
                data = json.loads(auth_file.read_text(encoding="utf-8"))
                for key, val in data.items():
                    config[key] = val
                for key in ["host", "port", "proxy_port", "routing_mode", "force_country", "routing_ip_type", "routing_protocol", "routing_min_speed_bps", "routing_latency", "connection_enabled", "fixed_node_id", "favorite_node_ids", "fav_fail_fallback", "web_domain", "routing_blocklist", "proxy_user", "proxy_pass", "log_auto_cleanup"]:
                    if key not in data:
                        updated = True
            except Exception:
                pass

        if not config.get("username"):
            config["username"] = generate_random_username()
            updated = True

        if not config.get("password"):
            config["password"] = generate_random_password()
            updated = True

        if config.get("fav_fail_fallback") is not True:
            config["fav_fail_fallback"] = True
            updated = True

        if not ISOLATED_INSTANCE:
            if config.get("host") != "127.0.0.1":
                config["host"] = "127.0.0.1"
                updated = True
            if config.get("port") != 8501:
                config["port"] = 8501
                updated = True

        normalized_port = bounded_int(config.get("port"), UI_PORT, 1, 65535)
        if normalized_port != config.get("port"):
            config["port"] = normalized_port
            updated = True

        normalized_proxy_port = env_int("LOCAL_PROXY_PORT", 8500, 1, 65535)
        if normalized_proxy_port != config.get("proxy_port"):
            config["proxy_port"] = normalized_proxy_port
            updated = True

        if not str(config.get("proxy_user") or "").strip():
            config["proxy_user"] = "socks5"
            updated = True
        if not str(config.get("proxy_pass") or ""):
            config["proxy_pass"] = "ilovestudy"
            updated = True

        if not auth_file.exists() or updated:
            try:
                DATA_DIR.mkdir(exist_ok=True, parents=True)
                write_json(auth_file, config)
            except Exception:
                pass

        with ui_config_cache_lock:
            ui_config_cache = dict(config)
            ui_config_cache["favorite_node_ids"] = list(config.get("favorite_node_ids") or [])
            ui_config_cache_at = time.monotonic()
        publish_proxy_auth(str(config.get("proxy_user") or "socks5"), str(config.get("proxy_pass") or "ilovestudy"))
        return dict(config)


