def set_manual_route_pin(*, protocol: str, endpoint_id: str = "", node_id: str = "", country: str = "") -> None:
    global manual_route_pin, manual_connection_quiet_until
    pinned_country = normalized_country_name(country)
    previous_country = normalized_country_name((manual_route_pin or {}).get("country") or "")
    manual_route_pin = {
        "protocol": str(protocol or ""),
        "endpoint_id": str(endpoint_id or ""),
        "node_id": str(node_id or ""),
        "country": pinned_country,
        "set_at": time.time(),
    }
    manual_connection_quiet_until = time.time() + 15.0
    try:
        DATA_DIR.mkdir(exist_ok=True, parents=True)
        write_json(DATA_DIR / "manual_route_pin.json", manual_route_pin)
    except OSError:
        pass
    if pinned_country and pinned_country != previous_country:
        try:
            release_standby()
            _clear_hot_standby_identity()
        except Exception:
            pass
        log_to_json("INFO", "Standby", f"手动切换到{pinned_country}，热备改到该国家")

