def safe_name(value: str) -> str:
    value = re.sub(r"[^A-Za-z0-9_.-]+", "_", value.strip())
    return value.strip("._") or "node"

def clear_active_connection_state(message: str) -> None:
    global active_openvpn_process, active_openvpn_node_id, active_external_tunnel, active_pool_endpoint_id
    stop_process(active_openvpn_process)
    active_openvpn_process = None
    active_openvpn_node_id = ""
    if active_external_tunnel is not None:
        try:
            if active_external_tunnel.protocol == "softether":
                details = active_external_tunnel.details or {}
                tunnel_adapters.SoftEtherAdapter().disconnect(
                    account=str(details.get("account") or "aimili"),
                    nic=str(details.get("nic") or "aimili"),
                    delete=True,
                    added_routes=details.get("added_host_routes") or [],
                )
            elif active_external_tunnel.protocol == "sstp":
                details = active_external_tunnel.details or {}
                tunnel_adapters.SSTPAdapter.disconnect(
                    active_external_tunnel.process,
                    added_routes=details.get("added_host_routes") or [],
                )
        except Exception:
            pass
    active_external_tunnel = None
    active_pool_endpoint_id = ""
    cleanup_policy_routing()
    with lock:
        nodes = read_nodes()
        for item in nodes:
            item["active"] = False
        write_json(NODES_FILE, nodes)
    set_state(

        active_openvpn_node_id="",
        active_openvpn_node={},
        active_pool_endpoint_id="",
        active_pool_endpoint={},
        active_tunnel_protocol="",
        active_tunnel_interface="",
        is_connecting=False,
        active_node_latency="无活动连接",
        last_check_message=message,
    )

def parse_int(value: Any) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

def proxy_basic_auth_header(username: str, password: str) -> str:
    token = base64.b64encode(f"{username}:{password}".encode("utf-8")).decode("ascii")
    return f"Proxy-Authorization: Basic {token}\r\n"

def recv_exact_from_socket(sock: socket.socket, size: int) -> bytes:
    data = b""
    while len(data) < size:
        chunk = sock.recv(size - len(data))
        if not chunk:
            raise RuntimeError("Unexpected EOF while reading proxy response")
        data += chunk
    return data

def read_http_response_head(sock: socket.socket, limit: int = 65536) -> bytes:
    data = b""
    while b"\r\n\r\n" not in data:
        chunk = sock.recv(4096)
        if not chunk:
            break
        data += chunk
        if len(data) > limit:
            raise RuntimeError("Proxy response header too large")
    if b"\r\n\r\n" not in data:
        raise RuntimeError("Incomplete HTTP proxy response header")
    return data

def socks5_address_bytes(host: str) -> tuple[int, bytes]:
    try:
        return 1, socket.inet_aton(host)
    except OSError:
        pass
    try:
        return 4, socket.inet_pton(socket.AF_INET6, host)
    except OSError:
        pass
    host_bytes = host.encode("idna")
    if len(host_bytes) > 255:
        raise RuntimeError("SOCKS5 target host name is too long")
    return 3, bytes([len(host_bytes)]) + host_bytes

def read_socks5_connect_reply(sock: socket.socket) -> None:
    header = recv_exact_from_socket(sock, 4)
    if header[0] != 5:
        raise RuntimeError("Invalid SOCKS5 reply version")
    atyp = header[3]
    if atyp == 1:
        recv_exact_from_socket(sock, 4)
    elif atyp == 3:
        domain_len = recv_exact_from_socket(sock, 1)[0]
        recv_exact_from_socket(sock, domain_len)
    elif atyp == 4:
        recv_exact_from_socket(sock, 16)
    else:
        raise RuntimeError(f"Invalid SOCKS5 reply address type: {atyp}")
    recv_exact_from_socket(sock, 2)
    if header[1] != 0:
        raise RuntimeError(f"SOCKS5 connection request rejected, code={header[1]}")

def format_host_port(host: str, port: int) -> str:
    return f"[{host}]:{port}" if ":" in host and not host.startswith("[") else f"{host}:{port}"

def fetch_api_text_via_proxy(url: str, ptype: str, phost: str, pport: int, use_ssl_verify: bool = True) -> str:
    import socket
    import ssl
    import urllib.parse

    parsed = urllib.parse.urlsplit(url)
    domain = parsed.hostname or "www.vpngate.net"
    port = parsed.port or (443 if parsed.scheme == "https" else 80)
    is_https = parsed.scheme == "https"
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query

    is_ipv6 = ":" in phost
    af = socket.AF_INET6 if is_ipv6 else socket.AF_INET
    s = None
    try:
        s = socket.socket(af, socket.SOCK_STREAM)
        s.settimeout(12)
        s.connect((phost, pport))
        proxy_user, proxy_pass = vpn_utils.get_upstream_proxy_auth()
        if ptype == "socks":
            # SOCKS5 Handshake
            if proxy_user is not None:
                s.sendall(b"\x05\x02\x00\x02")
            else:
                s.sendall(b"\x05\x01\x00")
            resp = recv_exact_from_socket(s, 2)
            if len(resp) < 2 or resp[0] != 5:
                raise RuntimeError("SOCKS5 authentication failed or unsupported")
            if resp[1] == 2:
                if proxy_user is None:
                    raise RuntimeError("SOCKS5 proxy requires username/password authentication")
                user_bytes = proxy_user.encode("utf-8")
                pass_bytes = (proxy_pass or "").encode("utf-8")
                if len(user_bytes) > 255 or len(pass_bytes) > 255:
                    raise RuntimeError("SOCKS5 proxy credentials are too long")
                s.sendall(b"\x01" + bytes([len(user_bytes)]) + user_bytes + bytes([len(pass_bytes)]) + pass_bytes)
                auth_resp = recv_exact_from_socket(s, 2)
                if len(auth_resp) < 2 or auth_resp[1] != 0:
                    raise RuntimeError("SOCKS5 username/password authentication failed")
            elif resp[1] != 0:
                raise RuntimeError("SOCKS5 authentication method unsupported")
            # SOCKS5 Connect
            atyp, addr_bytes = socks5_address_bytes(domain)
            req = b"\x05\x01\x00" + bytes([atyp]) + addr_bytes + port.to_bytes(2, 'big')
            s.sendall(req)
            read_socks5_connect_reply(s)
            # If HTTPS, wrap socket with SSL
            if is_https:
                ctx = ssl.create_default_context() if use_ssl_verify else ssl._create_unverified_context()
                s = ctx.wrap_socket(s, server_hostname=domain)
        else: # http proxy
            if is_https:
                # HTTP CONNECT tunnel
                authority = format_host_port(domain, port)
                auth_header = proxy_basic_auth_header(proxy_user, proxy_pass or "") if proxy_user is not None else ""
                req_str = f"CONNECT {authority} HTTP/1.1\r\nHost: {authority}\r\nUser-Agent: Mozilla/5.0 vpngate-openvpn-manager/2.0\r\n{auth_header}Proxy-Connection: Keep-Alive\r\n\r\n"
                s.sendall(req_str.encode('ascii'))
                resp = read_http_response_head(s)
                status_line = resp.split(b"\r\n", 1)[0].decode("utf-8", errors="replace")
                status_parts = status_line.split()
                status_code = int(status_parts[1]) if len(status_parts) >= 2 and status_parts[1].isdigit() else 0
                if status_code != 200:
                    raise RuntimeError(f"HTTP CONNECT tunnel failed: {status_line}")
                # Wrap socket with SSL
                ctx = ssl.create_default_context() if use_ssl_verify else ssl._create_unverified_context()
                s = ctx.wrap_socket(s, server_hostname=domain)
            else:
                # Direct HTTP request through proxy: request URI must be absolute
                pass

        # Send HTTP GET request
        if ptype == "http" and not is_https:
            request_uri = url
        else:
            request_uri = path

        req_headers = (
            f"GET {request_uri} HTTP/1.1\r\n"
            f"Host: {domain}\r\n"
            f"User-Agent: Mozilla/5.0 vpngate-openvpn-manager/2.0\r\n"
            f"Accept: text/plain,*/*\r\n"
            f"{proxy_basic_auth_header(proxy_user, proxy_pass or '') if ptype == 'http' and not is_https and proxy_user is not None else ''}"
            f"Connection: close\r\n\r\n"
        )
        s.sendall(req_headers.encode('utf-8'))

        # Read response
        response_data = b""
        while True:
            chunk = s.recv(4096)
            if not chunk:
                break
            response_data += chunk
            if len(response_data) > 10 * 1024 * 1024: # max 10MB safety guard
                break
    finally:
        if s is not None:
            try:
                s.close()
            except Exception:
                pass

    # Parse HTTP response
    header_end = response_data.find(b"\r\n\r\n")
    if header_end == -1:
        raise RuntimeError("Invalid HTTP response format")

    headers_part = response_data[:header_end].decode('utf-8', errors='replace')
    body_part = response_data[header_end+4:]

    # Check for HTTP status code
    lines = headers_part.splitlines()
    if not lines:
        raise RuntimeError("Empty response headers")
    status_line = lines[0]
    status_parts = status_line.split()
    if len(status_parts) >= 2:
        try:
            status_code = int(status_parts[1])
            if status_code != 200:
                raise RuntimeError(f"HTTP Server returned status {status_code}: {status_line}")
        except ValueError:
            pass

    # Handle chunked transfer encoding
    is_chunked = False
    for line in lines[1:]:
        if ":" in line:
            k, v = line.split(":", 1)
            if k.strip().lower() == "transfer-encoding" and "chunked" in v.lower():
                is_chunked = True
                break

    if is_chunked:
        decoded = b""
        idx = 0
        while idx < len(body_part):
            c_end = body_part.find(b"\r\n", idx)
            if c_end == -1:
                break
            chunk_size_str = body_part[idx:c_end].split(b";")[0].strip()
            try:
                chunk_size = int(chunk_size_str, 16)
            except ValueError:
                break
            if chunk_size == 0:
                break
            idx = c_end + 2
            decoded += body_part[idx : idx + chunk_size]
            idx += chunk_size + 2
        body_part = decoded

    return body_part.decode('utf-8', errors='replace')

def fetch_api_text(url: str | None = None, use_ssl_verify: bool = True) -> str:
    if url is None:
        url = API_URL

    ptype, phost, pport = vpn_utils.get_upstream_proxy()
    if ptype and phost and pport:
        try:
            print(f"[fetch_api_text] 监测到上游代理 ({ptype}://{phost}:{pport})，尝试通过代理获取 API...", flush=True)
            return fetch_api_text_via_proxy(url, ptype, phost, pport, use_ssl_verify)
        except Exception as e:
            print(f"[fetch_api_text] 通过代理获取 API 失败: {e}，尝试使用直连/默认系统代理...", flush=True)
            log_to_json("WARNING", "Main", f"使用代理 {ptype}://{phost}:{pport} 获取 API 失败: {e}")

    request = urllib.request.Request(
        url,
        headers={
            "User-Agent": "Mozilla/5.0 vpngate-openvpn-manager/2.0",
            "Accept": "text/plain,*/*",
        },
    )
    if url.startswith("https://") and not use_ssl_verify:
        import ssl
        ctx = ssl._create_unverified_context()
        with urllib.request.urlopen(request, timeout=12, context=ctx) as response:
            return response.read().decode("utf-8", errors="replace")
    else:
        with urllib.request.urlopen(request, timeout=12) as response:
            return response.read().decode("utf-8", errors="replace")

def parse_vpngate_rows(text: str) -> list[dict[str, str]]:
    lines = [line for line in text.splitlines() if line and not line.startswith("*")]
    if lines and lines[0].startswith("#"):
        lines[0] = lines[0][1:]
    return list(csv.DictReader(lines))

def decode_config(encoded: str) -> str:
    return base64.b64decode(encoded.encode("ascii"), validate=False).decode("utf-8", errors="replace")

def load_blacklist() -> dict[str, dict[str, Any]]:
    now = time.time()
    raw = read_json(BLACKLIST_FILE, {})
    if not isinstance(raw, dict):
        return {}
    cleaned: dict[str, dict[str, Any]] = {}
    changed = False
    for key, entry in raw.items():
        if not isinstance(entry, dict):
            changed = True
            continue
        until = float(entry.get("until", 0) or 0)
        if until and until > now:
            cleaned[str(key)] = entry
        else:
            changed = True
    if changed:
        write_json(BLACKLIST_FILE, cleaned)
    return cleaned

def mark_blacklisted(node: dict[str, Any], message: str) -> None:
    node_id = str(node.get("id") or "").strip()
    if not node_id:
        return
    blacklist = load_blacklist()
    now = time.time()
    blacklist[node_id] = {
        "id": node_id,
        "ip": node.get("ip") or node.get("remote_host") or "",
        "country": node.get("country", ""),
        "reason": message,
        "marked_at": now,
        "until": now + INVALID_BACKOFF_SECONDS,
    }
    write_json(BLACKLIST_FILE, blacklist)

def row_to_node(row: dict[str, str], config_text: str) -> dict[str, Any]:
    ip = row.get("IP", "")
    country_short = row.get("CountryShort", "")
    remote_host, remote_port, proto = vpn_utils.parse_remote(config_text, ip)
    node_id = safe_name("_".join([country_short or "XX", ip or remote_host, str(remote_port), proto]))
    config_path = CONFIG_DIR / f"{node_id}.ovpn"

    country_long = row.get("CountryLong", "")
    country_zh = vpn_utils.COUNTRY_TRANSLATIONS.get(country_long, vpn_utils.COUNTRY_TRANSLATIONS.get(country_long.strip(), country_long))
    return {
        "id": node_id,
        "country": country_zh,
        "country_short": country_short,
        "host_name": row.get("HostName", ""),
        "ip": ip,
        "score": parse_int(row.get("Score")),
        "ping": parse_int(row.get("Ping")),
        "speed": parse_int(row.get("Speed")),
        "sessions": parse_int(row.get("NumVpnSessions")),
        "owner": "",
        "asn": "",
        "as_name": "",
        "location": "",
        "ip_type": "",
        "quality": "",
        "latency_ms": 0,
        "config_file": str(config_path),
        "config_text": config_text,
        "proto": proto,
        "protocol": "openvpn",
        "remote_host": remote_host,
        "remote_port": remote_port,
        "fetched_at": time.time(),
        "probe_status": "not_checked",
        "probe_message": "",
        "probed_at": 0,
    }


def dedupe_ui_nodes(nodes: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Collapse visually identical protocol/IP/port rows while retaining fallback endpoints."""
    groups: dict[tuple[str, str, int], list[dict[str, Any]]] = {}
    passthrough: list[dict[str, Any]] = []

    def rank(node: dict[str, Any]) -> tuple[int, int, int, float, float]:
        status = str(node.get("probe_status") or "not_checked").lower()
        status_rank = {"available": 0, "testing": 1, "not_checked": 2, "unavailable": 3}.get(status, 4)
        active_rank = 0 if node.get("active") else 1
        trusted_rank = 0 if bool((node.get("_pool_metadata") or {}).get("trusted_observation")) else 1
        latency = float(node.get("latency_ms") or 999999)
        if latency <= 0:
            latency = 999999
        seen = float(node.get("probed_at") or node.get("fetched_at") or 0)
        return (active_rank, status_rank, trusted_rank, latency, -seen)

    for node in nodes:
        if not isinstance(node, dict):
            continue
        protocol = str(node.get("protocol") or "openvpn").strip().lower()
        ip = str(node.get("ip") or node.get("current_ip") or node.get("remote_host") or "").strip()
        try:
            port = int(node.get("remote_port") or 0)
        except (TypeError, ValueError):
            port = 0
        if not ip or not port:
            passthrough.append(node)
            continue
        groups.setdefault((protocol, ip, port), []).append(node)

    merged: list[dict[str, Any]] = []
    for group in groups.values():
        group.sort(key=rank)
        primary = dict(group[0])
        fallback_ids: list[str] = []
        for duplicate in group:
            endpoint_id = str(duplicate.get("pool_endpoint_id") or "").strip()
            node_id = str(duplicate.get("id") or "").strip()
            if endpoint_id and endpoint_id != str(primary.get("pool_endpoint_id") or ""):
                fallback_ids.append(endpoint_id)
            elif node_id and node_id != str(primary.get("id") or "") and node_id.startswith("pool:"):
                fallback_ids.append(node_id[5:])
        if len(group) > 1:
            existing = [str(x) for x in (primary.get("pool_endpoint_ids") or []) if x]
            primary["pool_endpoint_ids"] = list(dict.fromkeys(
                [str(primary.get("pool_endpoint_id") or "")] + existing + fallback_ids
            ))
            primary["duplicate_count"] = len(group) - 1
        merged.append(primary)

    merged.extend(passthrough)
    return merged


def protocol_endpoint_to_ui_node(endpoint: dict[str, Any]) -> dict[str, Any]:
    protocol = str(endpoint.get("protocol") or "").strip().lower()
    if not protocol:
        return {}
    metadata = endpoint.get("metadata") or {}
    server_metadata = endpoint.get("server_metadata") or {}
    status = str(endpoint.get("status") or "NEW").upper()
    probe_status = {
        "HOT": "available",
        "AVAILABLE": "available",
        "TESTING": "testing",
        "NEW": "not_checked",
        "DEGRADED": "unavailable",
        "COOLDOWN": "unavailable",
        "STALE": "unavailable",
        "RETIRED": "unavailable",
        "UNAVAILABLE": "unavailable",
    }.get(status, "not_checked")
    ip = str(endpoint.get("current_ip") or metadata.get("ip") or "").strip()
    host = str(metadata.get("hostname") or endpoint.get("hostname") or ip).strip()
    try:
        port = int(endpoint.get("port") or 0)
    except (TypeError, ValueError):
        port = 0
    return {
        "id": f"pool:{endpoint.get('endpoint_id', '')}",
        "pool_endpoint_id": str(endpoint.get("endpoint_id") or ""),
        "country": endpoint.get("country") or "",
        "country_short": "",
        "host_name": host,
        "ip": ip,
        "score": int(endpoint.get("latest_server_score") or 0),
        "ping": int(endpoint.get("latest_ping") or 0),
        "speed": int(endpoint.get("latest_speed") or (metadata or {}).get("last_probe_speed_bps") or server_metadata.get("last_ip_speed_bps") or 0),
        "speed_bps": int(endpoint.get("latest_speed") or (metadata or {}).get("last_probe_speed_bps") or server_metadata.get("last_ip_speed_bps") or 0),
        "sessions": int(endpoint.get("latest_sessions") or 0),
        "owner": str(server_metadata.get("owner") or server_metadata.get("isp") or server_metadata.get("as_name") or ""),
        "asn": str(server_metadata.get("asn") or ""),
        "as_name": str(server_metadata.get("as_name") or ""),
        "location": str(server_metadata.get("location") or endpoint.get("country") or ""),
        "ip_type": str(server_metadata.get("ip_type") or ""),
        "quality": str(server_metadata.get("quality") or ""),

        "latency_ms": usable_latency_ms(int(endpoint.get("latency_ewma") or 0), tcp_rtt_ms=int((metadata or {}).get("tcp_rtt_ms") or 0)),
        "config_file": str(endpoint.get("config_ref") or ""),
        "proto": str(endpoint.get("transport") or ""),
        "protocol": protocol,
        "remote_host": host,
        "remote_port": port,
        "fetched_at": float(endpoint.get("last_seen") or 0),
        "manual_added_at": float(metadata.get("manual_added_at") or server_metadata.get("manual_added_at") or 0),
        "probe_status": probe_status,
        "endpoint_status": status.lower(),
        "hot_standby": status == "HOT",
        "connection_status": "connected" if str(endpoint.get("endpoint_id") or "") == str(active_pool_endpoint_id or "") else "not_connected",
        "probe_message": str(metadata.get("last_error") or ""),
        "probed_at": float(endpoint.get("last_success") or endpoint.get("last_failure") or 0),
        "active": str(endpoint.get("endpoint_id") or "") == str(active_pool_endpoint_id or ""),
        "data_integrity": dict(endpoint.get("data_integrity") or {}),
    }


def persist_openvpn_candidates(candidates: list[dict[str, Any]]) -> int:
    """Keep the official OpenVPN configs. The pool row alone cannot open a tunnel."""
    usable = [
        dict(node) for node in (candidates or [])
        if str(node.get("id") or "").strip() and str(node.get("config_text") or "").strip()
    ]
    if not usable:
        return 0
    with lock:
        current = read_nodes()
        by_id = {str(node.get("id")): node for node in current if node.get("id")}
        for cand in usable:
            nid = str(cand.get("id"))
            previous = by_id.get(nid)
            if previous:
                for key in ("probe_status", "probe_message", "latency_ms", "probed_at", "active"):
                    if previous.get(key) not in (None, "", False):
                        cand[key] = previous.get(key)
            text = str(cand.get("config_text") or "")
            path = Path(str(cand.get("config_file") or ""))
            if text and path.name:
                try:
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_text(text, encoding="utf-8")
                except Exception:
                    pass
            by_id[nid] = cand
        merged = list(by_id.values())
        if len(merged) > 1000:
            merged = merged[:1000]
        write_json(NODES_FILE, merged)
    return len(usable)


def fetch_candidates() -> list[dict[str, Any]]:
    blacklist = load_blacklist()
    candidates: list[dict[str, Any]] = []
    seen_ips = set()

    # 检查本地是否有节点缓存，以确定最大重试尝试次数
    has_cache = len(cached_nodes()) > 0
    max_attempts = 1 if has_cache else 2

    # 尝试 URLs 队列: 1. HTTPS(验证证书) 2. HTTPS(不验证证书) 3. HTTP
    attempts_targets = [
        (API_URL, True),
        (API_URL, False)
    ]
    if API_URL.startswith("https://"):
        attempts_targets.append((API_URL.replace("https://", "http://"), True))

    log_to_json("INFO", "Main", "开始拉取官方 API 节点列表...")

    last_err = None
    for url, verify_ssl in attempts_targets:
        for i in range(max_attempts):
            if i > 0:
                time.sleep(1.5)
            try:
                msg = f"尝试拉取 {url} (SSL验证: {verify_ssl}, 第 {i+1} 次尝试)..."
                print(f"[fetch_candidates] {msg}", flush=True)
                log_to_json("INFO", "Main", msg)
                api_text = fetch_api_text(url, verify_ssl)
                rows = parse_vpngate_rows(api_text)
                for row in rows[:MAX_SCAN_ROWS]:
                    ip = row.get("IP", "")
                    if not ip or ip in seen_ips:
                        continue
                    encoded = row.get("OpenVPN_ConfigData_Base64", "")
                    if not encoded:
                        continue
                    try:
                        config_text = decode_config(encoded)
                        node = row_to_node(row, config_text)
                    except Exception as row_exc:
                        print(f"[fetch_candidates] 跳过损坏的节点配置记录: {row_exc}", flush=True)
                        log_to_json("WARNING", "Main", f"跳过损坏的节点配置记录: {row_exc}")
                        continue
                    entry = blacklist.get(node["id"])
                    if entry and float(entry.get("until", 0) or 0) > time.time():
                        continue
                    candidates.append(node)
                    seen_ips.add(ip)
                if candidates:
                    break
            except Exception as e:
                last_err = e
                print(f"[fetch_candidates] 拉取失败 (URL: {url}, 验证: {verify_ssl}): {e}", flush=True)
                log_to_json("WARNING", "Main", f"拉取失败 (URL: {url}, 验证: {verify_ssl}): {e}")
        if candidates:
            break

    if not candidates:
        err_code, diag_msg = vpn_utils.diagnose_api_failure(API_URL)
        full_err_msg = f"获取官方 API 节点最终失败: {last_err} | 诊断结果: {diag_msg}"
        print(f"[错误代码 {err_code}] {full_err_msg}", flush=True)
        log_to_json("ERROR", "Main", f"[错误代码 {err_code}] {full_err_msg}")
        set_state(
            last_fetch_status="error",
            last_fetch_error_code=err_code,
            last_fetch_message=diag_msg
        )
        if last_err:
            raise RuntimeError(diag_msg) from last_err
        else:
            raise RuntimeError(diag_msg)

    set_state(
        last_fetch_at=time.time(),
        last_fetch_status="ok",
        last_fetch_message=f"Fetched {len(candidates)} unique candidates across multiple attempts.",
        blacklisted_nodes=len(blacklist),
    )
    try:
        node_pool.upsert_openvpn_snapshot(candidates, source="official_csv")
    except Exception as pool_exc:
        print(f"[NodePool] 官方 CSV 快照写入失败: {pool_exc}", flush=True)
        log_to_json("WARNING", "Main", f"NodePool 快照写入失败: {pool_exc}")

    log_to_json("INFO", "Main", f"成功获取官方 API 节点，共 {len(candidates)} 个候选节点")
    try:
        saved = persist_openvpn_candidates(candidates)
        if saved:
            log_to_json("INFO", "Main", f"已写入 {saved} 份 OpenVPN 配置")
    except Exception as exc:
        log_to_json("WARNING", "Main", f"OpenVPN 配置写入失败: {exc}")
    return candidates

def cached_nodes() -> list[dict[str, Any]]:
    return read_nodes()

_openvpn_version = None

def split_openvpn_command() -> list[str]:
    try:
        return shlex.split(OPENVPN_CMD, posix=(os.name != "nt")) or ["openvpn"]
    except ValueError as exc:
        raise RuntimeError(f"OPENVPN_CMD 配置无法解析: {exc}") from exc

def get_openvpn_version() -> float:
    global _openvpn_version
    if _openvpn_version is not None:
        return _openvpn_version
    try:
        cmd = split_openvpn_command()
        res = subprocess.run(cmd + ["--version"], capture_output=True, text=True, timeout=2)
        match = re.search(r"OpenVPN\s+(\d+\.\d+)", res.stdout or res.stderr)
        if match:
            _openvpn_version = float(match.group(1))
            return _openvpn_version
    except Exception:
        pass
    _openvpn_version = 2.4
    return _openvpn_version

def openvpn_command(config_file: str, route_nopull: bool, dev: str = "tun0") -> list[str]:
    command = split_openvpn_command()
    command.extend(
        [
            "--config",
            config_file,
            "--dev",
            dev,
            "--dev-type",
            "tun",
            "--pull-filter",
            "ignore",
            "route-ipv6",
            "--pull-filter",
            "ignore",
            "ifconfig-ipv6",
            "--pull-filter",
            "ignore",
            "dhcp-option",
            "--pull-filter",
            "ignore",
            "redirect-gateway",
            "--route-delay",
            "2",
            "--connect-retry-max",
            "1",
            "--connect-timeout",
            "15",
            "--auth-user-pass",
            str(AUTH_FILE),
            "--auth-nocache",
        ]
    )

    version = get_openvpn_version()
    if version >= 2.5:
        command.extend(["--data-ciphers", "AES-128-CBC:AES-256-GCM:AES-128-GCM:CHACHA20-POLY1305"])
    else:
        command.extend(["--ncp-ciphers", "AES-128-CBC:AES-256-GCM:AES-128-GCM:CHACHA20-POLY1305"])

    command.extend(["--verb", "3"])

    if os.path.exists("/etc/ssl/certs"):
        command.extend(["--capath", "/etc/ssl/certs"])

    try:
        content = Path(config_file).read_text(encoding="utf-8", errors="replace")
        if vpn_utils.is_config_tcp(content):
            ptype, host, port = vpn_utils.get_upstream_proxy()
            auth_file = upstream_proxy_auth_file()
            if ptype == "socks" and host and port:
                command.extend(["--socks-proxy", host, str(port)])
                if auth_file:
                    command.append(auth_file)
            elif ptype == "http" and host and port:
                command.extend(["--http-proxy", host, str(port)])
                if auth_file:
                    command.append(auth_file)
    except Exception:
        pass

    if route_nopull:
        command.append("--route-nopull")
    return command

def stop_process(process: subprocess.Popen[str] | None) -> None:
    if process is None or process.poll() is not None:
        return
    process.terminate()
    try:
        process.wait(timeout=8)
    except subprocess.TimeoutExpired:
        process.kill()

def kill_existing_openvpn_processes() -> None:
    if ISOLATED_INSTANCE:
        return
    if not sys.platform.startswith("linux"):
        return
    try:
        own_markers = [
            str(DATA_DIR),
            str(CONFIG_DIR),
            str(AUTH_FILE),
            str(UPSTREAM_PROXY_AUTH_FILE),
        ]
        killed_pids: list[int] = []
        proc_root = Path("/proc")
        if not proc_root.exists():
            return
        for proc_dir in proc_root.iterdir():
            if not proc_dir.name.isdigit():
                continue
            pid = int(proc_dir.name)
            if pid == os.getpid():
                continue
            try:
                raw = (proc_dir / "cmdline").read_bytes()
            except OSError:
                continue
            if not raw:
                continue
            args = [part.decode("utf-8", errors="replace") for part in raw.split(b"\0") if part]
            if not args:
                continue
            cmdline = " ".join(args)
            executable = Path(args[0]).name.lower()
            if "openvpn" not in executable and "openvpn" not in cmdline.lower():
                continue
            if pid in standby_protected_pids():
                continue
            if any(marker and marker in cmdline for marker in own_markers):
                try:
                    os.kill(pid, signal.SIGTERM)
                    killed_pids.append(pid)
                except ProcessLookupError:
                    pass
                except PermissionError:
                    print(f"[Cleanup] No permission to terminate OpenVPN PID {pid}", flush=True)
        if killed_pids:
            time.sleep(0.5)
            for pid in killed_pids:
                try:
                    raw = (proc_root / str(pid) / "cmdline").read_bytes()
                    cmdline = " ".join(part.decode("utf-8", errors="replace") for part in raw.split(b"\0") if part)
                    if any(marker and marker in cmdline for marker in own_markers):
                        os.kill(pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                except (OSError, PermissionError):
                    pass
            print(f"[Cleanup] Terminated AimiliVPN OpenVPN processes: {killed_pids}", flush=True)
    except Exception as e:
        print(f"[Cleanup Error] Failed to kill existing OpenVPN processes: {e}", flush=True)

def update_handshake_status(line_lower: str) -> None:
    status_map = {
        "resolving": ("解析域名", "正在解析服务器域名与 IP 地址..."),
        "udp link local": ("物理连接", "已创建本地套接字，开始尝试发送数据包..."),
        "tcp link local": ("物理连接", "已创建本地套接字，开始尝试发送数据包..."),
        "tls: initial packet": ("证书握手", "已成功发送首包，正在与远程服务器建立 TLS 安全通道..."),
        "verify ok": ("证书校验", "服务器证书校验成功，正在进行身份验证..."),
        "peer connection initiated": ("协商加密", "控制通道已建立，已初始化与服务器的加密对等连接..."),
        "push_request": ("请求配置", "正在向服务器发送 PUSH_REQUEST 请求配置参数与 IP 分配..."),
        "push_reply": ("应用配置", "已接收服务器 PUSH_REPLY，获取到 IP 分配，正在准备配置网卡..."),
        "tun/tap device": ("创建网卡", "正在创建虚拟通道并打开 TUN 虚拟网卡设备..."),
        "do_ifconfig": ("网卡配置", "正在为虚拟网卡配置 IP 地址及相关网络属性..."),
    }
    for key, (short_status, detailed_desc) in status_map.items():
        if key in line_lower:
            set_state(active_node_latency=short_status, last_check_message=detailed_desc)
            break

def tcp_connect_ms(host: str, port: int, timeout: float = 2.0) -> int:
    """Round trip to the node port. This is the delay a new connection feels."""
    host = str(host or "").strip()
    port = parse_int(port)
    if not host or port <= 0:
        return 0
    started = time.perf_counter()
    try:
        with socket.create_connection((host, port), timeout=timeout):
            return max(1, int((time.perf_counter() - started) * 1000))
    except OSError:
        return 0


def _udp_reply_ms(host: str, port: int, payload: bytes, timeout: float = 0.8) -> tuple[int, bytes]:
    """One UDP packet. A reply is the availability signal. ICMP unreachable is closed."""
    host = str(host or "").strip()
    port = parse_int(port)
    if not host or port <= 0 or not payload:
        return 0, b""
    started = time.perf_counter()
    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        sock.settimeout(timeout)
        sock.connect((host, port))
        sock.send(payload)
        data = sock.recv(256)
        if not data:
            return 0, b""
        return max(1, int((time.perf_counter() - started) * 1000)), data
    except OSError:
        return 0, b""
    finally:
        sock.close()


def _openvpn_udp_hello() -> bytes:
    # P_CONTROL_HARD_RESET_CLIENT_V2. Not a tunnel: no TLS, no tun, no login.
    return bytes([0x38]) + os.urandom(8) + bytes([0x00]) + b"\x00\x00\x00\x00"


def _openvpn_udp_reply_ok(data: bytes) -> bool:
    if not data:
        return False
    if (data[0] >> 3) in (5, 8, 9, 10):
        return True
    if len(data) >= 29 and (data[28] >> 3) in (5, 8, 9, 10):
        return True
    return False


def _ike_hello() -> bytes:
    # IKEv1 header only. A reply means UDP 500/4500 is answering, not that IPsec is up.
    return os.urandom(8) + (b"\x00" * 8) + bytes([0x00, 0x10, 0x02, 0x00]) + b"\x00\x00\x00\x00" + (28).to_bytes(4, "big")


def _endpoint_host_port(endpoint: dict[str, Any]) -> tuple[str, int, str]:
    metadata = endpoint.get("metadata") or {}
    host = str(endpoint.get("current_ip") or metadata.get("ip") or endpoint.get("hostname") or metadata.get("hostname") or "").strip()
    port = parse_int(endpoint.get("port") or metadata.get("port"))
    transport = str(endpoint.get("transport") or endpoint.get("proto") or metadata.get("transport") or "").strip().lower()
    return host, port, transport


def _config_has_tls_auth(text: str) -> bool:
    for raw in str(text or "").splitlines():
        line = raw.strip().lower()
        if line.startswith("#"):
            continue
        if line.startswith("tls-auth") or line.startswith("tls-crypt"):
            return True
        if line.startswith("<tls-auth") or line.startswith("<tls-crypt"):
            return True
    return False


def _openvpn_udp_has_tls_auth(endpoint: dict[str, Any]) -> bool:
    """True when this OpenVPN config uses tls-auth or tls-crypt. No extra probe."""
    metadata = endpoint.get("metadata") if isinstance(endpoint.get("metadata"), dict) else {}
    if metadata.get("tls_auth") is True:
        return True
    blobs = [endpoint.get("config_text"), metadata.get("config_text")]
    for blob in blobs:
        if _config_has_tls_auth(str(blob or "")):
            return True
    paths = [
        endpoint.get("config_ref"),
        endpoint.get("config_file"),
        metadata.get("config_file"),
    ]
    node_id = str(metadata.get("node_id") or endpoint.get("id") or "").strip()
    if node_id:
        try:
            cached = _nodes_index_get().get(node_id) or {}
        except Exception:
            cached = {}
        if _config_has_tls_auth(str(cached.get("config_text") or "")):
            return True
        if cached.get("config_file"):
            paths.append(cached.get("config_file"))
    for ref in paths:
        path = str(ref or "").strip()
        if not path:
            continue
        try:
            if _config_has_tls_auth(Path(path).read_text(encoding="utf-8", errors="ignore")):
                return True
        except OSError:
            continue
    return False


def light_probe_endpoint(endpoint: dict[str, Any]) -> dict[str, Any]:
    """Catalog availability. TCP is a port connect. UDP is one protocol packet. Never a tunnel."""
    protocol = str(endpoint.get("protocol") or "").strip().lower()
    host, port, transport = _endpoint_host_port(endpoint)
    udp = protocol == "l2tp-ipsec" or transport == "udp" or (protocol == "openvpn" and transport not in ("", "tcp"))
    if udp:
        if protocol == "l2tp-ipsec":
            rtt, data = _udp_reply_ms(host, 500, _ike_hello(), 0.8)
            if rtt <= 0:
                rtt, data = _udp_reply_ms(host, 4500, b"\x00\x00\x00\x00" + _ike_hello(), 0.8)
            if rtt <= 0 or not data:
                return {"ok": False, "latency_ms": 0, "message": "UDP IKE 无应答"}
            return {"ok": True, "latency_ms": rtt, "message": f"UDP IKE 有应答 {rtt} ms"}
        rtt, data = _udp_reply_ms(host, port, _openvpn_udp_hello(), 0.8)
        if rtt > 0 and _openvpn_udp_reply_ok(data):
            return {"ok": True, "latency_ms": rtt, "message": f"UDP OpenVPN 有应答 {rtt} ms"}
        # tls-auth drops the bare packet. Do not add another probe, and do not
        # mark the node unavailable: a missing reply is not proof it is down.
        if _openvpn_udp_has_tls_auth(endpoint):
            return {
                "ok": False,
                "inconclusive": True,
                "latency_ms": 0,
                "message": "UDP tls-auth 不回应裸探测包，不算不可用",
            }
        return {"ok": False, "latency_ms": 0, "message": "UDP OpenVPN 无应答"}
    if port <= 0:
        port = 443
    rtt = tcp_connect_ms(host, port, 1.0)
    if rtt <= 0:
        return {"ok": False, "latency_ms": 0, "message": "TCP 端口未开放"}
    return {"ok": True, "latency_ms": rtt, "message": f"TCP 端口开放 {rtt} ms"}


def light_probe_endpoint_id(endpoint_id: str) -> dict[str, Any]:
    endpoint_id = str(endpoint_id or "").strip()
    endpoint = node_pool.get_endpoint(endpoint_id) if endpoint_id else None
    if not endpoint:
        return {"ok": False, "latency_ms": 0, "message": "端点不存在"}
    result = light_probe_endpoint(endpoint)
    if result.get("inconclusive"):
        return result
    try:
        node_pool.record_endpoint_probe(
            endpoint_id,
            bool(result.get("ok")),
            int(result.get("latency_ms") or 0),
            str(result.get("message") or ""),
            speed_bps=None,
        )
    except Exception as exc:
        log_to_json("WARNING", "Probe", f"轻量检测写入失败: {exc}")
    return result

def usable_latency_ms(measured_ms: int, advertised_ping: int = 0, tcp_rtt_ms: int = 0) -> int:
    """Latency shown in the list is the round trip from this server, never VPN Gate's own Ping."""
    tcp = parse_int(tcp_rtt_ms)
    if 0 < tcp <= 1500:
        return tcp
    measured = parse_int(measured_ms)
    # Values above 1.5s are tunnel-setup time, not the delay a webpage feels.
    if 0 < measured <= 1500:
        return measured
    return 0

_TCP_RTT_CACHE: dict[str, tuple[float, int]] = {}
_TCP_RTT_LOCK = threading.Lock()
_tcp_fill_running = False

def cached_tcp_rtt(host: str, port: int) -> int:
    key = f"{str(host or '').strip()}:{parse_int(port)}"
    with _TCP_RTT_LOCK:
        item = _TCP_RTT_CACHE.get(key)
    if not item or time.time() - item[0] > 1800:
        return 0
    return int(item[1] or 0)

def remember_tcp_rtt(host: str, port: int, latency_ms: int) -> None:
    latency_ms = parse_int(latency_ms)
    if latency_ms <= 0:
        return
    key = f"{str(host or '').strip()}:{parse_int(port)}"
    with _TCP_RTT_LOCK:
        _TCP_RTT_CACHE[key] = (time.time(), latency_ms)

def _node_accepts_tcp_rtt(node: dict[str, Any]) -> bool:
    """UDP and L2TP have no TCP handshake. Port RTT is only for TCP listeners."""
    protocol = str(node.get("protocol") or "").lower()
    transport = str(node.get("proto") or node.get("transport") or "").lower()
    if protocol == "l2tp-ipsec" or transport == "udp":
        return False
    if protocol == "openvpn" and transport != "tcp":
        return False
    return protocol in ("softether", "sstp", "openvpn")


def apply_cached_tcp_rtt(nodes: list[dict[str, Any]]) -> None:
    for node in nodes:
        if not isinstance(node, dict):
            continue
        host = str(node.get("ip") or node.get("remote_host") or "").strip()
        port = parse_int(node.get("remote_port"))
        cached = cached_tcp_rtt(host, port)
        if cached:
            node["latency_ms"] = cached

_rtt_queue: queue.Queue[tuple[str, int, str]] = queue.Queue(maxsize=48)
_rtt_queued: set[str] = set()
_rtt_workers_started = False


def _rtt_worker() -> None:
    while True:
        host, port, endpoint_id = _rtt_queue.get()
        key = f"{host}:{port}"
        try:
            if ui_query_active() or manual_connection_active:
                continue
            try:
                if proxy_server.proxy_forwarding_busy(1.0):
                    continue
            except Exception:
                pass
            latency_ms = tcp_connect_ms(host, port, 0.6)
            if latency_ms <= 0:
                continue
            remember_tcp_rtt(host, port, latency_ms)
            if endpoint_id:
                try:
                    node_pool.note_tcp_rtt(endpoint_id, latency_ms)
                except Exception:
                    pass
        finally:
            with _TCP_RTT_LOCK:
                _rtt_queued.discard(key)
            _rtt_queue.task_done()


def _ensure_rtt_workers() -> None:
    global _rtt_workers_started
    if _rtt_workers_started:
        return
    _rtt_workers_started = True
    for index in range(3):
        threading.Thread(target=_rtt_worker, daemon=True, name=f"tcp-rtt-{index}").start()


def enqueue_tcp_rtt(nodes: list[dict[str, Any]]) -> None:
    _ensure_rtt_workers()
    for node in nodes:
        if not isinstance(node, dict) or not _node_accepts_tcp_rtt(node):
            continue
        host = str(node.get("ip") or node.get("remote_host") or "").strip()
        port = parse_int(node.get("remote_port"))
        if not host or port <= 0 or cached_tcp_rtt(host, port):
            continue
        key = f"{host}:{port}"
        with _TCP_RTT_LOCK:
            if key in _rtt_queued:
                continue
            _rtt_queued.add(key)
        try:
            _rtt_queue.put_nowait((host, port, str(node.get("pool_endpoint_id") or "")))
        except queue.Full:
            with _TCP_RTT_LOCK:
                _rtt_queued.discard(key)


def schedule_tcp_rtt(nodes: list[dict[str, Any]]) -> None:
    apply_server_tcp_rtt(nodes)


def apply_server_tcp_rtt(nodes: list[dict[str, Any]]) -> None:
    """Cached port RTT only. Live probes stay on a 3-worker queue.
    """
    apply_cached_tcp_rtt(nodes)
    enqueue_tcp_rtt(nodes)


def _prefer_openvpn_ip(config_text: str, node: dict[str, Any]) -> str:
    """Keep the volunteer hostname. VPN Gate IPs are often dynamic; the domain is the stable address."""
    text_value = str(config_text or "")
    host = str(node.get("host_name") or node.get("remote_host") or "").strip()
    try:
        ipaddress.ip_address(host)
        host = ""
    except ValueError:
        pass
    if not host or "." not in host:
        return text_value
    port = parse_int(node.get("remote_port"))
    lines = text_value.splitlines()
    changed = False
    out: list[str] = []
    for line in lines:
        match = re.match(r"^(\s*remote\s+)(\S+)(\s+)(\d+)(.*)$", line, re.IGNORECASE)
        if match and (port <= 0 or parse_int(match.group(4)) == port) and match.group(2) != host:
            out.append(f"{match.group(1)}{host}{match.group(3)}{match.group(4)}{match.group(5)}")
            changed = True
        else:
            out.append(line)
    return "\n".join(out) + ("\n" if text_value.endswith("\n") else "") if changed else text_value

def run_openvpn_until_ready(config_file: str, keep_alive: bool, route_nopull: bool, timeout: int | None = None, dev: str = "tun0", latency_out: list[int] | None = None, quiet: bool = False) -> tuple[bool, str, subprocess.Popen[str] | None]:
    limit = timeout if timeout is not None else OPENVPN_TEST_TIMEOUT_SECONDS
    try:
        process = subprocess.Popen(
            openvpn_command(config_file, route_nopull, dev),
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            encoding="utf-8",
            errors="replace",
            cwd=str(ROOT_DIR),
        )
    except FileNotFoundError:
        return False, "[错误代码 2001] [ERR_OVPN_CMD_NOT_FOUND] 未找到 openvpn 命令。原因: 系统未安装 openvpn，或 PATH 环境变量不正确。", None
    except OSError as exc:
        return False, f"[错误代码 2002] [ERR_OVPN_START_FAILED] openvpn 启动失败: {exc}。原因: 系统权限不足或配置冲突。", None

    lines: queue.Queue[str | None] = queue.Queue()
    startup_done = [False]
    openvpn_logs: list[str] = []

    def reader() -> None:
        assert process.stdout is not None
        for line in process.stdout:
            line_str = line.rstrip()
            if not startup_done[0]:
                openvpn_logs.append(line_str)
                lines.put(line_str)
            else:
                if keep_alive:
                    print(f"[OpenVPN] {line_str}", flush=True)
                    level = "INFO"
                    line_lower = line_str.lower()
                    if "cannot be used in this context" in line_lower:
                        level = "INFO"
                    elif "error" in line_lower or "failed" in line_lower or "cannot" in line_lower or "fatal" in line_lower or "permission denied" in line_lower:
                        level = "ERROR"
                    elif "warning" in line_lower or "warn" in line_lower or "deprecated" in line_lower:
                        level = "WARNING"
                    log_to_json(level, "VPN", f"[OpenVPN] {line_str}")
        if not startup_done[0]:
            lines.put(None)

    threading.Thread(target=reader, daemon=True).start()
    started = time.time()
    tail: list[str] = []
    ok = False
    message = "OpenVPN did not complete initialization."
    peer_ms = 0
    while time.time() - started < limit:
        if dev not in ("tun0", "tun-sb", "tun-hot") and not str(dev).startswith("tun-sw") and (manual_connection_active or ui_query_active()):
            startup_done[0] = True
            stop_process(process)
            return False, "检测已让路给前台筛选或人工切换", None
        try:
            line = lines.get(timeout=0.5)
        except queue.Empty:
            if process.poll() is not None:
                break
            continue
        if line is None:
            break
        if line:
            tail.append(line)
            tail = tail[-50:]
            if keep_alive:
                print(f"[OpenVPN] {line}", flush=True)
        lower = line.lower()
        if keep_alive and dev == "tun0":
            update_handshake_status(lower)
        if peer_ms <= 0 and "peer connection initiated" in lower:
            peer_ms = max(1, int((time.time() - started) * 1000))
        if "initialization sequence completed" in lower:
            ok = True
            elapsed_ms = peer_ms or max(1, int((time.time() - started) * 1000))
            if latency_out is not None:
                latency_out[:] = [elapsed_ms]
            message = f"OpenVPN connected in {elapsed_ms} ms."
            relax_tun_offloads(dev)
            break
        if "auth_failed" in lower or "authentication failed" in lower:
            message = "AUTH_FAILED"
            break
        if "cannot ioctl" in lower or "fatal error" in lower:
            message = line[-220:]
            break
    else:
        message = f"OpenVPN timeout after {limit}s."

    if not quiet:
        for line_str in openvpn_logs:
            level = "INFO"
            line_lower = line_str.lower()
            if "cannot be used in this context" in line_lower:
                level = "INFO"
            elif "error" in line_lower or "failed" in line_lower or "cannot" in line_lower or "fatal" in line_lower or "permission denied" in line_lower:
                level = "ERROR"
            elif "warning" in line_lower or "warn" in line_lower or "deprecated" in line_lower:
                level = "WARNING"
            log_to_json(level, "VPN", f"[OpenVPN] {line_str}")

    if not ok:
        err_code, diag_msg = vpn_utils.diagnose_openvpn_failure(tail)
        message = f"[错误代码 {err_code}] {diag_msg} (原始日志尾部: {tail[-1][-100:] if tail else '无'})"
    startup_done[0] = True
    if not keep_alive or not ok:
        stop_process(process)
        process = None
    return ok, message, process


def relax_tun_offloads(dev: str) -> None:
    """GRO on this tun driver collapses TCP. Small probes still pass, pages do not."""
    dev = str(dev or "").strip()
    if not dev or not Path("/sys/class/net", dev).exists():
        return
    try:
        subprocess.run(
            ["ethtool", "-K", dev, "gro", "off", "gso", "off", "tso", "off"],
            capture_output=True,
            timeout=2,
        )
    except Exception:
        pass


def standby_device() -> str:
    """Hot standby must not reuse the live tunnel NIC. Promotion keeps that NIC."""
    active = ""
    try:
        active = str(proxy_server.get_active_interface() or "").strip()
    except Exception:
        active = ""
    for name in ("tun-hot", "tun-sb"):
        if name != active:
            return name
    return "tun-hot"


def setup_policy_routing(interface: str = "tun0", gateway: str = "") -> None:
    """Install the live oif rule before removing any other one.

    The old order deleted table 100 first. A failed add then left 8500 bound
    to a tunnel NIC with no route, and every new connection was
    "Network is unreachable" after an egress switch.
    """
    interface = str(interface or "").strip()
    gateway = str(gateway or "").strip()
    if not interface:
        return
    relax_tun_offloads(interface)
    table = str(ACTIVE_ROUTE_TABLE)
    success = False
    for attempt in range(1, 4):
        try:
            route_cmd = ["ip", "route", "replace", "default"]
            if gateway:
                route_cmd.extend(["via", gateway])
            route_cmd.extend(["dev", interface])
            if gateway:
                route_cmd.append("onlink")
            route_cmd.extend(["table", table])
            subprocess.run(route_cmd, check=True, timeout=2)
            if not _oif_rule_prefs(interface, int(table)):
                rule = subprocess.run(
                    ["ip", "rule", "add", "oif", interface, "table", table],
                    capture_output=True, text=True, timeout=2,
                )
                if rule.returncode != 0 and "File exists" not in (rule.stderr or ""):
                    raise RuntimeError((rule.stderr or rule.stdout or "策略规则添加失败").strip())
            _ensure_one_fwmark_rule(int(table))
            _drop_foreign_oif_rules(interface, ACTIVE_ROUTE_TABLE)
            for proc_path in ["all", "default", interface]:
                try:
                    subprocess.run(["sysctl", "-w", f"net.ipv4.conf.{proc_path}.rp_filter=2"], capture_output=True, timeout=2)
                except Exception:
                    pass
            try:
                (DATA_DIR / "active_gateway.txt").write_text(gateway, encoding="utf-8")
            except OSError:
                pass
            _quiesce_duplicate_tunnel_ifaces(interface)
            print(f"[policy_routing] Enabled policy routing for interface {interface} (attempt {attempt} success)", flush=True)
            success = True
            break
        except Exception as e:
            print(f"[policy_routing] Attempt {attempt} failed to enable policy routing: {e}", flush=True)
            time.sleep(0.4)

    if not success:
        print(f"[路由配置失败] [错误代码 3003] [ERR_ROUTE_TABLE_ADD_FAILED] 策略路由配置失败。原因: 无法向路由表 {ACTIVE_ROUTE_TABLE} 添加默认路由，这可能会导致通过 VPN 接口的出站路由无法正常解析。请检查系统是否支持策略路由、iproute2 工具是否完整，以及是否具有 root 权限。", flush=True)
        log_to_json("ERROR", "Routing", f"[错误代码 3003] [ERR_ROUTE_TABLE_ADD_FAILED] 策略路由配置失败。原因: 无法向路由表 {ACTIVE_ROUTE_TABLE} 添加默认路由")


def _fwmark_rule_prefs(table: int) -> list[str]:
    try:
        shown = subprocess.run(["ip", "-4", "rule", "show"], capture_output=True, text=True, timeout=2)
    except Exception:
        return []
    prefs = []
    for line in (shown.stdout or "").splitlines():
        if not re.search(rf"\blookup {int(table)}\b", line):
            continue
        if not re.search(r"\bfwmark 0x64\b", line):
            continue
        pref = line.split(":", 1)[0].strip()
        if pref.isdigit():
            prefs.append(pref)
    return prefs


def _ensure_one_fwmark_rule(table: int) -> None:
    """ip rule add does not always reject a duplicate fwmark rule."""
    prefs = _fwmark_rule_prefs(table)
    if not prefs:
        added = subprocess.run(
            ["ip", "rule", "add", "fwmark", "100", "lookup", str(int(table))],
            capture_output=True, text=True, timeout=2,
        )
        if added.returncode != 0 and "File exists" not in (added.stderr or ""):
            raise RuntimeError((added.stderr or added.stdout or "标记路由添加失败").strip())
        prefs = _fwmark_rule_prefs(table)
    for pref in prefs[1:]:
        subprocess.run(["ip", "rule", "del", "pref", pref], capture_output=True, text=True, timeout=2)


def _oif_rule_prefs(interface: str, table: int) -> list[str]:
    try:
        shown = subprocess.run(["ip", "-4", "rule", "show"], capture_output=True, text=True, timeout=2)
    except Exception:
        return []
    prefs = []
    for line in (shown.stdout or "").splitlines():
        if not re.search(rf"\blookup {int(table)}\b", line):
            continue
        match = re.search(r"\boif (\S+)", line)
        if not match or match.group(1) != interface:
            continue
        pref = line.split(":", 1)[0].strip()
        if pref.isdigit():
            prefs.append(pref)
    return prefs


def _drop_foreign_oif_rules(interface: str, table: int) -> None:
    try:
        shown = subprocess.run(["ip", "-4", "rule", "show"], capture_output=True, text=True, timeout=2)
    except Exception:
        return
    foreign = []
    own = []
    for line in (shown.stdout or "").splitlines():
        if not re.search(rf"\blookup {int(table)}\b", line):
            continue
        match = re.search(r"\boif (\S+)", line)
        if not match:
            continue
        other = match.group(1)
        pref = line.split(":", 1)[0].strip()
        if other != interface:
            foreign.append(other)
        elif pref.isdigit():
            own.append(pref)
    for other in foreign:
        try:
            subprocess.run(["ip", "rule", "del", "oif", other, "table", str(table)], capture_output=True, timeout=2)
        except Exception:
            pass
    for pref in own[1:]:
        try:
            subprocess.run(["ip", "rule", "del", "pref", pref], capture_output=True, timeout=2)
        except Exception:
            pass


def _iface_ipv4(interface: str) -> str:
    try:
        shown = subprocess.run(["ip", "-4", "-o", "addr", "show", "dev", interface], capture_output=True, text=True, timeout=2)
    except Exception:
        return ""
    match = re.search(r"\binet (\d+\.\d+\.\d+\.\d+)", shown.stdout or "")
    return match.group(1) if match else ""


def _quiesce_duplicate_tunnel_ifaces(active: str) -> None:
    """A leftover NIC with the same tunnel address makes the next bind unroutable."""
    active = str(active or "").strip()
    own_ip = _iface_ipv4(active)
    if not active or not own_ip:
        return
    try:
        names = os.listdir("/sys/class/net")
    except OSError:
        return
    for name in names:
        if name == active or name in ("tun-sb", "tun-hot"):
            continue
        if not name.startswith(("vpn", "tun", "tap", "ppp")):
            continue
        if _iface_ipv4(name) != own_ip:
            continue
        try:
            subprocess.run(["ip", "link", "set", "dev", name, "down"], capture_output=True, timeout=2)
            log_to_json("INFO", "Routing", f"已关闭与 {active} 相同地址的残留网卡 {name}")
        except Exception:
            pass


def ensure_active_policy_route() -> tuple[bool, str]:
    iface = str(proxy_server.get_active_interface() or "").strip()
    if not iface or not Path("/sys/class/net").joinpath(iface).exists():
        return False, f"活动网卡不存在 {iface or '-'}"
    gateway = ""
    if active_external_tunnel is not None:
        gateway = str(getattr(active_external_tunnel, "gateway", "") or "")
    if not gateway:
        try:
            gateway = (DATA_DIR / "active_gateway.txt").read_text(encoding="utf-8").strip()
        except OSError:
            gateway = ""
    setup_policy_routing(iface, gateway=gateway)
    try:
        probe = subprocess.run(["ip", "route", "get", "8.8.8.8", "oif", iface], capture_output=True, text=True, timeout=2)
    except Exception as exc:
        return False, str(exc)
    text = ((probe.stdout or "") + " " + (probe.stderr or "")).strip()
    if probe.returncode == 0 and iface in text:
        return True, iface
    return False, text[:180] or "策略路由未指向活动网卡"

def _delete_route_rules(table: int) -> None:
    """ip rule del removes one match. Keep going until table 100 is empty."""
    for _ in range(32):
        try:
            result = subprocess.run(
                ["ip", "rule", "del", "table", str(table)],
                capture_output=True, text=True, timeout=2,
            )
        except Exception:
            return
        if result.returncode != 0:
            return


def suspend_policy_routing() -> None:
    """Direct mode. Drop every lookup of table 100, including rules with no oif.

    The route stays in the table. Proxy mode puts the live oif rule back
    before the 8500 process starts using the tunnel again.
    """
    try:
        _delete_route_rules(int(ACTIVE_ROUTE_TABLE))
    except Exception:
        pass


def cleanup_policy_routing() -> None:
    try:
        _delete_route_rules(int(ACTIVE_ROUTE_TABLE))
        subprocess.run(["ip", "route", "flush", "table", str(ACTIVE_ROUTE_TABLE)], capture_output=True, timeout=2)
        print(f"[policy_routing] Cleared policy routing table {ACTIVE_ROUTE_TABLE}", flush=True)
    except Exception:
        pass

def _clear_all_node_active_flags() -> None:
    with lock:
        nodes = read_nodes()
        changed = False
        for item in nodes:
            if item.get("active"):
                item["active"] = False
                changed = True
        if changed:
            write_json(NODES_FILE, nodes)

def stop_active_openvpn(keep_policy: bool = False) -> None:
    global active_openvpn_process, active_openvpn_node_id
    remember_connection_ended(openvpn_node_id=str(active_openvpn_node_id or ""))
    with lock:
        if not keep_policy:
            cleanup_policy_routing()
        config_to_delete = None
        if active_openvpn_node_id:
            nodes = read_nodes()
            node = next((item for item in nodes if item.get("id") == active_openvpn_node_id), None)
            if node:
                config_to_delete = node.get("config_file")

        stop_process(active_openvpn_process)
        active_openvpn_process = None
        active_openvpn_node_id = ""
        if not ISOLATED_INSTANCE:
            kill_existing_openvpn_processes()

        if config_to_delete:
            try:
                path = Path(config_to_delete)
                if path.exists():
                    path.unlink()
            except Exception:
                pass
        _clear_all_node_active_flags()

def active_openvpn_running() -> bool:
    return active_openvpn_process is not None and active_openvpn_process.poll() is None

def active_external_tunnel_running() -> bool:
    tunnel = active_external_tunnel
    if tunnel is None or not tunnel.ok or not tunnel.interface:
        return False
    # unknown means iproute timed out. The tunnel may still be forwarding.
    return tunnel_adapters.interface_ipv4_state(tunnel.interface) != "down"

def active_tunnel_running() -> bool:
    return active_openvpn_running() or active_external_tunnel_running()

def _tunnel_carrier_alive() -> bool:
    """True when the tunnel process is still there, even if iproute just timed out."""
    if active_openvpn_running():
        return True
    tunnel = active_external_tunnel
    if tunnel is None:
        return False
    protocol = str(tunnel.protocol or "")
    if protocol == "softether":
        try:
            return tunnel_adapters.SoftEtherAdapter()._vpnclient_running()
        except Exception:
            return False
    process = tunnel.process
    return process is not None and process.poll() is None

def _disconnect_external_tunnel(tunnel: tunnel_adapters.TunnelResult | None) -> None:
    """Stop one tunnel process. Does not clear the published 8500 interface."""
    if tunnel is None:
        return
    try:
        if tunnel.protocol == "softether":
            details = tunnel.details or {}
            tunnel_adapters.SoftEtherAdapter().disconnect(
                account=str(details.get("account") or "aimili"),
                nic=str(details.get("nic") or "aimili"),
                delete=True,
                added_routes=details.get("added_host_routes") or [],
            )
        elif tunnel.protocol == "sstp":
            details = tunnel.details or {}
            tunnel_adapters.SSTPAdapter.disconnect(
                tunnel.process,
                added_routes=details.get("added_host_routes") or [],
            )
        elif tunnel.protocol == "l2tp-ipsec":
            l2tp_adapter.disconnect(tunnel.namespace or "aimili-l2tp-prod")
    except Exception as exc:
        log_to_json("WARNING", "VPN", f"停止 {tunnel.protocol} 隧道失败: {exc}")


def stop_active_external_tunnel() -> None:
    global active_external_tunnel, active_pool_endpoint_id
    remember_connection_ended(endpoint_id=str(active_pool_endpoint_id or ""))
    tunnel = active_external_tunnel
    if tunnel is None:
        active_pool_endpoint_id = ""
        return
    _disconnect_external_tunnel(tunnel)
    cleanup_policy_routing()
    proxy_server.clear_active_interface()
    active_external_tunnel = None
    active_pool_endpoint_id = ""
    _clear_all_node_active_flags()
    set_state(active_pool_endpoint_id="", active_pool_endpoint={}, active_openvpn_node={}, active_tunnel_protocol="", active_tunnel_interface="")

def stop_all_tunnels() -> None:
    stop_active_external_tunnel()
    stop_active_openvpn()

def refresh_multi_protocol_catalog(force: bool = False) -> dict[str, Any]:
    global last_protocol_discovery_at
    now = time.time()
    if not force and now - last_protocol_discovery_at < 300:
        return {"ok": True, "skipped": True, "pool": node_pool.stats()}
    if not protocol_discovery_lock.acquire(blocking=False):
        return {"ok": True, "running": True, "pool": node_pool.stats()}
    try:
        servers, sources = vpngate_discovery.fetch_multi_source_tables(max_mirrors=None)
        upsert = node_pool.upsert_discovery_snapshot(servers, source="official_html_multi") or {}
        last_protocol_discovery_at = time.time()
        stats = node_pool.stats()
        set_state(
            protocol_catalog_last_at=last_protocol_discovery_at,
            protocol_catalog_count=len(servers),
            protocol_catalog_sources=len(sources),
        )
        log_to_json("INFO", "Main", f"多协议目录刷新完成，本轮合并 {len(servers)} 台服务器，来源 {len(sources)} 个，Master Pool={stats}")
        return {"ok": True, "servers": len(servers), "sources": sources, "pool": stats, "upsert": upsert}
    except Exception as exc:
        log_to_json("WARNING", "Main", f"多协议目录刷新失败: {exc}")
        return {"ok": False, "error": str(exc), "pool": node_pool.stats()}
    finally:
        protocol_discovery_lock.release()



def _tcp_port_open(host: str, port: int, timeout: float = 1.2) -> bool:
    """Cheap gate before a full VPN handshake. A closed port should not wait out a tunnel timeout."""
    try:
        port = int(port or 0)
    except (TypeError, ValueError):
        return False
    if port <= 0:
        return False
    try:
        with socket.create_connection((str(host or "").strip(), port), timeout=timeout):
            return True
    except Exception:
        return False


def parse_manual_endpoint(value: str) -> tuple[str, int]:
    """Parse a manual VPN Gate target.
    
    The port is optional for VPN Gate hostnames. When it is omitted, the
    official VPN Gate endpoint page is queried and each advertised protocol
    port is tested independently. Explicit address:port input remains fully
    supported.
    """
    raw = str(value or "").strip()
    if not raw:
        raise ValueError("节点地址不能为空")
    if raw.startswith("["):
        match = re.match(r"^\[([0-9a-fA-F:]+)\](?::(\d+))?$", raw)
        if not match:
            raise ValueError("IPv6 节点格式应为 [IPv6] 或 [IPv6]:端口")
        return match.group(1), int(match.group(2) or 0)
    match = re.match(r"^([^:]+)(?::(\d+))?$", raw)
    if not match:
        raise ValueError("节点格式应为 域名、域名:端口、IPv4 或 IPv4:端口")
    host = match.group(1).strip()
    if not host:
        raise ValueError("节点地址不能为空")
    return host, int(match.group(2) or 0)

def _manual_openvpn_template() -> str:
    """Return a current VPN Gate OpenVPN template already present on this instance."""
    try:
        for node in read_nodes():
            text = str(node.get("config_text") or "").strip()
            if text and "<ca>" in text and "<key>" in text and "remote " in text:
                return text
    except Exception:
        pass
    return ""

def _build_manual_openvpn_node(host: str, ip: str, port: int, transport: str = "tcp") -> dict[str, Any] | None:
    template = _manual_openvpn_template()
    if not template:
        try:
            fetched = fetch_candidates()
            for node in fetched:
                template = str(node.get("config_text") or "").strip()
                if template and "<ca>" in template and "<key>" in template and "remote " in template:
                    break
        except Exception:
            template = ""
    if not template:
        return None
    config_text = re.sub(r"(?m)^remote\s+\S+\s+\d+\s*$", f"remote {host} {int(port)}", template, count=1)
    transport = str(transport or "tcp").strip().lower()
    if transport not in ("tcp", "udp"):
        transport = "tcp"
    config_text = re.sub(r"(?m)^proto\s+\S+\s*$", f"proto {transport}", config_text, count=1)
    node_id = safe_name(f"MANUAL_{host}_{port}_{transport}")
    config_path = CONFIG_DIR / f"{node_id}.ovpn"
    node = {
        "id": node_id, "country": "", "country_short": "", "host_name": host, "ip": ip or host,
        "score": 0, "ping": 0, "speed": 0, "sessions": 0, "owner": "", "asn": "", "as_name": "",
        "location": "", "ip_type": "", "quality": "manual", "latency_ms": 0,
        "config_file": str(config_path), "config_text": config_text, "proto": transport, "protocol": "openvpn",
        "remote_host": host, "remote_port": int(port), "fetched_at": time.time(),
        "probe_status": "not_checked", "probe_message": "手动添加，等待本机验证", "probed_at": 0,
        "manual_added": True, "manual_source": "user_input",
    }
    try:
        CONFIG_DIR.mkdir(exist_ok=True, parents=True)
        config_path.write_text(config_text, encoding="utf-8")
    except Exception:
        pass
    try:
        vpn_utils.enrich_ip_info([node])
        # Manual nodes used to keep country="" even after IP enrichment. That
        # made the UI fall back to 🌐 and made the country filter unable to
        # include the manually-added endpoint. Persist the first location token
        # as the canonical country and keep the translated Chinese label.
        if not str(node.get("country") or "").strip():
            location = str(node.get("location") or "").strip()
            country_token = location.split()[0] if location else ""
            if country_token:
                node["country"] = vpn_utils.COUNTRY_TRANSLATIONS.get(country_token, country_token)
    except Exception:
        pass
    return node

def _manual_measure_speed(interface: str, gateway: str = "") -> int:
    """Download a short sample through the still-up manual tunnel and return bits/s."""
    interface = str(interface or "").strip()
    if not interface or proxy_server.proxy_forwarding_busy():
        return 0
    table = _acquire_probe_route_table()
    if table is None:
        return 0
    try:
        measured = measure_interface_speed(interface, gateway=gateway, table=table)
        return max(0, int(measured.get("speed_bps") or 0))
    except Exception:
        return 0
    finally:
        _release_probe_route_table(table)


def _manual_probe_openvpn(host: str, ip: str, port: int, transport: str = "tcp", timeout: int = 6) -> dict[str, Any]:
    transport = str(transport or "tcp").strip().lower()
    if transport not in ("tcp", "udp"):
        transport = "tcp"
    started = time.perf_counter()
    template = _manual_openvpn_template()
    if not template:
        return {
            "protocol": "openvpn",
            "transport": transport,
            "port": int(port),
            "ok": False,
            "elapsed_ms": int((time.perf_counter() - started) * 1000),
            "message": "本机没有可复用的 VPN Gate OpenVPN 配置模板",
        }
    test_id = safe_name(f"MANUAL_TEST_{host}_{port}_{transport}")
    temp_path = test_config_path(test_id)
    idx = None
    process = None
    try:
        config_text = re.sub(r"(?m)^remote\s+\S+\s+\d+\s*$", f"remote {host} {int(port)}", template, count=1)
        config_text = re.sub(r"(?m)^proto\s+\S+\s*$", f"proto {transport}", config_text, count=1)
        CONFIG_DIR.mkdir(exist_ok=True, parents=True)
        temp_path.write_text(config_text, encoding="utf-8")
        idx = get_free_test_index()
        dev = f"tun{idx}"
        ok, message, process = run_openvpn_until_ready(
            str(temp_path), keep_alive=True, route_nopull=True, timeout=int(timeout), dev=dev
        )
        speed_bps = _manual_measure_speed(dev) if ok else 0
        elapsed_ms = int((time.perf_counter() - started) * 1000)
        text = "OpenVPN 隧道建立成功" if ok else message
        if ok and speed_bps > 0:
            text += f" · {round(speed_bps / 1_000_000, 1)} Mbps"
        return {
            "protocol": "openvpn",
            "transport": transport,
            "port": int(port),
            "ok": bool(ok),
            "elapsed_ms": elapsed_ms,
            "speed_bps": speed_bps,
            "message": text,
        }
    except Exception as exc:
        return {
            "protocol": "openvpn",
            "transport": transport,
            "port": int(port),
            "ok": False,
            "elapsed_ms": int((time.perf_counter() - started) * 1000),
            "message": str(exc),
        }
    finally:
        if process is not None:
            stop_process(process)
        if idx is not None:
            release_test_index(idx)
        try:
            if temp_path.exists():
                temp_path.unlink()
        except Exception:
            pass


def _manual_probe_protocol(host: str, ip: str, protocol: str, port: int, transport: str = "tcp") -> dict[str, Any]:
    """Add-node check. TCP port or one UDP protocol packet. Not a tunnel."""
    protocol = str(protocol or "").strip().lower()
    transport = str(transport or "tcp").strip().lower()
    if protocol == "l2tp-ipsec":
        transport = "udp"
    started = time.perf_counter()
    probed = light_probe_endpoint({
        "protocol": protocol,
        "transport": transport,
        "port": int(port or 0),
        "current_ip": str(ip or host or "").strip(),
        "hostname": host,
    })
    return {
        "protocol": protocol,
        "transport": transport,
        "port": int(port or 0),
        "ok": bool(probed.get("ok")),
        "speed_bps": 0,
        "elapsed_ms": int((time.perf_counter() - started) * 1000),
        "message": str(probed.get("message") or ""),
    }


def _promote_manual_endpoint(host: str, ip: str, country: str, result: dict[str, Any], source_info: dict[str, Any] | None = None) -> dict[str, Any]:
    now = time.time()
    protocol = str(result.get("protocol") or "").lower()
    transport = str(result.get("transport") or "tcp").lower()
    port = int(result.get("port") or 0)
    source_info = source_info or {}

    # Immediately enrich manually-added endpoints so the row is usable in the
    # country/location filters as soon as the user clicks “完成”. The periodic
    # metadata loop remains a fallback, not a prerequisite for first display.
    enriched: dict[str, Any] = {"ip": ip or host, "remote_host": host}
    try:
        vpn_utils.enrich_ip_info([enriched])
    except Exception as exc:
        log_to_json("WARNING", "Probe", f"手工节点 IP 信息补全失败: {exc}")
    location = str(enriched.get("location") or "").strip()
    inferred_country = str(country or "").strip()
    if not inferred_country and location:
        country_prefixes = [
            "United Arab Emirates", "United Kingdom", "United States",
            "South Africa", "New Zealand", "Saudi Arabia", "Czech Republic",
            "Costa Rica", "Dominican Republic", "Hong Kong", "Taiwan",
            "Russian Federation", "Viet Nam", "Korea Republic of",
        ]
        location_lower = location.lower()
        for prefix in sorted(country_prefixes, key=len, reverse=True):
            if location_lower == prefix.lower() or location_lower.startswith(prefix.lower() + " "):
                inferred_country = prefix
                break
        if not inferred_country:
            inferred_country = location.split(" ", 1)[0]
    metadata_updates = {
        key: enriched.get(key) or ""
        for key in ("owner", "asn", "as_name", "location", "ip_type", "quality")
    }

    if protocol == "openvpn":
        node = _build_manual_openvpn_node(host, ip or host, port, transport=transport)
        if not node:
            raise RuntimeError("OpenVPN 有应答，但当前实例没有可复用的配置模板，无法保存节点")
        node["country"] = inferred_country or node.get("country") or ""
        for key, value in metadata_updates.items():
            if value:
                node[key] = value
        node["manual_added_at"] = now
        node["manual_source"] = "direct_connection"
        node["probe_status"] = "available"
        node["probe_message"] = "快速检测通过"
        node["probed_at"] = now
        node["latency_ms"] = int(result.get("elapsed_ms") or 0)
        speed_bps = int(result.get("speed_bps") or 0)
        node["speed"] = speed_bps
        node["speed_bps"] = speed_bps
        node_pool.upsert_openvpn_snapshot([node], source="manual_direct")
        node_pool.record_probe(node, ok=True, latency_ms=int(result.get("elapsed_ms") or 0), message="快速检测通过", speed_bps=speed_bps or None)
        with lock:
            nodes = read_nodes()
            nodes = [item for item in nodes if str(item.get("id") or "") != str(node.get("id") or "")]
            nodes.append(node)
            write_json(NODES_FILE, sort_all_nodes(nodes))
        _invalidate_ui_nodes_cache()
        node_pool.invalidate_ui_lists()
        return node

    server = {
        "hostname": host,
        "ip": ip or host,
        "country": inferred_country or "",
        "protocols": [{"protocol": protocol, "transport": transport, "port": port}],
        "source_count": 1 if source_info.get("found") else 0,
        "trusted_observation": True,
        "_sources": list(source_info.get("sources") or ["manual_direct"]),
        "manual_added_at": now,
        "speed": int(result.get("speed_bps") or 0),
    }
    node_pool.upsert_discovery_snapshot([server], source="manual_direct")
    if any(metadata_updates.values()) and (ip or host):
        node_pool.update_server_metadata_batch({str(ip or host): metadata_updates})
    endpoint_id = node_pool.endpoint_id(node_pool.server_key(server), protocol, transport, port)
    speed_bps = int(result.get("speed_bps") or 0)
    node_pool.record_endpoint_probe(endpoint_id, ok=True, latency_ms=int(result.get("elapsed_ms") or 0), message="快速检测通过", speed_bps=speed_bps or None)
    endpoint = node_pool.get_endpoint(endpoint_id)
    if not endpoint:
        raise RuntimeError("检测已通过，但写入 Master Pool 后无法读取协议端点")
    ui_node = protocol_endpoint_to_ui_node(endpoint)
    ui_node["manual_added_at"] = now
    ui_node["manual_source"] = "direct_connection"
    ui_node["probe_status"] = "available"
    ui_node["probe_message"] = "快速检测通过"
    ui_node["probed_at"] = now
    ui_node["latency_ms"] = int(result.get("elapsed_ms") or 0)
    ui_node["speed"] = speed_bps
    ui_node["speed_bps"] = speed_bps
    with lock:
        nodes = read_nodes()
        nodes = [item for item in nodes if not (str(item.get("pool_endpoint_id") or "") == endpoint_id or str(item.get("id") or "") == "pool:" + endpoint_id)]
        nodes.append(ui_node)
        write_json(NODES_FILE, sort_all_nodes(nodes))
    _invalidate_ui_nodes_cache()
    node_pool.invalidate_ui_lists()
    return ui_node


def manual_direct_verify(value: str, promote: bool = True) -> dict[str, Any]:
    host, port = parse_manual_endpoint(value)
    resolved_ip = host
    if not re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", resolved_ip) and ":" not in resolved_ip:
        try:
            infos = socket.getaddrinfo(host, None, socket.AF_INET)
            if infos:
                resolved_ip = str(infos[0][4][0])
        except Exception:
            resolved_ip = host

    if not manual_add_probe_lock.acquire(blocking=False):
        raise RuntimeError("已有手动节点检测任务正在运行，请稍候")

    try:
        source_info = {"found": False, "sources": []}
        existing = node_pool.find_library_matches(host, resolved_ip if resolved_ip != host else "")
        if not existing and resolved_ip:
            existing = node_pool.find_library_matches("", resolved_ip)
        if existing:
            shown = existing[0]
            label = str(shown.get("hostname") or host or resolved_ip)
            ip_label = str(shown.get("current_ip") or resolved_ip or "")
            country = str(shown.get("country") or "")
            where = "，".join(part for part in (label, ip_label, country) if part)
            return {
                "ok": True,
                "already_exists": True,
                "added": False,
                "passed": False,
                "input": str(value or "").strip(),
                "hostname": host,
                "ip": resolved_ip,
                "existing_count": len(existing),
                "message": f"全球资源库已有该节点（{where}），没有重复添加。刷新页面后，用筛选就能看到它。",
            }

        official = None
        if host.lower().endswith(".opengw.net"):
            try:
                official = vpngate_discovery.fetch_openvpn_endpoint_page(host, timeout=4)
            except Exception:
                official = None
            if official:
                source_info = {"found": True, "sources": list(official.get("_sources") or [])}

        official_protocols: dict[str, list[tuple[str, int]]] = {}
        if official:
            for item in official.get("protocols") or []:
                p = str(item.get("protocol") or "").lower()
                t = str(item.get("transport") or "tcp").lower()
                pport = int(item.get("port") or 0)
                # L2TP/IPsec is an exception: VPN Gate advertises it as a
                # supported protocol but there is no TCP/UDP service port to
                # parse from the table. The adapter handles it as IKE/UDP 500
                # + NAT-T/UDP 4500 internally, so keep a zero-port marker.
                if p and (pport > 0 or p == "l2tp-ipsec"):
                    official_protocols.setdefault(p, []).append((t if p != "l2tp-ipsec" else "udp", pport))

        attempts: list[dict[str, Any]] = []
        added_nodes: list[dict[str, Any]] = []
        successful_protocols: list[str] = []
        protocol_order = ["openvpn", "softether", "l2tp-ipsec", "sstp"]

        for protocol in protocol_order:
            offered = official_protocols.get(protocol) or []
            default_transport = "udp" if protocol == "l2tp-ipsec" else "tcp"

            # With a VPN Gate hostname and no explicit port, use every
            # advertised endpoint for that protocol until one really connects.
            # This is important because OpenVPN may advertise a TCP and a UDP
            # port, while SSL-VPN/SSTP use the published TCP port.
            if official and not offered:
                attempts.append({
                    "protocol": protocol,
                    "transport": default_transport,
                    "port": 0 if protocol == "l2tp-ipsec" else int(port),
                    "ok": False,
                    "skipped": True,
                    "message": f"当前节点未公布 {protocol} 接入方式",
                })
                continue

            if protocol == "l2tp-ipsec":
                candidates = [("udp", 0)]
            else:
                candidates = offered if official else [(default_transport, int(port))]
            if protocol != "l2tp-ipsec":
                candidates = sorted(candidates, key=lambda item: 0 if str(item[0]).lower() == "tcp" else 1)
            protocol_passed = False
            for transport, test_port in candidates:
                transport_name = str(transport or "").strip().lower()
                udp_endpoint = protocol == "l2tp-ipsec" or transport_name == "udp"
                reachable = udp_endpoint or int(test_port or 0) <= 0 or _tcp_port_open(resolved_ip or host, int(test_port))
                if not reachable:
                    attempts.append({
                        "protocol": protocol,
                        "transport": transport,
                        "port": int(test_port or 0),
                        "ok": False,
                        "skipped": True,
                        "message": "端口未开放，已跳过完整握手",
                    })
                    continue
                port_label = f" {int(test_port)}" if int(test_port or 0) > 0 else ""
                set_state(manual_add_message=f"正在检测 {protocol}{port_label}…")
                result = _manual_probe_protocol(host, resolved_ip, protocol, int(test_port), transport)
                attempts.append(result)
                if not result.get("ok"):
                    continue

                protocol_passed = True
                successful_protocols.append(protocol)
                promoted = _promote_manual_endpoint(
                    host,
                    resolved_ip,
                    str((official or {}).get("country") or ""),
                    result,
                    source_info=source_info,
                ) if promote else None
                if promoted:
                    added_nodes.append(promoted)
                break

            if not protocol_passed and not official and not port:
                attempts.append({
                    "protocol": protocol,
                    "transport": default_transport,
                    "port": 0,
                    "ok": False,
                    "skipped": True,
                    "message": "未提供端口，且当前地址无法从 VPN Gate 官方页面自动获取协议端口",
                })

        if successful_protocols:
            primary = next(
                (item for item in reversed(attempts)
                 if str(item.get("protocol") or "").lower() == successful_protocols[0] and item.get("ok")),
                {}
            )
            return {
                "ok": True,
                "mode": "direct_connection",
                "passed": True,
                "input": str(value or "").strip(),
                "hostname": host,
                "ip": resolved_ip,
                "country": (official or {}).get("country") or "",
                "protocol": primary.get("protocol"),
                "transport": primary.get("transport"),
                "port": primary.get("port"),
                "protocols": successful_protocols,
                "attempts": attempts,
                "added": bool(added_nodes),
                "added_nodes": added_nodes,
                "source_count": 1 if source_info.get("found") else 0,
                "sources": source_info.get("sources") or [],
                "message": (
                    f"快速检测完成：{len(successful_protocols)} 种协议有应答，"
                    f"{'已全部写入资源池并加入筛选列表。' if promote else ''}"
                ),
            }

        return {
            "ok": False,
            "mode": "direct_connection",
            "passed": False,
            "input": str(value or "").strip(),
            "hostname": host,
            "ip": resolved_ip,
            "attempts": attempts,
            "added": False,
            "added_nodes": [],
            "source_count": 1 if source_info.get("found") else 0,
            "sources": source_info.get("sources") or [],
            "error": "4 种 VPN Gate 接入方式都没有端口或协议应答，节点未加入资源池。",
        }
    finally:
        manual_add_probe_lock.release()


def _kick_manual_availability_check() -> None:
    # 新增资源立即进入持久化可用性检测引擎；若当前正处于连接/维护临界区，
    # 短暂重试而不阻塞前端“添加节点”请求。
    for _ in range(10):
        try:
            result = availability_sweep_once("")
            if not result.get("skipped") and not result.get("running"):
                return
        except Exception as exc:
            log_to_json("WARNING", "Probe", f"新增节点即时可用性检测触发失败: {exc}")
        time.sleep(2)

def add_manual_vpngate_node(value: str) -> dict[str, Any]:
    result = manual_direct_verify(value, promote=True)
    if result.get("ok"):
        set_state(
            last_check_message="新增节点已入库 · 已通知可用性检测模块，后台立即复核其余协议端点",
            availability_engine_message="新增节点已入库 · 已通知可用性检测模块，正在立即复核",
        )
        threading.Thread(target=_kick_manual_availability_check, daemon=True, name="manual-add-availability").start()
        result["detection_queued"] = True
        result["message"] = "添加成功。刷新页面后，筛选列表里就能看到刚添加的节点。"
    return result


def refresh_protocol_ip_metadata(max_ips: int = 100) -> int:
    """Fill ISP, ASN, location and IP-type for multi-protocol server records from the shared IP cache/query."""
    endpoints = node_pool.list_endpoints(limit=1000)
    seen: set[str] = set()
    probe_nodes: list[dict[str, Any]] = []
    for endpoint in endpoints:
        protocol = str(endpoint.get("protocol") or "").lower()
        if protocol == "openvpn":
            continue
        ip = str(endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "").strip()
        if not ip or ip in seen:
            continue
        meta = endpoint.get("server_metadata") or {}
        if all(str(meta.get(k) or "").strip() for k in ("owner", "as_name", "ip_type", "location")):
            continue
        seen.add(ip)
        probe_nodes.append({"ip": ip, "remote_host": ip})
        if len(probe_nodes) >= max(1, int(max_ips)):
            break

    if not probe_nodes:
        return 0
    try:
        vpn_utils.enrich_ip_info(probe_nodes)
    except Exception as exc:
        log_to_json("WARNING", "Main", f"多协议 IP/ISP 信息补全失败: {exc}")
        return 0
    updates: dict[str, dict[str, Any]] = {}
    for node in probe_nodes:
        ip = str(node.get("ip") or "").strip()
        if not ip:
            continue
        updates[ip] = {
            "owner": node.get("owner") or "",
            "asn": node.get("asn") or "",
            "as_name": node.get("as_name") or "",
            "location": node.get("location") or "",
            "ip_type": node.get("ip_type") or "",
            "quality": node.get("quality") or "",
        }
    updated = node_pool.update_server_metadata_batch(updates)
    if updated:
        log_to_json("INFO", "Main", f"多协议 IP/ISP 信息补全 {updated} 台服务器")
    return updated

def protocol_catalog_loop() -> None:
    # Initial catalog refresh shortly after startup, then refresh periodically.
    time.sleep(10)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        try:
            if ui_command_plane.is_busy() or global_pool_refresh_running:
                time.sleep(5)
                continue
            if not ISOLATED_INSTANCE:
                # Catalog acquisition is owned by resource_collect_loop.
                # This lightweight loop only refreshes missing ISP/IP metadata.
                refresh_protocol_ip_metadata(max_ips=50)
        except Exception as exc:
            log_to_json("WARNING", "Main", f"多协议 IP/ISP 元数据后台刷新异常: {exc}")
        time.sleep(1800)


def _background_share_sync(peer_id: str) -> None:
    try:
        result = resource_share.sync_peer(peer_id, timeout=60, force=True)
        imported = result.get("imported") or result.get("received") or 0
        if result.get("ok") is False:
            log_to_json("WARNING", "Share", f"资源共享同步失败: {peer_id} {result.get('error') or ''}")
        else:
            log_to_json("INFO", "Share", f"资源共享同步完成: {peer_id} 导入 {imported}")
    except Exception as exc:
        log_to_json("WARNING", "Share", f"资源共享同步失败: {peer_id} {exc}")
    finally:
        try:
            resource_share.mark_syncing(peer_id, False)
        except Exception:
            pass


def _start_share_sync(peer_id: str) -> None:
    peer_id = str(peer_id or "").strip()
    if not peer_id:
        return
    resource_share.mark_syncing(peer_id, True)
    threading.Thread(target=_background_share_sync, args=(peer_id,), name=f"share-sync-{peer_id}", daemon=True).start()


def resource_share_loop() -> None:
    # The loop is only a lightweight scheduler sweep. Each Peer decides when
    # its next real sync is due according to its configured hour/day/week interval.
    time.sleep(45)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        try:
            if ui_command_plane.is_busy() or global_pool_refresh_running:
                time.sleep(5)
                continue
            peers = resource_share.list_peers()
            if peers:
                results = resource_share.sync_all(force=False)
                actual = [item for item in results if not item.get("skipped")]
                if actual:
                    ok_count = sum(1 for item in actual if item.get("ok"))
                    log_to_json("INFO", "Share", f"资源共享周期同步完成：{ok_count}/{len(actual)} 个实际同步任务完成")
        except Exception as exc:
            log_to_json("WARNING", "Share", f"资源共享调度扫描异常: {exc}")
        time.sleep(RESOURCE_SHARE_SYNC_INTERVAL_SECONDS)


def _wait_for_automatic_connection_idle(timeout: float = 2.0) -> None:
    deadline = time.time() + float(timeout)
    warned = False
    while True:
        with lock:
            busy = bool(is_connecting)
        if not busy:
            return
        if not warned:
            warned = True
            set_state(
                last_check_message="人工操作已获得优先权，正在等待当前自动连接任务收尾；不会再启动新的自动连接。"
            )
        if time.time() >= deadline:
            set_state(
                last_check_message="人工切换已获得优先权，自动检测仍在收尾；不再继续等待，立即建立候选隧道。",
                manual_switch_message="正在优先建立新隧道，当前连接继续保持在线…",
            )
            return
        time.sleep(0.25)

def connect_pool_endpoint(endpoint_id: str, manual: bool = False, fast: bool = False) -> str:
    global active_external_tunnel, active_pool_endpoint_id, active_openvpn_node_id, is_connecting, manual_connection_active, manual_connection_epoch, connection_generation, active_connection_generation
    endpoint_id = str(endpoint_id or "").strip()
    endpoint = node_pool.get_endpoint(endpoint_id)
    if endpoint is None:
        raise ValueError("Protocol endpoint not found")
    protocol = str(endpoint.get("protocol") or "").lower()
    metadata = endpoint.get("metadata") or {}
    quick = bool(fast or manual)
    if protocol not in ("softether", "sstp", "l2tp-ipsec"):
        raise RuntimeError(f"协议 {protocol} 当前尚未开放生产连接")

    # Untrusted endpoints get a port or one UDP packet before the production
    # tunnel below. The connect itself is the real tunnel; do not dial twice.
    if not metadata.get("trusted_observation") and not quick:
        probe_result = None
        endpoint_now = endpoint
        for _ in range(2):
            probe_result = light_probe_endpoint(endpoint_now)
            if probe_result.get("ok") or (probe_result or {}).get("inconclusive"):
                break
        if not (probe_result or {}).get("inconclusive"):
            try:
                node_pool.record_endpoint_probe(
                    endpoint_id,
                    bool((probe_result or {}).get("ok")),
                    int((probe_result or {}).get("latency_ms") or 0),
                    str((probe_result or {}).get("message") or ""),
                    speed_bps=None,
                )
            except Exception as exc:
                log_to_json("WARNING", "Probe", f"连接前快速检测写入失败: {exc}")
        if (probe_result or {}).get("inconclusive"):
            pass
        elif not probe_result or not probe_result.get("ok"):
            reason = str((probe_result or {}).get("message") or "端口或协议无应答")
            raise RuntimeError(f"该端点尚未完成多源确认，已先做快速可用性检测，但未通过：{reason}")
        endpoint = node_pool.get_endpoint(endpoint_id) or endpoint
        metadata = endpoint.get("metadata") or {}

    if protocol == "softether" and not tunnel_adapters.SoftEtherAdapter.available():
        raise RuntimeError("SoftEther 客户端组件未安装")
    if protocol == "sstp" and not tunnel_adapters.SSTPAdapter.available():
        raise RuntimeError("SSTP 客户端组件未安装")
    if protocol == "l2tp-ipsec":
        l2tp_env = tunnel_adapters.L2TPIPsecAdapter.environment_report(run_kernel_test=False)
        if not l2tp_env.get("ready"):
            raise RuntimeError(f"L2TP/IPsec 隔离环境未就绪: {l2tp_env}")

    manual_guard = False
    if manual:
        if not manual_connection_lock.acquire(blocking=False):
            raise RuntimeError("已有人工连接操作正在执行，请等待当前切换完成")
        manual_guard = True
        with lock:
            if manual_connection_active:
                manual_connection_lock.release()
                manual_guard = False
                raise RuntimeError("当前已有手动连接任务正在运行，请稍候")
            manual_connection_epoch += 1
            manual_connection_active = True
        set_state(
            manual_switch_active=True,
            manual_switch_started_at=time.time(),
            pending_connection_id=endpoint_id,
            pending_connection_pool_endpoint_id=endpoint_id,
            pending_connection_protocol=protocol,
            pending_connection_country=str(endpoint.get("country") or ""),
            pending_connection_address=(
                str(metadata.get("ip") or metadata.get("hostname") or endpoint.get("hostname") or endpoint.get("current_ip") or endpoint_id)
                + (f":{parse_int(endpoint.get('port'))}" if parse_int(endpoint.get('port')) else "")
            ),
            manual_switch_message=f"正在建立 {protocol} 安全隧道…",
            is_connecting=True,
            last_check_message=f"正在切换至 {protocol} 节点，请稍候…",
        )
    if manual and manual_guard:
        try:
            _wait_for_automatic_connection_idle()
        except Exception:
            with lock:
                manual_connection_active = False
            manual_connection_lock.release()
            manual_guard = False
            raise
    with lock:
        if is_connecting and not manual:
            if manual_guard:
                manual_connection_active = False
                manual_connection_lock.release()
                manual_guard = False
            raise RuntimeError("当前已有连接或节点检测任务正在运行，请稍后再试")
        is_connecting = True

    result: tunnel_adapters.TunnelResult | None = None
    promoted = False
    token = re.sub(r"[^a-z0-9]", "", endpoint_id.lower())[:8] or uuid.uuid4().hex[:8]

    def cleanup_new() -> None:
        if result is None:
            return
        try:
            if result.protocol == "softether":
                details = result.details or {}
                tunnel_adapters.SoftEtherAdapter().disconnect(
                    account=str(details.get("account") or f"prod{token}"),
                    nic=str(details.get("nic") or f"a{token}"),
                    delete=True,
                    added_routes=details.get("added_host_routes") or [],
                )
            elif result.protocol == "sstp":
                details = result.details or {}
                tunnel_adapters.SSTPAdapter.disconnect(
                    result.process,
                    added_routes=details.get("added_host_routes") or [],
                )
            elif result.protocol == "l2tp-ipsec":
                l2tp_adapter.disconnect(result.namespace)
        except Exception:
            pass

    try:
        set_state(is_connecting=True, last_check_message=f"正在预连接并验证 {protocol} 端点 {endpoint_id}")

        metadata = endpoint.get("metadata") or {}
        host = str(metadata.get("hostname") or endpoint.get("hostname") or endpoint.get("current_ip") or "").strip()
        if not host:
            raise RuntimeError("端点缺少可连接的 Hostname/IP")
        port = parse_int(endpoint.get("port"))

        # Make-before-break: establish a completely separate candidate tunnel
        # while the existing production 8500 path continues serving traffic.
        if manual:
            set_state(manual_switch_message=f"正在建立 {protocol} 安全隧道…")
        if protocol == "softether":
            result = tunnel_adapters.SoftEtherAdapter().connect(
                host=host,
                port=port or 443,
                account=f"prod{token}",
                nic=f"a{token}",
                username="vpn",
                password="vpn",
            )
        elif protocol == "sstp":
            result = tunnel_adapters.SSTPAdapter().connect(
                hostname=host if port in (0, 443) else f"{host}:{port}",
                username="vpn",
                password="vpn",
                timeout=5 if quick else 20,
                reuse_existing=False,
            )
        else:
            def _l2tp_progress(stage: str) -> None:
                labels = {
                    "ipsec": "IPsec 握手中…",
                    "l2tp": "IPsec 已完成，正在建立 L2TP…",
                    "ppp": "L2TP 已发起，正在等待 PPP 地址…",
                }
                text = labels.get(stage) or "正在建立 L2TP/IPsec…"
                if manual:
                    set_state(manual_switch_message=text, last_check_message=text)

            if manual:
                set_state(manual_switch_message="IPsec 握手中…", last_check_message="正在进行 IPsec 握手，随后进入 L2TP 和 PPP。")
            result = l2tp_adapter.connect(
                host=host,
                username="vpn",
                password="vpn",
                psk="vpn",
                namespace=f"aimili-l2tp-{token}",
                timeout=5 if quick else 35,
                on_progress=_l2tp_progress,
            )

        if not result.ok or not result.interface:
            detail = str(result.message or f"{protocol} 连接失败")
            node_pool.record_endpoint_probe(endpoint_id, False, 0, detail[:500])
            log_to_json("WARNING", "VPN", f"{protocol} 连接失败 {endpoint_id}: {detail[:800]}")
            if protocol == "l2tp-ipsec" and detail.startswith("L2TP/IPsec 已失败"):
                raise RuntimeError(detail.splitlines()[0][:180])
            if protocol == "l2tp-ipsec":
                raise RuntimeError("L2TP/IPsec 未完成：IPsec、L2TP 或 PPP 在时限内没有拿到地址")
            short = " ".join(detail.split())
            raise RuntimeError(short[:180] or f"{protocol} 连接失败")

        if protocol == "l2tp-ipsec":
            ensure_l2tp_namespace_forward(result)
        if quick:
            direct_health = {"ok": True, "latency_ms": 0, "ip": ""}
            if manual:
                set_state(manual_switch_message="隧道已建立，正在接管…", last_check_message="未做网页检测，直接接管")
        else:
            if manual:
                set_state(manual_switch_message="目标隧道已建立，正在验证真实出口与网络质量…", last_check_message="目标节点已建立隧道，正在进行真实出口验证…")
            direct_health = (
                tunnel_adapters.L2TPIPsecAdapter.egress_check(result)
                if protocol == "l2tp-ipsec"
                else check_interface_egress(result.interface, result.gateway)
            )
        if not direct_health.get("ok"):
            message = str(direct_health.get("error") or "候选隧道出口检测失败")
            node_pool.record_endpoint_probe(endpoint_id, False, 0, message)
            raise RuntimeError(message)
        local_forward_note = ""
        if protocol == "l2tp-ipsec":
            forwarded = check_root_via_interface(str(result.interface or ""), str(result.gateway or ""))
            layer = "OK" if forwarded.get("ok") else ("FAIL " + str(forwarded.get("error") or ""))
            log_to_json("INFO", "VPN", f"L2TP inner PPP: OK; root→{result.interface}: {layer}")
            if not forwarded.get("ok"):
                local_forward_note = "节点可用，本机转发未通过：" + str(forwarded.get("error") or "root→host_veth 失败")
                node_pool.note_local_forward(endpoint_id, False, local_forward_note)

        old_tunnel = active_external_tunnel
        old_openvpn = active_openvpn_running()
        previous_iface = proxy_server.get_active_interface()
        if (
            old_tunnel is not None
            and old_tunnel.interface
            and result.interface
            and old_tunnel.interface == result.interface
        ):
            raise RuntimeError(f"{protocol} 没有建立独立隧道，仍占用当前网卡 {result.interface}")
        if manual:
            set_state(manual_switch_message="隧道已建立，正在接管 8500…", last_check_message="未做网页检测，直接接管")
        if not manual and (manual_connection_active or time.time() < manual_connection_quiet_until):
            raise RuntimeError("人工切换优先，取消这次自动接管")

        # Publish the new NIC before the old tunnel is removed, then let 8500
        # drop sockets that are still bound to the previous device.
        proxy_server.set_active_interface(result.interface)
        setup_policy_routing(result.interface, gateway=result.gateway)
        if not _wait_iface_applied(str(result.interface or ""), timeout=1.0):
            log_to_json("WARNING", "VPN", f"8500 未在 1 秒内确认新网卡 {result.interface}")

        in_direct = proxy_server.get_egress_mode() == "direct"
        health = (
            {"ok": True, "ip": str(direct_health.get("ip") or ""), "latency_ms": direct_health.get("latency_ms") or 0}
            if in_direct or quick
            else check_proxy_health(fast=True)
        )
        if not health.get("ok"):
            if previous_iface:
                proxy_server.set_active_interface(previous_iface)
            if old_tunnel is not None and old_tunnel.interface:
                setup_policy_routing(old_tunnel.interface, gateway=str(getattr(old_tunnel, "gateway", "") or ""))
            elif previous_iface:
                setup_policy_routing(previous_iface)
            node_pool.record_endpoint_probe(endpoint_id, False, 0, str(health.get("error") or "8500 代理出口检测失败"))
            raise RuntimeError(str(health.get("error") or "8500 代理出口检测失败"))

        if old_tunnel is not None:
            _disconnect_external_tunnel(old_tunnel)
        if old_openvpn:
            stop_active_openvpn(keep_policy=True)

        active_external_tunnel = result
        active_pool_endpoint_id = endpoint_id
        active_openvpn_node_id = ""
        promoted = True
        connection_generation += 1
        active_connection_generation = connection_generation

        latency = parse_int(health.get("latency_ms")) or parse_int(direct_health.get("latency_ms"))
        node_pool.record_endpoint_probe(endpoint_id, True, latency, "production connect ok")
        remember_live_connection(endpoint_id=endpoint_id)
        if manual:
            set_manual_route_pin(protocol=protocol, endpoint_id=endpoint_id, country=str(endpoint.get("country") or ""))
            align_proxy_settings_to_manual(
                str(endpoint.get("country") or ""),
                str(endpoint_ip_type(endpoint) or ""),
                protocol=protocol,
            )
        endpoint_meta = endpoint.get("server_metadata") or {}
        endpoint_summary = {
            "endpoint_id": endpoint_id,
            "protocol": protocol,
            "transport": endpoint.get("transport", ""),
            "port": endpoint.get("port", 0),
            "hostname": endpoint.get("hostname", ""),
            "current_ip": endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "",
            "country": endpoint.get("country", ""),
            "location": endpoint_meta.get("location") or endpoint.get("country", ""),
            "owner": endpoint_meta.get("owner") or endpoint_meta.get("as_name") or "",
            "ip_type": endpoint_meta.get("ip_type") or "",
            "quality": endpoint_meta.get("quality") or "",
            "speed": endpoint.get("latest_speed", 0),
            "latency_ms": latency,
        }
        set_state(
            active_pool_endpoint_id=endpoint_id,
            active_pool_endpoint=endpoint_summary,
            active_openvpn_node={},
            active_tunnel_protocol=protocol,
            manual_switch_message=("切换完成，正在确认客户端状态…" if manual else ""),
            active_tunnel_interface=result.interface,
            tunnel_forward_ok=not bool(local_forward_note),
            proxy_ok=not in_direct,
            proxy_ip="" if in_direct else health.get("ip", ""),
            proxy_latency_ms=latency,
            proxy_error=local_forward_note,
            is_connecting=False,
            last_check_message=local_forward_note or f"Connected {protocol} {endpoint_id}",
        )
        log_to_json(
            "INFO",
            "VPN",
            f"{protocol} 候选隧道验证成功后接管 8500，接口 {result.interface}",
        )
        return f"Connected {protocol} endpoint {endpoint_id}"
    except Exception:
        if not promoted:
            cleanup_new()
        raise
    finally:
        is_connecting = False
        if manual_guard:
            with lock:
                manual_connection_active = False
            manual_connection_lock.release()

def sort_all_nodes(nodes: list[dict[str, Any]]) -> list[dict[str, Any]]:
    now = time.time()

    def manual_sort_key(node: dict[str, Any]) -> tuple[int, float]:
        ts = float(node.get("manual_added_at") or 0)
        recent = bool(ts and now - ts <= 3600)
        return (0 if recent else 1, -ts if recent else 0.0)

    available_nodes = sorted(
        [n for n in nodes if n.get("probe_status") == "available" or n.get("active")],
        key=lambda n: (
            0 if n.get("active") else 1,
            manual_sort_key(n),
            0 if n.get("ip_type") in ("residential", "mobile") else 1,
            parse_int(n.get("latency_ms")) or 999999,
            -parse_int(n.get("score"))
        )
    )
    untested_nodes = sorted(
        [n for n in nodes if n.get("probe_status") in ("not_checked", "testing") and not n.get("active")],
        key=lambda n: (manual_sort_key(n), -parse_int(n.get("score")), parse_int(n.get("ping")))
    )
    unavailable_nodes = sorted(
        [n for n in nodes if n.get("probe_status") == "unavailable" and not n.get("active")],
        key=lambda n: (-parse_int(n.get("score")), -float(n.get("probed_at", 0)))
    )
    return available_nodes + untested_nodes + unavailable_nodes

_COUNTRY_REGION_GROUPS = {
    "east_asia": {"中国", "日本", "韩国", "台湾", "香港", "澳门", "蒙古"},
    "southeast_asia": {"新加坡", "马来西亚", "印度尼西亚", "泰国", "越南", "菲律宾", "柬埔寨"},
    "south_asia": {"印度"},
    "north_america": {"美国", "加拿大", "墨西哥"},
    "south_america": {"巴西", "阿根廷", "智利", "哥伦比亚"},
    "europe": {"英国", "爱尔兰", "法国", "德国", "荷兰", "比利时", "卢森堡", "瑞士", "奥地利", "意大利", "西班牙", "葡萄牙", "波兰", "捷克", "匈牙利", "罗马尼亚", "希腊", "瑞典", "挪威", "丹麦", "芬兰", "冰岛", "乌克兰", "土耳其", "格鲁吉亚"},
    "middle_east": {"以色列", "阿联酋", "沙特阿拉伯", "伊朗", "伊拉克"},
    "central_asia": {"哈萨克斯坦"},
    "oceania": {"澳大利亚", "新西兰"},
    "africa": {"南非", "埃及"},
}

def country_region(country: Any) -> str:
    normalized = normalized_country_name(country)
    for region, countries in _COUNTRY_REGION_GROUPS.items():
        if normalized in countries:
            return region
    return ""

def country_preference_rank(target_country: Any, candidate_country: Any) -> int:
    target = normalized_country_name(target_country)
    candidate = normalized_country_name(candidate_country)
    if not target:
        return 0
    if candidate == target:
        return 0
    target_region = country_region(target)
    candidate_region = country_region(candidate)
    if target_region and target_region == candidate_region:
        return 1
    return 2

def ip_type_preference_rank(preferred: str, actual: Any) -> int:
    preferred = str(preferred or "all").lower()
    actual = str(actual or "").lower()
    # Fixed product order: mobile -> residential -> hosting -> proxy -> other.
    ranks = {
        "all": {"mobile": 0, "residential": 1, "hosting": 2, "proxy": 3, "unknown": 4},
        "mobile": {"mobile": 0, "residential": 1, "hosting": 2, "proxy": 3, "unknown": 4},
        "residential": {"residential": 0, "mobile": 0, "hosting": 2, "proxy": 3, "unknown": 4},
        "hosting": {"hosting": 0, "mobile": 1, "residential": 2, "proxy": 3, "unknown": 4},
    }
    return ranks.get(preferred, ranks["all"]).get(actual, 4)


ROUTING_PROTOCOL_CHOICES = {"", "openvpn", "softether", "sstp", "l2tp-ipsec"}
ROUTING_SPEED_CHOICES = {0, 50_000_000, 100_000_000, 300_000_000, 500_000_000, 700_000_000, 1_000_000_000}
ROUTING_LATENCY_CHOICES = {"", "100", "200", "400", "800", "1000", "gt1000"}

def normalize_routing_protocol(value: Any) -> str:
    protocol = str(value or "").strip().lower()
    if protocol in ("all", "any"):
        protocol = ""
    if protocol not in ROUTING_PROTOCOL_CHOICES:
        raise ValueError("无效的协议筛选")
    return protocol

def normalize_routing_min_speed(value: Any) -> int:
    try:
        speed = int(value or 0)
    except (TypeError, ValueError):
        raise ValueError("无效的速度筛选")
    if speed not in ROUTING_SPEED_CHOICES:
        raise ValueError("无效的速度筛选")
    return speed

def normalize_routing_latency(value: Any) -> str:
    text = str(value or "").strip().lower()
    if text in ("0", "all", "any", "none"):
        text = ""
    if text not in ROUTING_LATENCY_CHOICES:
        raise ValueError("无效的延迟筛选")
    return text

def normalize_routing_blocklist(value: Any) -> str:
    """One domain or IP per line. * blocks every candidate. vpn_87* blocks that prefix."""
    if value is None:
        return ""
    if isinstance(value, list):
        raw_lines = [str(item) for item in value]
    else:
        raw_lines = str(value).replace("\r\n", "\n").replace("\r", "\n").split("\n")
    kept: list[str] = []
    seen: set[str] = set()
    for line in raw_lines:
        text = " ".join(str(line).strip().split())
        if not text or text.startswith("#"):
            continue
        compact = text.replace(" ", "")
        if re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", compact):
            text = compact
        if len(text) > 253:
            raise ValueError("屏蔽规则过长")
        key = text.lower()
        if key in seen:
            continue
        if len(kept) >= 200:
            raise ValueError("屏蔽列表最多 200 条")
        seen.add(key)
        kept.append(text)
    return "\n".join(kept)

def routing_block_rules(ui_cfg: dict[str, Any]) -> list[str]:
    try:
        text = normalize_routing_blocklist(ui_cfg.get("routing_blocklist") or "")
    except ValueError:
        text = str(ui_cfg.get("routing_blocklist") or "")
    return [line.strip().lower() for line in text.splitlines() if line.strip()]

def _block_rule_is_ip(rule: str) -> bool:
    return bool(re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", rule) or re.fullmatch(r"(?:\d{1,3}\.){1,3}\*", rule))

def _ip_rule_matches(rule: str, ip: str) -> bool:
    if not re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", ip):
        return False
    if re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", rule):
        return rule == ip
    if not re.fullmatch(r"(?:\d{1,3}\.){1,3}\*", rule):
        return False
    return ip.startswith(rule[:-1])

def _block_rule_matches(rule: str, value: str) -> bool:
    if not rule or not value:
        return False
    if rule == "*":
        return True
    if "*" not in rule:
        return rule == value
    try:
        regex = re.escape(rule).replace(r"\*", ".*")
        return re.fullmatch(regex, value) is not None
    except re.error:
        return False

def endpoint_block_values(endpoint: dict[str, Any]) -> list[str]:
    meta = endpoint.get("metadata") if isinstance(endpoint.get("metadata"), dict) else {}
    values: list[str] = []
    for raw in (
        endpoint.get("hostname"),
        endpoint.get("host_name"),
        meta.get("hostname") if isinstance(meta, dict) else "",
        endpoint.get("current_ip"),
        meta.get("ip") if isinstance(meta, dict) else "",
        _endpoint_ip(endpoint),
    ):
        text = str(raw or "").strip().lower()
        if text and text not in values:
            values.append(text)
    return values

def endpoint_is_blocked(endpoint: dict[str, Any] | None, ui_cfg: dict[str, Any]) -> bool:
    rules = routing_block_rules(ui_cfg)
    if not rules or not endpoint:
        return False
    if "*" in rules:
        return True
    ips = [value for value in endpoint_block_values(endpoint) if re.fullmatch(r"(?:\d{1,3}\.){3}\d{1,3}", value)]
    hosts = [value for value in endpoint_block_values(endpoint) if value not in ips]
    for rule in rules:
        if _block_rule_is_ip(rule):
            if any(_ip_rule_matches(rule, ip) for ip in ips):
                return True
        elif any(_block_rule_matches(rule, host) for host in hosts):
            return True
    return False

def latency_filter_matches(latency_ms: int, latency_filter: str) -> bool:
    text = str(latency_filter or "").strip().lower()
    if text in ("", "0", "all", "any", "none"):
        return True
    ms = int(latency_ms or 0)
    if text == "gt1000":
        return ms > 1000
    return 0 < ms <= int(text)

def endpoint_display_latency_ms(endpoint: dict[str, Any]) -> int:
    meta = endpoint.get("metadata") or {}
    measured = endpoint.get("latency_ewma")
    if not measured:
        measured = endpoint.get("latency_ms") or 0
    try:
        measured_ms = int(float(measured or 0))
    except (TypeError, ValueError):
        measured_ms = 0
    try:
        tcp_rtt_ms = int(float(meta.get("tcp_rtt_ms") or 0))
    except (TypeError, ValueError):
        tcp_rtt_ms = 0
    return usable_latency_ms(measured_ms, tcp_rtt_ms=tcp_rtt_ms)

def endpoint_ip_type(endpoint: dict[str, Any]) -> str:
    meta = endpoint.get("server_metadata") or {}
    if meta.get("ip_type"):
        return str(meta.get("ip_type") or "")
    return str((endpoint.get("metadata") or {}).get("ip_type") or "")

ROUTING_MIN_LINE_SPEED_BPS = 50_000_000
ROUTING_HIGH_SPEED_BPS = 500_000_000


def _speed_floor_bps(ui_cfg: dict[str, Any]) -> int:
    """Lowest speed that may be selected. User choice wins when it is at least 50 Mbps."""
    try:
        chosen = int((ui_cfg or {}).get("routing_min_speed_bps") or 0)
    except (TypeError, ValueError):
        chosen = 0
    if chosen < ROUTING_MIN_LINE_SPEED_BPS:
        return ROUTING_MIN_LINE_SPEED_BPS
    return chosen

def routing_target_country(ui_cfg: dict[str, Any]) -> str:
    """Manual switch country first, then an explicit preference, then the server."""
    pinned = str((manual_route_pin or {}).get("country") or "").strip()
    if pinned:
        return normalized_country_name(pinned)
    explicit = str(ui_cfg.get("force_country") or "").strip()
    if explicit:
        return normalized_country_name(explicit)
    try:
        bootstrap = _read_bootstrap_state()
        local = str(bootstrap.get("local_server_country") or "").strip()
        if local:
            return normalized_country_name(local)
    except Exception:
        pass
    try:
        state = get_state()
        local = str(state.get("server_country") or "").strip()
        if local:
            return normalized_country_name(local)
    except Exception:
        pass
    # If the server's own location is unavailable, continue from the country
    # of the currently active tunnel. This keeps detection continuity after a
    # manual switch without making the browser responsible for probe state.
    try:
        if active_pool_endpoint_id:
            endpoint = node_pool.get_endpoint(active_pool_endpoint_id)
            active_country = str((endpoint or {}).get("country") or "").strip()
            if active_country:
                return normalized_country_name(active_country)
        if active_openvpn_node_id:
            active = next(
                (n for n in read_nodes() if str(n.get("id") or "") == str(active_openvpn_node_id)),
                None,
            )
            active_country = str((active or {}).get("country") or "").strip()
            if active_country:
                return normalized_country_name(active_country)
    except Exception:
        pass
    return ""

def routing_favorite_rank(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> int:
    favorites = {str(x) for x in (ui_cfg.get("favorite_node_ids") or []) if str(x)}
    if not favorites:
        return 1
    endpoint_id = str(endpoint.get("endpoint_id") or "")
    metadata = endpoint.get("metadata") or {}
    variants = {endpoint_id, "pool:" + endpoint_id if endpoint_id else "", str(metadata.get("node_id") or "")}
    return 0 if favorites.intersection(variants) else 1

def routing_speed_gate(endpoint: dict[str, Any]) -> int:
    """Global speed ladder: >=500 Mbps, >=50 Mbps, then <50 Mbps fallback."""
    speed = int(endpoint.get("latest_speed") or endpoint.get("speed") or 0)
    if speed >= ROUTING_HIGH_SPEED_BPS:
        return 0
    if speed >= ROUTING_MIN_LINE_SPEED_BPS:
        return 1
    return 2

def routing_web_health_rank(endpoint: dict[str, Any]) -> int:
    status = str(endpoint.get("status") or "").upper()
    return {"HOT": 0, "AVAILABLE": 1, "DEGRADED": 2}.get(status, 3)

def routing_preference_tier(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> int:
    if ui_cfg.get("routing_mode") == "fixed_ip":
        return 99

    # All routing preferences are soft priorities. The ordering is deliberate:
    # 1) server-local country, 2) favorite/custom preference group,
    # 3) mobile -> residential -> hosting -> proxy/other,
    # 4) >=500 Mbps -> >=50 Mbps -> slower fallback.
    # Latency and real web usability remain the final service-quality sort keys.
    target_country = routing_target_country(ui_cfg)
    country_rank = 0 if target_country and normalized_country_name(endpoint.get("country")) == target_country else 1
    favorite_rank = routing_favorite_rank(endpoint, ui_cfg)
    ip_rank = ip_type_preference_rank(ui_cfg.get("routing_ip_type", "all"), endpoint_ip_type(endpoint))
    speed_gate = routing_speed_gate(endpoint)
    return country_rank * 10000 + favorite_rank * 1000 + ip_rank * 100 + speed_gate * 10

def routing_session_rank(endpoint: dict[str, Any]) -> int:
    """0 会话且带宽够用最优先。10 以内优质，其后 20/30/50/80/100/100+。没有会话数据时保持中性。"""
    meta = endpoint.get("server_metadata") if isinstance(endpoint.get("server_metadata"), dict) else {}
    if "sessions" not in meta:
        return 4
    try:
        sessions = int(meta.get("sessions") or 0)
    except (TypeError, ValueError):
        return 4
    speed = int(endpoint.get("latest_speed") or endpoint.get("speed") or meta.get("speed") or 0)
    return NodePool.session_grade_rank(sessions, speed, True)


def routing_service_key(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> tuple:
    latency = float(endpoint.get("latency_ewma") or endpoint.get("latency_ms") or 999999)
    if latency <= 0:
        latency = 999999
    speed = int(endpoint.get("latest_speed") or endpoint.get("speed") or 0)
    jitter = float(endpoint.get("jitter_ewma") or 999999)
    success_streak = int(endpoint.get("success_streak") or 0)
    return (
        availability_rank(endpoint),
        routing_preference_tier(endpoint, ui_cfg),
        routing_speed_gate(endpoint),
        routing_session_rank(endpoint),
        # Within the same country/IP/speed tier, measured latency is preferred.
        latency,
        # Real web usability is the next quality gate; raw speed is only a
        # tie-breaker after the service is already in the preferred speed tier.
        routing_web_health_rank(endpoint),
        -speed,
        -float(endpoint.get("last_success") or 0),
        jitter,
        -int(endpoint.get("last_session_seconds") or 0),
        -success_streak,
    )

def openvpn_node_to_routing_endpoint(node: dict[str, Any]) -> dict[str, Any]:
    key = node_pool.server_key(node)
    eid = openvpn_pool_endpoint_id(node)
    return {
        "endpoint_id": eid,
        "server_key": key,
        "protocol": "openvpn",
        "transport": str(node.get("proto") or ""),
        "port": parse_int(node.get("remote_port")),
        "status": "HOT" if node.get("probe_status") == "available" and parse_int(node.get("latency_ms")) > 0 else "NEW",
        "first_seen": float(node.get("fetched_at") or 0),
        "last_seen": float(node.get("fetched_at") or 0),
        "last_success": float(node.get("probed_at") or 0),
        "success_streak": 1 if node.get("probe_status") == "available" else 0,
        "fail_streak": 0,
        "latency_ewma": float(node.get("latency_ms") or 0),
        "jitter_ewma": 0,
        "latest_ping": int(node.get("ping") or 0),
        "latest_speed": int(node.get("speed") or 0),
        "latest_sessions": int(node.get("sessions") or 0),
        "latest_server_score": int(node.get("score") or 0),
        "country": node.get("country") or "",
        "hostname": node.get("host_name") or node.get("remote_host") or node.get("ip") or "",
        "current_ip": node.get("ip") or node.get("remote_host") or "",
        "metadata": {
            "node_id": node.get("id") or "",
            "trusted_observation": True,
        },
        "server_metadata": {
            "owner": node.get("owner") or "",
            "asn": node.get("asn") or "",
            "as_name": node.get("as_name") or "",
            "location": node.get("location") or "",
            "ip_type": node.get("ip_type") or "",
            "quality": node.get("quality") or "",
            "sessions": int(node.get("sessions") or 0),
            "speed": int(node.get("speed") or 0),
        },
    }

def routing_node_service_key(node: dict[str, Any], ui_cfg: dict[str, Any]) -> tuple[int, int, float, int, float, int, float]:
    return routing_service_key(openvpn_node_to_routing_endpoint(node), ui_cfg)

def unified_hot_pool_candidates(ui_cfg: dict[str, Any], exclude_endpoint_id: str = "", limit: int = 100, protocol: str = "") -> list[dict[str, Any]]:
    endpoints: dict[str, dict[str, Any]] = {}
    wanted = str(protocol or "").strip().lower()

    # Routing reads only verified rows. The full catalog scan stalls this
    # 1GB box while a switch or the 8500 relay is waiting.
    pinned_country = normalized_country_name((manual_route_pin or {}).get("country") or "")
    if not pinned_country:
        pinned_country = routing_target_country(ui_cfg)
    try:
        routed = node_pool.list_routing_endpoints(limit=800, country=pinned_country)
        if pinned_country and not routed:
            routed = node_pool.list_routing_endpoints(limit=800)
        for endpoint in routed:
            eid = str(endpoint.get("endpoint_id") or "")
            status = str(endpoint.get("status") or "").upper()
            endpoint_protocol = str(endpoint.get("protocol") or "").lower()
            if wanted and endpoint_protocol != wanted:
                continue
            if (
                eid
                and status in ("HOT", "AVAILABLE")
                and endpoint_protocol in ("openvpn", "softether", "sstp", "l2tp-ipsec")
                and (
                    endpoint_protocol == "openvpn"
                    or bool((endpoint.get("metadata") or {}).get("trusted_observation"))
                )
            ):
                endpoints[eid] = endpoint
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"Master Pool 读取失败: {exc}")

    # nodes.json is several megabytes. Only parse it when the pool has no
    # verified candidate, otherwise every switch stalls on this 1GB box.
    if not endpoints:
        for node in read_nodes():
            if node.get("probe_status") != "available" or node.get("active"):
                continue
            endpoint = openvpn_node_to_routing_endpoint(node)
            if endpoint.get("endpoint_id") and endpoint.get("endpoint_id") not in endpoints:
                endpoints[endpoint["endpoint_id"]] = endpoint
    candidates = []
    for endpoint in endpoints.values():
        eid = str(endpoint.get("endpoint_id") or "")
        if not eid or eid == exclude_endpoint_id:
            continue
        if endpoint_is_blocked(endpoint, ui_cfg):
            continue
        if endpoint.get("status") not in ("HOT", "AVAILABLE"):
            continue
        if str(endpoint.get("protocol") or "").lower() != "openvpn" and not bool((endpoint.get("metadata") or {}).get("trusted_observation")):
            continue
        endpoint["routing_tier"] = routing_preference_tier(endpoint, ui_cfg)
        target_country = routing_target_country(ui_cfg)
        endpoint["routing_country_rank"] = 0 if target_country and normalized_country_name(endpoint.get("country")) == target_country else 2
        endpoint["routing_favorite_rank"] = routing_favorite_rank(endpoint, ui_cfg)
        endpoint["routing_ip_rank"] = ip_type_preference_rank(ui_cfg.get("routing_ip_type", "all"), endpoint_ip_type(endpoint))
        endpoint["routing_speed_gate"] = routing_speed_gate(endpoint)
        endpoint["routing_web_health_rank"] = routing_web_health_rank(endpoint)
        candidates.append(endpoint)

    # Default routing prefers residential/mobile only when they meet the
    # minimum 50 Mbps line-speed requirement. If none of those preferred IP
    # types reaches 50 Mbps, fall back to the wider pool instead of getting
    # stuck on a very slow residential/mobile endpoint. This affects routing
    # only; detection still measures every endpoint according to priority.
    before_speed_preference = list(candidates)
    if str(ui_cfg.get("routing_ip_type") or "all").lower() == "all":
        preferred_fast = [
            ep for ep in candidates
            if endpoint_ip_type(ep) in ("residential", "mobile")
            and int(ep.get("latest_speed") or ep.get("speed") or 0) >= ROUTING_MIN_LINE_SPEED_BPS
        ]
        if preferred_fast:
            candidates = preferred_fast

    # A manual switch pins the hot pool to that country. If the country has
    # any verified node, do not keep a standby from somewhere else.
    pinned_country = normalized_country_name((manual_route_pin or {}).get("country") or "")
    if pinned_country:
        local = [ep for ep in candidates if normalized_country_name(ep.get("country")) == pinned_country]
        if not local:
            local = [ep for ep in before_speed_preference if normalized_country_name(ep.get("country")) == pinned_country]
        if local:
            candidates = local

    # 住宅 IP 同时接受移动网。两边都没有可用节点时才回退到机房。
    ip_pref = str(ui_cfg.get("routing_ip_type") or "all").lower()
    if ip_pref == "residential":
        home = [
            ep for ep in candidates
            if str(endpoint_ip_type(ep) or "").lower() in ("residential", "mobile")
        ]
        if home:
            candidates = home

    # 协议和速度与首页筛选项相同，但出站不能因为筛空就断线，所以筛空时回退。
    preferred_protocol = str(protocol or "").strip().lower() or str(ui_cfg.get("routing_protocol") or "").strip().lower()
    if preferred_protocol and not str(protocol or "").strip():
        matched = [
            ep for ep in candidates
            if str(ep.get("protocol") or "").lower() == preferred_protocol
        ]
        if matched:
            candidates = matched
    # 速度是硬门槛：没设时保底 ≥50 Mbps，设了 300 就只留 ≥300。不够就空，不改挑更慢的。
    floor = _speed_floor_bps(ui_cfg)
    candidates = [
        ep for ep in candidates
        if int(ep.get("latest_speed") or ep.get("speed") or 0) >= floor
    ]
    latency_filter = str(ui_cfg.get("routing_latency") or "").strip().lower()
    if latency_filter:
        matched = [
            ep for ep in candidates
            if latency_filter_matches(endpoint_display_latency_ms(ep), latency_filter)
        ]
        if matched:
            candidates = matched

    candidates.sort(key=lambda endpoint: routing_service_key(endpoint, ui_cfg))
    return candidates[:max(1, min(int(limit), 100))]

def current_active_routing_endpoint() -> dict[str, Any] | None:
    if active_pool_endpoint_id:
        return node_pool.get_endpoint(active_pool_endpoint_id)
    if active_openvpn_node_id:
        node = next((n for n in read_nodes() if n.get("id") == active_openvpn_node_id), None)
        return openvpn_node_to_routing_endpoint(node) if node else None
    return None

def maybe_recover_preferred_route(force: bool = False) -> bool:
    if manual_route_pin or ui_command_plane.is_busy():
        return False
    ui_cfg = load_ui_config()
    if ui_cfg.get("routing_mode") in ("fixed_ip",) or not bool(ui_cfg.get("connection_enabled", True)):
        return False
    if _explicit_scheme_configured(ui_cfg):
        now = time.time()
        last_check = float(get_state().get("last_preference_recovery_at") or 0)
        if not force and now - last_check < 60:
            return False
        set_state(last_preference_recovery_at=now)
        try:
            return enter_explicit_scheme(immediate=bool(force))
        except Exception as exc:
            log_to_json("WARNING", "Routing", f"回到新方案失败: {exc}")
            return False
    if ui_cfg.get("routing_mode") in ("fixed_ip", "favorites") or not bool(ui_cfg.get("connection_enabled", True)):
        return False
    has_preference = (
        bool(routing_target_country(ui_cfg))
        or str(ui_cfg.get("routing_ip_type", "all")) != "all"
        or bool(ui_cfg.get("favorite_node_ids"))
    )
    if not has_preference:
        return False
    state = get_state()
    if bool(state.get("proxy_ok")) and active_tunnel_running():
        return False
    if bool(state.get("priority_running")):
        return False
    now = time.time()
    last_check = float(state.get("last_preference_recovery_at") or 0)
    if not force and now - last_check < 60:
        return False
    set_state(last_preference_recovery_at=now)
    current = current_active_routing_endpoint()
    if not current:
        return False
    if routing_preference_tier(current, ui_cfg) == 0:
        return False
    preferred = [
        ep for ep in unified_hot_pool_candidates(ui_cfg, limit=100)
        if int(ep.get("routing_country_rank") or 99) == 0
        and str(ep.get("status") or "").upper() in ("HOT", "AVAILABLE")
    ]
    if not preferred:
        return False
    target = preferred[0]
    try:
        ok = try_unified_failover(exclude_endpoint_id=str(current.get("endpoint_id") or ""), attempts=3, preferred_only=True)
        if ok:
            set_state(preference_recovery_at=time.time(), preference_recovery_endpoint=str(target.get("endpoint_id") or ""), last_check_message="已恢复用户设定的国家/IP类型偏好")
        return ok
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"偏好路由恢复失败: {exc}")
        return False

def endpoint_is_unstable(endpoint: dict[str, Any] | None) -> bool:
    if not endpoint:
        return False
    label = str(endpoint.get("stability") or "").lower()
    if label in ("不稳定", "unstable"):
        return True
    meta = endpoint.get("metadata") if isinstance(endpoint.get("metadata"), dict) else {}
    return str(meta.get("stability") or "").lower() in ("不稳定", "unstable")


def availability_rank(endpoint: dict[str, Any] | None) -> int:
    label = ""
    if endpoint:
        label = str(endpoint.get("stability") or "")
        if not label and isinstance(endpoint.get("metadata"), dict):
            label = str(endpoint["metadata"].get("stability") or "")
    return {"高可用": 0, "可用": 1, "待可用": 2, "不稳定": 4, "unstable": 4}.get(label, 2)


def _stable_candidates(endpoints: list[dict[str, Any]]) -> list[dict[str, Any]]:
    stable = [ep for ep in endpoints if not endpoint_is_unstable(ep)]
    return stable or list(endpoints)


def server_home_country() -> str:
    try:
        local = str(get_state().get("server_country") or "").strip()
        if local:
            return normalized_country_name(local)
    except Exception:
        pass
    return ""


def scheme_without_country(ui_cfg: dict[str, Any], country: str = "") -> dict[str, Any]:
    """Keep protocol, IP type, speed and latency. Only the country changes."""
    cfg = dict(ui_cfg)
    target = normalized_country_name(country)
    if target:
        cfg["routing_mode"] = "fixed_region"
        cfg["force_country"] = target
    else:
        cfg["routing_mode"] = "auto"
        cfg["force_country"] = ""
    if str(cfg.get("routing_ip_type") or "all") == "all":
        cfg["routing_ip_type"] = "residential"
    try:
        min_speed = int(cfg.get("routing_min_speed_bps") or 0)
    except (TypeError, ValueError):
        min_speed = 0
    if min_speed < ROUTING_MIN_LINE_SPEED_BPS:
        cfg["routing_min_speed_bps"] = ROUTING_MIN_LINE_SPEED_BPS
    return cfg


def default_routing_config(ui_cfg: dict[str, Any]) -> dict[str, Any]:
    return scheme_without_country(ui_cfg, server_home_country())


def _explicit_scheme_configured(ui_cfg: dict[str, Any]) -> bool:
    if str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        return False
    try:
        min_speed = int(ui_cfg.get("routing_min_speed_bps") or 0)
    except (TypeError, ValueError):
        min_speed = 0
    return bool(
        str(ui_cfg.get("routing_mode") or "") in ("fixed_region", "favorites")
        or str(ui_cfg.get("routing_ip_type") or "all") != "all"
        or str(ui_cfg.get("routing_protocol") or "").strip()
        or min_speed > 0
        or str(ui_cfg.get("routing_latency") or "").strip()
    )


def _current_session_age() -> float:
    started = float(get_state().get("active_connected_at") or 0)
    if started <= 0:
        return 10**9
    return max(0.0, time.time() - started)


def _resolve_openvpn_endpoint_id(node_id: str) -> str:
    parts = str(node_id or "").rsplit("_", 2)
    if len(parts) == 3 and str(parts[1]).isdigit():
        return node_pool.find_endpoint_id(parts[0], int(parts[1]), "openvpn") or ""
    return ""


def remember_live_connection(endpoint_id: str = "", openvpn_node_id: str = "") -> None:
    eid = str(endpoint_id or "").strip() or _resolve_openvpn_endpoint_id(openvpn_node_id)
    set_state(active_connected_at=time.time(), active_connected_endpoint=eid)
    if not eid:
        return
    try:
        node_pool.note_connection_started(eid)
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"记录连接时间失败: {exc}")


def remember_connection_ended(endpoint_id: str = "", openvpn_node_id: str = "") -> None:
    eid = str(endpoint_id or "").strip() or _resolve_openvpn_endpoint_id(openvpn_node_id)
    if not eid:
        return
    try:
        node_pool.note_connection_ended(eid)
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"记录断开时间失败: {exc}")


def endpoint_matches_explicit_routing(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> bool:
    """True when this exit already satisfies the filters the user just saved.

    Country is only required in 优先地区. 住宅 IP accepts residential and mobile.
    Speed is never optional: unset means ≥50 Mbps, and a saved 300 Mbps keeps only ≥300 Mbps.
    """
    if not endpoint:
        return False
    if endpoint_is_blocked(endpoint, ui_cfg):
        return False
    mode = str(ui_cfg.get("routing_mode") or "auto")
    if mode == "fixed_region":
        target = normalized_country_name(ui_cfg.get("force_country") or "")
        if target and normalized_country_name(endpoint.get("country")) != target:
            return False
    ip_pref = str(ui_cfg.get("routing_ip_type") or "all").lower()
    actual = str(endpoint_ip_type(endpoint) or "").lower()
    if ip_pref == "residential" and actual not in ("residential", "mobile"):
        return False
    if ip_pref == "mobile" and actual != "mobile":
        return False
    if ip_pref == "hosting" and actual != "hosting":
        return False
    protocol = str(ui_cfg.get("routing_protocol") or "").strip().lower()
    if protocol and str(endpoint.get("protocol") or "").lower() != protocol:
        return False
    floor = _speed_floor_bps(ui_cfg)
    speed = int(endpoint.get("latest_speed") or endpoint.get("speed") or 0)
    if speed < floor:
        return False
    if not latency_filter_matches(endpoint_display_latency_ms(endpoint), str(ui_cfg.get("routing_latency") or "")):
        return False
    if mode == "favorites" and routing_favorite_rank(endpoint, ui_cfg) != 0:
        return False
    return True


_scheme_snap_lock = threading.Lock()
_scheme_snap: dict[str, Any] = {"at": 0.0, "key": "", "value": None}
_scheme_snap_running = False


def _scheme_filter_label(ui_cfg: dict[str, Any]) -> str:
    parts: list[str] = []
    protocol = str(ui_cfg.get("routing_protocol") or "").strip().lower()
    parts.append({"openvpn": "OpenVPN", "softether": "SSL-VPN", "sstp": "SSTP", "l2tp-ipsec": "L2TP/IPsec"}.get(protocol, "所有协议"))
    ip_type = str(ui_cfg.get("routing_ip_type") or "all").lower()
    parts.append({"residential": "住宅", "hosting": "机房", "mobile": "移动", "all": "不限类型"}.get(ip_type, ip_type))
    latency = str(ui_cfg.get("routing_latency") or "").strip().lower()
    if latency == "gt1000":
        parts.append("＞1000 ms")
    elif latency:
        parts.append(f"≤{latency} ms")
    else:
        parts.append("不限延迟")
    try:
        speed = int(ui_cfg.get("routing_min_speed_bps") or 0)
    except (TypeError, ValueError):
        speed = 0
    if speed >= 1_000_000_000:
        parts.append(f"≥{speed / 1_000_000_000:.0f} Gbps")
    elif speed > 0:
        parts.append(f"≥{speed / 1_000_000:.0f} Mbps")
    else:
        parts.append("≥50 Mbps")
    if str(ui_cfg.get("routing_mode") or "") == "favorites":
        parts.append("仅收藏")
    rules = routing_block_rules(ui_cfg)
    if rules:
        parts.append(f"屏蔽 {len(rules)} 条")
    return " · ".join(parts)


def _scheme_cache_key(ui_cfg: dict[str, Any]) -> str:
    favorites = ",".join(str(item) for item in (ui_cfg.get("favorite_node_ids") or []))
    return "|".join([
        str(ui_cfg.get("routing_mode") or ""),
        normalized_country_name(ui_cfg.get("force_country") or ""),
        str(ui_cfg.get("routing_ip_type") or ""),
        str(ui_cfg.get("routing_protocol") or ""),
        str(ui_cfg.get("routing_min_speed_bps") or 0),
        str(ui_cfg.get("routing_latency") or ""),
        str(ui_cfg.get("routing_blocklist") or ""),
        favorites,
    ])


def _compute_scheme_snapshot(ui_cfg: dict[str, Any]) -> dict[str, Any]:
    mode = str(ui_cfg.get("routing_mode") or "")
    country = "" if mode == "fixed_ip" else normalized_country_name(ui_cfg.get("force_country") or "")
    protocol = str(ui_cfg.get("routing_protocol") or "").strip().lower()
    loose = dict(ui_cfg)
    loose["routing_latency"] = ""
    loose["routing_min_speed_bps"] = 0
    try:
        rows = node_pool.list_routing_endpoints(limit=800, country=country, protocol=protocol)
        if country and not rows:
            rows = node_pool.list_routing_endpoints(limit=800, protocol=protocol)
    except Exception:
        rows = []
    inventory: set[str] = set()
    available: set[str] = set()
    for endpoint in rows:
        if not endpoint_matches_explicit_routing(endpoint, loose):
            continue
        if country and normalized_country_name(endpoint.get("country")) != country:
            continue
        ip = _endpoint_ip(endpoint) or str(endpoint.get("endpoint_id") or "")
        if not ip:
            continue
        inventory.add(ip)
        if endpoint_matches_explicit_routing(endpoint, ui_cfg):
            available.add(ip)
    return {
        "country": country,
        "available": len(available),
        "inventory": len(inventory),
        "label": _scheme_filter_label(ui_cfg),
        "capped": len(rows) >= 800,
    }


def invalidate_scheme_snapshot() -> None:
    global _scheme_snap_running
    with _scheme_snap_lock:
        _scheme_snap["at"] = 0.0
        _scheme_snap["key"] = ""
        _scheme_snap["value"] = None
        _scheme_snap_running = False


def scheme_match_snapshot(ui_cfg: dict[str, Any]) -> dict[str, Any]:
    """Cached scheme counts. The UI poll must not scan the pool itself."""
    global _scheme_snap_running
    key = _scheme_cache_key(ui_cfg)
    placeholder = {
        "country": "" if str(ui_cfg.get("routing_mode") or "") == "fixed_ip" else normalized_country_name(ui_cfg.get("force_country") or ""),
        "available": 0,
        "inventory": 0,
        "label": _scheme_filter_label(ui_cfg),
        "capped": False,
    }
    with _scheme_snap_lock:
        cached = _scheme_snap.get("value") if _scheme_snap.get("key") == key else None
        fresh = isinstance(cached, dict) and time.time() - float(_scheme_snap.get("at") or 0) < 20
        if fresh:
            return dict(cached)
        if _scheme_snap_running or is_connecting or manual_connection_active:
            return dict(cached) if isinstance(cached, dict) else placeholder
        _scheme_snap_running = True

    def _refresh() -> None:
        global _scheme_snap_running
        try:
            value = _compute_scheme_snapshot(ui_cfg)
            with _scheme_snap_lock:
                _scheme_snap["at"] = time.time()
                _scheme_snap["key"] = key
                _scheme_snap["value"] = value
        except Exception:
            pass
        finally:
            with _scheme_snap_lock:
                _scheme_snap_running = False

    threading.Thread(target=_refresh, daemon=True, name="scheme-snap").start()
    return dict(cached) if isinstance(cached, dict) else placeholder


def enter_explicit_scheme(immediate: bool = False) -> bool:
    """Move onto the saved scheme once a stable node satisfies it."""
    # A manual switch pins the exit. Availability sweeps must not replace it,
    # and a paused box is reserved for forwarding measurements.
    if background_paused() or manual_route_pin:
        return False
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)) or not _explicit_scheme_configured(ui_cfg):
        return False
    if ui_cfg.get("routing_mode") == "fixed_ip":
        return False
    if ui_command_plane.is_busy() or manual_connection_active:
        return False
    current = current_active_routing_endpoint()
    if current and endpoint_matches_explicit_routing(current, ui_cfg) and not endpoint_is_unstable(current):
        set_state(routing_degraded=False, last_check_message="当前出口符合新方案")
        return False
    if not immediate and active_tunnel_running() and bool(get_state().get("proxy_ok")) and _current_session_age() < 90:
        return False
    matching = [
        ep for ep in _stable_candidates(unified_hot_pool_candidates(ui_cfg, limit=30))
        if endpoint_matches_explicit_routing(ep, ui_cfg) and not endpoint_is_unstable(ep)
    ]
    if not matching:
        return False
    best = matching[0]
    if current and str(best.get("endpoint_id") or "") == str(current.get("endpoint_id") or ""):
        set_state(routing_degraded=False, last_check_message="当前出口符合新方案")
        return False
    connect_ranked_endpoint(best)
    set_state(routing_degraded=False, last_check_message="条件已满足，已进入新方案")
    log_to_json("INFO", "Routing", f"进入新方案 {best.get('protocol')} {best.get('country')} {best.get('endpoint_id')}")
    return True


def degrade_to_default_scheme() -> bool:
    """If the chosen country has no stable node, change country and keep the rest."""
    if background_paused() or manual_route_pin:
        return False
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)) or ui_cfg.get("routing_mode") == "fixed_ip":
        return False
    if ui_command_plane.is_busy() or manual_connection_active:
        return False
    current = current_active_routing_endpoint()
    if current and endpoint_matches_explicit_routing(current, ui_cfg) and not endpoint_is_unstable(current):
        set_state(routing_degraded=False, last_check_message="当前出口符合新方案")
        return False

    def pick(cfg: dict[str, Any]) -> dict[str, Any] | None:
        found = [
            ep for ep in _stable_candidates(unified_hot_pool_candidates(cfg, limit=40))
            if endpoint_matches_explicit_routing(ep, cfg) and not endpoint_is_unstable(ep)
        ]
        return found[0] if found else None

    home = server_home_country()
    best = pick(scheme_without_country(ui_cfg, home)) if home else None
    message = f"目标国家暂无节点，已退回{home}并保持其余筛选"
    if best is None:
        best = pick(scheme_without_country(ui_cfg, ""))
        message = "目标国家暂无节点，已更换国家并保持协议、带宽和 IP 类型"
    if best is None:
        set_state(routing_degraded=True, last_check_message="新方案暂无稳定节点，保持当前出口")
        return False
    if current and active_tunnel_running() and str(best.get("endpoint_id") or "") == str(current.get("endpoint_id") or ""):
        set_state(routing_degraded=True, last_check_message=message)
        return False
    connect_ranked_endpoint(best)
    set_state(routing_degraded=True, last_check_message=message)
    log_to_json("INFO", "Routing", f"{message} {best.get('protocol')} {best.get('country')} {best.get('endpoint_id')}")
    return True


def switch_to_explicit_routing_if_needed() -> bool:
    return enter_explicit_scheme(immediate=True)


def apply_user_routing_preferences() -> None:
    try:
        ui_cfg = load_ui_config()
        if not bool(ui_cfg.get("connection_enabled", True)):
            return
        if ui_cfg.get("routing_mode") == "fixed_ip":
            return
        if enter_explicit_scheme(immediate=True):
            return
        if degrade_to_default_scheme():
            return
        target_country = ""
        if str(ui_cfg.get("routing_mode") or "") == "fixed_region":
            target_country = str(ui_cfg.get("force_country") or "").strip()
        if target_country:
            set_state(routing_degraded=True, last_check_message=f"{target_country} 还没有稳定节点，已退回默认并继续补齐")
            start_country_priority(target_country)
            return
        if active_tunnel_running():
            set_state(routing_degraded=True, last_check_message="新方案暂无稳定节点，保持当前出口")
            return
        auto_switch_node()
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"应用用户路由偏好失败: {exc}")


def _scheme_candidates(ui_cfg: dict[str, Any], limit: int = 30) -> list[dict[str, Any]]:
    return [
        ep for ep in _stable_candidates(unified_hot_pool_candidates(ui_cfg, limit=limit))
        if endpoint_matches_explicit_routing(ep, ui_cfg) and not endpoint_is_unstable(ep)
    ]


def _smart_floor_configs(ui_cfg: dict[str, Any]) -> list[dict[str, Any]]:
    """Default guarantee when the saved scheme has nothing to connect.

    智能模式, keep 移动/住宅/机房 and latency, bandwidth at least 50 Mbps.
    Does not start a country sweep.
    """
    floor = dict(ui_cfg)
    floor["routing_mode"] = "auto"
    floor["force_country"] = ""
    floor["routing_min_speed_bps"] = ROUTING_MIN_LINE_SPEED_BPS
    configs = [floor]
    if str(floor.get("routing_ip_type") or "all").lower() not in ("", "all"):
        wider = dict(floor)
        wider["routing_ip_type"] = "all"
        configs.append(wider)
    if str(floor.get("routing_protocol") or "").strip() or str(floor.get("routing_latency") or "").strip():
        widest = dict(floor)
        widest["routing_ip_type"] = "all"
        widest["routing_protocol"] = ""
        widest["routing_latency"] = ""
        configs.append(widest)
    return configs


_scheme_apply_lock = threading.Lock()
_connect_fail_until: dict[str, float] = {}


def _note_connect_fail(endpoint: dict[str, Any]) -> None:
    ip = ""
    try:
        ip = _endpoint_ip(endpoint)
    except Exception:
        ip = str(endpoint.get("current_ip") or "")
    if ip:
        _connect_fail_until[ip] = time.time() + 180


def _connect_recently_failed(endpoint: dict[str, Any]) -> bool:
    try:
        ip = _endpoint_ip(endpoint)
    except Exception:
        ip = str(endpoint.get("current_ip") or "")
    return bool(ip) and time.time() < float(_connect_fail_until.get(ip) or 0)


def _ladder_home(ui_cfg: dict[str, Any]) -> str:
    """Manual country first, then the saved proxy country, then the server country."""
    pinned = normalized_country_name((manual_route_pin or {}).get("country") or "")
    if pinned:
        return pinned
    chosen = normalized_country_name((ui_cfg or {}).get("force_country") or "")
    if chosen:
        return chosen
    return server_home_country()


def _smart_ladder(ui_cfg: dict[str, Any]) -> list[dict[str, Any]]:
    """智能模式：本机或已选国家，移动、住宅、机房，延迟低的优先，带宽不低于 50 Mbps。

    这个国家没有可连节点时，按国家延迟从低到高继续。不启动批量检测。
    """
    home = _ladder_home(ui_cfg)
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for country in ([home] if home else []) + [""]:
        try:
            batch = node_pool.list_routing_endpoints(limit=800, country=country)
        except Exception:
            continue
        for endpoint in batch:
            eid = str(endpoint.get("endpoint_id") or "")
            if not eid or eid in seen:
                continue
            seen.add(eid)
            rows.append(endpoint)
    qualified: list[dict[str, Any]] = []
    identities: set[str] = set()
    country_latency: dict[str, int] = {}
    for endpoint in rows:
        protocol = str(endpoint.get("protocol") or "").lower()
        if protocol not in ("openvpn", "softether", "sstp", "l2tp-ipsec"):
            continue
        if str(endpoint.get("status") or "").upper() not in ("HOT", "AVAILABLE"):
            continue
        if endpoint_is_blocked(endpoint, ui_cfg) or endpoint_is_unstable(endpoint):
            continue
        if int(endpoint.get("fail_streak") or 0) >= 3:
            continue
        if _endpoint_speed_bps(endpoint) < ROUTING_MIN_LINE_SPEED_BPS:
            continue
        ip = _endpoint_ip(endpoint)
        if not ip:
            continue
        identity = f"{protocol}|{ip}|{int(endpoint.get('port') or 0)}"
        if identity in identities:
            continue
        identities.add(identity)
        qualified.append(endpoint)
        country = normalized_country_name(endpoint.get("country"))
        ip_type = str(endpoint_ip_type(endpoint) or "").lower()
        if country and ip_type in ("mobile", "residential"):
            latency = endpoint_display_latency_ms(endpoint) or 999999
            country_latency[country] = min(country_latency.get(country, 999999), latency)

    def tier(endpoint: dict[str, Any]) -> int:
        country = normalized_country_name(endpoint.get("country"))
        ip_type = str(endpoint_ip_type(endpoint) or "").lower()
        same = bool(home) and country == home
        if same and ip_type == "mobile":
            return 0
        if same and ip_type == "residential":
            return 1
        if same and ip_type == "hosting":
            return 2
        if ip_type == "mobile":
            return 3
        if ip_type == "residential":
            return 4
        if ip_type == "hosting":
            return 5
        return 6

    def sort_key(endpoint: dict[str, Any]) -> tuple:
        country = normalized_country_name(endpoint.get("country"))
        level = tier(endpoint)
        latency = endpoint_display_latency_ms(endpoint) or 999999
        country_rank = country_latency.get(country, 999999) if level >= 3 else 0
        return (level, country_rank, latency, -_endpoint_speed_bps(endpoint))

    qualified.sort(key=sort_key)
    return qualified


def apply_saved_scheme_now() -> None:
    """Put the saved proxy settings on the live exit and the cold standby now.

    Saving always tries to connect. There is no disconnect button, so an empty
    tunnel is not a valid result. A strict scheme with no candidate falls back
    to 智能模式 at ≥50 Mbps without a batch sweep and without rewriting the
    saved settings. A higher saved speed is kept while any such node exists.
    """
    if not _scheme_apply_lock.acquire(blocking=False):
        return
    try:
        invalidate_scheme_snapshot()
        ui_cfg = load_ui_config()
        if not bool(ui_cfg.get("connection_enabled", True)):
            return
        if str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
            return
        if manual_route_pin and active_tunnel_running():
            set_state(last_check_message="手动切换优先，保持当前主连接")
            _refresh_cold_standby_now()
            return
        current = current_active_routing_endpoint()
        if (
            current
            and active_tunnel_running()
            and endpoint_matches_explicit_routing(current, ui_cfg)
            and not endpoint_is_unstable(current)
        ):
            set_state(routing_degraded=False, last_check_message="当前出口符合代理设置")
            _refresh_cold_standby_now()
            return
        strict = [
            ep for ep in _scheme_candidates(ui_cfg)
            if not _connect_recently_failed(ep)
        ]
        ladder = [
            ep for ep in _smart_ladder(ui_cfg)
            if not _connect_recently_failed(ep)
        ]
        plans: list[tuple[list[dict[str, Any]], str, bool, int]] = []
        if strict:
            plans.append((strict, "已按代理设置连接", False, 2))
        plans.append((
            ladder,
            "当前方案连不上，已按智能模式连接：本机国家优先，移动/住宅/机房，≥50 Mbps，不够再换延迟更低的国家",
            True,
            6,
        ))
        last_error = ""
        seen_ips: set[str] = set()
        for matching, message, degraded, limit in plans:
            if not matching:
                continue
            replacing = active_tunnel_running()
            connected = False
            tried = 0
            for endpoint in matching:
                ip = _endpoint_ip(endpoint)
                if ip and ip in seen_ips:
                    continue
                if tried >= limit:
                    break
                tried += 1
                if ip:
                    seen_ips.add(ip)
                try:
                    connect_ranked_endpoint(endpoint, manual=replacing, fast=True)
                except Exception as exc:
                    last_error = str(exc)
                    _note_connect_fail(endpoint)
                    log_to_json(
                        "WARNING",
                        "Routing",
                        f"按代理设置连接失败 {endpoint.get('protocol')} {endpoint.get('endpoint_id')}: {exc}",
                    )
                    continue
                if not active_tunnel_running():
                    last_error = "连接后隧道未起来"
                    _note_connect_fail(endpoint)
                    continue
                clear_manual_route_pin()
                set_state(
                    routing_degraded=degraded,
                    last_check_message=message,
                    manual_switch_active=False,
                    manual_switch_message=message,
                    is_connecting=False,
                    manual_connection_active=False,
                    pending_connection_id="",
                    pending_connection_pool_endpoint_id="",
                    pending_connection_protocol="",
                    pending_connection_country="",
                    pending_connection_address="",
                )
                log_to_json(
                    "INFO",
                    "Routing",
                    f"{message} {endpoint.get('protocol')} {endpoint.get('country')} {endpoint.get('endpoint_id')}",
                )
                if _auto_direct_fallback_active():
                    _engage_proxy_egress(message)
                _refresh_cold_standby_now()
                connected = True
                break
            if connected:
                return
        set_state(
            routing_degraded=True,
            last_check_message="代理设置暂无可用节点，主连接继续等待",
            manual_switch_active=False,
            is_connecting=False,
            manual_connection_active=False,
            pending_connection_id="",
            pending_connection_pool_endpoint_id="",
        )
        log_to_json("INFO", "Routing", "代理设置暂无可用节点，主连接继续等待" + (f": {last_error}" if last_error else ""))
        _refresh_cold_standby_now()
    except Exception as exc:
        log_to_json("WARNING", "Routing", f"应用新代理设置失败，保持当前出口: {exc}")
        try:
            clear_manual_route_pin()
            set_state(
                routing_degraded=True,
                last_check_message="切换新代理设置失败，保持当前出口",
                manual_switch_active=False,
                is_connecting=False,
                manual_connection_active=False,
            )
            _refresh_cold_standby_now()
        except Exception:
            pass
    finally:
        _scheme_apply_lock.release()


def ensure_main_connection(reason: str, engage_proxy: bool = False, force: bool = False) -> None:
    """Health and the proxy switch use this. A missing main must be connected."""
    if active_tunnel_running():
        if engage_proxy and proxy_server.get_egress_mode() != "proxy":
            _engage_proxy_egress(reason)
        elif _auto_direct_fallback_active() and proxy_server.get_egress_mode() != "proxy":
            _engage_proxy_egress(reason)
        return
    now = time.time()
    if not force and now - float(getattr(ensure_main_connection, "at", 0) or 0) < 45:
        return
    if is_connecting or manual_connection_active or ui_command_plane.is_busy():
        return
    ensure_main_connection.at = now
    log_to_json("INFO", "Proxy", f"主连接未启动，开始连接: {reason}")
    apply_saved_scheme_now()
    if not active_tunnel_running():
        return
    if (engage_proxy or _auto_direct_fallback_active()) and proxy_server.get_egress_mode() != "proxy":
        _engage_proxy_egress(reason)


def _refresh_cold_standby_now() -> None:
    try:
        cold_standby_pass()
    except Exception as exc:
        log_to_json("WARNING", "Standby", f"新代理设置冷备刷新失败: {exc}")


def apply_routing_filters(
    nodes: list[dict[str, Any]],
    ui_cfg: dict[str, Any],
    include_unknown_ip_type: bool = False,
) -> list[dict[str, Any]]:
    # Automatic routing preferences are soft; availability always wins when
    # the preferred pool is empty.
    return list(nodes)

def normalized_country_name(country: Any) -> str:
    value = str(country or "").strip()
    return vpn_utils.COUNTRY_TRANSLATIONS.get(value, value)

load_manual_route_pin()

def country_matches(node_country: Any, target_country: Any) -> bool:
    return bool(target_country) and normalized_country_name(node_country) == normalized_country_name(target_country)

def probe_priority_key(node: dict[str, Any]) -> tuple[int, int, int, int]:
    ping = parse_int(node.get("ping")) or 999999
    return (
        ping,
        -parse_int(node.get("score")),
        -parse_int(node.get("speed")),
        parse_int(node.get("sessions")),
    )

def current_fixed_node_id(ui_cfg: dict[str, Any]) -> str:
    if active_openvpn_node_id:
        return active_openvpn_node_id
    nodes = read_nodes()
    active_node = next((n for n in nodes if n.get("active") and n.get("id")), None)
    if active_node:
        return str(active_node.get("id") or "")
    return str(ui_cfg.get("fixed_node_id") or "").strip()

def validate_node_allowed_by_routing(node: dict[str, Any], ui_cfg: dict[str, Any]) -> None:
    # Country/IP/favorite rules are automatic preferences, not hard blocks.
    # Only fixed-IP mode is restricted to its explicitly selected node by its caller.
    return None

def enforce_active_node_allowed_by_routing(ui_cfg: dict[str, Any], reason: str = "路由规则已更新") -> str | None:
    active_id = active_openvpn_node_id
    if not active_id:
        return None

    nodes = read_nodes()
    active_node = next((item for item in nodes if item.get("id") == active_id), None)
    if not active_node:
        clear_active_connection_state(f"{reason}，当前活动节点已不在节点列表中，已断开连接")
        return "当前活动节点已不在节点列表中，已断开连接"

    try:
        validate_node_allowed_by_routing(active_node, ui_cfg)
        return None
    except Exception as exc:
        msg = f"{reason}，当前活动节点 {active_id} 不符合新规则，已断开连接: {exc}"
        print(f"[路由规则] {msg}", flush=True)
        log_to_json("WARNING", "Routing", msg)
        stop_active_openvpn()
        with lock:
            nodes = read_nodes()
            for item in nodes:
                item["active"] = False
            write_json(NODES_FILE, nodes)
        set_state(
            active_openvpn_node_id="",
            active_node_latency="无活动连接",
            proxy_ok=False,
            proxy_ip="-",
            proxy_latency_ms=0,
            proxy_error=msg,
            last_check_message=msg,
        )

        if ui_cfg.get("connection_enabled", True) and ui_cfg.get("routing_mode") != "fixed_ip":
            threading.Thread(target=auto_switch_node, daemon=True).start()
        return msg

def reconnect_fixed_node_if_needed(ui_cfg: dict[str, Any]) -> bool:
    global is_connecting
    if ui_cfg.get("routing_mode") != "fixed_ip" or active_openvpn_running():
        return False
    target_id = current_fixed_node_id(ui_cfg)
    if not target_id:
        return False
    nodes = read_nodes()
    if not any(n.get("id") == target_id for n in nodes):
        return False

    print(f"[维护线程] 固定 IP 模式下 OpenVPN 未运行，正在重新拉起同一节点: {target_id}", flush=True)
    previous_connecting = is_connecting
    is_connecting = False
    try:
        connect_node(target_id)
        return active_openvpn_running()
    except Exception as e:
        print(f"[维护线程] 重新拉起固定节点 {target_id} 失败: {e}", flush=True)
        return False
    finally:
        is_connecting = previous_connecting

active_test_indexes = set()
test_indexes_lock = threading.Lock()

def get_free_test_index() -> int:
    with test_indexes_lock:
        for idx in range(2, 100):
            if idx not in active_test_indexes:
                active_test_indexes.add(idx)
                return idx
        raise RuntimeError("没有可用的 OpenVPN 测试网卡编号，请稍后重试")

def release_test_index(idx: int) -> None:
    with test_indexes_lock:
        active_test_indexes.discard(idx)

def test_config_path(node_id: str) -> Path:
    safe_id = safe_name(node_id)
    return CONFIG_DIR / f".test_{safe_id}_{uuid.uuid4().hex}.ovpn"


def country_priority_snapshot(country: str) -> dict[str, Any]:
    global country_priority_snapshot_cache
    target_country = str(country or "").strip()
    cache_key = normalized_country_name(target_country)
    cached = country_priority_snapshot_cache.get(cache_key)
    if cached and time.time() - cached[0] < 10:
        return dict(cached[1])
    if not target_country:
        return {"country": "", "available": 0, "target": COUNTRY_AVAILABLE_TARGET, "minimum": COUNTRY_AVAILABLE_MIN}
    inventory_ips: set[str] = set()
    available_ips: set[str] = set()
    available_servers: set[str] = set()
    candidate_refs: list[dict[str, Any]] = []
    openvpn_nodes = read_nodes()
    for node in openvpn_nodes:
        if not country_matches(node.get("country"), target_country):
            continue
        status = str(node.get("probe_status") or "not_checked").lower()
        key = node_pool.server_key(node)
        ip = str(node.get("ip") or node.get("remote_host") or "").strip()
        if ip: inventory_ips.add(ip)
        if status == "available":
            if ip: available_ips.add(ip)
            available_servers.add(key)
        elif status in ("not_checked", "unavailable"):
            candidate_refs.append({
                "kind": "openvpn",
                "id": str(node.get("id") or ""),
                "server_key": key,
                "status": status,
                "probed_at": float(node.get("probed_at") or 0),
                "latency_ms": parse_int(node.get("latency_ms")),
                "ip_type": str(node.get("ip_type") or "").lower(),
                "speed": parse_int(node.get("speed")),
            })
    try:
        endpoints = node_pool.list_endpoints(limit=5000)
    except Exception:
        endpoints = []
    for endpoint in endpoints:
        if str(endpoint.get("protocol") or "").lower() == "openvpn":
            continue
        if not country_matches(endpoint.get("country"), target_country):
            continue
        status = str(endpoint.get("status") or "NEW").upper()
        key = str(endpoint.get("server_key") or "")
        ip = str(endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "").strip()
        if ip: inventory_ips.add(ip)
        if status in ("HOT", "AVAILABLE"):
            if ip: available_ips.add(ip)
            available_servers.add(key)
        elif status in ("NEW", "DEGRADED", "COOLDOWN"):
            meta = endpoint.get("server_metadata") or {}
            candidate_refs.append({
                "kind": "pool",
                "id": "pool:" + str(endpoint.get("endpoint_id") or ""),
                "server_key": key,
                "status": status.lower(),
                "probed_at": float(endpoint.get("last_success") or endpoint.get("last_failure") or 0),
                "ready_at": float(endpoint.get("next_test") or 0),
                "latency_ms": parse_int(endpoint.get("latency_ewma")),
                "ip_type": str(meta.get("ip_type") or "").lower(),
                "speed": parse_int(endpoint.get("latest_speed") or 0),
            })
    priority = {"not_checked": 0, "new": 0, "unavailable": 1, "degraded": 2, "cooldown": 3}
    now = time.time()
    candidate_refs = [
        x for x in candidate_refs
        if str(x.get("status")) in ("not_checked", "new")
        or (float(x.get("ready_at") or 0) <= now and now - float(x.get("probed_at") or 0) >= 900)
    ]
    def _priority_quality(ref):
        ip_type = str(ref.get("ip_type") or "").lower()
        speed = int(ref.get("speed") or 0)
        if ip_type in ("mobile", "residential") and speed >= ROUTING_MIN_LINE_SPEED_BPS:
            return 0
        if ip_type in ("mobile", "residential"):
            return 1
        if ip_type == "hosting":
            return 2
        return 3

    candidate_refs.sort(key=lambda x: (
        priority.get(str(x.get("status")), 4),
        _priority_quality(x),
        x.get("server_key") in available_servers,
        -(int(x.get("speed") or 0)),
        x.get("latency_ms") or 999999,
        x.get("probed_at") or 0,
    ))
    result = {"country": target_country, "inventory": len(inventory_ips), "available": len(available_ips), "available_servers": len(available_servers), "target": COUNTRY_AVAILABLE_TARGET, "minimum": COUNTRY_AVAILABLE_MIN, "inventory_target": COUNTRY_INVENTORY_TARGET, "candidates": candidate_refs}
    country_priority_snapshot_cache[cache_key] = (time.time(), result)
    return dict(result)

def _test_pool_reference(ref: dict[str, Any]) -> dict[str, Any]:
    kind = str(ref.get("kind") or "")
    ident = str(ref.get("id") or "")
    if kind == "openvpn":
        rows = test_multiple_nodes([ident])
        node = rows[0] if rows else {"id": ident, "probe_status": "unavailable", "probe_message": "节点不存在"}
        return {"ok": str(node.get("probe_status") or "") == "available", "kind": kind, "node": node}
    if kind == "pool":
        endpoint_id = ident.removeprefix("pool:")
        endpoint = node_pool.get_endpoint(endpoint_id)
        if endpoint is None:
            return {"ok": False, "kind": kind, "error": "端点不存在"}
        result = light_probe_endpoint_id(endpoint_id)
        endpoint = node_pool.get_endpoint(endpoint_id)
        node = protocol_endpoint_to_ui_node(endpoint) if endpoint else {}
        if isinstance(node, dict):
            if result.get("inconclusive"):
                node["probe_status"] = "not_checked"
            else:
                node["probe_status"] = "available" if result.get("ok") else "unavailable"
            node["probe_message"] = str(result.get("message") or "")
            node["latency_ms"] = int(result.get("latency_ms") or 0)
        return {
            "ok": bool(result.get("ok")) and not result.get("inconclusive"),
            "inconclusive": bool(result.get("inconclusive")),
            "kind": kind,
            "node": node,
            "result": result,
        }
    return {"ok": False, "error": "未知测试类型"}

def country_full_sweep(country: str) -> dict[str, Any]:
    global probe_engine_running, probe_engine_message, probe_engine_target_country
    """Run one complete resource-pool sweep for the selected/local country.

    Every non-retired protocol endpoint is tested once before global country
    rotation resumes. This prevents NEW/unverified mobile/residential/high-speed
    resources from being omitted from the usable pool.
    """
    global country_full_sweep_running, country_full_sweep_total
    global country_full_sweep_tested, country_full_sweep_remaining
    global country_full_sweep_country, country_full_sweep_message

    target = normalized_country_name(str(country or "").strip())
    if not target:
        return {"ok": False, "error": "国家不能为空"}

    persisted_sweeps = read_json(STATE_FILE, {}).get("country_full_sweep_completed_at", {})
    if isinstance(persisted_sweeps, dict) and target not in country_full_sweep_completed_at:
        try:
            country_full_sweep_completed_at[target] = float(persisted_sweeps.get(target) or 0)
        except Exception:
            pass
    completed_at = float(country_full_sweep_completed_at.get(target, 0) or 0)
    if completed_at and time.time() - completed_at < COUNTRY_FULL_SWEEP_REUSE_SECONDS:
        return {
            "ok": True,
            "skipped": True,
            "country": target,
            "reason": "recently_completed",
            "completed_at": completed_at,
        }

    with country_full_sweep_lock:
        completed_at = float(country_full_sweep_completed_at.get(target, 0) or 0)
        if completed_at and time.time() - completed_at < COUNTRY_FULL_SWEEP_REUSE_SECONDS:
            return {"ok": True, "skipped": True, "country": target, "reason": "recently_completed"}

        endpoint_rows = node_pool.list_endpoint_ids(country=target)
        refs = []
        seen = set()
        for endpoint in endpoint_rows:
            eid = str(endpoint.get("endpoint_id") or "").strip()
            if (
                not eid
                or eid in seen
                or str(endpoint.get("status") or "").upper() == "RETIRED"
                or (active_tunnel_running() and eid == str(active_pool_endpoint_id or ""))
            ):
                continue
            seen.add(eid)
            refs.append({
                "kind": "pool",
                "id": "pool:" + eid,
                "protocol": str(endpoint.get("protocol") or "").lower(),
                "server_key": str(endpoint.get("server_key") or ""),
            })

        country_full_sweep_running = True
        probe_engine_running = True
        probe_engine_target_country = target
        country_full_sweep_total = len(refs)
        country_full_sweep_tested = 0
        country_full_sweep_remaining = len(refs)
        country_full_sweep_country = target
        country_full_sweep_message = f"{target} 资源库全量首次检测：准备检测 {len(refs)} 个协议端点"
        set_state(
            priority_country=target,
            priority_running=True,
            priority_full_sweep_running=True,
            priority_full_sweep_total=len(refs),
            priority_full_sweep_tested=0,
            priority_full_sweep_remaining=len(refs),
            priority_full_sweep_country=target,
            priority_message=country_full_sweep_message,
        )

        cursor = 0
        while cursor < len(refs):
            if background_paused():
                country_full_sweep_running = False
                probe_engine_running = False
                set_state(
                    priority_running=False,
                    priority_full_sweep_running=False,
                    priority_message="后台检测已暂停，转发优先",
                )
                return {"ok": True, "paused": True, "country": target, "tested": cursor, "total": len(refs)}
            pause_reason = _nano_library_pause_reason()
            if pause_reason:
                country_full_sweep_running = False
                probe_engine_running = False
                set_state(
                    priority_running=False,
                    priority_full_sweep_running=False,
                    priority_message=pause_reason,
                )
                log_to_json("INFO", "Probe", f"{target} 全量检测让路：{pause_reason}")
                return {"ok": True, "paused": True, "country": target, "tested": cursor, "total": len(refs)}
            # A live tunnel, an open page, or a catalog refresh owns the small
            # VM. Wait here instead of opening another tunnel on top of them.
            while (
                manual_connection_active
                or ui_command_plane.is_busy()
                or proxy_server.proxy_forwarding_busy(20)
                or ui_query_active()
                or global_pool_refresh_running
            ):
                time.sleep(0.4)
            batch_size = 1 if active_tunnel_running() else COUNTRY_FULL_SWEEP_BATCH
            batch = refs[cursor:cursor + batch_size]
            cursor += len(batch)
            openvpn_ids = []
            pool_refs = []
            for ref in batch:
                endpoint = node_pool.get_endpoint(ref["id"].removeprefix("pool:"))
                if not endpoint:
                    continue
                protocol = str(endpoint.get("protocol") or "").lower()
                if protocol == "openvpn":
                    try:
                        openvpn_ids.append(ensure_openvpn_node_from_pool(endpoint))
                    except Exception as exc:
                        log_to_json("WARNING", "Probe", f"{target} 全量检测 OpenVPN 端点准备失败: {exc}")
                else:
                    pool_refs.append(ref)

            if openvpn_ids:
                # Serialize probe batches with other maintenance work, but do
                # NOT mutate production is_connecting state.
                maintenance_lock.acquire()
                try:
                    if manual_connection_active:
                        continue
                    test_multiple_nodes(openvpn_ids)
                finally:
                    maintenance_lock.release()

            if pool_refs:
                workers = 1 if active_tunnel_running() else COUNTRY_FULL_SWEEP_IDLE_CONCURRENCY
                workers = max(1, min(workers, len(pool_refs)))
                with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
                    list(executor.map(_test_pool_reference, pool_refs))

            if active_tunnel_running():
                time.sleep(1.5)

            country_full_sweep_tested = min(len(refs), cursor)
            country_full_sweep_remaining = max(0, len(refs) - cursor)
            country_full_sweep_message = f"{target} 资源库全量检测中：已检测 {country_full_sweep_tested}/{len(refs)}，剩余 {country_full_sweep_remaining}"
            probe_engine_message = country_full_sweep_message
            try:
                snap = country_priority_snapshot(target)
                set_state(
                    priority_inventory=int(snap.get("inventory") or 0),
                    priority_available=int(snap.get("available") or 0),
                    priority_full_sweep_running=True,
                    priority_full_sweep_total=len(refs),
                    priority_full_sweep_tested=country_full_sweep_tested,
                    priority_full_sweep_remaining=country_full_sweep_remaining,
                    priority_full_sweep_country=target,
                    priority_message=country_full_sweep_message,
                )
            except Exception:
                pass

        country_full_sweep_completed_at[target] = time.time()
        country_priority_snapshot_cache.pop(normalized_country_name(target), None)
        country_full_sweep_running = False
        persisted_sweeps = read_json(STATE_FILE, {}).get("country_full_sweep_completed_at", {})
        if not isinstance(persisted_sweeps, dict):
            persisted_sweeps = {}
        persisted_sweeps[target] = country_full_sweep_completed_at[target]
        set_state(country_full_sweep_completed_at=persisted_sweeps)
        country_full_sweep_message = f"{target} 资源库全量检测完成：共检测 {len(refs)} 个协议端点"
        try:
            snap = country_priority_snapshot(target)
            set_state(
                priority_inventory=int(snap.get("inventory") or 0),
                priority_available=int(snap.get("available") or 0),
                priority_running=False,
                priority_full_sweep_running=False,
                priority_full_sweep_total=len(refs),
                priority_full_sweep_tested=len(refs),
                priority_full_sweep_remaining=0,
                priority_full_sweep_country=target,
                priority_message=country_full_sweep_message,
            )
        except Exception:
            set_state(
                priority_running=False,
                priority_full_sweep_running=False,
                priority_full_sweep_total=len(refs),
                priority_full_sweep_tested=len(refs),
                priority_full_sweep_remaining=0,
                priority_full_sweep_country=target,
                priority_message=country_full_sweep_message,
            )
        return {"ok": True, "country": target, "total": len(refs), "tested": len(refs)}

def country_priority_worker(country: str) -> None:
    global country_priority_request
    if background_paused():
        country_priority_request = ""
        return
    try:
        # First pass is always a complete resource-pool sweep for the target
        # country. Only after every endpoint has been checked once do we let
        # the normal global-country scheduler resume.
        sweep_result = country_full_sweep(country)
        if sweep_result.get("ok"):
            return
        rounds = 0
        while rounds < 12:
            if manual_connection_active:
                time.sleep(2)
                continue
            rounds += 1
            snapshot = country_priority_snapshot(country)
            available = int(snapshot.get("available") or 0)
            inventory = int(snapshot.get("inventory") or 0)
            if rounds == 1 and inventory < COUNTRY_INVENTORY_TARGET:
                now = time.time()
                last_discovery = float(country_priority_last_discovery.get(country, 0) or 0)
                if now - last_discovery >= 600:
                    country_priority_last_discovery[country] = now
                    set_state(priority_country=country, priority_available=available, priority_inventory=inventory, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=True, priority_message=f"{country} 资源不足 {COUNTRY_INVENTORY_TARGET} IP，正在优先从主站和全部镜像补充资源")
                    try:
                        fetch_candidates()
                    except Exception as exc:
                        log_to_json("WARNING", "Main", f"{country} 优先补充 OpenVPN 资源失败: {exc}")
                    try:
                        refresh_multi_protocol_catalog(force=True)
                    except Exception as exc:
                        log_to_json("WARNING", "Main", f"{country} 优先补充多协议资源失败: {exc}")
                    snapshot = country_priority_snapshot(country)
                    available = int(snapshot.get("available") or 0)
                    inventory = int(snapshot.get("inventory") or 0)
            if available >= COUNTRY_AVAILABLE_TARGET:
                set_state(priority_country=country, priority_inventory=inventory, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=available, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=False, priority_message=f"{country} 已达到 {available} 个可用节点")
                return
            candidates = snapshot.get("candidates") or []
            if not candidates:
                set_state(priority_country=country, priority_inventory=inventory, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=available, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=False, priority_message=f"{country} 当前可检测候选不足，已得到 {available} 个可用节点")
                return
            batch: list[dict[str, Any]] = []
            seen_servers: set[str] = set()
            for ref in candidates:
                key = str(ref.get("server_key") or "")
                if key and key in seen_servers:
                    continue
                batch.append(ref)
                if key: seen_servers.add(key)
                if len(batch) >= COUNTRY_PRIORITY_BATCH:
                    break
            openvpn_refs = [x for x in batch if x.get("kind") == "openvpn"]
            pool_refs = [x for x in batch if x.get("kind") == "pool"]
            if openvpn_refs and maintenance_lock.acquire(blocking=False):
                try:
                    if not manual_connection_active:
                        set_state(last_check_message=f"正在优先检测 {country}，目标 {COUNTRY_AVAILABLE_MIN}-{COUNTRY_AVAILABLE_TARGET} 个可用节点")
                        test_multiple_nodes([str(x.get("id")) for x in openvpn_refs if x.get("id")])
                finally:
                    maintenance_lock.release()
            for ref in pool_refs:
                if manual_connection_active or ui_command_plane.is_busy():
                    break
                _test_pool_reference(ref)
            snapshot = country_priority_snapshot(country)
            available = int(snapshot.get("available") or 0)
            inventory = int(snapshot.get("inventory") or 0)
            set_state(priority_country=country, priority_inventory=inventory, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=available, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=True, priority_message=f"{country} 优先检测中：库存 {inventory}/{COUNTRY_INVENTORY_TARGET} IP，可用 {available}/{COUNTRY_AVAILABLE_TARGET}")
            if available >= COUNTRY_AVAILABLE_MIN and not (snapshot.get("candidates") or []):
                break
            if country_priority_request and country_priority_request != country:
                break
            time.sleep(1)
        final = country_priority_snapshot(country)
        available = int(final.get("available") or 0)
        inventory = int(final.get("inventory") or 0)
        set_state(priority_country=country, priority_inventory=inventory, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=available, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=False, priority_message=f"{country} 优先检测完成：库存 {inventory} IP，可用 {available} 个节点")
    except Exception as exc:
        set_state(priority_country=country, priority_inventory=0, priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=0, priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=False, priority_message=f"{country} 优先检测异常：{exc}")
    finally:
        pending = country_priority_request if country_priority_request and country_priority_request != country else ""
        country_priority_request = ""
        if country_priority_lock.locked():
            country_priority_lock.release()
        try:
            if not manual_connection_active and not background_paused() and not manual_route_pin:
                switch_to_explicit_routing_if_needed()
        except Exception as exc:
            log_to_json("WARNING", "Routing", f"优先国家检测结束后切换失败: {exc}")
        if pending:
            start_country_priority(pending)

def start_country_priority(country: str) -> dict[str, Any]:
    global country_priority_request
    target = str(country or "").strip()
    if not target:
        return {"ok": False, "error": "国家不能为空"}
    cache_key = normalized_country_name(target)
    cached = country_priority_snapshot_cache.get(cache_key)
    snapshot = dict(cached[1]) if cached and time.time() - cached[0] < 10 else {}
    country_priority_request = target
    recent_full_sweep = bool(
        country_full_sweep_completed_at.get(target)
        and time.time() - float(country_full_sweep_completed_at.get(target) or 0) < COUNTRY_FULL_SWEEP_REUSE_SECONDS
    )
    if recent_full_sweep:
        country_priority_request = ""
        set_state(
            priority_country=target,
            priority_inventory=int(snapshot.get("inventory") or 0),
            priority_inventory_target=COUNTRY_INVENTORY_TARGET,
            priority_available=int(snapshot.get("available") or 0),
            priority_target=COUNTRY_AVAILABLE_TARGET,
            priority_minimum=COUNTRY_AVAILABLE_MIN,
            priority_running=False,
            priority_full_sweep_running=False,
            priority_message=f"{target} 已完成近期资源库全量检测，当前可用 {snapshot.get('available', 0)} 个节点"
        )
        return {"ok": True, "running": False, "available": snapshot.get("available"), "target": COUNTRY_AVAILABLE_TARGET, "full_sweep_recent": True}
    if not country_priority_lock.acquire(blocking=False):
        return {"ok": True, "running": True, "available": snapshot.get("available"), "target": COUNTRY_AVAILABLE_TARGET, "message": "已有国家优先检测任务运行中"}
    set_state(priority_country=target, priority_inventory=int(snapshot.get("inventory") or 0), priority_inventory_target=COUNTRY_INVENTORY_TARGET, priority_available=int(snapshot.get("available") or 0), priority_target=COUNTRY_AVAILABLE_TARGET, priority_minimum=COUNTRY_AVAILABLE_MIN, priority_running=True, priority_message=f"{target} 优先检测已启动：目标 {COUNTRY_AVAILABLE_MIN}-{COUNTRY_AVAILABLE_TARGET} 个可用节点")
    threading.Thread(target=country_priority_worker, args=(target,), daemon=True).start()
    return {"ok": True, "running": True, "available": snapshot.get("available"), "target": COUNTRY_AVAILABLE_TARGET}

def test_node_by_id(node_id: str) -> dict[str, Any]:
    with lock:
        nodes = read_nodes()
        node = next((item for item in nodes if item.get("id") == node_id), None)
        if not node:
            raise ValueError(f"Node not found: {node_id}")
        config_text = node.get("config_text") or ""
        h = str(node.get("remote_host") or node.get("ip"))
        p = parse_int(node.get("remote_port"))
        fallback_ping = parse_int(node.get("ping"))

    temp_path = test_config_path(node_id)
    try:
        CONFIG_DIR.mkdir(exist_ok=True, parents=True)
        config_text = _prefer_openvpn_ip(config_text, node)
        temp_path.write_text(config_text, encoding="utf-8")
    except Exception as e:
        raise RuntimeError(f"Failed to write temp config file: {e}")

    # Latency is the real handshake, not a port probe and not a download.
    latency = 0
    openvpn_process: subprocess.Popen[str] | None = None
    ok = False
    message = "OpenVPN did not complete initialization."
    yielded = False

    idx = None
    try:
        idx = get_free_test_index()
        latency_box: list[int] = []
        ok, message, openvpn_process = run_openvpn_until_ready(
            str(temp_path), keep_alive=True, route_nopull=True, timeout=12, dev=f"tun{idx}",
            latency_out=latency_box,
        )
        yielded = "让路" in str(message or "")
        if ok and not yielded:
            health = check_interface_egress(f"tun{idx}")
            if not health.get("ok"):
                ok = False
                latency = 0
                message = "OpenVPN 已握手，但隧道出不了网"
            else:
                latency = int(health.get("latency_ms") or 0)
    finally:
        if openvpn_process is not None:
            stop_process(openvpn_process)
        if idx is not None:
            release_test_index(idx)
        try:
            if temp_path.exists():
                temp_path.unlink()
        except Exception:
            pass

    if yielded:
        with lock:
            nodes = read_nodes()
            node = next((item for item in nodes if item.get("id") == node_id), None)
            if node:
                node["probe_message"] = message
                return node
            return {"id": node_id, "probe_message": message, "probe_status": "not_checked"}

    with lock:
        nodes = read_nodes()
        node = next((item for item in nodes if item.get("id") == node_id), None)
        if node:
            node["latency_ms"] = latency if ok else 0
            node["probe_status"] = "available" if ok else "unavailable"
            node["probe_message"] = message
            node["probed_at"] = time.time()
            try:
                node_pool.record_probe(
                    node, ok=ok, latency_ms=latency, message=message, speed_bps=None
                )
            except Exception as pool_exc:
                log_to_json("WARNING", "Main", f"NodePool 单节点探测结果写入失败: {pool_exc}")
            sorted_nodes = sort_all_nodes(nodes)
            write_json(NODES_FILE, sorted_nodes)
            res = next((item for item in sorted_nodes if item.get("id") == node_id), node)
            return res
        else:
            return {}

def test_multiple_nodes(node_ids: list[str]) -> list[dict[str, Any]]:
    # Serve the probe from the in-memory OpenVPN cache. Rewriting nodes.json
    # here used to freeze every filter request for the whole dump.
    wanted = {str(node_id) for node_id in (node_ids or []) if str(node_id or "")}
    index = _nodes_index_get()
    to_test = [dict(index[nid]) for nid in wanted if nid in index]

    def test_worker(args: tuple[int, dict[str, Any]]) -> dict[str, Any]:
        idx, n_info = args
        node_id = n_info["id"]
        h = str(n_info.get("remote_host") or n_info.get("ip"))
        p = parse_int(n_info.get("remote_port"))
        probed = light_probe_endpoint({
            "protocol": "openvpn",
            "transport": n_info.get("proto") or n_info.get("transport") or "tcp",
            "port": p,
            "current_ip": n_info.get("ip") or h,
            "hostname": h,
            "config_text": n_info.get("config_text") or "",
            "config_file": n_info.get("config_file") or "",
            "id": node_id,
        })
        if probed.get("inconclusive"):
            return {
                "id": node_id,
                "skipped": True,
                "probe_status": "not_checked",
                "probe_message": str(probed.get("message") or ""),
            }
        ok = bool(probed.get("ok"))
        latency = int(probed.get("latency_ms") or 0)
        message = str(probed.get("message") or "")
        temp_node = {
            "id": node_id,
            "ip": n_info.get("ip") or h,
            "remote_host": h,
            "remote_port": p,
            "latency_ms": latency,
            "speed": parse_int(n_info.get("speed") or n_info.get("speed_bps")),
            "speed_bps": parse_int(n_info.get("speed_bps") or n_info.get("speed")),
            "probe_status": "available" if ok else "unavailable",
            "probe_message": message,
            "probed_at": time.time(),
            "record_speed_bps": None,
            "owner": "",
            "asn": "",
            "as_name": "",
            "location": "",
            "ip_type": "",
            "quality": "",
        }
        return temp_node

    updated_nodes_map = {}
    # Protect the production proxy path from CPU/TUN contention while still
    # refreshing the full candidate pool in the background.
    probe_worker_limit = 8
    max_workers = min(probe_worker_limit, max(1, len(to_test)))
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = {executor.submit(test_worker, (idx, n)): n["id"] for idx, n in enumerate(to_test)}
        for future in concurrent.futures.as_completed(futures):
            if manual_connection_active or ui_query_active():
                for pending in futures:
                    pending.cancel()
                break
            nid = futures[future]
            try:
                res = future.result()
                if res.get("skipped"):
                    continue
                updated_nodes_map[nid] = res
                try:
                    original_node = next((item for item in to_test if item.get("id") == nid), None)
                    if original_node:
                        recorded_speed = res.get("record_speed_bps") if "record_speed_bps" in res else parse_int(res.get("speed_bps"))
                        if recorded_speed is not None:
                            recorded_speed = parse_int(recorded_speed)
                        node_pool.record_probe(
                            original_node,
                            ok=res.get("probe_status") == "available",
                            latency_ms=parse_int(res.get("latency_ms")),
                            message=str(res.get("probe_message") or ""),
                            speed_bps=recorded_speed,
                        )
                except Exception as pool_exc:
                    log_to_json("WARNING", "Main", f"NodePool 批量探测结果写入失败: {pool_exc}")
            except Exception as e:
                updated_nodes_map[nid] = {
                    "id": nid,
                    "probe_status": "unavailable",
                    "probe_message": f"Test exception: {e}",
                    "latency_ms": 0
                }
                try:
                    original_node = next((item for item in to_test if item.get("id") == nid), None)
                    if original_node:
                        node_pool.record_probe(original_node, False, 0, f"Test exception: {e}", speed_bps=None)
                except Exception as pool_exc:
                    log_to_json("WARNING", "Main", f"NodePool 异常探测结果写入失败: {pool_exc}")

    if updated_nodes_map:
        schedule_nodes_probe_flush(updated_nodes_map)

    return list(updated_nodes_map.values())

def probe_listed_node(node_id: str) -> dict[str, Any]:
    """Manual 待检测. Same path as cold standby: dial the node, then webpage HTTP status."""
    node_id = str(node_id or "").strip()
    if not node_id:
        return {"ok": False, "error": "节点 ID 不能为空"}
    if node_id.startswith("pool:"):
        endpoint_id = node_id.removeprefix("pool:")
        endpoint = node_pool.get_endpoint(endpoint_id)
        if endpoint is None:
            return {"ok": False, "error": "端点不存在"}
        protocol = str(endpoint.get("protocol") or "").lower()
        if protocol == "openvpn":
            real_id = ensure_openvpn_node_from_pool(endpoint)
            node = test_node_by_id(real_id)
            message = str(node.get("probe_message") or "")
            if "让路" in message:
                return {
                    "ok": False,
                    "skipped": True,
                    "error": message,
                    "node": {"id": node_id, "probe_status": "not_checked", "probe_message": message},
                }
            ok = str(node.get("probe_status") or "") == "available"
            try:
                node_pool.record_endpoint_probe(
                    endpoint_id, ok, int(node.get("latency_ms") or 0), message, speed_bps=None
                )
            except Exception as exc:
                log_to_json("WARNING", "Probe", f"待检测结果写入失败: {exc}")
            fresh = node_pool.get_endpoint(endpoint_id)
            ui = protocol_endpoint_to_ui_node(fresh) if fresh else {}
            if isinstance(ui, dict):
                ui["id"] = node_id
                ui["probe_status"] = "available" if ok else "unavailable"
                ui["probe_message"] = message
                ui["latency_ms"] = int(node.get("latency_ms") or 0)
            return {"ok": ok, "node": ui or {"id": node_id, "probe_status": "available" if ok else "unavailable", "probe_message": message}}
        result = probe_pool_endpoint(endpoint_id)
        if result.get("skipped"):
            message = str(result.get("error") or "检测让路")
            return {
                "ok": False,
                "skipped": True,
                "error": message,
                "node": {"id": node_id, "probe_status": "not_checked", "probe_message": message},
            }
        ok = bool(result.get("ok"))
        message = str(result.get("message") or result.get("error") or "")
        fresh = node_pool.get_endpoint(endpoint_id)
        ui = protocol_endpoint_to_ui_node(fresh) if fresh else {}
        if isinstance(ui, dict):
            ui["id"] = node_id
            ui["probe_status"] = "available" if ok else "unavailable"
            ui["probe_message"] = message
            ui["latency_ms"] = int(result.get("latency_ms") or 0)
        return {"ok": ok, "node": ui, "result": result}
    node = test_node_by_id(node_id)
    message = str(node.get("probe_message") or "")
    if "让路" in message:
        return {"ok": False, "skipped": True, "error": message, "node": node}
    return {"ok": str(node.get("probe_status") or "") == "available", "node": node}


def auto_switch_node(attempt: int = 0) -> None:
    if ui_command_plane.is_busy():
        log_to_json("INFO", "VPN", "前端人工指令进行中，自动切换暂缓")
        return
    if manual_connection_active:
        log_to_json("INFO", "VPN", "用户正在手动操作，自动切换暂缓")
        return
    if attempt >= 3:
        print("[自动切换] 连续切换失败已达 3 次，备用节点不可用，切换直连模式。", flush=True)
        _fallback_direct_egress("连续切换失败已达 3 次")
        return
    if proxy_server.get_egress_mode() == "direct" and bool(read_json(STATE_FILE, {}).get("auto_direct_fallback")):
        return
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)):
        print("[自动切换] 连接已禁用，不进行自动切换。", flush=True)
        return
    routing_mode = ui_cfg.get("routing_mode", "auto")
    target_country = str(ui_cfg.get("force_country") or "").strip()
    if routing_mode == "fixed_ip":
        return
    if attempt == 0 and not active_tunnel_running() and proxy_server.get_egress_mode() == "proxy":
        outcome = promote_cold_standby_to_main()
        if outcome in ("up", "direct", "busy"):
            return

    if attempt == 0:
        auto_switch_node.failed_ids = set()
    failed_ids = getattr(auto_switch_node, "failed_ids", set())
    current = current_active_routing_endpoint()
    exclude_endpoint_id = str(current.get("endpoint_id") or "") if current else ""
    if exclude_endpoint_id:
        failed_ids.add(exclude_endpoint_id)
    candidates = [
        ep for ep in unified_hot_pool_candidates(ui_cfg, exclude_endpoint_id=exclude_endpoint_id, limit=30)
        if str(ep.get("endpoint_id") or "") not in failed_ids
    ]
    if candidates:
        preferred = candidates[0]
        msg = (
            f"当前连接失效，正在按偏好层级选择备用节点: "
            f"tier={preferred.get('routing_tier')} {preferred.get('protocol')} {preferred.get('endpoint_id')}"
        )
        print(f"[自动切换] {msg}", flush=True)
        log_to_json("INFO", "VPN", msg)
        for endpoint in candidates[:max(1, min(5, len(candidates)))]:
            eid = str(endpoint.get("endpoint_id") or "")
            if eid:
                failed_ids.add(eid)
            try:
                connect_ranked_endpoint(endpoint)
                auto_switch_node.failed_ids = set()
                if bool(read_json(STATE_FILE, {}).get("auto_direct_fallback")):
                    _engage_proxy_egress("备用节点已接上，切回代理模式")
                return
            except Exception as exc:
                log_to_json("WARNING", "VPN", f"备用节点 {endpoint.get('endpoint_id')} 切换失败: {exc}")
        auto_switch_node.failed_ids = failed_ids
        auto_switch_node(attempt + 1)
        return

    msg = "没有经过验证的备用节点，切换直连模式，并在后台继续补齐。"
    print(f"[自动切换] {msg}", flush=True)
    log_to_json("WARNING", "VPN", msg)
    stop_all_tunnels()
    with lock:
        nodes = read_nodes()
        for item in nodes:
            item["active"] = False
        write_json(NODES_FILE, nodes)
    set_state(active_openvpn_node_id="", active_pool_endpoint_id="", active_tunnel_protocol="", last_check_message=msg, proxy_ok=False, proxy_ip="-", proxy_latency_ms=0)
    _fallback_direct_egress(msg)

    def bg_fetch_and_switch():
        try:
            if target_country:
                start_country_priority(target_country)
            time.sleep(5)
            maintain_valid_nodes(force=False)
        except Exception as exc:
            print(f"[自动切换后台补齐] 获取并测试节点失败: {exc}", flush=True)
    threading.Thread(target=bg_fetch_and_switch, daemon=True).start()

STANDBY_DEV = "tun-sb"
standby_guard = threading.Lock()
standby_slot: dict[str, Any] = {
    "node_id": "", "process": None, "dev": "", "ready": False, "country": "",
    "protocol": "", "endpoint_id": "", "gateway": "", "tunnel": None, "validated_at": 0.0,
}

def standby_protected_pids() -> set[int]:
    proc = standby_slot.get("process")
    pid = getattr(proc, "pid", None)
    if not pid:
        return set()
    return {int(pid)}

def _standby_process_alive() -> bool:
    dev = str(standby_slot.get("dev") or "")
    if not dev or not Path("/sys/class/net", dev).exists():
        return False
    if standby_slot.get("tunnel") is not None:
        return True
    proc = standby_slot.get("process")
    if proc is None or proc.poll() is not None:
        return False
    return tunnel_adapters.interface_has_ipv4(dev)

def release_standby() -> None:
    with standby_guard:
        proc = standby_slot.get("process")
        tunnel = standby_slot.get("tunnel")
        standby_slot.update(
            node_id="", process=None, dev="", ready=False, country="",
            protocol="", endpoint_id="", gateway="", tunnel=None, validated_at=0.0,
        )
    if tunnel is not None:
        _disconnect_external_tunnel(tunnel)
        return
    if proc is not None and proc.poll() is None:
        stop_process(proc)

def take_standby(node_id: str) -> dict[str, Any] | None:
    with standby_guard:
        if not standby_slot.get("ready") or not _standby_process_alive():
            return None
        if str(standby_slot.get("node_id") or "") != str(node_id or ""):
            return None
        taken = {
            "node_id": standby_slot.get("node_id") or "",
            "process": standby_slot.get("process"),
            "dev": standby_slot.get("dev") or standby_device(),
            "tunnel": standby_slot.get("tunnel"),
            "gateway": standby_slot.get("gateway") or "",
            "endpoint_id": standby_slot.get("endpoint_id") or "",
            "protocol": standby_slot.get("protocol") or "",
        }
        standby_slot.update(
            node_id="", process=None, dev="", ready=False, country="",
            protocol="", endpoint_id="", gateway="", tunnel=None, validated_at=0.0,
        )
        return taken

def retire_process_later(process: subprocess.Popen[str] | None, delay: float = 20.0) -> None:
    """Keep the previous tunnel up briefly so flows already bound to it can finish."""
    if process is None:
        return
    def _run() -> None:
        time.sleep(max(0.0, delay))
        stop_process(process)
    threading.Thread(target=_run, daemon=True, name="retire-old-tunnel").start()

def _endpoint_ip(endpoint: dict[str, Any] | None) -> str:
    if not endpoint:
        return ""
    return str(endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "").strip()


def _active_exit_ip() -> str:
    return _endpoint_ip(current_active_routing_endpoint())


def _standby_speed_gap(endpoint: dict[str, Any], target: int) -> int:
    speed = int(endpoint.get("latest_speed") or endpoint.get("speed") or 0)
    if speed <= 0 or target <= 0:
        return 10**12
    return abs(speed - target)


def _select_standby_endpoint() -> dict[str, Any] | None:
    """Standby must meet the same speed floor as the main. No closest-under match."""
    ui_cfg = load_ui_config()
    active_ip = _active_exit_ip()
    active_eid = str(active_pool_endpoint_id or "")
    try:
        pool = unified_hot_pool_candidates(ui_cfg, limit=80)
    except Exception as exc:
        log_to_json("WARNING", "Standby", f"热备候选读取失败: {exc}")
        return None
    rows: list[dict[str, Any]] = []
    for endpoint in pool:
        ip = _endpoint_ip(endpoint)
        eid = str(endpoint.get("endpoint_id") or "")
        if not ip or (active_ip and ip == active_ip) or (active_eid and eid == active_eid):
            continue
        if endpoint_is_unstable(endpoint):
            continue
        if not endpoint_matches_explicit_routing(endpoint, ui_cfg):
            continue
        rows.append(endpoint)
    if not rows:
        return None
    rows.sort(key=lambda ep: routing_service_key(ep, ui_cfg))
    return rows[0]


def _publish_scheme_standby(endpoint: dict[str, Any]) -> bool:
    protocol = str(endpoint.get("protocol") or "").strip().lower()
    if protocol == "openvpn":
        try:
            node_id = ensure_openvpn_node_from_pool(endpoint)
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"热备节点准备失败: {exc}")
            return False
        node = next((item for item in read_nodes() if str(item.get("id") or "") == node_id), None)
        if not node or not node.get("config_text"):
            return False
        chosen = dict(node)
        chosen["country"] = normalized_country_name(endpoint.get("country") or "") or chosen.get("country") or ""
        return _bring_up_standby(chosen)
    return _bring_up_external_standby(endpoint)


def _select_standby_openvpn_node() -> dict[str, Any] | None:
    ui_cfg = load_ui_config()
    try:
        candidates = unified_hot_pool_candidates(ui_cfg, limit=40, protocol="openvpn")
    except Exception as exc:
        log_to_json("WARNING", "Standby", f"热备候选读取失败: {exc}")
        return None
    active_id = str(active_openvpn_node_id or "")
    active_ip, active_port = _active_exit_ip(), 0
    active_parts = active_id.rsplit("_", 2)
    if len(active_parts) == 3 and str(active_parts[1]).isdigit():
        active_ip = active_parts[0] or active_ip
        active_port = int(active_parts[1])
    ranked: list[tuple[float, dict[str, Any]]] = []
    for endpoint in candidates:
        if str(endpoint.get("protocol") or "").lower() != "openvpn":
            continue
        endpoint_ip = str(endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "").strip()
        endpoint_port = int(endpoint.get("port") or 0)
        if active_ip and endpoint_ip == active_ip:
            continue
        if active_ip and endpoint_ip == active_ip and endpoint_port == active_port:
            continue
        latency = float(endpoint.get("latency_ewma") or endpoint.get("latency_ms") or 0)
        if latency > 12000:
            continue
        meta = endpoint.get("metadata") or {}
        node_id = str(meta.get("node_id") or "")
        if node_id and node_id == active_id:
            continue
        if str(endpoint.get("endpoint_id") or "") and str(endpoint.get("endpoint_id") or "") == str(active_pool_endpoint_id or ""):
            continue
        ranked.append((latency, endpoint))
    ranked.sort(key=lambda item: item[0] if item[0] > 0 else 999999)
    pin = normalized_country_name((manual_route_pin or {}).get("country") or "")
    failed_until = getattr(_select_standby_openvpn_node, "failed_until", {})
    now = time.time()
    for _latency, endpoint in ranked[:8]:
        country = normalized_country_name(endpoint.get("country") or "")
        if pin and country and country != pin:
            continue
        try:
            node_id = ensure_openvpn_node_from_pool(endpoint)
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"热备节点准备失败: {exc}")
            continue
        if node_id == active_id or float(failed_until.get(node_id) or 0) > now:
            continue
        node = next((item for item in read_nodes() if str(item.get("id") or "") == node_id), None)
        if node and node.get("config_text"):
            chosen = dict(node)
            if country:
                chosen["country"] = country
            return chosen
    return None

def _bring_up_external_standby(endpoint: dict[str, Any]) -> bool:
    """Pre-dial SoftEther, SSTP or L2TP without touching the live table 100."""
    protocol = str(endpoint.get("protocol") or "").strip().lower()
    endpoint_id = str(endpoint.get("endpoint_id") or "")
    if protocol not in ("softether", "sstp", "l2tp-ipsec"):
        return False
    if (
        protocol == "softether"
        and active_external_tunnel is not None
        and str(active_external_tunnel.protocol or "") == "softether"
    ):
        log_to_json("INFO", "Standby", "当前已是 SoftEther，仍尝试用另一张虚拟网卡预拨热备")
    if standby_slot.get("ready") or standby_slot.get("tunnel") is not None or standby_slot.get("process") is not None:
        release_standby()
    metadata = endpoint.get("metadata") or {}
    host = str(metadata.get("hostname") or endpoint.get("hostname") or endpoint.get("current_ip") or "").strip()
    if not host:
        return False
    port = parse_int(endpoint.get("port"))
    token = re.sub(r"[^a-z0-9]", "", endpoint_id.lower())[:8] or uuid.uuid4().hex[:8]
    result: tunnel_adapters.TunnelResult | None = None
    try:
        if protocol == "softether":
            result = tunnel_adapters.SoftEtherAdapter().connect(
                host=host, port=port or 443, account=f"sb{token}", nic=f"s{token}",
                username="vpn", password="vpn",
            )
        elif protocol == "sstp":
            result = tunnel_adapters.SSTPAdapter().connect(
                hostname=host if port in (0, 443) else f"{host}:{port}",
                username="vpn", password="vpn", timeout=20, reuse_existing=False,
            )
        else:
            result = l2tp_adapter.connect(
                host=host, username="vpn", password="vpn", psk="vpn",
                namespace=f"aimili-l2tp-sb{token}"[:31], timeout=25,
            )
        if result is None or not result.ok or not result.interface:
            raise RuntimeError((result.message if result else "隧道未建立")[:180])
        if protocol == "l2tp-ipsec":
            ensure_l2tp_namespace_forward(result)
        probed = check_interface_egress(str(result.interface), str(result.gateway or ""), table=101)
        if not probed.get("ok"):
            raise RuntimeError(str(probed.get("error") or "热备数据面未通过")[:180])
        node_id = f"pool:{endpoint_id}" if endpoint_id else f"pool:{token}"
        with standby_guard:
            standby_slot.update(
                node_id=node_id,
                process=result.process,
                dev=str(result.interface),
                ready=True,
                country=normalized_country_name(endpoint.get("country") or ""),
                protocol=protocol,
                endpoint_id=endpoint_id,
                gateway=str(result.gateway or ""),
                tunnel=result,
                validated_at=time.time(),
            )
        set_state(
            standby_ready=True,
            standby_prepared=True,
            standby_node_id=node_id,
            standby_ip=_endpoint_ip(endpoint),
            standby_port=port,
            standby_protocol=protocol,
            standby_latency_ms=parse_int(probed.get("latency_ms")),
            standby_validated_at=time.time(),
            standby_health_age_ms=0,
        )
        log_to_json("INFO", "Standby", f"{protocol} 热备已就绪 {result.interface} · {probed.get('latency_ms') or 0} ms")
        return True
    except Exception as exc:
        if result is not None:
            _disconnect_external_tunnel(result)
        set_state(
            standby_prepared=True,
            standby_ready=False,
            standby_node_id=f"pool:{endpoint_id}" if endpoint_id else "",
            standby_ip=_endpoint_ip(endpoint),
            standby_port=port if host else 0,
            standby_protocol=protocol,
        )
        log_to_json("INFO", "Standby", f"{protocol} 热备未建立 {endpoint_id}: {exc}")
        return False


def _bring_up_standby(node: dict[str, Any]) -> bool:
    node_id = str(node.get("id") or "")
    if not node_id:
        return False
    config_path = CONFIG_DIR / f"standby-{node_id}.ovpn"
    CONFIG_DIR.mkdir(exist_ok=True, parents=True)
    config_path.write_text(_prefer_openvpn_ip(node.get("config_text") or "", node), encoding="utf-8")
    dev = standby_device()
    ok, message, process = run_openvpn_until_ready(
        str(config_path), keep_alive=True, route_nopull=True, timeout=12, dev=dev
    )
    if not ok or process is None:
        failed_until = getattr(_select_standby_openvpn_node, "failed_until", {})
        failed_until[node_id] = time.time() + 600
        _select_standby_openvpn_node.failed_until = failed_until
        log_to_json("INFO", "Standby", f"热备隧道未建立 {node_id}: {message}")
        return False
    if proxy_server.proxy_forwarding_busy():
        # Tunnel is already up. Count it as the hot standby immediately and
        # confirm the exit on a later pass, instead of leaving the card at 0.
        with standby_guard:
            standby_slot.update(node_id=node_id, process=process, dev=dev, ready=True, country=str(node.get("country") or ""), protocol="openvpn", endpoint_id="", gateway="", tunnel=None, validated_at=time.time())
        set_state(
            standby_ready=True,
            standby_node_id=node_id,
            standby_ip=str(node.get("ip") or node.get("remote_host") or ""),
            standby_port=parse_int(node.get("remote_port")),
            standby_protocol=str(node.get("protocol") or "openvpn"),
        )
        return True
    egress = check_interface_egress(dev, table=101)
    if not egress.get("ok"):
        stop_process(process)
        failed_until = getattr(_select_standby_openvpn_node, "failed_until", {})
        failed_until[node_id] = time.time() + 600
        _select_standby_openvpn_node.failed_until = failed_until
        log_to_json("INFO", "Standby", f"热备出口未通过 {node_id}: {egress.get('error') or ''}")
        return False
    with standby_guard:
        standby_slot.update(node_id=node_id, process=process, dev=dev, ready=True, country=str(node.get("country") or ""), protocol="openvpn", endpoint_id="", gateway="", tunnel=None)
    log_to_json("INFO", "Standby", f"热备隧道已就绪 {node_id} · {egress.get('latency_ms') or 0} ms")
    set_state(
        standby_ready=True,
        standby_node_id=node_id,
        standby_latency_ms=parse_int(egress.get("latency_ms")),
        standby_ip=str(node.get("ip") or node.get("remote_host") or ""),
        standby_port=parse_int(node.get("remote_port")),
        standby_protocol=str(node.get("protocol") or "openvpn"),
    )
    return True

_first_page_snapshot: dict[tuple[str, str], dict[str, Any]] = {}
_first_page_snapshot_lock = threading.Lock()

def warm_first_page_loop() -> None:
    """Keep the first pages ready so opening the site does not wait on SQLite."""
    time.sleep(0.2)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        try:
            if not manual_connection_active:
                countries = [str(_read_bootstrap_state().get("local_server_country") or "").strip(), ""]
                active = str(active_pool_endpoint_id or active_openvpn_node_id or "")
                seen: set[str] = set()
                for country in countries:
                    country_key = normalized_country_name(country) if country else ""
                    if country_key in seen:
                        continue
                    seen.add(country_key)
                    nodes, total, building = _get_ui_nodes_page(0, 60, country, "usable")
                    body = {
                        "ok": True,
                        "nodes": nodes,
                        "offset": 0,
                        "limit": 60,
                        "total": total,
                        "has_more": len(nodes) < int(total or 0),
                        "cache_building": bool(building),
                        "scope": {"country": country, "status": "usable", "protocol": "", "ip_type": "", "speed_min_bps": 0},
                        "generated_at": time.time(),
                    }
                    with _first_page_snapshot_lock:
                        _first_page_snapshot[(country_key, active)] = {"at": time.time(), "body": body}
        except Exception:
            pass
        time.sleep(15)

def _clear_hot_standby_identity() -> None:
    """Drop a live hot standby without erasing a prepared cold pin."""
    try:
        raw = read_json(STATE_FILE, {})
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    prepared = bool(raw.get("standby_prepared"))
    ip = str(raw.get("standby_ip") or "").strip()
    port = parse_int(raw.get("standby_port"))
    protocol = str(raw.get("standby_protocol") or "").strip().lower()
    sid = str(raw.get("standby_node_id") or "")
    if prepared and ip:
        found = ""
        if port > 0 and protocol:
            try:
                found = node_pool.find_endpoint_id(ip, port, protocol)
            except Exception:
                found = ""
        if found:
            wanted = "pool:" + found
            if sid == wanted and not raw.get("standby_ready"):
                return
            set_state(standby_ready=False, standby_node_id=wanted)
            return
        if sid.startswith("pool:"):
            set_state(standby_ready=False)
            return
        set_state(standby_ready=False, standby_node_id="")
        return
    set_state(standby_ready=False, standby_node_id="")


def _refresh_standby_validation() -> None:
    """Keep the hot standby's health younger than 2 seconds. One miss does not tear it down."""
    with standby_guard:
        if not standby_slot.get("ready"):
            return
        dev = str(standby_slot.get("dev") or "")
        gateway = str(standby_slot.get("gateway") or "")
    if not dev or not Path("/sys/class/net", dev).exists():
        return
    route_ok, _route_error = setup_probe_policy_routing(dev, gateway, table=101)
    ok = False
    if route_ok:
        ok, _detail = _probe_iface_tcp(dev, 1.0)
        cleanup_probe_policy_routing(101)
    now = time.time()
    if ok:
        with standby_guard:
            standby_slot["validated_at"] = now
            standby_slot["misses"] = 0
        set_state(standby_validated_at=now, standby_health_age_ms=0, standby_ready=True)
        return
    with standby_guard:
        misses = int(standby_slot.get("misses") or 0) + 1
        standby_slot["misses"] = misses
        validated_at = float(standby_slot.get("validated_at") or 0)
    age_ms = int(max(0.0, now - validated_at) * 1000) if validated_at else 0
    set_state(standby_health_age_ms=age_ms)
    if misses >= 2:
        log_to_json("INFO", "Standby", f"热备 {dev} 连续两次复测失败，放弃这条热备")
        release_standby()
        set_state(standby_ready=False, standby_health_age_ms=age_ms)


def warm_standby_loop() -> None:
    """Keep one dialed standby. Catalog pause must not stop this."""
    time.sleep(8)
    while True:
        try:
            if manual_connection_active or ui_command_plane.is_busy() or is_connecting or not active_tunnel_running():
                time.sleep(2)
                continue
            with standby_guard:
                ready = bool(standby_slot.get("ready")) and _standby_process_alive()
                pending = standby_slot.get("process") is not None and not standby_slot.get("ready")
                pending_id = str(standby_slot.get("node_id") or "")
            if ready:
                sid = str(standby_slot.get("node_id") or "")
                standby_ip = str(get_state().get("standby_ip") or "")
                active_ip = _active_exit_ip()
                if active_ip and standby_ip == active_ip:
                    release_standby()
                    set_state(standby_ready=False, standby_node_id="", standby_ip="", standby_port=0, standby_protocol="")
                    log_to_json("INFO", "Standby", "备连接与当前出口同一 IP，已放开并改选其他 IP")
                    continue
                chosen = _select_standby_endpoint()
                chosen_protocol = str((chosen or {}).get("protocol") or "").lower()
                chosen_ip = _endpoint_ip(chosen)
                slot_protocol = str(standby_slot.get("protocol") or "").lower()
                if chosen and chosen_ip and chosen_protocol and slot_protocol and chosen_protocol != slot_protocol:
                    release_standby()
                    _clear_hot_standby_identity()
                    _publish_scheme_standby(chosen)
                    time.sleep(8)
                    continue
                pin_country = normalized_country_name((manual_route_pin or {}).get("country") or "")
                standby_country = normalized_country_name(standby_slot.get("country") or "")
                if sid and sid == str(active_openvpn_node_id or ""):
                    release_standby()
                    _clear_hot_standby_identity()
                    continue
                if pin_country and standby_country and standby_country != pin_country:
                    replacement = _select_standby_openvpn_node()
                    replacement_country = normalized_country_name((replacement or {}).get("country") or "")
                    if not replacement or replacement_country != pin_country:
                        if time.time() - float(getattr(warm_standby_loop, "country_hold_log_at", 0) or 0) > 300:
                            warm_standby_loop.country_hold_log_at = time.time()
                            log_to_json("INFO", "Standby", f"热备不在{pin_country}，该国暂无可用 OpenVPN，先保留当前热备")
                        time.sleep(30)
                        continue
                    release_standby()
                    _clear_hot_standby_identity()
                    log_to_json("INFO", "Standby", f"热备改到{pin_country}")
                    _bring_up_standby(replacement)
                    time.sleep(8)
                    continue
                if not read_json(STATE_FILE, {}).get("standby_ready"):
                    set_state(standby_ready=True, standby_node_id=str(standby_slot.get("node_id") or ""))
                _refresh_standby_validation()
                time.sleep(0.5)
                continue
            if pending and _standby_process_alive():
                with standby_guard:
                    standby_slot["ready"] = True
                set_state(standby_ready=True, standby_node_id=pending_id)
                if not proxy_server.proxy_forwarding_busy():
                    egress = check_interface_egress(str(standby_slot.get("dev") or standby_device()), table=101)
                    if egress.get("ok"):
                        set_state(standby_ready=True, standby_node_id=pending_id, standby_latency_ms=parse_int(egress.get("latency_ms")))
                        log_to_json("INFO", "Standby", f"热备隧道已就绪 {pending_id} · {egress.get('latency_ms') or 0} ms")
                    else:
                        failed_until = getattr(_select_standby_openvpn_node, "failed_until", {})
                        failed_until[pending_id] = time.time() + 600
                        _select_standby_openvpn_node.failed_until = failed_until
                        release_standby()
                        _clear_hot_standby_identity()
                        log_to_json("INFO", "Standby", f"热备出口未通过 {pending_id}: {egress.get('error') or ''}")
                time.sleep(8)
                continue
            if pending:
                release_standby()
            node = _select_standby_openvpn_node()
            scheme = _select_standby_endpoint()
            if scheme and str(scheme.get("protocol") or "").lower() != "openvpn":
                _publish_scheme_standby(scheme)
                time.sleep(20)
                continue
            if scheme and str(scheme.get("protocol") or "").lower() == "openvpn":
                published = _publish_scheme_standby(scheme)
                if published:
                    time.sleep(8)
                    continue
            if not node:
                if time.time() - float(getattr(warm_standby_loop, "empty_log_at", 0) or 0) > 300:
                    warm_standby_loop.empty_log_at = time.time()
                    log_to_json("INFO", "Standby", "还没有可预连的 OpenVPN 热备")
                _clear_hot_standby_identity()
                time.sleep(30)
                continue
            _bring_up_standby(node)
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"热备隧道维护失败: {exc}")
        time.sleep(8)

COLD_PORT_SECONDS = 60
COLD_REAL_SECONDS = 10 * 60
PRECOLD_REAL_SECONDS = 20 * 60
SUBSTITUTE_REAL_SECONDS = 40 * 60
STANDBY_REAL_GAP_SECONDS = 3 * 60
LIBRARY_IDLE_FAST_SECONDS = 3 * 3600
LIBRARY_IDLE_SLOW_SECONDS = 6 * 3600
LIBRARY_IDLE_FAST_LIMIT = 15 * 60
PRECOLD_TARGET = 5
_cold_guard = threading.Lock()
_cold_mem: dict[str, Any] | None = None
_cold_announced = False


def _load_cold_state() -> dict[str, Any]:
    raw = read_json(DATA_DIR / "cold_standby.json", {})
    if not isinstance(raw, dict):
        raw = {}
    return {
        "order": [str(item) for item in (raw.get("order") or []) if str(item)],
        "failed": [str(item) for item in (raw.get("failed") or []) if str(item)],
        "precold": [str(item) for item in (raw.get("precold") or []) if str(item)],
        "precold_detail": raw.get("precold_detail") if isinstance(raw.get("precold_detail"), dict) else {},
        "published": str(raw.get("published") or ""),
        "last_connect": float(raw.get("last_connect") or 0),
        "last_real_any": float(raw.get("last_real_any") or 0),
        "real_at": _cold_real_at(raw.get("real_at")),
    }


def _cold_state() -> dict[str, Any]:
    global _cold_mem
    with _cold_guard:
        if _cold_mem is None:
            _cold_mem = _load_cold_state()
        return _cold_mem


def _save_cold_state() -> None:
    with _cold_guard:
        snapshot = dict(_cold_mem or _load_cold_state())
        snapshot["order"] = list(snapshot.get("order") or [])
        snapshot["failed"] = list(snapshot.get("failed") or [])
        snapshot["real_at"] = dict(snapshot.get("real_at") or {})
    try:
        write_json(DATA_DIR / "cold_standby.json", snapshot)
    except Exception:
        pass


def _endpoint_speed_bps(endpoint: dict[str, Any]) -> int:
    try:
        return int(endpoint.get("latest_speed") or endpoint.get("speed") or 0)
    except (TypeError, ValueError):
        return 0


def _current_route_protocol(ui_cfg: dict[str, Any]) -> str:
    allowed = ("openvpn", "softether", "sstp", "l2tp-ipsec")
    proto = str(ui_cfg.get("routing_protocol") or "").strip().lower()
    if proto in allowed:
        return proto
    try:
        proto = str(get_state().get("active_tunnel_protocol") or "").strip().lower()
    except Exception:
        proto = ""
    if proto in allowed:
        return proto
    if active_pool_endpoint_id:
        try:
            endpoint = node_pool.get_endpoint(active_pool_endpoint_id)
        except Exception:
            endpoint = None
        proto = str((endpoint or {}).get("protocol") or "").strip().lower()
        if proto in allowed:
            return proto
    return ""


_speed_recheck_at: dict[str, float] = {}


def _queue_unmeasured_speed(endpoint_ids: list[str]) -> None:
    now = time.time()
    fresh = [
        eid for eid in endpoint_ids
        if eid and now - float(_speed_recheck_at.get(eid) or 0) > 3600
    ][:8]
    if not fresh:
        return
    try:
        node_pool.queue_speed_recheck(fresh)
    except Exception:
        return
    for eid in fresh:
        _speed_recheck_at[eid] = now


def _cold_candidates(ui_cfg: dict[str, Any]) -> dict[str, dict[str, Any]] | None:
    """Verified backups, relaxed by tier. 50 Mbps is the floor that never drops."""
    active_eid = str(active_pool_endpoint_id or "")
    active_ip = _active_exit_ip()
    home = routing_target_country(ui_cfg)
    proto = _current_route_protocol(ui_cfg)
    cache_key = "|".join([
        home,
        proto,
        normalize_routing_blocklist(ui_cfg.get("routing_blocklist") or ""),
        str(ui_cfg.get("routing_mode") or ""),
        str(ui_cfg.get("routing_ip_type") or ""),
        str(ui_cfg.get("routing_min_speed_bps") or 0),
        str(ui_cfg.get("routing_latency") or ""),
    ])
    cached = getattr(_cold_candidates, "cache", None)
    now_rank = time.time()
    if isinstance(cached, dict) and cached.get("key") == cache_key and (now_rank - float(cached.get("at") or 0) < 3600 or ui_query_active()):
        _cold_candidates.stats = dict(cached.get("stats") or {})
        return dict(cached.get("found") or {})
    if ui_query_active():
        if isinstance(cached, dict):
            _cold_candidates.stats = dict(cached.get("stats") or {})
            return dict(cached.get("found") or {})
        return {}
    stats = {
        "same_protocol": 0,
        "other_protocol": 0,
        "other_country": 0,
        "excluded_speed": 0,
        "excluded_unmeasured": 0,
        "excluded_occupied": 0,
        "excluded_duplicate": 0,
        "excluded_unstable": 0,
        "excluded_blocked": 0,
    }
    try:
        rows = node_pool.list_routing_endpoints(limit=800, country=home) if home else []
        seen_rows = {str(item.get("endpoint_id") or "") for item in rows}
        for item in node_pool.list_routing_endpoints(limit=800):
            eid = str(item.get("endpoint_id") or "")
            if eid and eid not in seen_rows:
                seen_rows.add(eid)
                rows.append(item)
    except Exception as exc:
        log_to_json("WARNING", "Standby", f"冷备候选读取失败: {exc}")
        return None
    qualified: list[dict[str, Any]] = []
    unmeasured: list[str] = []
    seen_identity: set[str] = set()
    country_latency: dict[str, int] = {}
    for endpoint in rows:
        eid = str(endpoint.get("endpoint_id") or "")
        protocol = str(endpoint.get("protocol") or "").lower()
        if not eid or protocol not in ("openvpn", "softether", "sstp", "l2tp-ipsec"):
            continue
        if str(endpoint.get("status") or "").upper() not in ("HOT", "AVAILABLE"):
            continue
        if endpoint_is_blocked(endpoint, ui_cfg):
            stats["excluded_blocked"] += 1
            continue
        ip = _endpoint_ip(endpoint)
        if not ip:
            continue
        if endpoint_is_unstable(endpoint) or int(endpoint.get("fail_streak") or 0) >= 3:
            stats["excluded_unstable"] += 1
            continue
        if eid == active_eid or (active_ip and ip == active_ip):
            stats["excluded_occupied"] += 1
            continue
        speed = _endpoint_speed_bps(endpoint)
        if speed <= 0:
            stats["excluded_unmeasured"] += 1
            unmeasured.append(eid)
            continue
        if speed < ROUTING_MIN_LINE_SPEED_BPS:
            stats["excluded_speed"] += 1
            continue
        identity = f"{protocol}|{ip}|{int(endpoint.get('port') or 0)}"
        if identity in seen_identity:
            stats["excluded_duplicate"] += 1
            continue
        seen_identity.add(identity)
        endpoint["routing_favorite_rank"] = routing_favorite_rank(endpoint, ui_cfg)
        qualified.append(endpoint)
        country = normalized_country_name(endpoint.get("country"))
        ip_type = str(endpoint_ip_type(endpoint) or "").lower()
        if country and ip_type in ("mobile", "residential"):
            latency = endpoint_display_latency_ms(endpoint) or 999999
            country_latency[country] = min(country_latency.get(country, 999999), latency)

    def _tier(endpoint: dict[str, Any]) -> int:
        country = normalized_country_name(endpoint.get("country"))
        protocol = str(endpoint.get("protocol") or "").lower()
        ip_type = str(endpoint_ip_type(endpoint) or "").lower()
        same_country = bool(home) and country == home
        same_protocol = (not proto) or protocol == proto
        if same_country and same_protocol and ip_type == "mobile":
            return 0
        if same_country and same_protocol and ip_type == "residential":
            return 1
        if same_country and not same_protocol and ip_type == "mobile":
            return 2
        if same_country and not same_protocol and ip_type == "residential":
            return 3
        if not same_country and ip_type == "mobile":
            return 4
        if not same_country and ip_type == "residential":
            return 5
        if same_country and same_protocol and ip_type == "hosting":
            return 6
        if same_country and not same_protocol and ip_type == "hosting":
            return 7
        if not same_country and ip_type == "hosting":
            return 8
        return 9

    def _sort_key(endpoint: dict[str, Any]) -> tuple:
        tier = _tier(endpoint)
        country = normalized_country_name(endpoint.get("country"))
        latency = endpoint_display_latency_ms(endpoint) or 999999
        country_rank = country_latency.get(country, 999999) if tier in (4, 5, 8) else 0
        return (
            tier,
            int(endpoint.get("routing_favorite_rank") or 1),
            country_rank,
            latency,
            -_endpoint_speed_bps(endpoint),
        )

    qualified.sort(key=_sort_key)
    if _explicit_scheme_configured(ui_cfg):
        matched = [ep for ep in qualified if endpoint_matches_explicit_routing(ep, ui_cfg)]
        # 1 main is chosen elsewhere. Cold needs 1 + 5. Fewer than that, keep the ladder.
        if len(matched) >= 1 + PRECOLD_TARGET:
            qualified = matched
    found: dict[str, dict[str, Any]] = {}
    for endpoint in qualified:
        endpoint["_precold_tier"] = _tier(endpoint)
        found[str(endpoint.get("endpoint_id") or "")] = endpoint
    _queue_unmeasured_speed(unmeasured)
    _cold_candidates.stats = stats
    _cold_candidates.cache = {"at": time.time(), "key": cache_key, "found": found, "stats": dict(stats)}
    return found


def _precold_bucket(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> str:
    home = routing_target_country(ui_cfg)
    proto = _current_route_protocol(ui_cfg)
    country = normalized_country_name(endpoint.get("country"))
    protocol = str(endpoint.get("protocol") or "").lower()
    same_country = bool(home) and country == home
    same_protocol = (not proto) or protocol == proto
    if same_country and same_protocol:
        return "same_protocol"
    if same_country:
        return "other_protocol"
    return "other_country"


def _select_precold_ids(candidates: dict[str, dict[str, Any]], cold_eid: str) -> list[str]:
    """Fill up to five behind the cold standby. Earlier tiers stay put."""
    failed = {str(item) for item in (_cold_state().get("failed") or [])}
    picked: list[str] = []
    for eid in candidates:
        if not eid or eid == cold_eid or eid in failed:
            continue
        picked.append(eid)
        if len(picked) >= PRECOLD_TARGET:
            break
    return picked


def _remember_precold(candidates: dict[str, dict[str, Any]], cold_eid: str) -> None:
    precold = _select_precold_ids(candidates, cold_eid)
    ui_cfg = load_ui_config()
    detail = dict(getattr(_cold_candidates, "stats", {}) or {})
    detail["same_protocol"] = 0
    detail["other_protocol"] = 0
    detail["other_country"] = 0
    for eid in precold:
        bucket = _precold_bucket(candidates.get(eid) or {}, ui_cfg)
        detail[bucket] = int(detail.get(bucket) or 0) + 1
    detail["shown"] = len(precold)
    detail["target"] = PRECOLD_TARGET
    cold = _cold_state()
    if list(cold.get("precold") or []) == precold and dict(cold.get("precold_detail") or {}) == detail:
        return
    cold["precold"] = precold
    cold["precold_detail"] = detail
    _save_cold_state()


def _overlay_pool_roles(state: dict[str, Any]) -> None:
    """Live 1 primary + 1 cold + up to 5 pre-cold. Not the old HOT-row count."""
    primary = 1 if (active_pool_endpoint_id or active_openvpn_node_id) else 0
    standby_id = str(state.get("standby_node_id") or "")
    cold_on = bool(standby_slot.get("ready")) or (
        bool(standby_id) and bool(state.get("standby_ready") or state.get("standby_prepared"))
    )
    active_eid = str(active_pool_endpoint_id or "")
    cold_eid = standby_id.split(":", 1)[1] if standby_id.startswith("pool:") else standby_id
    try:
        raw = [str(item) for item in (_cold_state().get("precold") or []) if str(item)]
    except Exception:
        raw = []
    shown = [eid for eid in raw if eid not in {active_eid, cold_eid}]
    detail = _cold_state().get("precold_detail") if isinstance(_cold_state().get("precold_detail"), dict) else {}
    shown_count = min(PRECOLD_TARGET, len(shown))
    state["pool_primary"] = primary
    state["pool_cold"] = 1 if cold_on else 0
    state["pool_precold"] = shown_count
    state["pool_precold_target"] = PRECOLD_TARGET
    state["pool_precold_detail"] = (
        f"预冷备 {shown_count}/{PRECOLD_TARGET}"
        f" · 当前国家同协议 {int(detail.get('same_protocol') or 0)}"
        f" · 当前国家其它协议 {int(detail.get('other_protocol') or 0)}"
        f" · 其它低延迟国家 {int(detail.get('other_country') or 0)}"
        f" · 速度低于50Mbps排除 {int(detail.get('excluded_speed') or 0)}"
        f" · 未测速待补 {int(detail.get('excluded_unmeasured') or 0)}"
        f" · 主备占用或重复排除 {int(detail.get('excluded_occupied') or 0) + int(detail.get('excluded_duplicate') or 0)}"
    )
    _overlay_dataplane(state)


def _overlay_dataplane(state: dict[str, Any]) -> None:
    raw = read_json(DATA_DIR / "dataplane.json", {})
    if not isinstance(raw, dict):
        raw = {}
    state["dataplane_jitter"] = bool(raw.get("jitter"))
    state["tcp_retrans_delta"] = int(raw.get("tcp_retrans_delta") or 0)
    state["quic_fallback_tcp"] = int(raw.get("quic_fallback_tcp") or 0)
    state["udp443_flows"] = int(raw.get("udp443_flows") or 0)
    state["active_connections"] = int(raw.get("active_connections") or 0)
    state["queued_connections"] = int(raw.get("queued_connections") or 0)
    state["worker_busy"] = int(raw.get("worker_busy") or 0)
    state["accept_wait_ms"] = int(raw.get("accept_wait_ms") or 0)


def _open_cold_round(candidates: dict[str, dict[str, Any]]) -> None:
    """One new round per pass. Do not un-fail a node again inside the same pass."""
    cold = _cold_state()
    failed = [eid for eid in cold["failed"] if eid in candidates]
    if candidates and failed and all(eid in failed for eid in candidates):
        failed = []
        log_to_json("INFO", "Standby", "冷备已轮换一整轮，仍可用的节点可以重新作为备")
    cold["failed"] = failed
    cold["order"] = list(candidates.keys())
    _save_cold_state()


def _pick_cold(candidates: dict[str, dict[str, Any]]) -> dict[str, Any] | None:
    cold = _cold_state()
    failed = {eid for eid in cold["failed"] if eid in candidates}
    for eid in candidates:
        if eid not in failed:
            return candidates[eid]
    return None


def _rotate_cold(eid: str, candidates: dict[str, dict[str, Any]]) -> None:
    cold = _cold_state()
    order = [item for item in cold["order"] if item != eid and item in candidates]
    for item in candidates:
        if item not in order and item != eid:
            order.append(item)
    order.append(eid)
    if eid not in cold["failed"]:
        cold["failed"].append(eid)
    cold["order"] = order
    cold["failed"] = [item for item in cold["failed"] if item in candidates or item == eid]
    cold["published"] = ""
    _save_cold_state()


def _publish_cold_standby(endpoint: dict[str, Any] | None) -> None:
    global _cold_announced
    if standby_slot.get("ready"):
        return
    cold = _cold_state()
    if not endpoint:
        if cold.get("published") or _cold_announced:
            set_state(standby_prepared=False, standby_node_id="", standby_ip="", standby_port=0, standby_protocol="")
            cold["published"] = ""
            _cold_announced = True
            _save_cold_state()
        return
    eid = str(endpoint.get("endpoint_id") or "")
    if endpoint_is_blocked(endpoint, load_ui_config()):
        _publish_cold_standby(None)
        return
    wanted_id = ("pool:" + eid) if eid else ""
    try:
        raw_state = read_json(STATE_FILE, {})
    except Exception:
        raw_state = {}
    if not isinstance(raw_state, dict):
        raw_state = {}
    same = (
        cold.get("published") == eid
        and _cold_announced
        and bool(raw_state.get("standby_prepared"))
        and str(raw_state.get("standby_node_id") or "") == wanted_id
        and str(raw_state.get("standby_ip") or "") == _endpoint_ip(endpoint)
    )
    if same:
        return
    set_state(
        standby_prepared=True,
        standby_node_id="pool:" + eid,
        standby_ip=_endpoint_ip(endpoint),
        standby_port=int(endpoint.get("port") or 0),
        standby_protocol=str(endpoint.get("protocol") or ""),
    )
    cold["published"] = eid
    _cold_announced = True
    _save_cold_state()
    log_to_json("INFO", "Standby", f"冷备已准备 {endpoint.get('protocol')} {_endpoint_ip(endpoint)}:{int(endpoint.get('port') or 0)}")


def _cold_port_open(endpoint: dict[str, Any]) -> bool | None:
    """One-minute spare check. TCP is a port connect, UDP is one protocol packet. Never a tunnel."""
    result = light_probe_endpoint(endpoint)
    if result.get("inconclusive"):
        return None
    return bool(result.get("ok"))


_cold_promote_lock = threading.Lock()
_cold_promote_cooldown_until = 0.0


def _auto_direct_fallback_active() -> bool:
    try:
        return bool(read_json(STATE_FILE, {}).get("auto_direct_fallback"))
    except Exception:
        return False


def _fallback_direct_egress(reason: str) -> bool:
    """Last resort when every prepared backup failed. Leaves 8500 on the server NIC."""
    ui_cfg = load_ui_config()
    if str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        return False
    if not bool(ui_cfg.get("connection_enabled", True)):
        return False
    if manual_connection_active or ui_command_plane.is_busy():
        return False
    if proxy_server.get_egress_mode() == "direct":
        if not _auto_direct_fallback_active():
            try:
                manual_direct = str(read_json(STATE_FILE, {}).get("manual_egress_mode") or "") == "direct"
            except Exception:
                manual_direct = False
            if not manual_direct:
                set_state(auto_direct_fallback=True)
        return True
    if active_tunnel_running():
        return False
    generation = _begin_egress_transaction()
    if generation is None:
        log_to_json("INFO", "Standby", "出口切换进行中，直连兜底稍后再试")
        return False
    try:
        try:
            stop_all_tunnels()
        except Exception:
            pass
        try:
            _detach_dead_forwarding()
        except Exception:
            pass
        proxy_server.set_egress_mode("direct")
        if not _wait_egress_applied("direct", timeout=1.2):
            proxy_server.set_egress_mode("proxy")
            log_to_json("WARNING", "Standby", "冷备失败后切直连未确认，已恢复代理模式")
            return False
        suspend_policy_routing()
        note = "备用节点不可用，已切换直连：" + str(reason or "")
        set_state(
            auto_direct_fallback=True,
            egress_mode="direct",
            egress_switching=True,
            egress_generation=generation,
            proxy_ok=False,
            proxy_error="",
            active_tunnel_ok=False,
            last_check_message=note[:300],
        )
        log_to_json("WARNING", "Standby", note)

        def _commit() -> None:
            try:
                _refresh_egress_health("direct", "proxy", generation)
            finally:
                _end_egress_transaction(generation)

        threading.Thread(target=_commit, daemon=True, name="cold-direct-fallback").start()
        return True
    except Exception as exc:
        try:
            _end_egress_transaction(generation)
        except Exception:
            pass
        log_to_json("WARNING", "Standby", f"切换直连失败: {exc}")
        return False


def _engage_proxy_egress(reason: str) -> bool:
    """A backup tunnel is up. Leave automatic direct mode and forward 8500 through it."""
    if not active_tunnel_running():
        return False
    if proxy_server.get_egress_mode() == "proxy" and not _auto_direct_fallback_active():
        return True
    generation = _begin_egress_transaction()
    if generation is None:
        log_to_json("INFO", "Standby", "出口切换进行中，切回代理稍后再试")
        return False
    try:
        proxy_server.set_egress_mode("proxy")
        if not _wait_egress_applied("proxy", timeout=1.2):
            proxy_server.set_egress_mode("direct")
            log_to_json("WARNING", "Standby", "冷备接上后切回代理未确认，仍保持直连")
            return False
        try:
            ensure_active_policy_route()
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"切回代理路由失败: {exc}")
        note = str(reason or "冷备已接上，切回代理模式")
        set_state(
            auto_direct_fallback=False,
            egress_mode="proxy",
            egress_switching=True,
            egress_generation=generation,
            proxy_error="",
            last_check_message=note[:300],
        )
        log_to_json("INFO", "Standby", note)

        def _commit() -> None:
            try:
                _refresh_egress_health("proxy", "direct", generation)
            finally:
                _end_egress_transaction(generation)

        threading.Thread(target=_commit, daemon=True, name="cold-proxy-restore").start()
        return True
    except Exception as exc:
        try:
            _end_egress_transaction(generation)
        except Exception:
            pass
        log_to_json("WARNING", "Standby", f"切回代理失败: {exc}")
        return False


def _cold_eid(raw: str) -> str:
    raw = str(raw or "").strip()
    if raw.startswith("pool:"):
        return raw.split(":", 1)[1]
    return raw


def _lookup_cold_endpoint(eid: str, candidates: dict[str, dict[str, Any]]) -> dict[str, Any] | None:
    eid = str(eid or "").strip()
    if not eid:
        return None
    found = candidates.get(eid)
    if found is None:
        try:
            found = node_pool.get_endpoint(eid)
        except Exception:
            found = None
    if not isinstance(found, dict):
        return None
    try:
        if endpoint_is_blocked(found, load_ui_config()):
            return None
    except Exception:
        return None
    return found


def _promote_next_cold(promoted_eid: str, candidates: dict[str, dict[str, Any]]) -> None:
    """The promoted node is now primary. Slide one precold into the cold slot and refill."""
    cold = _cold_state()
    failed = {str(item) for item in (cold.get("failed") or [])}
    nxt: dict[str, Any] | None = None
    for eid in [str(item) for item in (cold.get("precold") or [])]:
        if not eid or eid == promoted_eid or eid in failed:
            continue
        found = _lookup_cold_endpoint(eid, candidates)
        if found:
            nxt = found
            break
    if nxt is None:
        for eid, found in candidates.items():
            if eid and eid != promoted_eid and eid not in failed:
                nxt = found
                break
    new_cold = str((nxt or {}).get("endpoint_id") or "")
    _publish_cold_standby(nxt)
    _remember_precold(candidates, new_cold or promoted_eid)
    filled = [str(item) for item in (_cold_state().get("precold") or []) if str(item)]
    if len(filled) < PRECOLD_TARGET:
        log_to_json("INFO", "Standby", f"预冷备不足，已补到 {len(filled)}/{PRECOLD_TARGET}")
    else:
        log_to_json("INFO", "Standby", f"冷备已前移，预冷备 {len(filled)}/{PRECOLD_TARGET}")


def promote_cold_standby_to_main(exclude_endpoint_id: str = "", candidates: dict[str, dict[str, Any]] | None = None) -> str:
    """Main is down. Promote prepared cold, then one precold. up/direct/busy/cooldown/skip."""
    global _cold_promote_cooldown_until
    if active_tunnel_running():
        return "up"
    if is_connecting or manual_connection_active or ui_command_plane.is_busy():
        return "busy"
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)) or str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        return "skip"
    mode = proxy_server.get_egress_mode()
    auto_direct = _auto_direct_fallback_active()
    if mode not in ("proxy", "direct"):
        return "skip"
    now = time.time()
    if now < _cold_promote_cooldown_until:
        return "cooldown"
    if not _cold_promote_lock.acquire(blocking=False):
        return "busy"
    try:
        if active_tunnel_running():
            return "up"
        if _promote_live_standby():
            _cold_promote_cooldown_until = 0.0
            pool = candidates if isinstance(candidates, dict) else (_cold_candidates(ui_cfg) or {})
            _promote_next_cold(str(exclude_endpoint_id or ""), pool)
            if auto_direct:
                _engage_proxy_egress("热备已接管，切回代理模式")
            log_to_json("INFO", "Standby", "主连接未启动，已由就绪热备接管")
            return "up"
        if candidates is None:
            candidates = _cold_candidates(ui_cfg)
        if candidates is None:
            return "busy"
        cold = _cold_state()
        published = _cold_eid(str(cold.get("published") or ""))
        precold = [_cold_eid(item) for item in (cold.get("precold") or [])]
        exclude = str(exclude_endpoint_id or "").strip()
        order: list[str] = []
        for eid in [published] + precold:
            if eid and eid != exclude and eid not in order:
                order.append(eid)
        if not order:
            chosen = _pick_cold(candidates)
            if chosen:
                eid = str(chosen.get("endpoint_id") or "")
                if eid and eid != exclude:
                    order.append(eid)
                for extra in _select_precold_ids(candidates, eid):
                    if extra and extra != exclude and extra not in order:
                        order.append(extra)
        if _explicit_scheme_configured(ui_cfg) and candidates:
            matching = [
                eid for eid, endpoint in candidates.items()
                if eid and eid != exclude and endpoint_matches_explicit_routing(endpoint, ui_cfg)
            ]
            if matching:
                order = [eid for eid in order if eid in matching]
                for eid in matching:
                    if eid not in order:
                        order.append(eid)
        order = order[: 1 + PRECOLD_TARGET]
        if not order:
            return "skip"
        for eid in order:
            if active_tunnel_running() or manual_connection_active or is_connecting:
                break
            endpoint = _lookup_cold_endpoint(eid, candidates)
            if not endpoint:
                continue
            if _explicit_scheme_configured(ui_cfg) and not endpoint_matches_explicit_routing(endpoint, ui_cfg):
                log_to_json(
                    "INFO",
                    "Standby",
                    f"冷备不符合当前筛选，跳过 {_endpoint_ip(endpoint)}:{int(endpoint.get('port') or 0)}",
                )
                continue
            probed = _cold_port_open(endpoint)
            if probed is False:
                log_to_json("INFO", "Standby", f"冷备端口不可用，跳过 {_endpoint_ip(endpoint)}:{endpoint.get('port')}")
                _rotate_cold(eid, candidates)
                continue
            log_to_json(
                "INFO",
                "Standby",
                f"主连接未启动，冷备接管 {endpoint.get('protocol')} {_endpoint_ip(endpoint)}:{int(endpoint.get('port') or 0)}",
            )
            try:
                connect_ranked_endpoint(endpoint, fast=True)
            except Exception as exc:
                log_to_json("WARNING", "Standby", f"冷备接管失败 {eid}: {exc}")
                _rotate_cold(eid, candidates)
                continue
            if not active_tunnel_running():
                _rotate_cold(eid, candidates)
                continue
            _cold_promote_cooldown_until = 0.0
            _promote_next_cold(eid, candidates)
            if auto_direct:
                _engage_proxy_egress("冷备已接上，切回代理模式")
            return "up"
        _cold_promote_cooldown_until = time.time() + 180
        if proxy_server.get_egress_mode() == "proxy":
            _fallback_direct_egress("冷备与预冷备均不可用或切换失败")
        if proxy_server.get_egress_mode() == "direct":
            return "direct"
        return "skip"
    except Exception as exc:
        log_to_json("WARNING", "Standby", f"冷备接管异常: {exc}")
        return "skip"
    finally:
        _cold_promote_lock.release()


def _refill_unblocked_primary(ui_cfg: dict[str, Any]) -> None:
    if active_tunnel_running() or str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        return
    if is_connecting or manual_connection_active:
        return
    if time.time() - float(getattr(_refill_unblocked_primary, "at", 0) or 0) <= 180:
        return
    _refill_unblocked_primary.at = time.time()
    log_to_json("INFO", "Routing", "主连接空缺，改用未屏蔽节点")
    auto_switch_node()


def _cold_real_at(raw: Any) -> dict[str, float]:
    if not isinstance(raw, dict):
        return {}
    parsed: dict[str, float] = {}
    for key, value in raw.items():
        text = str(key or "").strip()
        if not text:
            continue
        try:
            parsed[text] = float(value or 0)
        except (TypeError, ValueError):
            continue
    return parsed


def _standby_real_ids(candidates: dict[str, dict[str, Any]]) -> list[str]:
    """Published cold, the five precold, then the next substitutes in this round."""
    cold = _cold_state()
    published = _cold_eid(str(cold.get("published") or ""))
    precold = [_cold_eid(item) for item in (cold.get("precold") or [])]
    bench: list[str] = []
    for eid in [published] + precold:
        if eid and eid not in bench and eid in candidates:
            bench.append(eid)
    failed = {str(item) for item in (cold.get("failed") or [])}
    order = [str(item) for item in (cold.get("order") or []) if str(item)] or list(candidates.keys())
    extras = 0
    for eid in order:
        if extras >= PRECOLD_TARGET:
            break
        if not eid or eid in bench or eid in failed or eid not in candidates:
            continue
        bench.append(eid)
        extras += 1
    return bench


def _standby_is_live(eid: str, endpoint: dict[str, Any] | None) -> bool:
    if eid and eid == str(active_pool_endpoint_id or ""):
        return True
    node_id = str(((endpoint or {}).get("metadata") or {}).get("node_id") or "")
    return bool(node_id and node_id == str(active_openvpn_node_id or ""))


def _standby_role_interval(eid: str, cold: dict[str, Any]) -> tuple[str, int]:
    """Cold is the only one on a 10 minute real check. The bench behind it waits longer."""
    published = _cold_eid(str(cold.get("published") or ""))
    if eid and eid == published:
        return "冷备", COLD_REAL_SECONDS
    precold_ids = {_cold_eid(item) for item in (cold.get("precold") or [])}
    if eid in precold_ids:
        return "预冷备", PRECOLD_REAL_SECONDS
    return "替补预冷备", SUBSTITUTE_REAL_SECONDS


def _light_check_spare_bench(candidates: dict[str, dict[str, Any]]) -> None:
    """One light probe each for precold and substitutes. Rotate a single dead spare."""
    if library_check_phase in ("running", "paused"):
        return
    if is_connecting or manual_connection_active or ui_query_active():
        return
    try:
        if proxy_server.proxy_forwarding_busy():
            return
    except Exception:
        return
    cold = _cold_state()
    published = _cold_eid(str(cold.get("published") or ""))
    bench = [eid for eid in _standby_real_ids(candidates) if eid and eid != published]
    for eid in bench:
        endpoint = candidates.get(eid) or {}
        if not endpoint or _standby_is_live(eid, endpoint):
            continue
        if _cold_port_open(endpoint) is not False:
            continue
        role, _interval = _standby_role_interval(eid, cold)
        log_to_json(
            "INFO",
            "Standby",
            f"{role}端口不可用，排到队尾 {_endpoint_ip(endpoint)}:{int(endpoint.get('port') or 0)}",
        )
        _rotate_cold(eid, candidates)
        cold = _cold_state()
        cold["precold"] = [item for item in (cold.get("precold") or []) if _cold_eid(item) != eid]
        _save_cold_state()
        chosen = _pick_cold(candidates)
        _publish_cold_standby(chosen)
        _remember_precold(candidates, str((chosen or {}).get("endpoint_id") or ""))
        return


def _verify_one_standby_real(candidates: dict[str, dict[str, Any]]) -> None:
    """At most one real tunnel plus a webpage. Cold every 10 minutes and it goes first.
    Precold every 20 minutes, substitutes every 40. Anyone except cold waits 3 minutes
    after the previous real tunnel, so the bench is not a scan.
    """
    if is_connecting or manual_connection_active or ui_command_plane.is_busy() or ui_query_active():
        return
    if library_check_phase in ("running", "paused"):
        return
    try:
        if proxy_server.proxy_forwarding_busy():
            return
    except Exception:
        return
    bench = _standby_real_ids(candidates)
    if not bench:
        return
    now = time.time()
    cold = _cold_state()
    real_at = dict(cold.get("real_at") or {})
    last_any = float(cold.get("last_real_any") or 0)
    gap_ok = (now - last_any) >= STANDBY_REAL_GAP_SECONDS
    chosen_eid = ""
    for eid in bench:
        endpoint = candidates.get(eid) or {}
        if _standby_is_live(eid, endpoint):
            continue
        role, interval = _standby_role_interval(eid, cold)
        if now - float(real_at.get(eid) or 0) < interval:
            continue
        if role != "冷备" and not gap_ok:
            continue
        chosen_eid = eid
        break
    if not chosen_eid:
        return
    eid = chosen_eid
    endpoint = candidates.get(eid) or {}
    protocol = str(endpoint.get("protocol") or "").lower()
    ok = False
    skipped = False
    message = ""
    try:
        if protocol == "openvpn":
            node_id = ensure_openvpn_node_from_pool(endpoint)
            node = test_node_by_id(node_id)
            message = str(node.get("probe_message") or "")
            if "让路" in message:
                skipped = True
            else:
                ok = str(node.get("probe_status") or "") == "available"
        else:
            result = probe_pool_endpoint(eid)
            if result.get("skipped"):
                skipped = True
                message = str(result.get("error") or "真实连接让路")
            else:
                ok = bool(result.get("ok"))
                message = str(result.get("message") or result.get("error") or "")
    except Exception as exc:
        ok = False
        message = str(exc)
    if skipped:
        cold = _cold_state()
        role, interval = _standby_role_interval(eid, cold)
        now_skip = time.time()
        cold["last_real_any"] = now_skip
        stamped = dict(cold.get("real_at") or {})
        stamped[eid] = now_skip - interval + STANDBY_REAL_GAP_SECONDS
        cold["real_at"] = stamped
        _save_cold_state()
        return
    label = f"{protocol} {_endpoint_ip(endpoint)}:{int(endpoint.get('port') or 0)}"
    cold = _cold_state()
    stamped = dict(cold.get("real_at") or {})
    stamped[eid] = time.time()
    cold["real_at"] = stamped
    cold["last_real_any"] = stamped[eid]
    _save_cold_state()
    role, _interval = _standby_role_interval(eid, cold)
    if ok:
        log_to_json("INFO", "Standby", f"{role}真实连接通过 {label} {message}")
        return
    log_to_json("INFO", "Standby", f"{role}真实连接未通过，换下一个 {label}: {message}")
    _rotate_cold(eid, candidates)
    cold = _cold_state()
    cold["precold"] = [item for item in (cold.get("precold") or []) if _cold_eid(item) != eid]
    _save_cold_state()
    chosen = _pick_cold(candidates)
    _publish_cold_standby(chosen)
    _remember_precold(candidates, str((chosen or {}).get("endpoint_id") or ""))


def cold_standby_pass() -> None:
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)) or str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        _publish_cold_standby(None)
        _cold_candidates.stats = {}
        _remember_precold({}, "")
        return
    if is_connecting or manual_connection_active or ui_command_plane.is_busy():
        return
    if ui_query_active():
        if (
            not active_tunnel_running()
            and not proxy_server.proxy_forwarding_busy()
        ):
            promote_cold_standby_to_main()
        return
    current = current_active_routing_endpoint()
    manual_hold = bool(manual_route_pin) and active_tunnel_running()
    if (
        not manual_hold
        and active_tunnel_running()
        and current
        and _explicit_scheme_configured(ui_cfg)
        and not endpoint_matches_explicit_routing(current, ui_cfg)
        and not endpoint_is_unstable(current)
    ):
        now_scheme = time.time()
        if now_scheme - float(getattr(cold_standby_pass, "scheme_at", 0) or 0) > 60:
            cold_standby_pass.scheme_at = now_scheme
            if enter_explicit_scheme(immediate=True):
                return
    if current and endpoint_is_blocked(current, ui_cfg) and not manual_hold:
        blocked_eid = str(current.get("endpoint_id") or "")
        log_to_json("INFO", "Routing", f"屏蔽节点退出主连接 {_endpoint_ip(current)}")
        if not try_unified_failover(exclude_endpoint_id=blocked_eid, attempts=4):
            auto_switch_node()
        return
    candidates = _cold_candidates(ui_cfg)
    if candidates is None:
        return
    _open_cold_round(candidates)
    chosen: dict[str, Any] | None = None
    for _ in range(3):
        chosen = _pick_cold(candidates)
        if not chosen:
            break
        probed = _cold_port_open(chosen)
        if probed is False:
            eid = str(chosen.get("endpoint_id") or "")
            log_to_json("INFO", "Standby", f"冷备端口不可用，排到队尾 {_endpoint_ip(chosen)}:{chosen.get('port')}")
            _rotate_cold(eid, candidates)
            chosen = None
            continue
        break
    if chosen is None and any(
        eid not in set(_cold_state().get("failed") or []) for eid in candidates
    ):
        chosen = _pick_cold(candidates)
    _publish_cold_standby(chosen)
    _remember_precold(candidates, str((chosen or {}).get("endpoint_id") or ""))
    if active_tunnel_running() and not proxy_server.proxy_forwarding_busy():
        _light_check_spare_bench(candidates)
        _verify_one_standby_real(candidates)
    if active_tunnel_running() or proxy_server.proxy_forwarding_busy():
        if active_tunnel_running() and proxy_server.get_egress_mode() == "direct" and _auto_direct_fallback_active():
            _engage_proxy_egress("备用已接上，切回代理模式")
        return
    if is_connecting or manual_connection_active or ui_command_plane.is_busy():
        return
    if str(ui_cfg.get("routing_mode") or "") == "fixed_ip":
        return
    outcome = promote_cold_standby_to_main(candidates=candidates)
    if outcome in ("up", "direct", "busy", "cooldown"):
        return
    if proxy_server.get_egress_mode() == "proxy":
        _refill_unblocked_primary(ui_cfg)


def cold_standby_loop() -> None:
    """Keep one cold standby and up to five precold. Promote when the main tunnel is down."""
    time.sleep(4)
    while True:
        try:
            favorite_connectivity_pass()
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"收藏连通检测失败: {exc}")
        try:
            cold_standby_pass()
        except Exception as exc:
            log_to_json("WARNING", "Standby", f"冷备维护失败: {exc}")
        time.sleep(COLD_PORT_SECONDS)


FAVORITE_PROBE_SECONDS = 3600


def favorite_connectivity_pass() -> None:
    """Check one saved favorite per hour. Does not touch the live tunnel while it is busy."""
    if is_connecting or manual_connection_active or ui_command_plane.is_busy() or ui_query_active():
        return
    ui_cfg = load_ui_config()
    raw_ids = [str(item).strip() for item in (ui_cfg.get("favorite_node_ids") or []) if str(item or "").strip()]
    if not raw_ids:
        return
    try:
        stamp = read_json(DATA_DIR / "favorite_probe.json", {})
    except Exception:
        stamp = {}
    if not isinstance(stamp, dict):
        stamp = {}
    now = time.time()
    due = [item for item in raw_ids if now - float(stamp.get(item) or 0) >= FAVORITE_PROBE_SECONDS]
    if not due:
        return
    node_id = due[0]
    endpoint_id = node_id[5:] if node_id.startswith("pool:") else node_id
    endpoint = None
    try:
        endpoint = node_pool.get_endpoint(endpoint_id)
    except Exception:
        endpoint = None
    if endpoint is None:
        stamp[node_id] = now
        try:
            write_json(DATA_DIR / "favorite_probe.json", stamp)
        except Exception:
            pass
        return
    if proxy_server.proxy_forwarding_busy():
        return
    result = light_probe_endpoint_id(endpoint_id)
    stamp[node_id] = now
    try:
        write_json(DATA_DIR / "favorite_probe.json", stamp)
    except Exception:
        pass
    if result.get("inconclusive"):
        log_to_json("INFO", "Standby", f"收藏连通检测不算不可用 {endpoint_id}: {result.get('message') or ''}")
    elif result.get("ok"):
        log_to_json("INFO", "Standby", f"收藏连通检测通过 {endpoint_id}")
    else:
        log_to_json("INFO", "Standby", f"收藏连通检测未通过 {endpoint_id}: {result.get('message') or result.get('error') or ''}")

def _manual_smooth_openvpn_switch(node: dict[str, Any], ui_cfg: dict[str, Any]) -> str:
    """Make-before-break manual OpenVPN switch with rollback before the new route is committed."""
    global active_openvpn_process, active_openvpn_node_id, active_external_tunnel
    global active_pool_endpoint_id, connection_generation, active_connection_generation

    node_id = str(node.get("id") or "")
    config_path = Path(node["config_file"])
    CONFIG_DIR.mkdir(exist_ok=True, parents=True)
    config_text = _prefer_openvpn_ip(node.get("config_text") or "", node)
    config_path.write_text(config_text, encoding="utf-8")

    old_openvpn_process = active_openvpn_process
    old_openvpn_node_id = str(active_openvpn_node_id or "")
    old_external_tunnel = active_external_tunnel
    old_iface = str(proxy_server.get_active_interface() or "")
    old_gateway = str(getattr(old_external_tunnel, "gateway", "") or "")
    candidate_token = re.sub(r"[^a-z0-9]", "", node_id.lower())[:8] or uuid.uuid4().hex[:8]
    candidate_dev = f"tun-sw-{candidate_token}"[:15]

    set_state(
        manual_switch_active=True,
        pending_connection_id=node_id,
        pending_connection_pool_endpoint_id="",
        pending_connection_protocol="openvpn",
        pending_connection_country=str(node.get("country") or ""),
        pending_connection_address=(
            str(node.get("ip") or node.get("remote_host") or node_id)
            + (f":{parse_int(node.get('remote_port'))}" if parse_int(node.get("remote_port")) else "")
        ),
        manual_switch_message="正在建立候选 OpenVPN 隧道，当前连接保持在线…",
        last_check_message=f"正在建立候选 OpenVPN 节点 {node_id}…",
    )

    adopted = take_standby(node_id) if str(standby_slot.get("node_id") or "") == node_id else None
    candidate_egress: dict[str, Any] = {"ok": True, "latency_ms": 0, "ip": ""}
    if adopted and adopted.get("process") is not None:
        candidate_process = adopted["process"]
        candidate_dev = str(adopted.get("dev") or standby_device())
        set_state(
            standby_ready=False,
            standby_node_id="",
            manual_switch_message="热备隧道已在线，正在接管 8500…",
            last_check_message=f"热备隧道已在线，直接切换 {node_id}",
        )
    else:
        ok, message, candidate_process = run_openvpn_until_ready(
            str(config_path), keep_alive=True, route_nopull=True, timeout=5, dev=candidate_dev
        )
        if not ok or candidate_process is None:
            raise RuntimeError(message or "候选 OpenVPN 隧道建立失败")
        if not tunnel_adapters.interface_has_ipv4(candidate_dev):
            stop_process(candidate_process)
            raise RuntimeError("候选 OpenVPN 隧道已启动，但未获得 IPv4 地址")
        candidate_egress = {"ok": True, "latency_ms": 0, "ip": str(node.get("ip") or "")}
        set_state(
            manual_switch_message="隧道已建立，正在接管…",
            last_check_message="未做网页检测，直接接管",
        )

    set_state(
        manual_switch_message="隧道已建立，正在接管 8500…",
        last_check_message="未做网页检测，直接切换出口",
    )

    cleanup_policy_routing()
    cleanup_probe_policy_routing(101)
    proxy_server.set_active_interface(candidate_dev)
    setup_policy_routing(candidate_dev)
    final_health = {"ok": True, "ip": "", "latency_ms": 0}

    if old_external_tunnel is not None:
        try:
            details = old_external_tunnel.details or {}
            if old_external_tunnel.protocol == "softether":
                tunnel_adapters.SoftEtherAdapter().disconnect(
                    account=str(details.get("account") or "aimili"),
                    nic=str(details.get("nic") or "aimili"),
                    delete=True,
                    added_routes=details.get("added_host_routes") or [],
                )
            elif old_external_tunnel.protocol == "sstp":
                tunnel_adapters.SSTPAdapter.disconnect(
                    old_external_tunnel.process,
                    added_routes=details.get("added_host_routes") or [],
                )
            elif old_external_tunnel.protocol == "l2tp-ipsec":
                l2tp_adapter.disconnect(old_external_tunnel.namespace or "aimili-l2tp-prod")
        except Exception as exc:
            log_to_json("WARNING", "VPN", f"旧多协议隧道清理失败（新连接已接管）: {exc}")
    elif old_openvpn_process is not None and old_openvpn_process is not candidate_process:
        retire_process_later(old_openvpn_process, 20)

    if old_openvpn_node_id and old_openvpn_node_id != node_id:
        old_node = next((x for x in read_nodes() if x.get("id") == old_openvpn_node_id), None)
        if old_node:
            try:
                old_cfg = Path(old_node.get("config_file") or "")
                if old_cfg.exists() and old_cfg != config_path:
                    old_cfg.unlink()
            except Exception:
                pass

    active_external_tunnel = None
    active_pool_endpoint_id = ""
    active_openvpn_process = candidate_process
    active_openvpn_node_id = node_id
    connection_generation += 1
    active_connection_generation = connection_generation

    nodes = read_nodes()
    for item in nodes:
        item["active"] = item.get("id") == node_id
        if item["active"]:
            _ph = f"[{LOCAL_PROXY_HOST}]" if ":" in LOCAL_PROXY_HOST else LOCAL_PROXY_HOST
            item["probe_message"] = f"Active node. HTTP proxy: http://{_ph}:{LOCAL_PROXY_PORT}"
            item["probe_status"] = "available"
            item["latency_ms"] = int(final_health.get("latency_ms") or candidate_egress.get("latency_ms") or 0)
    write_json(NODES_FILE, nodes)

    latency = parse_int(final_health.get("latency_ms")) or parse_int(candidate_egress.get("latency_ms")) or 0
    active_summary = {
        "id": node_id,
        "country": node.get("country", ""),
        "location": node.get("location", ""),
        "ip": node.get("ip") or node.get("remote_host") or "",
        "remote_host": node.get("remote_host") or node.get("ip") or "",
        "remote_port": node.get("remote_port") or 0,
        "protocol": node.get("protocol") or "openvpn",
        "owner": node.get("owner") or node.get("as_name") or "",
        "ip_type": node.get("ip_type") or "",
        "latency_ms": latency,
    }
    set_state(
        active_openvpn_node_id=node_id,
        active_openvpn_node=active_summary,
        active_pool_endpoint_id="",
        active_pool_endpoint={},
        active_tunnel_protocol="openvpn",
        active_tunnel_interface=candidate_dev,
        proxy_ok=True,
        proxy_ip=final_health.get("ip") or candidate_egress.get("ip") or "",
        proxy_latency_ms=latency,
        proxy_error="",
        active_node_latency=(f"{latency} ms" if latency else "出口已连接，等待延迟"),
        last_check_message=f"Connected {node_id}",
        manual_switch_message="切换完成",
    )
    set_manual_route_pin(protocol="openvpn", node_id=node_id, country=str(node.get("country") or ""))
    align_proxy_settings_to_manual(str(node.get("country") or ""), str(node.get("ip_type") or ""), protocol="openvpn")
    return f"Connected {node_id} (smooth switch)"

def connect_node(node_id: str, enable_connection: bool = False, manual: bool = False, fast: bool = False) -> str:
    global active_openvpn_process, active_openvpn_node_id, is_connecting, manual_connection_active, manual_connection_epoch, connection_generation, active_connection_generation
    node_id = str(node_id or "").strip()
    quick = bool(fast or manual)
    if not node_id:
        raise ValueError("Node id is required")
    stopped_existing = False
    manual_guard = False
    if manual:
        if not manual_connection_lock.acquire(blocking=False):
            raise RuntimeError("已有人工连接操作正在执行，请等待当前切换完成")
        manual_guard = True
        with lock:
            if manual_connection_active:
                manual_connection_lock.release()
                manual_guard = False
                raise RuntimeError("当前已有手动连接任务正在运行，请稍候")
            manual_connection_epoch += 1
            manual_connection_active = True
        set_state(
            manual_switch_active=True,
            manual_switch_started_at=time.time(),
            pending_connection_id=node_id,
            pending_connection_pool_endpoint_id="",
            pending_connection_protocol="openvpn",
            manual_switch_message="正在准备 OpenVPN 切换…",
            last_check_message="已开始人工切换，正在准备目标节点…",
        )
    if manual and manual_guard:
        try:
            _wait_for_automatic_connection_idle()
        except Exception:
            with lock:
                manual_connection_active = False
            manual_connection_lock.release()
            manual_guard = False
            raise
    with lock:
        if is_connecting and not manual:
            if manual_guard:
                manual_connection_active = False
                manual_connection_lock.release()
                manual_guard = False
            print("[连接] 正在建立其他连接中，跳过此请求", flush=True)
            raise RuntimeError("当前已有连接或节点检测任务正在运行，请稍后再试")
        is_connecting = True
        set_state(is_connecting=True, manual_connection_active=manual_connection_active, active_node_latency="正在连接", last_check_message=f"正在初始化连接配置: {node_id}")

    try:
        log_to_json("INFO", "VPN", f"开始连接节点: {node_id}")

        nodes = read_nodes()
        node = next((item for item in nodes if item.get("id") == node_id), None)
        if not node:
            with _nodes_index_lock:
                if _nodes_index is not None:
                    node = _nodes_index.get(node_id)
            if node:
                nodes.append(dict(node))
        if not node:
            raise ValueError(f"Node not found: {node_id}")

        if manual:
            set_state(
                manual_switch_active=True,
                pending_connection_id=node_id,
                pending_connection_pool_endpoint_id="",
                pending_connection_protocol="openvpn",
                pending_connection_country=str(node.get("country") or ""),
                pending_connection_address=(
                    str(node.get("ip") or node.get("remote_host") or node_id)
                    + (f":{parse_int(node.get('remote_port'))}" if parse_int(node.get('remote_port')) else "")
                ),
                manual_switch_message="正在准备 OpenVPN 安全隧道…",
                last_check_message=f"正在切换至 OpenVPN 节点 {node_id}，请稍候…",
            )

        ui_cfg = load_ui_config()
        validate_node_allowed_by_routing(node, ui_cfg)
        if not enable_connection and not ui_cfg.get("connection_enabled", True):
            raise RuntimeError("连接已被用户禁用，拒绝后台自动重连")
        if enable_connection:
            auth_file = DATA_DIR / "ui_auth.json"
            with lock:
                DATA_DIR.mkdir(exist_ok=True, parents=True)
                latest_cfg = load_ui_config()
                latest_cfg["connection_enabled"] = True
                if latest_cfg.get("routing_mode") == "fixed_ip":
                    latest_cfg["fixed_node_id"] = node_id
                ui_cfg = latest_cfg
                write_json(auth_file, ui_cfg)

        if manual and active_tunnel_running():
            return _manual_smooth_openvpn_switch(node, ui_cfg)

        if manual:
            set_state(manual_switch_message="正在建立候选连接，当前 VPN 暂不受影响…")
        set_state(active_node_latency="清理连接", last_check_message="正在准备新的 OpenVPN 连接…")
        stop_all_tunnels()
        stopped_existing = True
        with lock:
            active_openvpn_node_id = node_id
        set_state(
            active_openvpn_node_id=node_id,
            active_openvpn_node=_openvpn_status_node(node_id),
            active_pool_endpoint_id="",
            active_pool_endpoint={},
            active_tunnel_protocol="openvpn",
            is_connecting=True,
            last_check_message=f"正在连接 {node.get('ip') or node.get('remote_host') or node_id}",
        )

        set_state(active_node_latency="写入配置", last_check_message="正在写入 OpenVPN 节点配置文件...")
        config_path = Path(node["config_file"])
        try:
            CONFIG_DIR.mkdir(exist_ok=True, parents=True)
            config_text = _prefer_openvpn_ip(node.get("config_text") or "", node)
            config_path.write_text(config_text, encoding="utf-8")
        except Exception as e:
            raise RuntimeError(f"Failed to write configuration: {e}")

        set_state(active_node_latency="启动核心", last_check_message="正在启动 OpenVPN Core 核心服务并建立连接...", manual_switch_message=("正在建立 OpenVPN 安全隧道…" if manual else ""))
        ok, message, process = run_openvpn_until_ready(
            str(node["config_file"]), keep_alive=True, route_nopull=True, timeout=(5 if quick else None)
        )
        if not ok or process is None:
            try:
                if config_path.exists():
                    config_path.unlink()
            except Exception:
                pass
            node["probe_status"] = "unavailable"
            node["probe_message"] = message
            for item in nodes:
                item["active"] = False
            write_json(NODES_FILE, nodes)
            log_to_json("ERROR", "VPN", f"连接节点 {node_id} 失败: {message}")
            print(f"[连接核心失败] 无法与 VPN 节点 {node_id} 建立隧道连接！详情: {message}", flush=True)
            set_state(active_openvpn_node_id="", is_connecting=False, active_node_latency="无活动连接", last_check_message=f"连接失败: {message}")
            with lock:
                active_openvpn_node_id = ""
            raise RuntimeError(message)

        with lock:
            active_openvpn_process = process
            active_openvpn_node_id = node_id
            connection_generation += 1
            active_connection_generation = connection_generation

        proxy_server.set_active_interface("tun0")
        set_state(active_tunnel_protocol="openvpn", active_tunnel_interface="tun0")
        if manual:
            set_state(manual_switch_message="隧道已建立，正在接管…", last_check_message="未做网页检测，直接接管")
        set_state(active_node_latency="配置路由", last_check_message="正在配置策略路由规则与流量转发...")
        setup_policy_routing("tun0")

        global last_active_ping_time, last_active_latency
        last_active_ping_time = time.time()
        last_active_latency = 0

        set_state(
            active_node_latency="接管出口",
            last_check_message=("隧道已建立，未做网页检测" if quick else "正在测试本地代理出站联通性与出口 IP..."),
        )

        for item in nodes:
            item["active"] = item.get("id") == node_id
            if item["active"]:
                _ph = f"[{LOCAL_PROXY_HOST}]" if ":" in LOCAL_PROXY_HOST else LOCAL_PROXY_HOST
                item["probe_message"] = f"Active node. HTTP proxy: http://{_ph}:{LOCAL_PROXY_PORT}"
        write_json(NODES_FILE, nodes)

        if quick:
            res = {"ok": True, "ip": "", "latency_ms": 0}
        else:
            set_state(last_check_message="正在测试本地代理出站联通性与出口 IP...")
            res = check_proxy_health()
        if res["ok"]:
            last_active_latency = parse_int(res.get("latency_ms")) or 0
            set_state(
                proxy_ok=True,
                proxy_ip=res["ip"],
                proxy_latency_ms=res["latency_ms"],
                active_node_latency=(f"{last_active_latency} ms" if last_active_latency > 0 else "出口已连接，等待延迟"),
                proxy_error=""
            )
        else:
            error_message = str(res.get("error") or "网页出口检测失败")
            set_state(proxy_ok=False, proxy_ip="-", proxy_latency_ms=0, proxy_error=error_message)

            node["probe_status"] = "unavailable"
            node["probe_message"] = error_message
            for item in nodes:
                item["active"] = False
            write_json(NODES_FILE, nodes)
            raise RuntimeError("网页出口检测失败: " + error_message)

        latency_str = f"{last_active_latency} ms" if last_active_latency > 0 else "检测超时"
        if manual:
            set_state(manual_switch_message="切换完成", last_check_message="隧道已接管，未做网页检测")
            set_manual_route_pin(protocol="openvpn", node_id=node_id, country=str(node.get("country") or ""))
            align_proxy_settings_to_manual(str(node.get("country") or ""), str(node.get("ip_type") or ""), protocol="openvpn")
        set_state(active_openvpn_node_id=node_id, is_connecting=False, last_check_message=f"Connected {node_id}", active_node_latency=latency_str)
        log_to_json("INFO", "VPN", f"节点 {node_id} 连接成功，出口网卡 tun0 已启用")
        remember_live_connection(openvpn_node_id=node_id)
        return f"Connected {node_id}"
    except Exception as exc:
        if stopped_existing or (active_openvpn_node_id == node_id and not active_openvpn_running()):
            clear_active_connection_state(f"连接失败: {exc}")
        else:
            set_state(is_connecting=False, last_check_message=f"连接失败: {exc}")
        raise
    finally:
        with lock:
            is_connecting = False
            if manual_guard:
                manual_connection_active = False
        if manual_guard:
            manual_connection_lock.release()

PROBE_ROUTE_TABLE = 200

def cleanup_probe_policy_routing(table: int = PROBE_ROUTE_TABLE) -> None:
    try:
        subprocess.run(["ip", "rule", "del", "table", str(table)], capture_output=True, timeout=2)
    except Exception:
        pass
    try:
        subprocess.run(["ip", "route", "flush", "table", str(table)], capture_output=True, timeout=2)
    except Exception:
        pass

def setup_probe_policy_routing(interface: str, gateway: str = "", table: int = PROBE_ROUTE_TABLE) -> tuple[bool, str]:
    interface = str(interface or "").strip()
    gateway = str(gateway or "").strip()
    if not interface:
        return False, "缺少测试网卡"
    last_error = "临时策略路由建立失败"
    for _ in range(4):
        cleanup_probe_policy_routing(table)
        try:
            route_cmd = ["ip", "route", "replace", "default"]
            if gateway:
                route_cmd.extend(["via", gateway])
            route_cmd.extend(["dev", interface])
            if gateway:
                route_cmd.append("onlink")
            route_cmd.extend(["table", str(table)])
            route = subprocess.run(route_cmd, capture_output=True, text=True, timeout=3)
            if route.returncode != 0 and "File exists" not in (route.stderr or ""):
                raise RuntimeError((route.stderr or route.stdout or "route replace failed").strip())
            rule = subprocess.run(
                ["ip", "rule", "add", "oif", interface, "table", str(table)],
                capture_output=True, text=True, timeout=3,
            )
            if rule.returncode != 0 and "File exists" not in (rule.stderr or ""):
                raise RuntimeError((rule.stderr or rule.stdout or "rule add failed").strip())
            return True, ""
        except Exception as exc:
            last_error = str(exc)
            time.sleep(0.4)
    cleanup_probe_policy_routing(table)
    return False, last_error

def check_interface_egress(interface: str, gateway: str = "", table: int = PROBE_ROUTE_TABLE) -> dict[str, Any]:
    interface = str(interface or "").strip()
    if not interface:
        return {"ok": False, "error": "缺少测试网卡"}

    route_ok, route_error = setup_probe_policy_routing(interface, gateway, table=table)
    if not route_ok:
        return {"ok": False, "error": f"临时策略路由建立失败: {route_error}"}

    cmd = [
        "curl", "-4", "-k", "-sS", "-o", "/dev/null",
        "-w", "%{http_code} %{time_total}",
        "--interface", f"if!{interface}",
        "--connect-timeout", "3",
        "--max-time", "4",
    ]
    try:
        proven = None
        for url in ("https://8.8.8.8/resolve?name=example.com&type=A", "https://www.google.com/generate_204", "https://example.com/"):
            res = subprocess.run(cmd + [url], capture_output=True, text=True, timeout=6)
            parts = (res.stdout or "").strip().split()
            if res.returncode == 0 and len(parts) == 2 and parts[0] in {"200", "204", "301", "302"}:
                proven = {"ok": True, "ip": "", "latency_ms": int(float(parts[1]) * 1000)}
                break
        if not proven:
            diagnostics: list[str] = [f"gateway={gateway or '-'}", "connectivity=example.com/google unreachable"]
            for label, diag_cmd in [
                ("addr", ["ip", "-4", "addr", "show", "dev", interface]),
                ("probe_table", ["ip", "route", "show", "table", str(table)]),
                ("route_get", ["ip", "route", "get", "8.8.8.8", "oif", interface]),
            ]:
                try:
                    diag = subprocess.run(diag_cmd, capture_output=True, text=True, timeout=3)
                    diagnostics.append(f"{label}={(diag.stdout or diag.stderr).strip()[-400:]}")
                except Exception as exc:
                    diagnostics.append(f"{label}_error={exc}")
            return {"ok": False, "error": " | ".join(diagnostics)}
        ip_cmd = [
            "curl", "-4", "-sS",
            "--interface", f"if!{interface}",
            "-w", "\n%{http_code}",
            "http://api.ipify.org",
            "--connect-timeout", "2",
            "--max-time", "2",
        ]
        try:
            ip_res = subprocess.run(ip_cmd, capture_output=True, text=True, timeout=3)
            lines = (ip_res.stdout or "").strip().splitlines()
            if ip_res.returncode == 0 and len(lines) >= 2 and lines[-1].strip() == "200":
                ip = lines[0].strip()
                if re.fullmatch(r"\d+\.\d+\.\d+\.\d+", ip):
                    proven["ip"] = ip
        except Exception:
            pass
        return proven
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    finally:
        cleanup_probe_policy_routing(table)

def measure_interface_speed(interface: str, gateway: str = "", table: int = PROBE_ROUTE_TABLE) -> dict[str, Any]:
    """Speed downloads are disabled. GCP bills egress, and detection must not fetch them."""
    return {"ok": False, "skipped": True, "speed_bps": 0, "error": "测速已关闭，避免访问 Cloudflare 产生云出口流量"}

def measure_or_reuse_ip_speed(interface: str, endpoint_id: str, gateway: str = "", table: int = PROBE_ROUTE_TABLE) -> dict[str, Any]:
    """Run one real download speed test per current IP within the reuse window."""
    endpoint_id = str(endpoint_id or "").strip()
    if endpoint_id:
        try:
            cached = node_pool.get_cached_ip_speed(endpoint_id, SPEED_TEST_REUSE_SECONDS)
        except Exception:
            cached = {"hit": False, "speed_bps": 0}
        if cached.get("hit"):
            speed_bps = max(0, int(cached.get("speed_bps") or 0))
            return {
                "ok": speed_bps > 0,
                "speed_bps": speed_bps,
                "speed_mbps": round(speed_bps / 1_000_000, 1) if speed_bps > 0 else 0,
                "reused": True,
                "error": "" if speed_bps > 0 else "复用的最近一次 IP 测速结果为 0",
            }
    result = measure_interface_speed(interface, gateway=gateway, table=table)
    result["reused"] = False
    return result

def _acquire_probe_route_table() -> int | None:
    with probe_route_table_lock:
        if not probe_route_tables_free:
            return None
        return probe_route_tables_free.pop()

def _release_probe_route_table(table: int) -> None:
    cleanup_probe_policy_routing(table)
    with probe_route_table_lock:
        probe_route_tables_free.add(int(table))

def probe_pool_endpoint(endpoint_id: str) -> dict[str, Any]:
    """Real tunnel plus a webpage check. Catalog scans must not call this.

    Cold standby, precold, the substitute bench, and a manual 待检测 click do.
    """
    endpoint_id = str(endpoint_id or "").strip()
    if not endpoint_id:
        return {"ok": False, "error": "endpoint_id 为空"}
    if is_connecting or manual_connection_active:
        return {"ok": False, "skipped": True, "error": "生产连接正在切换，跳过后台探测"}
    if active_tunnel_running() and endpoint_id == str(active_pool_endpoint_id or ""):
        endpoint = node_pool.get_endpoint(endpoint_id) or {}
        if proxy_server.get_egress_mode() == "proxy" and bool(get_state().get("proxy_ok")):
            return {
                "ok": True,
                "skipped": True,
                "active": True,
                "latency_ms": int(float(endpoint.get("latency_ewma") or 0)),
                "speed_bps": int((endpoint.get("metadata") or {}).get("last_probe_speed_bps") or 0),
                "message": "代理模式由 8500 实际出口代表，不重复拨号",
            }
        return {
            "ok": False,
            "skipped": True,
            "active": True,
            "error": "隧道已连接，但当前是直连，不能把拨号成功当成代理可用",
        }
    if not protocol_probe_lock.acquire(blocking=False):
        return {"ok": False, "skipped": True, "error": "已有协议探测任务运行中"}

    endpoint = node_pool.get_endpoint(endpoint_id)
    if endpoint is None:
        protocol_probe_lock.release()
        return {"ok": False, "error": "端点不存在"}

    protocol = str(endpoint.get("protocol") or "").lower()
    metadata = endpoint.get("metadata") or {}
    host = str(metadata.get("hostname") or endpoint.get("hostname") or endpoint.get("current_ip") or "").strip()
    port = parse_int(endpoint.get("port"))
    token = re.sub(r"[^a-z0-9]", "", endpoint_id.lower())[:10] or uuid.uuid4().hex[:10]
    result: tunnel_adapters.TunnelResult | None = None
    cleanup = None
    started = time.perf_counter()

    try:
        if protocol == "softether" and active_tunnel_running() and active_external_tunnel is not None and str(active_external_tunnel.protocol or "") == "softether":
            return {"ok": False, "skipped": True, "error": "生产隧道正在使用 SoftEther，跳过并行探测以免打断 vpnclient"}
        if protocol == "softether":
            account = f"probe{token}"
            nic = f"p{token}"
            adapter = tunnel_adapters.SoftEtherAdapter()
            result = adapter.connect(
                host=host,
                port=port or 443,
                account=account,
                nic=nic,
                username="vpn",
                password="vpn",
            )
            cleanup = lambda: adapter.disconnect(
                account=account,
                nic=nic,
                delete=True,
                added_routes=((result.details or {}).get("added_host_routes") if result else []),
            )
        elif protocol == "sstp":
            adapter = tunnel_adapters.SSTPAdapter()
            target = host if port in (0, 443) else f"{host}:{port}"
            result = adapter.connect(
                target, username="vpn", password="vpn", timeout=20, reuse_existing=False
            )
            cleanup = lambda: tunnel_adapters.SSTPAdapter.disconnect(
                result.process if result else None,
                added_routes=((result.details or {}).get("added_host_routes") if result else []),
            )
        elif protocol == "l2tp-ipsec":
            namespace = f"aimili-l2tp-p{token}"[:31]
            result = l2tp_adapter.connect(
                host=host,
                username="vpn",
                password="vpn",
                psk="vpn",
                namespace=namespace,
                timeout=35,
            )
            cleanup = lambda: l2tp_adapter.disconnect(namespace)
        else:
            return {"ok": False, "skipped": True, "error": f"协议 {protocol} 暂不允许后台实连测试"}

        if result is None or not result.ok or not result.interface:
            message = result.message if result else "隧道未建立"
            lowered = message.lower()
            if "not installed" in lowered or "未安装" in message:
                return {"ok": False, "skipped": True, "protocol": protocol, "error": message}
            node_pool.record_endpoint_probe(endpoint_id, False, 0, message)
            return {"ok": False, "protocol": protocol, "error": message}

        egress_latency = 0
        if protocol == "l2tp-ipsec":
            ensure_l2tp_namespace_forward(result)
            inner = tunnel_adapters.L2TPIPsecAdapter.egress_check(result)
            if not inner.get("ok"):
                message = "L2TP 已拨通，但 PPP 出不了网"
                node_pool.mark_endpoint_degraded(endpoint_id, message)
                log_to_json("INFO", "Probe", f"L2TP inner PPP: FAIL {endpoint_id}")
                return {"ok": False, "protocol": protocol, "error": message}
            egress_latency = int(inner.get("latency_ms") or 0)
            forwarded = check_root_via_interface(str(result.interface or ""), str(result.gateway or ""))
            if not forwarded.get("ok"):
                note = "节点可用，本机转发未通过"
                node_pool.note_local_forward(endpoint_id, False, note)
                log_to_json("INFO", "Probe", f"L2TP inner PPP: OK; root→{result.interface}: FAIL {endpoint_id}")
            else:
                node_pool.note_local_forward(endpoint_id, True, "")
                log_to_json("INFO", "Probe", f"L2TP inner PPP: OK; root→{result.interface}: OK {endpoint_id}")
        elif protocol in ("softether", "sstp"):
            health = check_interface_egress(str(result.interface or ""), str(getattr(result, "gateway", "") or ""))
            if not health.get("ok"):
                message = "协议已连接，但隧道出不了网"
                node_pool.mark_endpoint_degraded(endpoint_id, message)
                log_to_json("INFO", "Probe", f"{protocol} tunnel egress FAIL {endpoint_id}")
                return {"ok": False, "protocol": protocol, "error": message}
            egress_latency = int(health.get("latency_ms") or 0)

        latency_ms = egress_latency if 0 < egress_latency <= 1500 else 0
        forward_failed = protocol == "l2tp-ipsec" and not forwarded.get("ok")
        probe_message = (
            f"{protocol} 隧道可上网，本机转发未通过"
            if forward_failed
            else f"{protocol} 隧道可上网 {latency_ms} ms"
        )
        node_pool.record_endpoint_probe(
            endpoint_id, True, latency_ms, probe_message, speed_bps=None
        )
        return {
            "ok": True,
            "protocol": protocol,
            "interface": result.interface,
            "latency_ms": latency_ms,
            "speed_bps": 0,
            "message": probe_message,
        }
    except Exception as exc:
        try:
            node_pool.record_endpoint_probe(endpoint_id, False, 0, str(exc))
        except Exception:
            pass
        return {"ok": False, "protocol": protocol, "error": str(exc)}
    finally:
        if cleanup is not None:
            try:
                cleanup()
            except Exception:
                pass
        protocol_probe_lock.release()

def protocol_probe_loop() -> None:
    """Scheduled global library check. Not a continuous scan."""
    time.sleep(20)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        try:
            maybe_start_scheduled_library_check()
        except Exception as exc:
            log_to_json("ERROR", "Probe", f"全球库定时检测异常: {exc}")
        time.sleep(30)


def openvpn_pool_endpoint_id(node: dict[str, Any] | None) -> str:
    if not node:
        return ""
    try:
        key = node_pool.server_key(node)
        return node_pool.endpoint_id(
            key,
            "openvpn",
            str(node.get("proto") or "unknown").lower(),
            parse_int(node.get("remote_port")),
        )
    except Exception:
        return ""

def ensure_openvpn_node_from_pool(endpoint: dict[str, Any]) -> str:
    """Rehydrate a historical OpenVPN Master-Pool endpoint into nodes.json for connection."""
    metadata = endpoint.get("metadata") or {}
    server_meta = endpoint.get("server_metadata") or {}
    endpoint_id = str(endpoint.get("endpoint_id") or "").strip()
    node_id = str(metadata.get("node_id") or "").strip()
    if not node_id:
        transport = str(endpoint.get("transport") or "tcp").lower()
        ip = str(endpoint.get("current_ip") or "").strip()
        port = int(endpoint.get("port") or 0)
        country = endpoint.get("country") or "XX"
        node_id = safe_name(f"{country}_{ip}_{port}_{transport}")
    if node_id and node_id in _nodes_index_get():
        return node_id
    config_file = str(endpoint.get("config_ref") or metadata.get("config_file") or "").strip()
    config_text = ""
    if config_file:
        try:
            config_text = Path(config_file).read_text(encoding="utf-8")
        except Exception:
            config_text = ""
    host = str(endpoint.get("hostname") or endpoint.get("current_ip") or "").strip()
    port = int(endpoint.get("port") or 0)
    transport = str(endpoint.get("transport") or "tcp").lower()
    if not config_text:
        config_text = _manual_openvpn_template()
        if not config_text:
            raise RuntimeError(f"OpenVPN Pool 端点 {endpoint_id} 缺少配置文件，且当前实例没有可用模板")
        config_text = re.sub(r"(?m)^remote\s+\S+\s+\d+\s*$", f"remote {host} {port}", config_text, count=1)
        config_text = re.sub(r"(?m)^proto\s+\S+\s*$", f"proto {transport}", config_text, count=1)
        config_dir = CONFIG_DIR
        config_dir.mkdir(exist_ok=True, parents=True)
        config_file = str(config_dir / f"{node_id}.ovpn")
        try:
            Path(config_file).write_text(config_text, encoding="utf-8")
        except Exception:
            pass
    endpoint_status = str(endpoint.get("status") or "").upper()
    real_probe_at = float(endpoint.get("last_success") or 0)
    real_latency = int(endpoint.get("latency_ewma") or 0)
    is_realtime_verified = endpoint_status in ("HOT", "AVAILABLE") and real_probe_at > 0 and real_latency > 0
    node = {
        "id": node_id,
        "country": endpoint.get("country") or "",
        "country_short": "",
        "host_name": endpoint.get("hostname") or host,
        "ip": endpoint.get("current_ip") or host,
        "score": int(endpoint.get("latest_server_score") or 0),
        "ping": int(endpoint.get("latest_ping") or 0),
        "speed": int(endpoint.get("latest_speed") or (endpoint.get("metadata") or {}).get("last_probe_speed_bps") or server_meta.get("last_ip_speed_bps") or 0),
        "speed_bps": int(endpoint.get("latest_speed") or (endpoint.get("metadata") or {}).get("last_probe_speed_bps") or server_meta.get("last_ip_speed_bps") or 0),
        "sessions": int(endpoint.get("latest_sessions") or 0),
        "owner": str(server_meta.get("owner") or ""),
        "asn": str(server_meta.get("asn") or ""),
        "as_name": str(server_meta.get("as_name") or ""),
        "location": str(server_meta.get("location") or endpoint.get("country") or ""),
        "ip_type": str(server_meta.get("ip_type") or ""),
        "quality": str(server_meta.get("quality") or ""),
        "latency_ms": real_latency if is_realtime_verified else 0,
        "config_file": config_file,
        "config_text": config_text,
        "proto": transport,
        "protocol": "openvpn",
        "remote_host": host,
        "remote_port": port,
        "fetched_at": time.time(),
        "probe_status": "available" if is_realtime_verified else "not_checked",
        "probe_message": "已完成真实 OpenVPN 隧道测速" if is_realtime_verified else "来自 Master Pool 的资源，等待真实 OpenVPN 隧道测速",
        "probed_at": real_probe_at,
        "pool_endpoint_id": endpoint_id,
        "pool_rehydrated": True,
    }
    _remember_openvpn_node(node)
    schedule_nodes_probe_flush({node_id: node})
    return node_id

def _endpoint_physical_key(endpoint: dict[str, Any] | None, endpoint_id: str) -> tuple[str, str, int]:
    if not isinstance(endpoint, dict):
        return ("", endpoint_id, 0)
    metadata = endpoint.get("metadata") or {}
    protocol = str(endpoint.get("protocol") or "").strip().lower()
    host = str(
        endpoint.get("current_ip")
        or metadata.get("ip")
        or endpoint.get("hostname")
        or metadata.get("hostname")
        or ""
    ).strip().lower()
    return (protocol, host, parse_int(endpoint.get("port")))


def connect_pool_endpoint_with_fallback(endpoint_ids: list[str], manual: bool = False, fast: bool = False) -> str:
    quick = bool(fast or manual)
    ids = list(dict.fromkeys(str(x or "").strip() for x in endpoint_ids if str(x or "").strip()))
    if not ids:
        raise ValueError("没有可连接的协议端点")
    if manual:
        # The clicked row already merged duplicate catalog sources of the same
        # protocol/IP/port. Trying each id again spends another 35s on one L2TP.
        clicked = ids[0]
        try:
            clicked_endpoint = node_pool.get_endpoint(clicked)
        except Exception:
            clicked_endpoint = None
        clicked_key = _endpoint_physical_key(clicked_endpoint, clicked)
        ids = [clicked]
        log_to_json("INFO", "VPN", f"人工切换只尝试 {clicked_key[0] or '-'} {clicked_key[1] or clicked}:{clicked_key[2] or '-'}")
    errors: list[str] = []
    started = time.monotonic()
    for endpoint_id in ids:
        if quick and time.monotonic() - started > 8:
            errors.append("5秒内没有连上")
            break
        if manual and time.monotonic() - started > 50:
            errors.append("已超过人工切换时间预算")
            break
        try:
            endpoint = node_pool.get_endpoint(endpoint_id)
            if endpoint is not None and str(endpoint.get("protocol") or "").lower() == "openvpn":
                return connect_ranked_endpoint(endpoint, manual=manual, fast=quick)
            return connect_pool_endpoint(endpoint_id, manual=manual, fast=quick)
        except Exception as exc:
            errors.append(f"{endpoint_id[:10]}: {exc}")
            continue
    raise RuntimeError("人工切换失败，已停止重试：" + " | ".join(errors[-3:]) if manual else "已尝试该 IP/协议的全部候选端点，均未连接成功：" + " | ".join(errors[-4:]))

def connect_ranked_endpoint(endpoint: dict[str, Any], manual: bool = False, fast: bool = False) -> str:
    quick = bool(fast or manual)
    protocol = str(endpoint.get("protocol") or "").lower()
    if protocol == "openvpn":
        node_id = ensure_openvpn_node_from_pool(endpoint)
        return connect_node(node_id, manual=manual, fast=quick)
    return connect_pool_endpoint_with_fallback(
        [str(endpoint.get("endpoint_id") or "")],
        manual=manual,
        fast=quick,
    )

def restore_manual_previous_connection(previous_openvpn_node_id: str = "", previous_pool_endpoint_id: str = "") -> tuple[bool, str]:
    """Restore the connection that existed before a manual switch failed.
    This is deliberately a manual rollback, not an automatic failover.
    """
    try:
        previous_pool_endpoint_id = str(previous_pool_endpoint_id or "").strip()
        previous_openvpn_node_id = str(previous_openvpn_node_id or "").strip()
        if previous_pool_endpoint_id:
            if active_pool_endpoint_id == previous_pool_endpoint_id and active_tunnel_running():
                return True, "原多协议连接保持不变"
            return True, connect_pool_endpoint(previous_pool_endpoint_id, manual=True)
        if previous_openvpn_node_id:
            if active_openvpn_node_id == previous_openvpn_node_id and active_tunnel_running():
                return True, "原 OpenVPN 连接保持不变"
            return True, connect_node(previous_openvpn_node_id, manual=True)
    except Exception as exc:
        return False, str(exc)
    return False, "之前没有可恢复的活动连接"

def endpoint_allowed_by_pool_routing(endpoint: dict[str, Any], ui_cfg: dict[str, Any]) -> bool:
    # Favorites are a preference, never a hard lock.
    return ui_cfg.get("routing_mode", "auto") != "fixed_ip"

def try_unified_failover(exclude_endpoint_id: str = "", attempts: int = 4, preferred_only: bool = False, manual: bool = False) -> bool:
    if ui_command_plane.is_busy() and not manual:
        return False
    if not failover_lock.acquire(blocking=False):
        return True
    started = time.time()
    ui_cfg = load_ui_config()
    if not bool(ui_cfg.get("connection_enabled", True)):
        failover_lock.release()
        return False
    if manual_connection_active and not manual:
        failover_lock.release()
        return False
    from_protocol = ""
    from_endpoint = ""
    if active_external_tunnel is not None:
        from_protocol = str(active_external_tunnel.protocol or "")
        from_endpoint = str(active_pool_endpoint_id or "")
    elif active_openvpn_running():
        from_protocol = "openvpn"
        from_endpoint = str(active_openvpn_node_id or "")

    hot_pool = [
        ep for ep in unified_hot_pool_candidates(ui_cfg, exclude_endpoint_id=exclude_endpoint_id, limit=100)
        if endpoint_allowed_by_pool_routing(ep, ui_cfg)
    ]
    if preferred_only:
        hot_pool = [ep for ep in hot_pool if int(ep.get("routing_tier") or 99) == 0]
    set_state(
        failover_in_progress=True,
        failover_started_at=started,
        failover_from_protocol=from_protocol,
        failover_from_endpoint=from_endpoint,
        failover_candidate_count=len(hot_pool),
        failover_preferred_only=preferred_only,
    )
    last_error = ""
    for endpoint in hot_pool[:max(1, attempts)]:
        try:
            connect_ranked_endpoint(endpoint, manual=manual)
            if not bool(load_ui_config().get("connection_enabled", True)):
                stop_all_tunnels()
                set_state(failover_in_progress=False, last_failover_ok=False, last_failover_error="用户已手动断开连接")
                failover_lock.release()
                return False
            duration_ms = int((time.time() - started) * 1000)
            set_state(
                hot_pool_size=len(hot_pool),
                hot_pool_selected_score=endpoint.get("selection_score", 0),
                failover_selected_tier=int(endpoint.get("routing_tier") or 0),
                failover_in_progress=False,
                last_failover_ok=True,
                last_failover_at=time.time(),
                last_failover_duration_ms=duration_ms,
                last_failover_from_protocol=from_protocol,
                last_failover_from_endpoint=from_endpoint,
                last_failover_to_protocol=str(endpoint.get("protocol") or ""),
                last_failover_to_endpoint=str(endpoint.get("endpoint_id") or ""),
                last_failover_error="",
            )
            log_to_json("INFO", "VPN", f"统一 Hot Pool 切换成功 tier={endpoint.get('routing_tier')} {from_protocol or '-'} -> {endpoint.get('protocol')}，耗时 {duration_ms} ms")
            failover_lock.release()
            return True
        except Exception as exc:
            last_error = str(exc)
            log_to_json("WARNING", "VPN", f"统一 Hot Pool 切换失败 {endpoint.get('protocol')} {endpoint.get('endpoint_id')}: {exc}")
    duration_ms = int((time.time() - started) * 1000)
    set_state(
        failover_in_progress=False,
        last_failover_ok=False,
        last_failover_at=time.time(),
        last_failover_duration_ms=duration_ms,
        last_failover_from_protocol=from_protocol,
        last_failover_from_endpoint=from_endpoint,
        last_failover_to_protocol="",
        last_failover_to_endpoint="",
        last_failover_error=last_error or "无可用 Hot Pool 候选",
    )
    failover_lock.release()
    return False


def _global_country_pool_snapshot() -> dict[str, dict[str, set[str]]]:
    """Build one in-memory country inventory snapshot from the persistent pool."""
    result: dict[str, dict[str, set[str]]] = {}
    def add(country: Any, ip: Any, available: bool) -> None:
        name = normalized_country_name(country)
        value = str(ip or "").strip()
        if not name or not value:
            return
        bucket = result.setdefault(name, {"inventory": set(), "available": set()})
        bucket["inventory"].add(value)
        if available:
            bucket["available"].add(value)

    for node in read_nodes():
        add(
            node.get("country"),
            node.get("ip") or node.get("remote_host"),
            str(node.get("probe_status") or "").lower() == "available",
        )
    try:
        endpoints = node_pool.list_endpoints(limit=5000)
    except Exception:
        endpoints = []
    for endpoint in endpoints:
        status = str(endpoint.get("status") or "").upper()
        add(
            endpoint.get("country"),
            endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip"),
            status in ("HOT", "AVAILABLE"),
        )
    return result


def _pick_global_country_for_coverage() -> str:
    snapshot = _global_country_pool_snapshot()
    candidates: list[tuple[int, int, int, str]] = []
    now = time.time()
    for country, values in snapshot.items():
        inventory = len(values["inventory"])
        available = len(values["available"])
        if inventory <= 0 or available >= COUNTRY_AVAILABLE_TARGET:
            continue
        last_attempt = float(global_country_coverage_last_attempt.get(country, 0) or 0)
        # Avoid repeatedly retrying a country with no usable source every few seconds.
        if now - last_attempt < 1800 and available >= COUNTRY_AVAILABLE_MIN:
            continue
        candidates.append((available, -min(inventory, COUNTRY_INVENTORY_TARGET), int(last_attempt > 0), country))
    if not candidates:
        return ""
    candidates.sort()
    return candidates[0][3]


def schedule_global_country_coverage() -> dict[str, Any]:
    if ui_command_plane.is_busy():
        return {"ok": True, "running": True, "message": "前端人工指令进行中，暂缓国家覆盖任务"}
    if manual_connection_active:
        return {"ok": True, "running": True, "message": "手动连接正在进行，暂缓国家覆盖检测"}
    if country_priority_lock.locked() or country_priority_request:
        return {"ok": True, "running": True}

    # The five-minute global coverage scheduler must obey the same strict
    # priority gate as the main availability engine. It may never start another
    # country's probe while the explicit/server-local priority country still has
    # eligible candidates below the target reserve.
    try:
        ui_cfg = load_ui_config()
        priority_country = normalized_country_name(
            str(ui_cfg.get("force_country") or routing_target_country(ui_cfg) or "").strip()
        )
        if priority_country:
            priority_snapshot = country_priority_snapshot(priority_country)
            priority_available = int(priority_snapshot.get("available") or 0)
            priority_candidates = priority_snapshot.get("candidates") or []
            if priority_available < COUNTRY_AVAILABLE_TARGET:
                if not country_priority_lock.locked() and not country_priority_request:
                    start_country_priority(priority_country)
                message = (
                    f"{priority_country} 尚未完成优先检测，暂不进入全球其它国家"
                    if priority_candidates else
                    f"{priority_country} 优先级锁定：暂无到期候选，等待资源补充/复检，暂不进入全球其它国家"
                )
                return {
                    "ok": True,
                    "running": True,
                    "priority": priority_country,
                    "message": message,
                }
    except Exception as exc:
        log_to_json("WARNING", "Probe", f"全球覆盖调度优先级检查失败: {exc}")
        return {"ok": True, "running": True, "message": "优先国家状态读取失败，本轮暂缓全球覆盖"}

    country = _pick_global_country_for_coverage()
    if not country:
        return {"ok": True, "running": False, "message": "当前资源池已有足够覆盖或暂无可补充国家"}
    global_country_coverage_last_attempt[country] = time.time()
    return start_country_priority(country)


def global_probe_sweep_once() -> dict[str, Any]:
    """Probe due OpenVPN and non-OpenVPN resources without touching the active tunnel."""
    if ui_command_plane.is_busy() or country_full_sweep_running or active_tunnel_running() or proxy_server.proxy_forwarding_busy(20):
        return {"ok": True, "skipped": True, "reason": "在线连接或全量检测优先，本轮不额外拉隧道"}
    if maintenance_lock.locked() or is_connecting:
        return {"ok": True, "skipped": True, "reason": "busy"}
    openvpn_limit = 6 if active_tunnel_running() else 10
    non_openvpn_limit = 2 if active_tunnel_running() else 4
    tested_openvpn = 0
    tested_pool = 0

    openvpn_ids: list[str] = []
    try:
        due = node_pool.due_endpoints(("openvpn",), limit=openvpn_limit)
        for endpoint in due:
            node_id = str((endpoint.get("metadata") or {}).get("node_id") or "").strip()
            if node_id and node_id not in openvpn_ids:
                openvpn_ids.append(node_id)
            if len(openvpn_ids) >= openvpn_limit:
                break
    except Exception as exc:
        log_to_json("WARNING", "Probe", f"全球 OpenVPN 到期队列读取失败: {exc}")

    if openvpn_ids and maintenance_lock.acquire(blocking=False):
        try:
            if not is_connecting:
                test_multiple_nodes(openvpn_ids)
                tested_openvpn = len(openvpn_ids)
        finally:
            maintenance_lock.release()

    if not is_connecting:
        try:
            due_pool = node_pool.due_endpoints(("softether", "sstp", "l2tp-ipsec"), limit=non_openvpn_limit)
        except Exception as exc:
            due_pool = []
            log_to_json("WARNING", "Probe", f"全球多协议到期队列读取失败: {exc}")
        for endpoint in due_pool:
            if is_connecting:
                break
            endpoint_id = str(endpoint.get("endpoint_id") or "")
            if not endpoint_id:
                continue
            result = light_probe_endpoint_id(endpoint_id)
            tested_pool += 1

    return {"ok": True, "openvpn_tested": tested_openvpn, "pool_tested": tested_pool}


_library_preview_at = 0.0
_library_preview_total = 0
_library_preview_running = False


def _refresh_library_preview() -> None:
    global _library_preview_at, _library_preview_total, _library_preview_running
    total = 0
    try:
        for protocol, count in node_pool.count_by_protocol(exclude_retired=True).items():
            if _library_protocol_ready(protocol):
                total += int(count)
        _library_preview_total = total
        _library_preview_at = time.time()
    except Exception:
        pass
    finally:
        _library_preview_running = False


def library_check_preview_total() -> int:
    """How many endpoints a library check would dial. Shown before Start.

    The count is a full table scan. The homepage poll must not do it inline:
    holding the state lock across that scan is what made every 4s refresh wait
    behind SQLite while the manager was swapped out.
    """
    global _library_preview_running
    now = time.time()
    if _library_preview_total and now - _library_preview_at < 120:
        return _library_preview_total
    if not _library_preview_running:
        _library_preview_running = True
        threading.Thread(target=_refresh_library_preview, daemon=True, name="library-preview").start()
    return int(_library_preview_total or 0)


def _library_check_public_state() -> dict[str, Any]:
    with library_check_lock:
        tested = int(library_check_tested)
        total = int(library_check_total)
        available = int(library_check_available)
        unavailable = int(library_check_unavailable)
        samples = int(library_check_rate_samples)
        rate = float(library_check_rate_seconds)
        phase = str(library_check_phase or "idle")
        message = str(library_check_message or "")
        wait = str(library_check_wait_reason or "")
        paused = bool(library_check_paused)
    remaining = max(0, total - tested)
    if phase in ("", "idle") and total <= 0:
        remaining = int(library_check_preview_total() or 0)
    eta = 0
    if samples > 0 and rate > 0 and remaining > 0 and phase in ("running", "paused", "stopping"):
        eta = int(remaining * (rate / samples))
    return {
        "library_check_running": phase in ("running", "paused", "stopping"),
        "library_check_phase": phase,
        "library_check_paused": paused or phase == "paused",
        "library_check_total": total,
        "library_check_preview_total": library_check_preview_total(),
        "library_check_tested": tested,
        "library_check_available": available,
        "library_check_unavailable": unavailable,
        "library_check_remaining": remaining,
        "library_check_eta_seconds": eta,
        "library_check_message": message,
        "library_check_wait_reason": wait,
        **global_scan_public_state(),
    }


def _library_set_wait(reason: str) -> None:
    global library_check_wait_reason
    with library_check_lock:
        library_check_wait_reason = str(reason or "")


def _library_set_message(message: str) -> None:
    global library_check_message
    with library_check_lock:
        library_check_message = str(message or "")


def _library_protocol_ready(protocol: str) -> bool:
    # Light probes do not need a VPN client. Unknown protocols stay out.
    return str(protocol or "").strip().lower() in ("openvpn", "softether", "sstp", "l2tp-ipsec")


def _library_status_rank(status: str) -> int:
    value = str(status or "").upper()
    if value == "NEW":
        return 0
    if value in ("STALE", "DEGRADED"):
        return 1
    if value == "COOLDOWN":
        return 2
    return 3


def _library_wait_until_slot(generation: int) -> str:
    """Yield briefly for the data plane. On a small host, exit the round instead of waiting forever."""
    deadline = time.monotonic() + 60.0
    while True:
        with library_check_lock:
            if library_check_generation != generation or library_check_stop:
                return "stop"
            paused = library_check_paused
        total_kb, avail_kb = _meminfo_kb()
        if 0 < total_kb < 700 * 1024 and (
            _self_swap_kb() > 64 * 1024 or 0 < avail_kb < 90 * 1024
        ):
            _library_set_wait("内存不够，本轮检测退出，剩余留到下次")
            return "stop"
        if paused:
            if time.monotonic() >= deadline:
                return "stop"
            _library_set_wait("已暂停")
            time.sleep(0.4)
            continue
        if (
            manual_connection_active
            or is_connecting
            or maintenance_lock.locked()
            or proxy_server.proxy_forwarding_busy()
            or ui_query_active()
        ):
            if time.monotonic() >= deadline:
                _library_set_wait("让路超过 60 秒，本轮检测退出，剩余留到下次")
                return "stop"
            _library_set_wait("页面或转发占用，检测让路，等待不算失败")
            time.sleep(0.4)
            continue
        _library_set_wait("")
        return "go"


def _library_is_live_production(endpoint: dict[str, Any]) -> bool:
    if not active_tunnel_running():
        return False
    endpoint_id = str(endpoint.get("endpoint_id") or "")
    if endpoint_id and endpoint_id == str(active_pool_endpoint_id or ""):
        return True
    node_id = str((endpoint.get("metadata") or {}).get("node_id") or "")
    if node_id and node_id == str(active_openvpn_node_id or ""):
        return True
    ip = str(endpoint.get("current_ip") or "").strip()
    port = str(int(endpoint.get("port") or 0))
    transport = str(endpoint.get("transport") or "").strip().lower()
    active_id = str(active_openvpn_node_id or "")
    needle = f"{ip}_{port}_{transport}" if transport else f"{ip}_{port}"
    return bool(ip and port != "0" and active_id and (active_id == needle or active_id.endswith("_" + needle)))


def _library_openvpn_config(endpoint: dict[str, Any]) -> str:
    metadata = endpoint.get("metadata") or {}
    node_id = str(metadata.get("node_id") or "").strip()
    host = str(endpoint.get("hostname") or metadata.get("hostname") or endpoint.get("current_ip") or "").strip()
    port = int(endpoint.get("port") or 0)
    transport = str(endpoint.get("transport") or "tcp").strip().lower() or "tcp"
    text = ""
    if node_id:
        try:
            cached = _nodes_index_get().get(node_id) or {}
        except Exception:
            cached = {}
        text = str(cached.get("config_text") or "")
        if text.strip():
            return _prefer_openvpn_ip(text, cached)
    config_file = str(endpoint.get("config_ref") or metadata.get("config_file") or "").strip()
    if config_file:
        try:
            text = Path(config_file).read_text(encoding="utf-8")
        except Exception:
            text = ""
    if not text.strip():
        text = _manual_openvpn_template() or ""
        if text.strip():
            text = re.sub(r"(?m)^remote\s+\S+\s+\d+\s*$", f"remote {host} {port}", text, count=1)
            text = re.sub(r"(?m)^proto\s+\S+\s*$", f"proto {transport}", text, count=1)
    if not text.strip():
        return ""
    return _prefer_openvpn_ip(text, {
        "host_name": host,
        "remote_host": host,
        "remote_port": port,
        "proto": transport,
    })


def _library_probe_openvpn(endpoint: dict[str, Any]) -> dict[str, Any]:
    endpoint_id = str(endpoint.get("endpoint_id") or "")
    config_text = _library_openvpn_config(endpoint)
    if not config_text.strip():
        return {"ok": False, "latency_ms": 0, "message": "缺少 OpenVPN 配置"}
    if not protocol_probe_lock.acquire(blocking=False):
        return {"deferred": True, "message": "已有协议探测，检测让路"}
    temp_path = test_config_path(endpoint_id or "library")
    idx = None
    try:
        CONFIG_DIR.mkdir(exist_ok=True, parents=True)
        temp_path.write_text(config_text, encoding="utf-8")
        idx = get_free_test_index()
        latency_box: list[int] = []
        ok, message, process = run_openvpn_until_ready(
            str(temp_path), True, True, timeout=12, dev=f"tun{idx}",
            latency_out=latency_box, quiet=True,
        )
        try:
            if "让路" in str(message or ""):
                return {"deferred": True, "message": message}
            if not ok:
                return {"ok": False, "latency_ms": 0, "message": message}
            health = check_interface_egress(f"tun{idx}")
            if not health.get("ok"):
                return {"ok": False, "latency_ms": 0, "message": "OpenVPN 已握手，但隧道出不了网"}
            latency = int(health.get("latency_ms") or 0)
            return {"ok": True, "latency_ms": latency, "message": message}
        finally:
            if process is not None:
                stop_process(process)
    except Exception as exc:
        return {"ok": False, "latency_ms": 0, "message": str(exc)}
    finally:
        if idx is not None:
            release_test_index(idx)
        try:
            if temp_path.exists():
                temp_path.unlink()
        except Exception:
            pass
        protocol_probe_lock.release()


_GLOBAL_SCAN_MODES = ("loop", "daily", "mon", "tue", "wed", "thu", "fri", "sat", "sun")


def global_scan_settings() -> dict[str, Any]:
    cfg = load_ui_config()
    mode = str(cfg.get("global_scan_mode") or "loop").strip().lower()
    if mode not in _GLOBAL_SCAN_MODES:
        mode = "loop"
    try:
        hour = int(cfg.get("global_scan_hour") if cfg.get("global_scan_hour") is not None else 0)
    except (TypeError, ValueError):
        hour = 0
    hour = max(0, min(23, hour))
    try:
        interval = int(cfg.get("global_scan_interval_hours") if cfg.get("global_scan_interval_hours") is not None else 1)
    except (TypeError, ValueError):
        interval = 1
    interval = max(1, min(24, interval))
    try:
        last = float(cfg.get("last_global_scan_at") or 0)
    except (TypeError, ValueError):
        last = 0.0
    return {
        "auto": bool(cfg.get("global_scan_auto")),
        "mode": mode,
        "hour": hour,
        "interval": interval,
        "last": last,
        "last_duration": _scan_last_duration(cfg),
    }


def _scan_last_duration(cfg: dict[str, Any] | None = None) -> float:
    raw = cfg if isinstance(cfg, dict) else load_ui_config()
    try:
        return max(0.0, float(raw.get("last_global_scan_seconds") or 0))
    except (TypeError, ValueError):
        return 0.0


def _library_idle_interval_seconds(last_duration: float) -> int:
    """3 hours when the last idle sweep finished within 15 minutes, otherwise 6."""
    if last_duration > LIBRARY_IDLE_FAST_LIMIT:
        return LIBRARY_IDLE_SLOW_SECONDS
    return LIBRARY_IDLE_FAST_SECONDS


def global_scan_public_state() -> dict[str, Any]:
    settings = global_scan_settings()
    return {
        "global_scan_auto": settings["auto"],
        "global_scan_mode": settings["mode"],
        "global_scan_hour": settings["hour"],
        "global_scan_interval_hours": settings["interval"],
        "last_global_scan_at": settings["last"],
    }


def save_global_scan_settings(changes: dict[str, Any]) -> dict[str, Any]:
    current = global_scan_settings()
    auto = bool(changes.get("global_scan_auto")) if "global_scan_auto" in changes else current["auto"]
    mode = str(changes.get("global_scan_mode") or current["mode"]).strip().lower()
    if mode not in _GLOBAL_SCAN_MODES:
        mode = current["mode"]
    try:
        hour = int(changes.get("global_scan_hour") if "global_scan_hour" in changes else current["hour"])
    except (TypeError, ValueError):
        hour = current["hour"]
    hour = max(0, min(23, hour))
    try:
        interval = int(changes.get("global_scan_interval_hours") if "global_scan_interval_hours" in changes else current["interval"])
    except (TypeError, ValueError):
        interval = current["interval"]
    interval = max(1, min(24, interval))
    if mode == "loop":
        hour = current["hour"]
    else:
        interval = current["interval"]
    with lock:
        path = DATA_DIR / "ui_auth.json"
        stored: dict[str, Any] = {}
        if path.exists():
            try:
                loaded = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    stored = loaded
            except Exception:
                stored = {}
        stored["global_scan_auto"] = auto
        stored["global_scan_mode"] = mode
        stored["global_scan_hour"] = hour
        stored["global_scan_interval_hours"] = interval
        write_json(path, stored)
    invalidate_ui_config_cache()
    return global_scan_public_state()


def remember_global_scan(when: float | None = None, duration: float | None = None) -> None:
    with lock:
        path = DATA_DIR / "ui_auth.json"
        stored: dict[str, Any] = {}
        if path.exists():
            try:
                loaded = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(loaded, dict):
                    stored = loaded
            except Exception:
                stored = {}
        if when is not None or duration is None:
            stored["last_global_scan_at"] = float(when if when is not None else time.time())
        if duration is not None:
            stored["last_global_scan_seconds"] = max(0.0, float(duration))
        write_json(path, stored)
    invalidate_ui_config_cache()


def global_scan_due(now: float | None = None) -> bool:
    settings = global_scan_settings()
    now = time.time() if now is None else now
    local = time.localtime(now)
    if not settings["auto"]:
        last = settings["last"]
        if last <= 0:
            remember_global_scan(now)
            return False
        return (now - last) >= _library_idle_interval_seconds(float(settings.get("last_duration") or 0))
    if settings["mode"] == "loop":
        last = settings["last"]
        if last <= 0:
            return True
        return (now - last) >= int(settings["interval"]) * 3600
    if local.tm_hour < settings["hour"]:
        return False
    if settings["last"] <= 0:
        return True
    previous = time.localtime(settings["last"])
    if settings["mode"] == "daily":
        return (previous.tm_year, previous.tm_yday) != (local.tm_year, local.tm_yday)
    names = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")
    if names[local.tm_wday] != settings["mode"]:
        return False
    return (previous.tm_year, previous.tm_yday) != (local.tm_year, local.tm_yday)


def maybe_start_scheduled_library_check() -> None:
    if library_check_phase in ("running", "paused", "stopping"):
        return
    if not global_scan_due():
        return
    total_kb, avail_kb = _meminfo_kb()
    if 0 < total_kb < 700 * 1024 and (
        _self_swap_kb() > 64 * 1024 or 0 < avail_kb < 90 * 1024
    ):
        return
    if (
        proxy_server.proxy_forwarding_busy()
        or is_connecting
        or manual_connection_active
        or ui_command_plane.is_busy()
    ):
        return
    library_check_control("start", {"reason": "scheduled_global_scan"})
    remember_global_scan()
    settings = global_scan_settings()
    if not settings["auto"]:
        hours = _library_idle_interval_seconds(float(settings.get("last_duration") or 0)) // 3600
        mode = f"每 {hours} 小时"
    else:
        mode = settings["mode"]
    log_to_json("INFO", "Probe", f"空闲，按计划开始全球库检测（{mode}）")


def _hostname_ipv4s(host: str) -> set[str]:
    host = str(host or "").strip()
    if not host or re.fullmatch(r"\d+\.\d+\.\d+\.\d+", host):
        return set()
    try:
        infos = socket.getaddrinfo(host, None, socket.AF_INET, socket.SOCK_STREAM)
    except Exception:
        return set()
    return {str(item[4][0]) for item in infos if item and item[4]}


def reconcile_endpoint_address(endpoint: dict[str, Any]) -> dict[str, Any]:
    """Drop a stale IP when the hostname no longer resolves to it."""
    host = str(endpoint.get("hostname") or "").strip()
    current = str(endpoint.get("current_ip") or "").strip()
    if not host or re.fullmatch(r"\d+\.\d+\.\d+\.\d+", host):
        return endpoint
    found = _hostname_ipv4s(host)
    if not found or current in found:
        return endpoint
    time.sleep(0.2)
    found = _hostname_ipv4s(host)
    if not found or current in found:
        return endpoint
    new_ip = sorted(found)[0]
    try:
        changed = node_pool.replace_hostname_ip(host, new_ip)
    except Exception as exc:
        log_to_json("WARNING", "Probe", f"域名 IP 修订失败 {host}: {exc}")
        return endpoint
    if changed:
        log_to_json("INFO", "Probe", f"DNS_IP_CHANGED {host} {current or '-'} -> {new_ip}")
    updated = dict(endpoint)
    updated["current_ip"] = new_ip
    metadata = dict(updated.get("metadata") or {})
    metadata["ip"] = new_ip
    updated["metadata"] = metadata
    return updated


def _library_probe_one(row: dict[str, Any]) -> tuple[str, int, str]:
    if library_check_stop:
        return ("stop", 0, "")
    endpoint_id = str(row.get("endpoint_id") or "")
    if not endpoint_id:
        return ("unavailable", 0, "端点不存在")
    if _library_is_live_production(row):
        return ("live", 0, "")
    result = light_probe_endpoint(row)
    if result.get("inconclusive"):
        return ("inconclusive", 0, str(result.get("message") or ""))
    return (
        "available" if result.get("ok") else "unavailable",
        int(result.get("latency_ms") or 0),
        str(result.get("message") or ""),
    )


def _library_check_worker(generation: int) -> None:
    global library_check_phase, library_check_total, library_check_tested
    global library_check_available, library_check_unavailable
    global library_check_rate_seconds, library_check_rate_samples
    global library_check_message, library_check_wait_reason
    global library_check_stop, library_check_paused
    probe_started = 0.0
    try:
        reason = str(library_check_fetch_reason or "manual_global_scan")
        with library_check_lock:
            if library_check_generation == generation:
                library_check_message = "正在更新全球资源库"
                library_check_wait_reason = ""
        try:
            fetched = resource_collect_once(force=True, reason=reason, wait=True)
            if isinstance(fetched, dict) and fetched.get("ok") is False and not node_pool.stats().get("endpoints"):
                raise RuntimeError(str(fetched.get("error") or "资源库无法读取"))
            note = str((fetched or {}).get("message") or "资源更新完成")
            with library_check_lock:
                if library_check_generation == generation:
                    library_check_message = note
        except Exception as exc:
            log_to_json("WARNING", "Probe", f"全球库检测前资源更新未完成，继续检测现有库: {exc}")
            with library_check_lock:
                if library_check_generation == generation:
                    library_check_message = f"资源更新未完成，继续检测现有库：{exc}"
        rows = node_pool.list_probe_targets()
        ready_rows: list[dict[str, Any]] = []
        skipped = 0
        for row in rows:
            if str(row.get("status") or "").upper() == "RETIRED":
                continue
            if not _library_protocol_ready(str(row.get("protocol") or "")):
                skipped += 1
                continue
            ready_rows.append(row)
        home = ""
        try:
            ui_cfg = load_ui_config()
            home = normalized_country_name(
                str(ui_cfg.get("force_country") or "").strip() or server_home_country()
            )
        except Exception:
            home = ""

        def _library_row_key(item: dict[str, Any]) -> tuple[int, int, str]:
            country = normalized_country_name(str(item.get("country") or ""))
            same = 0 if home and country == home else 1
            return (same, _library_status_rank(str(item.get("status") or "")), str(item.get("endpoint_id") or ""))

        ready_rows.sort(key=_library_row_key)
        queue = [item for item in ready_rows if str(item.get("endpoint_id") or "")]
        with library_check_lock:
            if library_check_generation != generation:
                return
            library_check_total = len(queue)
            note = "TCP 测端口，UDP 发一包协议探测。不建立隧道，不测速。tls-auth 的 UDP 无应答不算不可用"
            if skipped:
                note += f"；已跳过 {skipped} 个未知协议的端点"
            library_check_message = note
            stop_now = library_check_stop
        if stop_now:
            return
        log_to_json(
            "INFO",
            "Probe",
            f"全球库检测开始：轻量检测 {len(queue)}，"
            + (f"同国家 {home} 优先，" if home else "未识别本机国家，按状态检测，")
            + f"跳过 {skipped}",
        )
        index = 0
        total_kb, _avail_kb = _meminfo_kb()
        batch_size = 4 if 0 < total_kb < 700 * 1024 else 24
        probe_started = time.time()
        while index < len(queue):
            if _library_wait_until_slot(generation) == "stop":
                break
            batch = queue[index:index + batch_size]
            started = time.perf_counter()
            outcomes: dict[str, tuple[str, int, str]] = {}
            with concurrent.futures.ThreadPoolExecutor(max_workers=len(batch)) as executor:
                futures = {
                    executor.submit(_library_probe_one, row): str(row.get("endpoint_id") or "")
                    for row in batch
                }
                for future in concurrent.futures.as_completed(futures):
                    endpoint_id = futures[future]
                    try:
                        result = future.result()
                        if not isinstance(result, tuple) or len(result) != 3:
                            result = ("unavailable", 0, "")
                        outcomes[endpoint_id] = (str(result[0] or "unavailable"), int(result[1] or 0), str(result[2] or ""))
                    except Exception as exc:
                        outcomes[endpoint_id] = ("unavailable", 0, str(exc))
                        log_to_json("WARNING", "Probe", f"全球库检测失败 {endpoint_id}: {exc}")
            finished = [
                endpoint_id for endpoint_id in futures.values()
                if outcomes.get(endpoint_id, ("", 0, ""))[0] != "stop"
            ]
            elapsed = max(0.0, time.perf_counter() - started)
            probed = [
                endpoint_id for endpoint_id in finished
                if outcomes.get(endpoint_id, ("", 0, ""))[0] in ("available", "unavailable")
            ]
            per = (elapsed / len(probed)) if probed else 0.0
            writes: list[tuple[str, bool, int, str]] = []
            with library_check_lock:
                if library_check_generation != generation:
                    return
                for endpoint_id in finished:
                    outcome, latency_ms, message = outcomes.get(endpoint_id) or ("unavailable", 0, "")
                    library_check_tested += 1
                    if outcome == "available":
                        library_check_available += 1
                    elif outcome == "unavailable":
                        library_check_unavailable += 1
                    if outcome in ("available", "unavailable"):
                        library_check_rate_seconds += per
                        library_check_rate_samples += 1
                        writes.append((endpoint_id, outcome == "available", latency_ms, message))
                tested_now = library_check_tested
                library_check_wait_reason = ""
            if writes:
                try:
                    node_pool.record_light_probe_batch(writes)
                except Exception as exc:
                    log_to_json("WARNING", "Probe", f"全球库检测写入失败: {exc}")
            if tested_now <= batch_size or tested_now % 96 < batch_size:
                log_to_json("INFO", "Probe", f"全球库检测进度 {tested_now}/{library_check_total}")
            if any(outcomes.get(endpoint_id, ("", 0, ""))[0] == "stop" for endpoint_id in futures.values()):
                break
            index += len(batch)
            if 0 < total_kb < 700 * 1024:
                if probe_started and time.time() - probe_started >= LIBRARY_IDLE_FAST_LIMIT:
                    log_to_json("INFO", "Probe", "小机器本轮全球库检测已满 15 分钟，剩下的留到下次，避免把出口卡死")
                    with library_check_lock:
                        if library_check_generation == generation:
                            library_check_message = "本轮检测暂停：小机器已检测 15 分钟，剩余留到下次"
                    break
                time.sleep(1.0)
    except Exception as exc:
        log_to_json("ERROR", "Probe", f"全球库检测异常: {exc}")
        with library_check_lock:
            if library_check_generation == generation:
                library_check_phase = "error"
                library_check_message = f"检测异常：{exc}"
                library_check_wait_reason = ""
    finally:
        with library_check_lock:
            if library_check_generation != generation:
                finished = False
            else:
                finished = True
                if library_check_phase == "error":
                    library_check_paused = False
                    library_check_stop = False
                else:
                    stopped = bool(library_check_stop) or library_check_phase == "stopping"
                    if stopped:
                        library_check_phase = "stopped"
                        library_check_message = "检测已停止"
                    elif library_check_total <= 0:
                        library_check_phase = "done"
                        if not library_check_message:
                            library_check_message = "没有可检测的端点"
                    else:
                        library_check_phase = "done"
                        library_check_message = "检测完成。TCP 看端口，UDP 看协议应答，没有建立隧道"
                    library_check_wait_reason = ""
                    library_check_paused = False
                    library_check_stop = False
        if finished and probe_started and library_check_phase == "done" and library_check_tested > 0:
            try:
                remember_global_scan(duration=time.time() - probe_started)
            except Exception:
                pass
        if finished:
            try:
                _drop_ui_page_snapshots()
            except Exception:
                pass


def library_check_control(action: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    global library_check_generation, library_check_stop, library_check_paused
    global library_check_phase, library_check_total, library_check_tested
    global library_check_available, library_check_unavailable
    global library_check_rate_seconds, library_check_rate_samples
    global library_check_message, library_check_wait_reason, library_check_fetch_reason
    action = str(action or "start").strip().lower()
    if action == "save_schedule":
        save_global_scan_settings(payload or {})
        return _library_check_public_state()
    if action not in ("start", "pause", "resume", "stop"):
        action = "start"
    start_thread = False
    generation = 0
    with library_check_lock:
        if action == "pause":
            if library_check_phase == "running":
                library_check_paused = True
                library_check_phase = "paused"
                library_check_wait_reason = "已暂停"
        elif action == "resume":
            if library_check_phase == "paused":
                library_check_paused = False
                library_check_phase = "running"
                library_check_wait_reason = ""
        elif action == "stop":
            if library_check_phase in ("running", "paused"):
                library_check_stop = True
                library_check_paused = False
                library_check_phase = "stopping"
                library_check_wait_reason = "正在停止，当前这一批检测结束后停止"
        elif library_check_phase == "paused":
            library_check_paused = False
            library_check_phase = "running"
            library_check_wait_reason = ""
        elif library_check_phase == "stopping":
            library_check_message = "正在停止上一次检测，请稍后再开始"
        elif library_check_phase != "running":
            library_check_generation += 1
            generation = library_check_generation
            library_check_stop = False
            library_check_paused = False
            library_check_phase = "running"
            library_check_total = library_check_preview_total()
            library_check_tested = 0
            library_check_available = 0
            library_check_unavailable = 0
            library_check_rate_seconds = 0.0
            library_check_rate_samples = 0
            library_check_message = "正在更新全球资源库"
            library_check_wait_reason = ""
            library_check_fetch_reason = (
                "scheduled_global_scan"
                if str((payload or {}).get("reason") or "") == "scheduled_global_scan"
                else "manual_global_scan"
            )
            start_thread = True
    if start_thread:
        remember_global_scan()
        threading.Thread(
            target=_library_check_worker, args=(generation,), daemon=True, name="library-check",
        ).start()
    return _library_check_public_state()


def refresh_global_pool_background(force: bool = True) -> dict[str, Any]:
    global global_pool_refresh_running, global_pool_refresh_last_at
    global global_pool_refresh_status, global_pool_refresh_message
    global global_pool_refresh_servers, global_pool_refresh_sources
    if not global_pool_refresh_lock.acquire(blocking=False):
        return {
            "ok": True,
            "running": True,
            "message": "全球节点库刷新正在后台进行",
        }
    with lock:
        if global_pool_refresh_running:
            global_pool_refresh_lock.release()
            return {"ok": True, "running": True, "message": "全球节点库刷新正在后台进行"}
        global_pool_refresh_running = True
        global_pool_refresh_status = "running"
        global_pool_refresh_message = "正在重新开始全球资源轮询；保留历史节点与质量数据，不断开当前 VPN。"
        global_pool_refresh_servers = 0
        global_pool_refresh_sources = 0

    set_state(
        global_pool_refresh_running=True,
        global_pool_refresh_status="running",
        global_pool_refresh_message=global_pool_refresh_message,
        global_pool_refresh_servers=0,
        global_pool_refresh_sources=0,
    )

    def worker() -> None:
        global global_pool_refresh_running, global_pool_refresh_last_at
        global global_pool_refresh_status, global_pool_refresh_message
        global global_pool_refresh_servers, global_pool_refresh_sources
        try:
            # Do not compete with the connection/maintenance critical section.
            for _ in range(120):
                if not maintenance_lock.locked() and not is_connecting:
                    break
                time.sleep(1)
            # Requeue the entire persisted pool without deleting history.
            try:
                requeued = node_pool.reset_probe_schedule(include_retired=False)
                log_to_json("INFO", "Probe", f"人工重新轮询：已重新排队 {requeued} 个非退役端点")
            except Exception as exc:
                requeued = 0
                log_to_json("WARNING", "Probe", f"人工重新轮询排队失败: {exc}")
            candidates: list[dict[str, Any]] = []
            try:
                candidates = fetch_candidates()
            except Exception as exc:
                log_to_json("WARNING", "Main", f"全球 OpenVPN 资源拉取失败: {exc}")
            catalog = refresh_multi_protocol_catalog(force=True)
            global_pool_refresh_servers = len(candidates) + int(catalog.get("servers") or 0)
            global_pool_refresh_sources = len(catalog.get("sources") or [])
            global_pool_refresh_last_at = time.time()
            global_pool_refresh_status = "ok"
            global_pool_refresh_message = (
                f"全球资源重新轮询完成：OpenVPN {len(candidates)} 个候选，多协议目录 {int(catalog.get('servers') or 0)} 台；"
                "已有资源已重新排入检测，后台会继续进行全量可用性复核与国家缺口补齐。"
            )
            log_to_json("INFO", "Main", global_pool_refresh_message)

            # Start a bounded immediate validation pass; lifecycle loops continue
            # the complete persistent-pool recheck afterwards.
            try:
                threading.Thread(target=global_probe_sweep_once, daemon=True).start()
            except Exception:
                pass
            try:
                threading.Thread(target=schedule_global_country_coverage, daemon=True).start()
            except Exception:
                pass
        except Exception as exc:
            global_pool_refresh_status = "error"
            global_pool_refresh_message = f"全球节点库刷新异常：{exc}"
            log_to_json("ERROR", "Main", global_pool_refresh_message)
        finally:
            global_pool_refresh_running = False
            set_state(
                global_pool_refresh_running=False,
                global_pool_refresh_last_at=global_pool_refresh_last_at,
                global_pool_refresh_status=global_pool_refresh_status,
                global_pool_refresh_message=global_pool_refresh_message,
                global_pool_refresh_servers=global_pool_refresh_servers,
                global_pool_refresh_sources=global_pool_refresh_sources,
            )
            global_pool_refresh_lock.release()

    threading.Thread(target=worker, daemon=True).start()
    return {"ok": True, "running": True, "message": "已启动全球节点库后台刷新"}


def global_country_coverage_loop() -> None:
    global global_country_coverage_heartbeat
    # Start after the initial catalog has had a chance to load.
    time.sleep(30)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        try:
            global_country_coverage_heartbeat = time.time()
            if not global_pool_refresh_running and not ui_command_plane.is_busy() and not maintenance_lock.locked() and not manual_connection_active:
                schedule_global_country_coverage()
        except Exception as exc:
            log_to_json("WARNING", "Main", f"全球国家可用性补齐调度异常: {exc}")
        time.sleep(300)

def maintain_valid_nodes(force: bool = False):
    global active_openvpn_process, active_openvpn_node_id, is_connecting, manual_connection_epoch
    ensure_dirs()
    if ui_command_plane.is_busy() and not force:
        return "前端人工指令进行中，后台维护本轮暂缓"
    if global_pool_refresh_running and not force:
        return "全球资源重新轮询进行中，后台维护本轮暂缓"
    if not maintenance_lock.acquire(blocking=False):
        msg = "节点维护任务正在运行，请稍后再试"
        set_state(last_check_message=msg)
        return msg
    with lock:
        if manual_connection_active:
            maintenance_lock.release()
            msg = "用户正在手动切换节点，后台检测本轮暂缓"
            set_state(last_check_message=msg)
            return msg
        if is_connecting:
            maintenance_lock.release()
            msg = "当前已有连接或节点测试任务正在运行，请稍后再试"
            set_state(last_check_message=msg)
            return msg
        cycle_manual_epoch = manual_connection_epoch
        is_connecting = True
    try:
        if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
            return "检测周期被用户手动切换打断"
        if force:
            with lock:
                if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
                    return "检测周期被用户手动切换打断"
                stop_all_tunnels()
            reconnect_fixed_node_if_needed(load_ui_config())
        elif not active_tunnel_running():
            if bool(get_state().get("proxy_ok")) and _tunnel_carrier_alive():
                log_to_json("WARNING", "VPN", "活动网卡地址瞬时读不到，但进程仍在且出口刚刚可用，不切换")
            else:
                ui_cfg = load_ui_config()
                routing_mode = ui_cfg.get("routing_mode", "auto")
                connection_enabled = ui_cfg.get("connection_enabled", True)
                if connection_enabled:
                    if routing_mode == "fixed_ip":
                        reconnect_fixed_node_if_needed(ui_cfg)
                    else:
                        has_active_id = False
                        with lock:
                            if active_openvpn_node_id:
                                has_active_id = True
                                stop_all_tunnels()
                        if has_active_id:
                            print("[维护线程] 检测到当前 OpenVPN 进程已意外退出，准备自动切换节点", flush=True)
                            is_connecting = False
                            auto_switch_node()
                            is_connecting = True
                        elif routing_mode in ("auto", "fixed_region"):
                            # Warm-start from persisted validated endpoints before
                            # doing a fresh network-wide scan.
                            is_connecting = False
                            try:
                                if try_unified_failover(attempts=3):
                                    log_to_json("INFO", "VPN", "已从持久化 Hot Pool 快速恢复生产出口")
                            finally:
                                is_connecting = True

        try:
            if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
                return "检测周期被用户手动切换打断"
            # Connection maintenance is strictly state/probe work. Resource
            # acquisition is a separate daemon (resource_collect_loop), so a
            # browser refresh, connection recovery, or node switch can never
            # trigger a network-wide fetch or block the active VPN tunnel.
            candidates = read_nodes()
            set_state(
                is_connecting=True,
                last_check_message="使用 Master Pool 已有节点进行状态检测；资源采集由独立后台任务运行",
            )
        except Exception as exc:
            set_state(last_fetch_at=time.time(), last_fetch_status="error", last_fetch_message=f"读取 Master Pool 失败：{exc}")
            candidates = []

        if not candidates:
            return "没有拉取到新节点"
        if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
            return "检测周期被用户手动切换打断"

        with lock:
            current_nodes = read_nodes()
            current_by_id = {
                str(n.get("id")): n
                for n in current_nodes
                if n.get("id")
            }
            active_node = None
            if active_openvpn_node_id:
                active_node = next((n for n in current_nodes if n.get("id") == active_openvpn_node_id), None)

            merged: list[dict[str, Any]] = []
            seen_ids: set[str] = set()

            if active_node:
                merged.append(active_node)
                seen_ids.add(active_node["id"])

            for cand in candidates:
                if cand["id"] not in seen_ids:
                    previous = current_by_id.get(str(cand["id"]))
                    if previous:
                        # Keep prior probe state, but prefer freshly enriched ISP/IP
                        # metadata from the latest fetch. This prevents stale cached
                        # classifications from overwriting a newly corrected result.
                        for key in [
                            "probe_status",
                            "probe_message",
                            "latency_ms",
                            "probed_at",
                        ]:
                            if previous.get(key) not in (None, ""):
                                cand[key] = previous.get(key)
                        for key in [
                            "owner",
                            "asn",
                            "as_name",
                            "location",
                            "ip_type",
                            "quality",
                        ]:
                            if cand.get(key) in (None, "") and previous.get(key) not in (None, ""):
                                cand[key] = previous.get(key)
                    merged.append(cand)
                    seen_ids.add(cand["id"])

            if len(merged) > 1000:
                merged = merged[:1000]

            for n in merged:
                config_path = Path(n["config_file"])
                if not config_path.exists():
                    try:
                        config_path.write_text(n["config_text"], encoding="utf-8")
                    except Exception:
                        pass

            write_json(NODES_FILE, merged)

        initial_tested_ids: set[str] = set()
        ui_cfg = load_ui_config()
        should_fast_connect = (
            ui_cfg.get("connection_enabled", True)
            and ui_cfg.get("routing_mode", "auto") != "fixed_ip"
            and not active_tunnel_running()
        )
        if should_fast_connect and not manual_connection_active and manual_connection_epoch == cycle_manual_epoch:
            with lock:
                current_nodes = read_nodes()
                fast_candidates = [
                    n for n in current_nodes
                    if not n.get("active") and n.get("probe_status") != "unavailable"
                ]
                fast_candidates = apply_routing_filters(fast_candidates, ui_cfg, include_unknown_ip_type=True)
                fast_candidates.sort(key=lambda n: routing_node_service_key(n, ui_cfg))
                fast_test_ids = [
                    n["id"] for n in fast_candidates
                    if n.get("id")
                ][:INITIAL_CONNECT_TEST_LIMIT]

            if fast_test_ids:
                initial_tested_ids = set(fast_test_ids)
                msg = f"首次快速连接模式：优先测试 {len(fast_test_ids)} 个高优先级节点，发现可用节点后立即连接"
                print(f"[快速首连] {msg}", flush=True)
                log_to_json("INFO", "Main", msg)
                set_state(is_connecting=True, last_check_message=msg)
                test_multiple_nodes(fast_test_ids)
                if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
                    return "检测周期被用户手动切换打断"

                with lock:
                    fast_nodes = read_nodes()
                    available_candidates = [
                        n for n in fast_nodes
                        if n.get("probe_status") == "available" and not n.get("active")
                    ]
                    available_candidates = apply_routing_filters(available_candidates, ui_cfg)

                if available_candidates:
                    is_connecting = False
                    set_state(is_connecting=False, last_check_message="快速首连已找到可用节点，正在建立连接...")
                    auto_switch_node()
                    if active_tunnel_running():
                        valid_nodes_count = len([n for n in read_nodes() if n.get("probe_status") == "available"])
                        message = f"Fetched {len(candidates)} nodes. Fast-tested {len(fast_test_ids)} nodes and connected."
                        set_state(
                            last_check_at=time.time(),
                            last_check_message=message,
                            active_openvpn_node_id=active_openvpn_node_id,
                            valid_nodes=valid_nodes_count,
                        )
                        return message
                    is_connecting = True

        # Test only OpenVPN endpoints whose lifecycle backoff has expired.
        # This prevents repeatedly reconnecting every failed node on each cycle.
        batch_limit = 1 if active_tunnel_running() else 3
        due_openvpn = node_pool.due_endpoints(("openvpn",), limit=batch_limit + len(initial_tested_ids))
        to_test_ids: list[str] = []
        seen_test_ids: set[str] = set()
        for endpoint in due_openvpn:
            metadata = endpoint.get("metadata") or {}
            node_id = str(metadata.get("node_id") or "").strip()
            if not node_id or node_id in initial_tested_ids or node_id in seen_test_ids:
                continue
            to_test_ids.append(node_id)
            seen_test_ids.add(node_id)
            if len(to_test_ids) >= batch_limit:
                break
        total_due = len(due_openvpn)

        msg = f"开始按退避队列低频轮询 OpenVPN，本轮检测 {len(to_test_ids)} 个到期节点（查询到 {total_due} 个候选），避免重复扫描与连接风暴"
        print(f"[周期检测] {msg}", flush=True)
        log_to_json("INFO", "Main", msg)

        if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
            return "检测周期被用户手动切换打断"
        while proxy_server.proxy_forwarding_busy() and not manual_connection_active:
            time.sleep(0.5)
        set_state(last_check_message=f"后台检测 {len(to_test_ids)} 个节点，不影响当前连接")
        test_multiple_nodes(to_test_ids)

        if manual_connection_active or manual_connection_epoch != cycle_manual_epoch:
            return "检测周期被用户手动切换打断"

        with lock:
            merged = read_nodes()

            # Identify available, unavailable, and active nodes
            available_nodes = [n["id"] for n in merged if n.get("probe_status") == "available"]
            unavailable_nodes = [n["id"] for n in merged if n.get("probe_status") == "unavailable"]
            active_node = next((n["id"] for n in merged if n.get("active")), "无")

            status_report = (
                f"周期节点检测完成。实时同步状态: 获取到候选节点共 {len(merged)} 个。 "
                f"其中【可用节点】{len(available_nodes)} 个: {available_nodes[:15]}...; "
                f"【不可用节点】{len(unavailable_nodes)} 个; "
                f"当前【正在正常运行的活动连接节点】为: {active_node}。"
            )
            print(f"[周期检测] {status_report}", flush=True)
            log_to_json("INFO", "Main", status_report)

            if active_node != "无" and not active_openvpn_running():
                warn_msg = f"[诊断警告] 活动节点 {active_node} 被标记为活动状态，但 OpenVPN 进程实际并未正常运行！"
                print(warn_msg, flush=True)
                log_to_json("WARNING", "Main", warn_msg)

            if not active_tunnel_running() and not (bool(get_state().get("proxy_ok")) and _tunnel_carrier_alive()):
                ui_cfg = load_ui_config()
                connection_enabled = ui_cfg.get("connection_enabled", True)
                if connection_enabled:
                    routing_mode = ui_cfg.get("routing_mode", "auto")

                    if routing_mode != "fixed_ip":
                        available_candidates = [n for n in merged if n.get("probe_status") == "available"]
                        available_candidates = apply_routing_filters(available_candidates, ui_cfg)

                        if available_candidates and not manual_connection_active and manual_connection_epoch == cycle_manual_epoch:
                            auto_switch_node()

        valid_nodes_count = len([n for n in merged if n.get("probe_status") == "available"])
        message = f"Fetched {len(candidates)} nodes. Tested {len(to_test_ids)} non-active nodes."
        set_state(
            last_check_at=time.time(),
            last_check_message=message,
            active_openvpn_node_id=active_openvpn_node_id,
            valid_nodes=valid_nodes_count,
        )
        return message
    except Exception as e:
        raise e
    finally:
        is_connecting = False
        maintenance_lock.release()


def resource_collect_loop() -> None:
    """Independent resource acquisition daemon.

    Fetching VPNGate/multi-protocol catalogs is intentionally decoupled from
    connection maintenance. It may add resources to Master Pool, but it never
    owns the active tunnel and never toggles the frontend connection state.
    """
    # Give the web/UI and tunnel daemon a quiet startup window. Resource
    # acquisition is intentionally not on the critical path of page opening.
    time.sleep(120)
    while True:
        if background_paused():
            time.sleep(5)
            continue
        total_kb, _avail_kb = _meminfo_kb()
        pause_reason = _nano_library_pause_reason()
        if (0 < total_kb < 700 * 1024 and _self_swap_kb() > 64 * 1024) or pause_reason:
            time.sleep(60)
            continue
        try:
            if (not ISOLATED_INSTANCE and not initial_bootstrap_active
                    and not ui_command_plane.is_busy() and not global_pool_refresh_running):
                result = resource_collect_once(force=False, reason="background")
                if isinstance(result, dict) and result.get("busy"):
                    time.sleep(30)
                    continue
        except Exception as exc:
            log_to_json("WARNING", "Main", f"独立资源采集循环异常: {exc}")
        time.sleep(_resource_next_interval(_load_resource_history()))


def collector_loop() -> None:
    global last_collector_heartbeat
    while True:
        if background_paused():
            time.sleep(5)
            continue
        last_collector_heartbeat = time.time()
        success = False
        try:
            if active_tunnel_running() or proxy_server.proxy_forwarding_busy() or is_connecting or manual_connection_active:
                time.sleep(30)
                continue
            print("[守护线程] 当前没有活动隧道，执行一轮节点检测...", flush=True)
            log_to_json("INFO", "Main", "开始执行节点拉取与可用性检测周期任务...")
            res = maintain_valid_nodes(force=False)
            if "没有拉取到新节点" not in res:
                success = True
            log_to_json("INFO", "Main", f"周期同步与检测任务完成，结果: {res}")
        except Exception as exc:
            err_msg = f"周期节点同步任务执行异常: {exc}"
            print(f"[错误] {err_msg}", flush=True)
            log_to_json("ERROR", "Main", err_msg)

            set_state(last_check_at=time.time(), last_check_message=f"check error: {exc}")

        if not active_tunnel_running() and not success:
            sleep_time = 30
        else:
            sleep_time = CHECK_INTERVAL_SECONDS

        time.sleep(sleep_time)

