def _sanitize_ui_nodes(nodes):
    cleaned = []
    for node in nodes:
        if not isinstance(node, dict):
            continue
        item = dict(node)
        item.pop("config_text", None)
        item.pop("_pool_metadata", None)
        cleaned.append(item)
    return dedupe_ui_nodes(cleaned)

def _build_ui_nodes_cache():
    global ui_nodes_cache, ui_nodes_cache_at, ui_nodes_cache_building
    try:
        nodes = read_nodes()
        try:
            # OpenVPN is already represented by read_nodes(); Master Pool
            # contributes the additional protocols. Pull the full pool so the
            # UI cache is no longer capped at the old 5,000-endpoint window.
            for endpoint in node_pool.list_endpoints(limit=10000):
                if str(endpoint.get("protocol") or "").lower() == "openvpn":
                    continue
                pool_node = protocol_endpoint_to_ui_node(endpoint)
                if pool_node:
                    nodes.append(pool_node)
        except Exception as exc:
            log_to_json("WARNING", "Main", f"后台多协议节点快照合并失败: {exc}")
        snapshot = _sanitize_ui_nodes(nodes)
        with ui_nodes_cache_lock:
            ui_nodes_cache = snapshot
            ui_nodes_cache_at = time.time()
    except Exception as exc:
        log_to_json("WARNING", "Main", f"后台节点列表快照构建失败: {exc}")
    finally:
        ui_nodes_cache_building = False

_server_identity_lock = threading.Lock()
_server_identity_refreshing = False
_server_identity_attempt_at = 0.0
_SO_BINDTODEVICE = getattr(socket, "SO_BINDTODEVICE", 25)


def _ip_api_fetch(url: str, iface: str = "") -> dict[str, Any]:
    """HTTP GET to ip-api. Bind the socket to the physical NIC when iface is set."""
    parsed = urllib.parse.urlsplit(url)
    host = parsed.hostname or ""
    if not host or parsed.scheme not in ("http", ""):
        return {}
    port = parsed.port or 80
    path = parsed.path or "/"
    if parsed.query:
        path += "?" + parsed.query
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        sock.settimeout(5)
        if iface:
            try:
                sock.setsockopt(socket.SOL_SOCKET, _SO_BINDTODEVICE, iface.encode("utf-8") + b"\0")
            except OSError as exc:
                log_to_json("WARNING", "Bootstrap", f"绑定物理网卡 {iface} 失败: {exc}")
        sock.connect((host, port))
        request = (
            f"GET {path} HTTP/1.0\r\n"
            f"Host: {host}\r\n"
            "User-Agent: aimilivpn/server-identity\r\n"
            "Accept: application/json\r\n"
            "Connection: close\r\n\r\n"
        )
        sock.sendall(request.encode("ascii", errors="ignore"))
        chunks: list[bytes] = []
        total = 0
        while total < 200000:
            data = sock.recv(8192)
            if not data:
                break
            chunks.append(data)
            total += len(data)
    except Exception as exc:
        log_to_json("WARNING", "Bootstrap", f"本机直连身份请求失败: {exc}")
        return {}
    finally:
        try:
            sock.close()
        except Exception:
            pass
    raw = b"".join(chunks)
    body = raw.split(b"\r\n\r\n", 1)[-1] if raw else b""
    try:
        data = json.loads(body.decode("utf-8", errors="replace"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def _public_ip_type_from_api(data: dict[str, Any]) -> str:
    if data.get("hosting") is True:
        return "hosting"
    if data.get("mobile") is True:
        return "mobile"
    if data.get("proxy") is True:
        return "proxy"
    return "residential"


def _public_location_from_api(data: dict[str, Any], country: str) -> str:
    region = str(data.get("regionName") or "").strip()
    city = str(data.get("city") or "").strip()
    bits: list[str] = []
    for part in (region, city):
        if part and part != country and part not in bits:
            bits.append(part)
    return " ".join(bits)


def _identity_from_api(data: dict[str, Any]) -> dict[str, str]:
    if str(data.get("status") or "").lower() not in ("success", ""):
        return {}
    ip = str(data.get("query") or "").strip()
    if not ip:
        return {}
    country = str(data.get("country") or "").strip()
    try:
        country = normalized_country_name(country) or country
    except Exception:
        pass
    owner = str(data.get("isp") or data.get("org") or "").strip()
    return {
        "public_ip": ip,
        "country": country,
        "country_code": str(data.get("countryCode") or "").strip().upper(),
        "location": _public_location_from_api(data, country),
        "owner": owner,
        "ip_type": _public_ip_type_from_api(data),
    }


def _known_direct_server_ip() -> str:
    try:
        ip = str(_read_bootstrap_state().get("local_server_public_ip") or "").strip()
    except Exception:
        ip = ""
    return ip


def _active_tunnel_exit_ip_from_state(state: dict[str, Any] | None = None) -> str:
    if isinstance(state, dict):
        ep = state.get("active_pool_endpoint")
        if isinstance(ep, dict):
            ip = str(ep.get("current_ip") or "").strip()
            if ip:
                return ip
    try:
        raw = read_json(STATE_FILE, {})
    except Exception:
        raw = {}
    if isinstance(raw, dict):
        ep = raw.get("active_pool_endpoint")
        if isinstance(ep, dict):
            return str(ep.get("current_ip") or "").strip()
    return ""


def _lookup_direct_server_identity() -> dict[str, str]:
    """Identity of this machine's own egress. Never the VPN tunnel exit."""
    iface = ""
    try:
        iface = str(proxy_server.physical_egress_interface() or "")
    except Exception:
        iface = ""
    tunnel_ip = _active_tunnel_exit_ip_from_state()
    fields = "status,message,query,country,countryCode,regionName,city,isp,org,mobile,hosting,proxy"
    bound = _identity_from_api(_ip_api_fetch(
        f"http://ip-api.com/json/?lang=zh-CN&fields={fields}",
        iface,
    ))
    bound_ip = str(bound.get("public_ip") or "")
    if bound_ip and bound_ip != tunnel_ip:
        return bound
    if bound_ip and bound_ip == tunnel_ip:
        log_to_json("WARNING", "Bootstrap", f"直连探测走到了隧道出口 {bound_ip}，已丢弃")
    remembered = _known_direct_server_ip()
    if remembered and remembered == tunnel_ip:
        remembered = ""
    if not remembered:
        return {}
    pinned = _identity_from_api(_ip_api_fetch(
        f"http://ip-api.com/json/{remembered}?lang=zh-CN&fields={fields}",
        iface,
    ))
    if str(pinned.get("public_ip") or "") != remembered:
        return {
            "public_ip": remembered,
            "country": "",
            "country_code": "",
            "location": "",
            "owner": "",
            "ip_type": "",
        }
    pinned["public_ip"] = remembered
    return pinned


def _cached_server_identity() -> dict[str, Any]:
    try:
        boot = _read_bootstrap_state()
    except Exception:
        boot = {}
    return {
        "public_ip": str(boot.get("local_server_public_ip") or "").strip(),
        "country": str(boot.get("local_server_country") or "").strip(),
        "country_code": str(boot.get("local_server_country_code") or "").strip().upper(),
        "location": str(boot.get("local_server_location") or "").strip(),
        "owner": str(boot.get("local_server_owner") or "").strip(),
        "ip_type": str(boot.get("local_server_ip_type") or "").strip().lower(),
        "at": float(boot.get("local_server_identity_at") or 0),
    }


def _schedule_server_identity_refresh() -> None:
    global _server_identity_refreshing, _server_identity_attempt_at
    now = time.time()
    with _server_identity_lock:
        if _server_identity_refreshing or now - _server_identity_attempt_at < 60:
            return
        _server_identity_refreshing = True
        _server_identity_attempt_at = now

    def _run() -> None:
        global _server_identity_refreshing, fast_state_cache, fast_state_cache_at
        try:
            found = _lookup_direct_server_identity()
            ip = str(found.get("public_ip") or "").strip()
            tunnel_ip = _active_tunnel_exit_ip_from_state()
            if not ip or (tunnel_ip and ip == tunnel_ip):
                return
            updates = {
                "local_server_public_ip": ip,
                "local_server_identity_at": time.time(),
                "detection_source": "ip-api-direct-nic",
            }
            if found.get("country"):
                updates["local_server_country"] = found["country"]
            if found.get("country_code"):
                updates["local_server_country_code"] = found["country_code"]
            if found.get("location"):
                updates["local_server_location"] = found["location"]
            if found.get("owner"):
                updates["local_server_owner"] = found["owner"]
            if found.get("ip_type"):
                updates["local_server_ip_type"] = found["ip_type"]
            _write_bootstrap_state(**updates)
            with fast_state_cache_lock:
                fast_state_cache = None
                fast_state_cache_at = 0.0
        except Exception as exc:
            log_to_json("WARNING", "Bootstrap", f"本机直连身份写入失败: {exc}")
        finally:
            with _server_identity_lock:
                _server_identity_refreshing = False

    threading.Thread(target=_run, daemon=True, name="server-identity").start()


def _attach_local_server_identity(state: dict[str, Any]) -> None:
    """Expose this machine's direct egress. Never the connected VPN node."""
    ident = _cached_server_identity()
    tunnel_ip = _active_tunnel_exit_ip_from_state(state)
    if tunnel_ip and ident.get("public_ip") == tunnel_ip:
        ident = {
            "public_ip": "",
            "country": ident.get("country") or "",
            "country_code": ident.get("country_code") or "",
            "location": "",
            "owner": "",
            "ip_type": "",
            "at": 0,
        }
    age = time.time() - float(ident.get("at") or 0)
    incomplete = not (
        ident.get("public_ip") and ident.get("location") and ident.get("owner") and ident.get("ip_type")
    )
    if incomplete or age > 6 * 3600:
        _schedule_server_identity_refresh()
    state["server_public_ip"] = str(ident.get("public_ip") or "")
    if ident.get("country"):
        state["server_country"] = str(ident.get("country") or "")
    else:
        state.setdefault("server_country", "")
    if ident.get("country_code"):
        state["server_country_code"] = str(ident.get("country_code") or "")
    else:
        state.setdefault("server_country_code", "")
    state["server_location"] = str(ident.get("location") or "")
    state["server_owner"] = str(ident.get("owner") or "")
    state["server_ip_type"] = str(ident.get("ip_type") or "")


def _detect_local_server_country():
    """Detect this server's public egress once during first-install bootstrap."""
    found = _lookup_direct_server_identity()
    if found.get("country") or found.get("public_ip"):
        return {
            "country": str(found.get("country") or ""),
            "country_code": str(found.get("country_code") or ""),
            "public_ip": str(found.get("public_ip") or ""),
            "location": str(found.get("location") or ""),
            "owner": str(found.get("owner") or ""),
            "ip_type": str(found.get("ip_type") or ""),
            "source": "ip-api-direct-nic",
        }
    if active_tunnel_running():
        return {"country": "", "country_code": "", "public_ip": "", "source": ""}
    urls = (
        "http://ip-api.com/json/?lang=zh-CN&fields=status,query,country,countryCode",
        "https://ipapi.co/json/",
    )
    for url in urls:
        try:
            request = urllib.request.Request(url, headers={"User-Agent": "aimilivpn/bootstrap"})
            with urllib.request.urlopen(request, timeout=5) as response:
                data = json.loads(response.read().decode("utf-8", errors="replace"))
            if not isinstance(data, dict):
                continue
            country = str(data.get("country") or data.get("country_name") or "").strip()
            if country:
                try:
                    country = normalized_country_name(country)
                except Exception:
                    pass
                return {
                    "country": country,
                    "country_code": str(data.get("countryCode") or data.get("country_code") or "").strip().upper(),
                    "public_ip": str(data.get("query") or data.get("ip") or "").strip(),
                    "source": url,
                }
        except Exception as exc:
            log_to_json("WARNING", "Bootstrap", f"本机服务器国家探测失败: {exc}")
    return {"country": "", "country_code": "", "public_ip": "", "source": ""}

def _read_bootstrap_state():
    try:
        data = read_json(BOOTSTRAP_STATE_FILE, {})
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def _write_bootstrap_state(**updates):
    state = _read_bootstrap_state()

    state.update(updates)
    write_json(BOOTSTRAP_STATE_FILE, state)
    return state

def _first_install_bootstrap_needed():
    state = _read_bootstrap_state()
    if state.get("completed"):
        return False
    try:
        stats = node_pool.stats()
        return int(stats.get("endpoints") or 0) == 0
    except Exception:
        return not BOOTSTRAP_STATE_FILE.exists()

def _meminfo_kb() -> tuple[int, int]:
    total = 0
    avail = 0
    try:
        for line in Path("/proc/meminfo").read_text(encoding="utf-8", errors="replace").splitlines():
            if line.startswith("MemTotal:"):
                total = int(line.split()[1])
            elif line.startswith("MemAvailable:"):
                avail = int(line.split()[1])
    except (OSError, ValueError, IndexError):
        return 0, 0
    return total, avail


def _self_rss_kb() -> int:
    return _self_status_kb("VmRSS:")


def _self_swap_kb() -> int:
    return _self_status_kb("VmSwap:")


def _nano_library_pause_reason() -> str:
    """Small hosts must not start a catalog write while the data plane is up.

    Empty means a background collect or country sweep may run. This never
    touches the proxy, the live tunnel, or the list cache.
    """
    total_kb, avail_kb = _meminfo_kb()
    if not (0 < total_kb < 700 * 1024):
        return ""
    if _self_swap_kb() > 64 * 1024:
        return "小机器正在换页，资源库让路"
    if 0 < avail_kb < 90 * 1024:
        return "小机器空闲内存不够，资源库让路"
    try:
        if active_tunnel_running():
            return "小机器隧道在用，资源库让路"
    except Exception:
        pass
    return ""


def _self_status_kb(prefix: str) -> int:
    try:
        for line in Path("/proc/self/status").read_text(encoding="utf-8", errors="replace").splitlines():
            if line.startswith(prefix):
                return int(line.split()[1])
    except (OSError, ValueError, IndexError):
        return 0
    return 0


def memory_guard_loop() -> None:
    """Shrink only this process, and only when it is actually oversized.

    A 512MB machine sits at 40–70MB free while healthy. The previous guard
    treated that as pressure, wiped the list cache every 15 seconds and ran
    gc.collect(). Filters then scanned the whole pool and the page timed out.
    The proxy and the tunnel are other processes; this loop never signals them.
    """
    time.sleep(60)
    while True:
        try:
            total, _avail = _meminfo_kb()
            rss = _self_rss_kb()
            swap = _self_swap_kb()
            # Free arenas only. Do not drop the list index: the previous guard
            # did that whenever free RAM was under 80MB, which is the normal
            # state of this 512MB host, and every filter then scanned cold.
            if swap > 64 * 1024:
                try:
                    import gc
                    gc.collect()
                except Exception:
                    pass
                try:
                    import ctypes
                    ctypes.CDLL("libc.so.6").malloc_trim(0)
                except Exception:
                    pass
            cap = 140 * 1024 if total < 700 * 1024 else 320 * 1024
            if rss > cap:
                global ui_nodes_cache, ui_nodes_cache_at, ui_nodes_cache_building
                with ui_nodes_cache_lock:
                    ui_nodes_cache = []
                    ui_nodes_cache_at = 0.0
                    ui_nodes_cache_building = False
                import gc
                gc.collect()
                try:
                    import ctypes
                    ctypes.CDLL("libc.so.6").malloc_trim(0)
                except Exception:
                    pass
                log_to_json(
                    "INFO",
                    "Memory",
                    f"管理进程 {rss // 1024}MB 超过 {cap // 1024}MB，已丢掉节点全量缓存，列表索引和转发未动",
                )
        except Exception as exc:
            log_to_json("ERROR", "Memory", f"内存回收异常: {exc}")
        time.sleep(300)


def _refresh_ui_nodes_cache_async(force=False):
    global ui_nodes_cache_building
    total, _avail = _meminfo_kb()
    # The open page reads one SQLite page. Building all 10k nodes here is what
    # pushed the 512MB box into swap. Never build that copy on a small machine,
    # including after a manual insert: that path already drops the list index.
    if 0 < total < 700 * 1024:
        return
    with ui_nodes_cache_lock:
        fresh = bool(ui_nodes_cache) and (time.time() - ui_nodes_cache_at) < UI_NODES_CACHE_TTL_SECONDS
        if ui_nodes_cache_building or (not force and fresh):
            return
        ui_nodes_cache_building = True
    threading.Thread(target=_build_ui_nodes_cache, daemon=True, name="ui-node-cache").start()

def _drop_ui_page_snapshots() -> None:
    with _first_page_snapshot_lock:
        _first_page_snapshot.clear()
    try:
        node_pool.invalidate_scoped_pages()
    except Exception:
        pass

def _invalidate_ui_nodes_cache() -> None:
    global ui_nodes_cache, ui_nodes_cache_at, ui_nodes_cache_building
    with ui_nodes_cache_lock:
        ui_nodes_cache = []
        ui_nodes_cache_at = 0.0
        ui_nodes_cache_building = False
    _refresh_ui_nodes_cache_async(force=True)

def _sort_ui_nodes_for_page(nodes):
    """Return the same stable ranking used by the browser, but server-side.

    This lets the first 100 rows be the true first page instead of an arbitrary
    slice of a multi-thousand-node snapshot.
    """
    status_rank = {"available": 0, "testing": 1, "not_checked": 2, "unavailable": 3}
    protocol_rank = {"softether": 0, "sstp": 1, "l2tp-ipsec": 2, "openvpn": 3}
    # One read for the whole page. get_state() opens SQLite; calling it from
    # the sort key ran it once per row and stalled the list for a minute.
    standby = _ui_standby_fields()
    standby_on = bool(standby.get("standby_ready") or standby.get("standby_prepared"))
    standby_id = str(standby.get("standby_node_id") or "")
    standby_ip = str(standby.get("standby_ip") or "")
    standby_port = parse_int(standby.get("standby_port"))
    standby_protocol = str(standby.get("standby_protocol") or "").strip().lower()
    pool_id = standby_id[5:] if standby_id.startswith("pool:") else standby_id

    def key(n):
        active = 2
        if active_pool_endpoint_id and n.get("pool_endpoint_id") == active_pool_endpoint_id:
            active = 0
        elif (not active_pool_endpoint_id and n.get("id") == active_openvpn_node_id):
            active = 0
        elif standby_on:
            node_port = parse_int(n.get("remote_port") or n.get("port"))
            node_protocol = str(n.get("protocol") or "").strip().lower()
            id_match = bool(standby_id) and (
                n.get("id") == standby_id or n.get("pool_endpoint_id") == standby_id
                or n.get("id") == pool_id or n.get("pool_endpoint_id") == pool_id
            )
            ip_match = bool(standby_ip) and str(n.get("ip") or "") == standby_ip and (
                not standby_port or node_port == standby_port
            ) and (not standby_protocol or node_protocol == standby_protocol)
            if id_match or ip_match:
                active = 1
        status = str(n.get("probe_status") or "not_checked").lower()
        latency = float(n.get("latency_ms") or 0)
        latency_key = latency if latency > 0 else float("inf")
        protocol = str(n.get("protocol") or "openvpn").lower()
        score = -float(n.get("score") or 0)
        return (
            active,
            status_rank.get(status, 2),
            latency_key,
            protocol_rank.get(protocol, 9),
            score,
            str(n.get("id") or ""),
        )

    return sorted(_sanitize_ui_nodes(nodes), key=key)


def _get_ui_nodes_snapshot():
    _refresh_ui_nodes_cache_async()
    with ui_nodes_cache_lock:
        if ui_nodes_cache:
            return [dict(x) for x in ui_nodes_cache]
    return _sanitize_ui_nodes(read_nodes())


def _node_matches_ui_scope(node: dict[str, Any], country: str = "", status: str = "", protocol: str = "", ip_type: str = "", speed_min_bps: int = 0, latency: str = "") -> bool:
    country = str(country or "").strip()
    status = str(status or "").strip().lower()
    protocol = str(protocol or "").strip().lower()
    ip_type = str(ip_type or "").strip().lower()
    speed_min_bps = max(0, int(speed_min_bps or 0))

    if country and not country_matches(node.get("country"), country):
        # A populated canonical country is authoritative. Only fall back to
        # location when the source did not provide a country at all; otherwise
        # stale/mismatched IP geolocation must never leak another country's row
        # into a scoped result.
        node_country = str(node.get("country") or "").strip()
        if node_country:
            return False
        location = str(node.get("location") or "").strip()
        if not location or not country_matches(location.split()[0], country):
            return False

    node_protocol = str(node.get("protocol") or "openvpn").strip().lower()
    if protocol and node_protocol != protocol:
        return False

    node_ip_type = str(node.get("ip_type") or "").strip().lower()
    if ip_type and node_ip_type != ip_type:
        return False

    if speed_min_bps > 0 and int(node.get("speed_bps") or node.get("speed") or 0) < speed_min_bps:
        return False
    if not latency_filter_matches(int(node.get("latency_ms") or 0), latency):
        return False

    if status == "usable":
        probe = str(node.get("probe_status") or "").lower()
        return probe in ("available", "testing", "not_checked") or bool(node.get("active"))
    if status == "standby":
        return _ui_node_is_live_standby(node, _ui_standby_fields())
    if status == "available":
        return str(node.get("probe_status") or "").lower() == "available" or bool(node.get("active"))
    if status == "testing":
        return str(node.get("probe_status") or "").lower() == "testing"
    if status == "unavailable":
        return str(node.get("probe_status") or "").lower() == "unavailable" and not bool(node.get("active"))
    return True


def _ui_standby_fields() -> dict[str, Any]:
    """Standby pin for the node table. Do not call get_state() here.

    get_state() also reads pool stats and the active endpoint. Doing that on
    every filter request stacked behind the country sweep and made the table
    miss the browser timeout.
    """
    try:
        raw = read_json(STATE_FILE, {})
    except Exception:
        raw = {}
    if not isinstance(raw, dict):
        raw = {}
    return {
        "standby_ready": bool(raw.get("standby_ready")),
        "standby_prepared": bool(raw.get("standby_prepared")),
        "standby_node_id": str(raw.get("standby_node_id") or ""),
        "standby_ip": str(raw.get("standby_ip") or ""),
        "standby_port": parse_int(raw.get("standby_port")),
        "standby_protocol": str(raw.get("standby_protocol") or "openvpn").strip().lower() or "openvpn",
        "active_pool_endpoint": raw.get("active_pool_endpoint") if isinstance(raw.get("active_pool_endpoint"), dict) else {},
    }


def _ui_node_is_live_standby(node: dict[str, Any], standby_state: dict[str, Any]) -> bool:
    if not node or not (standby_state.get("standby_ready") or standby_state.get("standby_prepared")):
        return False
    sid = str(standby_state.get("standby_node_id") or "")
    pool_id = sid[5:] if sid.startswith("pool:") else sid
    node_ids = {str(node.get("id") or ""), str(node.get("pool_endpoint_id") or "")}
    if sid and node_ids.intersection({sid, pool_id}):
        return True
    ip = str(standby_state.get("standby_ip") or "").strip()
    port = parse_int(standby_state.get("standby_port"))
    protocol = str(standby_state.get("standby_protocol") or "").strip().lower()
    if protocol and str(node.get("protocol") or "").strip().lower() != protocol:
        return False
    return bool(ip) and str(node.get("ip") or "").strip() == ip and (not port or parse_int(node.get("remote_port") or node.get("port")) == port)


def _repair_standby_node_id(endpoint_id: str) -> None:
    """Put a prepared cold standby's pool id back after a hot-standby clear."""
    endpoint_id = str(endpoint_id or "").strip()
    if not endpoint_id:
        return
    wanted = "pool:" + endpoint_id
    try:
        raw = read_json(STATE_FILE, {})
    except Exception:
        return
    if not isinstance(raw, dict):
        return
    if str(raw.get("standby_node_id") or "") == wanted:
        return
    if not (raw.get("standby_prepared") or raw.get("standby_ready")):
        return
    if not str(raw.get("standby_ip") or "").strip():
        return
    set_state(standby_node_id=wanted)


def _load_live_standby_ui_node(standby_state: dict[str, Any]) -> dict[str, Any] | None:
    sid = str(standby_state.get("standby_node_id") or "")
    endpoint = None
    if sid:
        lookup = sid[5:] if sid.startswith("pool:") else sid
        endpoint = node_pool.get_endpoint(lookup)
        if not endpoint:
            parts = sid.rsplit("_", 2)
            if len(parts) == 3 and str(parts[1]).isdigit():
                found = node_pool.find_endpoint_id(parts[0], int(parts[1]), str(standby_state.get("standby_protocol") or "openvpn"))
                if found:
                    endpoint = node_pool.get_endpoint(found)
    if not endpoint:
        ip = str(standby_state.get("standby_ip") or "").strip()
        port = parse_int(standby_state.get("standby_port"))
        protocol = str(standby_state.get("standby_protocol") or "").strip().lower()
        if ip and port and protocol:
            found = node_pool.find_endpoint_id(ip, port, protocol)
            if found:
                endpoint = node_pool.get_endpoint(found)
                if endpoint and not sid:
                    _repair_standby_node_id(found)
    if not endpoint:
        return None
    node = protocol_endpoint_to_ui_node(endpoint)
    return dict(node) if node else None


def _pin_connected_then_standby(page_nodes: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Keep the live exit first and its hot standby directly underneath."""
    nodes = [dict(node) for node in (page_nodes or []) if node]
    standby_state = _ui_standby_fields()
    active_ids = {str(active_pool_endpoint_id or ""), str(active_openvpn_node_id or "")}
    active_ids.discard("")

    def is_active(node: dict[str, Any]) -> bool:
        ids = {str(node.get("id") or ""), str(node.get("pool_endpoint_id") or "")}
        return bool(node.get("active")) or bool(active_ids and ids.intersection(active_ids))

    active = next((node for node in nodes if is_active(node)), None)
    rest = [node for node in nodes if node is not active]
    standby = next((node for node in rest if _ui_node_is_live_standby(node, standby_state)), None)
    if standby is not None:
        rest = [node for node in rest if node is not standby]
    elif standby_state.get("standby_ready") or standby_state.get("standby_prepared"):
        standby = _load_live_standby_ui_node(standby_state)
        if standby and active and {str(standby.get("id") or ""), str(standby.get("pool_endpoint_id") or "")} & {str(active.get("id") or ""), str(active.get("pool_endpoint_id") or "")}:
            standby = None
    if standby and active and str(standby.get("ip") or "").strip() and str(standby.get("ip") or "").strip() == str(active.get("ip") or "").strip():
        standby = None
    ordered: list[dict[str, Any]] = []
    if active:
        ordered.append(active)
    if standby:
        standby = dict(standby)
        standby["standby_row"] = True
        ordered.append(standby)
    ordered.extend(rest)
    seen: set[str] = set()
    unique: list[dict[str, Any]] = []
    for node in ordered:
        ip = str(node.get("ip") or "").strip()
        protocol = str(node.get("protocol") or "").strip().lower()
        try:
            port = int(node.get("remote_port") or node.get("port") or 0)
        except (TypeError, ValueError):
            port = 0
        key = f"{protocol}|{ip}|{port}" if ip and port else "id:" + str(node.get("pool_endpoint_id") or node.get("id") or "")
        if key in seen:
            continue
        seen.add(key)
        unique.append(node)
    return unique


def _get_ui_nodes_page(offset=0, limit=100, country="", status="", protocol="", ip_type="", speed_min_bps=0, latency=""):
    """Return a bounded page for the requested scope.

    The browser should never download the global pool merely to populate a
    dropdown. Country/status/protocol/IP-type selection is a server-side query;
    only the selected scope is transferred to the browser.
    """
    offset = max(0, int(offset or 0))
    limit = max(1, min(200, int(limit or 100)))
    speed_min_bps = max(0, int(speed_min_bps or 0))
    started = time.perf_counter()

    # Do not start/build the heavyweight global UI snapshot here. The Master
    # Pool is the normal source for this endpoint, so a country/filter request
    # must remain fast and independent of global cache construction.
    with ui_nodes_cache_lock:
        building = bool(ui_nodes_cache_building)

    # Master Pool is authoritative for every UI node read, including the
    # explicit “全球国家” scope. The browser must never depend on the
    # heavyweight global snapshot being complete before filters or pages work.
    # SQLite performs the scope/count query and HTTP returns only one page.
    try:
        active_endpoint_id = str(active_pool_endpoint_id or "")
        active_ip = active_protocol = ""
        active_port = 0
        standby_state = _ui_standby_fields()
        active_meta = standby_state.get("active_pool_endpoint") or {}
        if active_endpoint_id and str(active_meta.get("endpoint_id") or "") == active_endpoint_id:
            active_ip = str(active_meta.get("current_ip") or "").strip()
            active_protocol = str(active_meta.get("protocol") or "").strip().lower()
            active_port = parse_int(active_meta.get("port"))
        elif active_openvpn_node_id:
            parts = str(active_openvpn_node_id).rsplit("_", 2)
            if len(parts) == 3 and str(parts[1]).isdigit():
                active_ip = parts[0].strip()
                active_port = int(parts[1])
                active_protocol = "openvpn"
        standby_endpoint_id = ""
        standby_ip = str(standby_state.get("standby_ip") or "").strip()
        standby_protocol = str(standby_state.get("standby_protocol") or "openvpn").strip().lower()
        standby_port = parse_int(standby_state.get("standby_port"))
        if standby_state.get("standby_ready") or standby_state.get("standby_prepared"):
            standby_id = str(standby_state.get("standby_node_id") or "")
            if standby_id.startswith("pool:"):
                standby_endpoint_id = standby_id[5:]
            else:
                found = node_pool.get_endpoint(standby_id) if standby_id else None
                if found:
                    standby_endpoint_id = standby_id
                    standby_ip = standby_ip or str(found.get("current_ip") or "")
                    standby_port = standby_port or parse_int(found.get("port"))
                    standby_protocol = str(found.get("protocol") or standby_protocol)
                else:
                    parts = standby_id.rsplit("_", 2)
                    if len(parts) == 3 and str(parts[1]).isdigit():
                        standby_ip = standby_ip or parts[0].strip()
                        standby_port = standby_port or int(parts[1])
            if not standby_endpoint_id and standby_ip and standby_port > 0 and standby_protocol:
                try:
                    found_id = node_pool.find_endpoint_id(standby_ip, standby_port, standby_protocol)
                except Exception:
                    found_id = ""
                if found_id:
                    standby_endpoint_id = found_id
                    if not standby_id:
                        _repair_standby_node_id(found_id)
        scoped_endpoints, endpoint_total = node_pool.list_endpoints_scoped(
            country=country,
            status=status,
            protocol=protocol,
            ip_type=ip_type,
            offset=offset,
            limit=limit,
            speed_min_bps=speed_min_bps,
            latency=latency,
            active_endpoint_id=active_endpoint_id,
            active_ip=active_ip,
            active_protocol=active_protocol,
            active_port=active_port,
            standby_endpoint_id=standby_endpoint_id,
            standby_ip=standby_ip,
            standby_protocol=standby_protocol,
            standby_port=standby_port,
        )
        scoped_nodes = [
            protocol_endpoint_to_ui_node(endpoint)
            for endpoint in scoped_endpoints
        ]
        scoped_nodes = _sanitize_ui_nodes([node for node in scoped_nodes if node])
        sqlite_ms = int((time.perf_counter() - started) * 1000)
        apply_server_tcp_rtt(scoped_nodes)
        # Keep the browser-facing ranking deterministic inside the returned
        # page. The SQL query already applies the same primary status/latency
        # ordering, so we do not materialize thousands of rows in Python.
        ordered = _sort_ui_nodes_for_page(scoped_nodes)
        # The SQL total is already one row per protocol/IP/port. If this page
        # held every matching endpoint, the deduped payload is the number the
        # footer must show — never a larger raw COUNT.
        if offset == 0 and len(scoped_endpoints) < limit:
            endpoint_total = len(ordered)
        total_ms = int((time.perf_counter() - started) * 1000)
        if total_ms > 200:
            log_to_json("INFO", "UI", f"ui_nodes_ms={total_ms} sqlite_ms={sqlite_ms} serialize_ms={max(0, total_ms - sqlite_ms)} country={country or '-'} protocol={protocol or '-'}")
        return ordered, endpoint_total, building
    except Exception as exc:
        if "busy" in str(exc).lower():
            raise
        log_to_json("WARNING", "Main", f"按范围读取 Master Pool UI 页面失败，回退 UI 快照: {exc}")

    # Emergency compatibility fallback for an unavailable/locked Master Pool.
    # This path is never the normal source of country/filter data.
    _refresh_ui_nodes_cache_async()
    with ui_nodes_cache_lock:
        snapshot = [dict(x) for x in ui_nodes_cache] if ui_nodes_cache else []
    if not snapshot:
        snapshot = _sanitize_ui_nodes(read_nodes())
    filtered = [n for n in snapshot if _node_matches_ui_scope(n, country, status, protocol, ip_type, speed_min_bps, latency)]
    ordered = _sort_ui_nodes_for_page(filtered)
    total = len(ordered)
    return ordered[offset:offset + limit], total, building


def _get_ui_filter_counts(country="", protocol="", ip_type="", speed_min_bps=0, latency=""):
    """Return status counts for the currently selected filter scope."""
    started = time.perf_counter()
    country = normalized_country_name(country) if country else ""
    protocol = str(protocol or "").strip().lower()
    ip_type = str(ip_type or "").strip().lower()
    speed_min_bps = max(0, int(speed_min_bps or 0))
    try:
        latency = normalize_routing_latency(latency)
    except ValueError:
        latency = ""
    status_counts = node_pool.status_counts(country=country, protocol=protocol, ip_type=ip_type, speed_min_bps=speed_min_bps, latency=latency)
    connected_count = 0
    try:
        if active_pool_endpoint_id:
            endpoint = node_pool.get_endpoint(active_pool_endpoint_id)
            node = protocol_endpoint_to_ui_node(endpoint) if endpoint else {}
            connected_count = 1 if node and _node_matches_ui_scope(node, country, "", protocol, ip_type, speed_min_bps, latency) else 0
        elif active_openvpn_node_id:
            node = _openvpn_status_node(active_openvpn_node_id)
            connected_count = 1 if node and _node_matches_ui_scope(node, country, "", protocol, ip_type, speed_min_bps, latency) else 0
    except Exception:
        connected_count = 0
    elapsed_ms = int((time.perf_counter() - started) * 1000)
    if elapsed_ms > 200:
        log_to_json("INFO", "UI", f"filter_counts_ms={elapsed_ms} country={country or '-'} protocol={protocol or '-'}")
    return {
        "country": country,
        "protocol": protocol,
        "ip_type": ip_type,
        "status_counts": status_counts,
        "connected_count": connected_count,
    }


def _get_ui_country_catalog(status="", protocol="", ip_type="", speed_min_bps=0, latency=""):
    """Return global country/IP totals without transferring global node rows."""
    started = time.perf_counter()
    status = str(status or "").strip().lower()
    protocol = str(protocol or "").strip().lower()
    ip_type = str(ip_type or "").strip().lower()
    speed_min_bps = max(0, int(speed_min_bps or 0))
    try:
        latency = normalize_routing_latency(latency)
    except ValueError:
        latency = ""
    try:
        catalog = node_pool.country_catalog(
            status=status,
            protocol=protocol,
            ip_type=ip_type,
            connected_endpoint_id=active_pool_endpoint_id,
            speed_min_bps=speed_min_bps,
            latency=latency,
        )
    except Exception:
        catalog = {"total_ip_count": 0, "countries": {}}

    # Country/IP inventory is authoritative in Master Pool. Manual nodes are
    # promoted into the same SQLite pool when added, so the UI never has to
    # scan nodes.json or compute a second country inventory on the frontend.
    countries = dict(catalog.get("countries") or {})

    if status == "connected" and not active_pool_endpoint_id and active_openvpn_node_id:
        try:
            active = next(
                (n for n in read_nodes() if str(n.get("id") or "") == str(active_openvpn_node_id)),
                None,
            )
            active_country = normalized_country_name((active or {}).get("country") or "")
            if active_country:
                countries = {active_country: {"ip_count": 1, "server_count": 1}}
                catalog["total_ip_count"] = 1
                catalog["country_ip_count"] = 1
        except Exception:
            pass

    bootstrap = _read_bootstrap_state()
    server_country = str(
        bootstrap.get("local_server_country")
        or read_json(STATE_FILE, {}).get("initial_bootstrap_country")
        or ""
    ).strip()
    elapsed_ms = int((time.perf_counter() - started) * 1000)
    if elapsed_ms > 200:
        log_to_json("INFO", "UI", f"country_catalog_ms={elapsed_ms} protocol={protocol or '-'} ip_type={ip_type or '-'}")
    return {
        "total_ip_count": int(catalog.get("total_ip_count") or 0),
        "country_ip_count": int(catalog.get("country_ip_count") or sum(int(v.get("ip_count") or 0) for v in countries.values())),
        "countries": countries,
        "server_country": server_country,
        "status": status,
        "protocol": protocol,
        "ip_type": ip_type,
    }


def _openvpn_status_node(node_id: str) -> dict[str, Any]:
    """Lightweight status-card payload. Avoids parsing the multi-megabyte node file."""
    node_id = str(node_id or "").strip()
    lookup_id = node_id[7:] if node_id.startswith("MANUAL_") else node_id
    parts = lookup_id.rsplit("_", 2)
    host, port = "", 0
    if len(parts) == 3 and str(parts[1]).isdigit():
        host, port = parts[0], int(parts[1])
    endpoint = None
    if host and port:
        try:
            endpoint_id = ""
            if re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", host):
                endpoint_id = node_pool.find_endpoint_id(host, port, "openvpn")
            if not endpoint_id:
                endpoint_id = node_pool.find_endpoint_id_by_host(host, port, "openvpn")
            if endpoint_id:
                endpoint = node_pool.get_endpoint(endpoint_id)
        except Exception:
            endpoint = None
    if endpoint:
        node = protocol_endpoint_to_ui_node(endpoint)
        node["id"] = node_id
        return node
    display_host = host[7:] if host.startswith("MANUAL_") else host
    return {
        "id": node_id,
        "ip": display_host if re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", display_host) else "",
        "host_name": "" if re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", display_host or "") else display_host,
        "remote_host": display_host,
        "remote_port": port,
        "protocol": "openvpn",
        "country": "",
        "location": "",
        "owner": "",
        "ip_type": "",
        "speed": 0,
    }


def _publish_fast_state_overlay(state: dict[str, Any]) -> None:
    """Live flags only. No SQLite and no `ip addr` on the 4s poll."""
    state["is_connecting"] = is_connecting
    state["manual_connection_active"] = manual_connection_active
    state["connection_generation"] = connection_generation
    state["active_connection_generation"] = active_connection_generation
    state["active_openvpn_node_id"] = active_openvpn_node_id
    state["active_pool_endpoint_id"] = active_pool_endpoint_id
    state["maintenance_running"] = maintenance_lock.locked()
    if is_connecting or manual_connection_active or failover_lock.locked():
        state["connection_status"] = "connecting"
        state["connection_message"] = "正在建立或切换 VPN 隧道"
        state["client_status"] = "validating"
        state["client_usable"] = False
    try:
        state.update(_library_check_public_state())
    except Exception:
        pass
    try:
        _overlay_pool_roles(state)
    except Exception:
        pass


def _refresh_fast_state_bg() -> None:
    global _fast_state_refreshing
    try:
        _build_fast_nodes_state()
    except Exception as exc:
        log_to_json("WARNING", "UI", f"状态缓存刷新失败: {exc}")
    finally:
        with fast_state_cache_lock:
            _fast_state_refreshing = False


def _get_fast_nodes_state():
    """Return the last state immediately. Rebuild off the request thread.

    The 4s poll used to rebuild on the request itself. A rebuild that took
    longer than the cache TTL started another one, and the browser gave up
    at 4s with 请求超时. Switching still shows up at once via the in-memory
    flags overlaid below.
    """
    global _fast_state_refreshing
    now_mono = time.monotonic()
    with fast_state_cache_lock:
        cached = dict(fast_state_cache) if isinstance(fast_state_cache, dict) else None
        age = now_mono - fast_state_cache_at if cached is not None else 1e9
        stale = cached is None or age >= FAST_STATE_CACHE_TTL_SECONDS
        launch = stale and not _fast_state_refreshing
        if launch:
            _fast_state_refreshing = True
    if cached is not None:
        if launch:
            threading.Thread(target=_refresh_fast_state_bg, daemon=True, name="fast-state").start()
        _publish_fast_state_overlay(cached)
        return cached
    if not launch:
        for _ in range(40):
            time.sleep(0.05)
            with fast_state_cache_lock:
                if isinstance(fast_state_cache, dict):
                    cached = dict(fast_state_cache)
                    break
        if cached is not None:
            _publish_fast_state_overlay(cached)
            return cached
    try:
        return _build_fast_nodes_state()
    finally:
        with fast_state_cache_lock:
            _fast_state_refreshing = False


def _build_fast_nodes_state():
    global fast_state_cache, fast_state_cache_at
    state = read_json(STATE_FILE, {})
    state.pop("password", None)
    cert_state = web_certificate.snapshot()
    state["web_domain"] = str(load_ui_config().get("web_domain") or cert_state.get("domain") or "")
    state["web_certificate"] = cert_state
    state["active_openvpn_node_id"] = active_openvpn_node_id
    state["active_pool_endpoint_id"] = active_pool_endpoint_id
    if not is_connecting and not manual_connection_active:
        state["manual_switch_active"] = False
    state["probe_engine_running"] = probe_engine_running
    state["probe_engine_message"] = probe_engine_message
    state["probe_engine_target_country"] = probe_engine_target_country
    state.setdefault("priority_full_sweep_running", False)
    state.setdefault("priority_full_sweep_total", 0)
    state.setdefault("priority_full_sweep_tested", 0)
    state.setdefault("priority_full_sweep_remaining", 0)
    state.setdefault("priority_full_sweep_country", "")
    state["connected_count"] = 1 if (active_pool_endpoint_id or active_openvpn_node_id) else 0
    cached_active = state.get("active_openvpn_node")
    cached_incomplete = (
        not isinstance(cached_active, dict)
        or not str(cached_active.get("country") or "").strip()
        or not str(cached_active.get("ip_type") or cached_active.get("owner") or "").strip()
    )
    if active_openvpn_node_id and cached_incomplete:
        state["active_openvpn_node"] = _openvpn_status_node(active_openvpn_node_id)
    elif isinstance(cached_active, dict) and cached_active.get("id"):
        state["active_openvpn_node"] = cached_active
    elif active_openvpn_node_id:
        state["active_openvpn_node"] = _openvpn_status_node(active_openvpn_node_id)
    else:
        state["active_openvpn_node"] = None
    pooled = state.get("active_pool_endpoint") if isinstance(state.get("active_pool_endpoint"), dict) else {}
    if active_pool_endpoint_id and not (pooled.get("location") and pooled.get("owner") and pooled.get("ip_type")):
        try:
            full = node_pool.get_endpoint(active_pool_endpoint_id) or {}
            meta = full.get("server_metadata") or {}
            merged = dict(pooled)
            merged.update({
                "endpoint_id": active_pool_endpoint_id,
                "protocol": full.get("protocol") or merged.get("protocol") or "",
                "hostname": full.get("hostname") or merged.get("hostname") or "",
                "current_ip": full.get("current_ip") or merged.get("current_ip") or "",
                "port": full.get("port") or merged.get("port") or 0,
                "country": full.get("country") or merged.get("country") or "",
                "location": meta.get("location") or full.get("country") or merged.get("location") or "",
                "owner": meta.get("owner") or meta.get("as_name") or merged.get("owner") or "",
                "ip_type": meta.get("ip_type") or merged.get("ip_type") or "",
            })
            state["active_pool_endpoint"] = merged
        except Exception:
            pass
    # Do not parse nodes.json here. It is a multi-megabyte config snapshot, and
    # doing it on the homepage state request blocks every other UI call.
    cached_pool = state.get("active_pool_endpoint")
    if isinstance(cached_pool, dict) and cached_pool.get("endpoint_id"):
        state["active_pool_endpoint"] = cached_pool
    else:
        state["active_pool_endpoint"] = None
    if active_pool_endpoint_id and not state["active_pool_endpoint"]:
        try:
            endpoint = node_pool.get_endpoint(active_pool_endpoint_id)
            if endpoint:
                meta = endpoint.get("server_metadata") or {}
                state["active_pool_endpoint"] = {
                    "endpoint_id": endpoint.get("endpoint_id", ""),
                    "protocol": endpoint.get("protocol", ""),
                    "transport": endpoint.get("transport", ""),
                    "port": endpoint.get("port", 0),
                    "hostname": endpoint.get("hostname", ""),
                    "current_ip": endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "",
                    "country": endpoint.get("country", ""),
                    "location": meta.get("location") or endpoint.get("country", ""),
                    "owner": meta.get("owner") or meta.get("as_name") or "",
                    "ip_type": meta.get("ip_type") or "",
                    "quality": meta.get("quality") or "",
                    "speed": endpoint.get("latest_speed", 0),
                    "speed_bps": endpoint.get("latest_speed", 0),
                    "speed_source": "vpngate_observation" if int(endpoint.get("latest_speed") or 0) > 0 else "not_measured",
                    "latency_ms": endpoint.get("latency_ewma", 0),
                }
        except Exception:
            state["active_pool_endpoint"] = None

    try:
        pool_stats = node_pool.stats()
        state["pool_servers"] = int(pool_stats.get("servers") or 0)
        state["pool_endpoints"] = int(pool_stats.get("endpoints") or 0)
        state["pool_distinct_ips"] = int(pool_stats.get("distinct_ips") or 0)
        state["pool_country_ips"] = int(pool_stats.get("country_ips") or 0)
        state["pool_states"] = pool_stats.get("states") or {}
        state["hot_pool_size"] = int((pool_stats.get("states") or {}).get("HOT") or 0)
        state["hot_pool_target"] = HOT_POOL_TARGET
        state["hot_pool_deficit"] = max(0, HOT_POOL_TARGET - state["hot_pool_size"])
    except Exception:
        state.setdefault("pool_servers", 0)
        state.setdefault("pool_endpoints", 0)
    _overlay_pool_roles(state)
    state["is_connecting"] = is_connecting
    state["manual_connection_active"] = manual_connection_active
    state["connection_generation"] = connection_generation
    state["active_connection_generation"] = active_connection_generation
    state["manual_route_pin"] = dict(manual_route_pin)
    state["manual_connection_quiet_until"] = manual_connection_quiet_until
    state["ui_command_plane"] = ui_command_plane.ui_state()
    state["maintenance_running"] = maintenance_lock.locked()
    state["global_pool_refresh_running"] = global_pool_refresh_running
    state["global_pool_refresh_last_at"] = global_pool_refresh_last_at
    state["global_pool_refresh_status"] = global_pool_refresh_status
    state["global_pool_refresh_message"] = global_pool_refresh_message
    state["global_pool_refresh_servers"] = global_pool_refresh_servers
    state["global_pool_refresh_sources"] = global_pool_refresh_sources
    state.update(_library_check_public_state())

    try:
        active = active_tunnel_running()
    except Exception:
        active = False
    state["active_tunnel_ok"] = bool(active)
    state["egress_mode"] = proxy_server.get_egress_mode()
    if active:
        state["connection_status"] = "connected"
        state["connection_message"] = "当前 VPN 隧道正常运行"
        if state.get("egress_mode") == "proxy":
            flag = state.get("client_proxy_ok")
            if flag is None:
                flag = state.get("proxy_ok")
            if flag is True:
                state["client_status"] = "usable"
            elif flag is False:
                state["client_status"] = "degraded"
            else:
                state["client_status"] = "validating"
        else:
            state["client_status"] = "validating"
    elif manual_connection_active or failover_lock.locked() or is_connecting:
        state["connection_status"] = "connecting"
        state["connection_message"] = "正在建立或切换 VPN 隧道"
        state["client_status"] = "validating"
    else:
        state["connection_status"] = "disconnected"
        state["connection_message"] = "当前没有活动 VPN 隧道"
        state["client_status"] = "not_connected"
    state["client_usable"] = state["client_status"] == "usable"

    state["resource_engine_running"] = bool(resource_engine_running)
    state["resource_engine_message"] = resource_engine_message
    state["resource_engine_last_at"] = resource_engine_last_at
    state["availability_engine_running"] = bool(availability_engine_running)
    state["availability_engine_message"] = availability_engine_message
    state["availability_tested_total"] = int(availability_tested_total)
    state["availability_queue"] = int(availability_queue)
    state["availability_new_pending"] = int(availability_new_pending)
    state["availability_recheck_seconds"] = 4 * 3600
    state["coverage_country"] = coverage_country
    state["coverage_inventory"] = int(coverage_inventory)
    state["coverage_available"] = int(coverage_available)
    state["coverage_selected"] = int(coverage_selected)
    state["coverage_target"] = int(coverage_target)
    state["coverage_last_at"] = coverage_last_at
    proxy_state = _upstream_proxy_state()
    state["upstream_proxy_mode"] = proxy_state["mode"]
    state["upstream_proxy_type"] = proxy_state["type"]
    state["upstream_proxy_host"] = proxy_state["host"]
    state["upstream_proxy_port"] = proxy_state["port"]
    state["upstream_proxy_label"] = proxy_state["label"]
    state.setdefault("target_valid_nodes", TARGET_VALID_NODES)
    state.setdefault("favorite_node_ids", [])
    ui_cfg = load_ui_config()
    state["routing_mode"] = ui_cfg.get("routing_mode", "auto")
    state["force_country"] = ui_cfg.get("force_country", "")
    state["routing_ip_type"] = ui_cfg.get("routing_ip_type", "all")
    state["routing_protocol"] = str(ui_cfg.get("routing_protocol") or "")
    state["routing_min_speed_bps"] = int(ui_cfg.get("routing_min_speed_bps") or 0)
    state["routing_latency"] = str(ui_cfg.get("routing_latency") or "")
    state["routing_blocklist"] = str(ui_cfg.get("routing_blocklist") or "")
    state["background_paused"] = background_paused()
    if state["background_paused"]:
        state["priority_running"] = False
        state["priority_full_sweep_running"] = False
    try:
        scheme = scheme_match_snapshot(ui_cfg)
    except Exception:
        scheme = {}
    state["scheme_country"] = str((scheme or {}).get("country") or "")
    state["scheme_available"] = int((scheme or {}).get("available") or 0)
    state["scheme_inventory"] = int((scheme or {}).get("inventory") or 0)
    state["scheme_label"] = str((scheme or {}).get("label") or "")
    state["scheme_capped"] = bool((scheme or {}).get("capped"))
    _attach_local_server_identity(state)
    with fast_state_cache_lock:
        fast_state_cache = dict(state)
        fast_state_cache_at = time.monotonic()
    return state

def _runtime_connection_status():
    if active_tunnel_running():
        return "connected", "当前 VPN 隧道正常运行"
    if manual_connection_active or failover_lock.locked():
        return "connecting", "正在建立或切换 VPN 隧道"
    return "disconnected", "当前没有活动 VPN 隧道"

def _runtime_client_status():
    if not active_tunnel_running():
        return "not_connected"
    state = _legacy_get_state_v2()
    if state.get("proxy_ok") is True:
        return "usable"
    if state.get("proxy_ok") is False:
        return "degraded"
    return "validating"

def _upstream_proxy_state():
    try:
        ptype, host, port = vpn_utils.get_upstream_proxy()
    except Exception:
        ptype = host = port = None
    if host and port:
        return {"mode":"custom_upstream","type":str(ptype or ""), "host":str(host), "port":int(port),
                "label":f"自定义上游代理 · {ptype or 'proxy'}://{host}:{port}"}
    return {"mode":"system_default","type":"","host":"","port":0,"label":"系统默认网络（未设置自定义上游代理）"}


def _endpoint_country(endpoint):
    return normalized_country_name(endpoint.get("country") or "")

def _endpoint_ip(endpoint):
    if not endpoint:
        return ""
    return str(endpoint.get("current_ip") or (endpoint.get("metadata") or {}).get("ip") or "").strip()

def _endpoint_ip_type(endpoint):
    m=endpoint.get("server_metadata") or {}
    value=str(m.get("ip_type") or (endpoint.get("metadata") or {}).get("ip_type") or "").lower()
    return value if value in ("residential","mobile","hosting") else "unknown"

def country_reserve_snapshot(country, target=COUNTRY_RESERVE_TARGET):
    target_country=normalized_country_name(country)
    if not target_country:
        return {"country":"","inventory":0,"available":0,"selected":0,"target":0,"selected_endpoints":[]}
    all_items=[]
    available_items=[]
    for ep in node_pool.list_endpoints(limit=5000):
        if _endpoint_country(ep)!=target_country:
            continue
        if not _endpoint_ip(ep):
            continue
        status=str(ep.get("status") or "").upper()
        if status in ("RETIRED","STALE"):
            continue
        all_items.append(ep)
        if status in ("HOT","AVAILABLE"):
            ep["selection_score"]=node_pool._selection_score(ep)[0]
            available_items.append(ep)

    inventory={_endpoint_ip(x) for x in all_items if _endpoint_ip(x)}
    available_ips={_endpoint_ip(x) for x in available_items if _endpoint_ip(x)}
    selected=[]; used=set()
    for protocol in ("openvpn","softether","sstp","l2tp-ipsec"):
        for ip_type in ("residential","mobile","hosting"):
            bucket=[x for x in available_items if str(x.get("protocol") or "").lower()==protocol and _endpoint_ip_type(x)==ip_type and _endpoint_ip(x) not in used]
            bucket.sort(key=lambda x:(-float(x.get("selection_score") or 0),float(x.get("latency_ewma") or 999999),-int(x.get("success_streak") or 0)))
            taken=0
            for ep in bucket:
                ip=_endpoint_ip(ep)
                if not ip or ip in used:
                    continue
                selected.append(ep); used.add(ip); taken+=1
                if taken>=COUNTRY_RESERVE_PER_BUCKET or len(selected)>=target:
                    break
            if len(selected)>=target:
                break
        if len(selected)>=target:
            break
    if len(selected)<target:
        rest=[x for x in available_items if _endpoint_ip(x) not in used]
        rest.sort(key=lambda x:(-float(x.get("selection_score") or 0),float(x.get("latency_ewma") or 999999),-int(x.get("success_streak") or 0)))
        for ep in rest:
            ip=_endpoint_ip(ep)
            if not ip or ip in used:
                continue
            selected.append(ep); used.add(ip)
            if len(selected)>=target:
                break
    return {"country":target_country,"inventory":len(inventory),"available":len(available_ips),"selected":len(selected),
            "target":min(int(target),max(1,len(inventory))) if inventory else 0,"selected_endpoints":selected[:int(target)]}

def _pick_global_country_for_coverage_v2():
    """Choose the next country only after the priority country is healthy.

    Ranking is primarily measured minimum latency, then remaining reserve
    deficit. This makes the next detection country useful for actual failover
    rather than simply cycling alphabetically or by inventory size.
    """
    snapshot=_global_country_pool_snapshot(); now=time.time(); ranked=[]
    endpoints = node_pool.list_endpoints(limit=5000)
    latency_by_country={}
    for ep in endpoints:
        country=_endpoint_country(ep)
        status=str(ep.get("status") or "").upper()
        if not country or status not in ("HOT","AVAILABLE"):
            continue
        latency=float(ep.get("latency_ewma") or ep.get("latest_ping") or 999999)
        if latency>0:
            latency_by_country[country]=min(latency_by_country.get(country,999999),latency)
    for country,values in snapshot.items():
        inventory=len(values.get("inventory") or set()); available=len(values.get("available") or set())
        if inventory<=0: continue
        target=min(COUNTRY_RESERVE_TARGET,inventory)
        if available>=target: continue
        last=float(global_country_coverage_last_attempt.get(country,0) or 0)
        if now-last<COUNTRY_COVERAGE_ROTATION_SECONDS: continue
        best_latency=latency_by_country.get(country,999999)
        deficit=(target-available)/max(1,target)
        ranked.append((best_latency, -deficit, -inventory, last, country))
    ranked.sort()
    return ranked[0][4] if ranked else ""



def _due_endpoints(country="", protocols=("openvpn","softether","sstp","l2tp-ipsec"), limit=10):
    target=normalized_country_name(country)
    rows=node_pool.due_endpoints(tuple(protocols), limit=max(1,min(int(limit),100)), country=target)
    rows=[ep for ep in rows if str(ep.get("status") or "").upper() not in ("STALE","RETIRED")]
    def _probe_priority(ep):
        meta = ep.get("server_metadata") or {}
        ip_type = str(meta.get("ip_type") or (ep.get("metadata") or {}).get("ip_type") or "").lower()
        speed = int(ep.get("latest_speed") or ep.get("speed") or 0)
        preferred_fast = ip_type in ("residential", "mobile") and speed >= ROUTING_MIN_LINE_SPEED_BPS
        preferred_type = 0 if preferred_fast else (1 if speed >= ROUTING_MIN_LINE_SPEED_BPS else 2)
        type_rank = {"mobile": 0, "residential": 1, "hosting": 2}.get(ip_type, 3)
        latency = float(ep.get("latency_ewma") or ep.get("latest_ping") or 999999)
        return (0 if str(ep.get("status") or "").upper()=="NEW" else 1, preferred_type, type_rank, latency, float(ep.get("next_test") or 0), float(ep.get("last_success") or 0))
    rows.sort(key=_probe_priority)
    return rows[:max(1,min(int(limit),5000))]

def _due_counts():
    counts = node_pool.due_counts(("openvpn","softether","sstp","l2tp-ipsec"))
    return int(counts.get("openvpn", 0)), sum(int(counts.get(p, 0)) for p in ("softether","sstp","l2tp-ipsec"))

def _finish_priority_if_ready(country):
    global country_priority_request,country_priority_explicit
    if not country_priority_explicit or not country: return
    snap=country_reserve_snapshot(country); available=int(snap.get("available") or 0); inventory=int(snap.get("inventory") or 0)
    if available>=COUNTRY_PRIORITY_AVAILABLE_TARGET:
        set_state(priority_country=country,priority_inventory=inventory,priority_inventory_target=min(60,max(1,inventory)),priority_available=COUNTRY_PRIORITY_AVAILABLE_TARGET,
                  priority_target=COUNTRY_PRIORITY_AVAILABLE_TARGET,priority_minimum=5,priority_running=False,priority_message=f"{country} 已达到 {COUNTRY_PRIORITY_AVAILABLE_TARGET} 个可用节点")
        country_priority_request=""; country_priority_explicit=False
    elif not _due_endpoints(country,("openvpn","softether","sstp","l2tp-ipsec"),1):
        set_state(priority_country=country,priority_inventory=inventory,priority_inventory_target=min(60,max(1,inventory)) if inventory else 60,
                  priority_available=min(COUNTRY_PRIORITY_AVAILABLE_TARGET,available),priority_target=COUNTRY_PRIORITY_AVAILABLE_TARGET,
                  priority_minimum=5,priority_running=False,priority_message=f"{country} 当前资源已完成检测，可用 {available}；等待新资源自动进入")
        country_priority_request=""; country_priority_explicit=False

def availability_sweep_once(priority_country=""):
    global availability_engine_running,availability_engine_message,availability_tested_total,availability_queue,availability_new_pending
    if manual_connection_active or failover_lock.locked() or is_connecting: return {"ok":True,"skipped":True,"reason":"用户连接或主备切换进行中"}
    if not availability_engine_lock.acquire(blocking=False): return {"ok":True,"running":True}
    availability_engine_running=True
    try:
        active=active_tunnel_running()
        ov_limit=AVAILABILITY_OPENVPN_ACTIVE_BATCH if active else AVAILABILITY_OPENVPN_IDLE_BATCH
        pool_limit=AVAILABILITY_PROTOCOL_ACTIVE_BATCH if active else AVAILABILITY_PROTOCOL_IDLE_BATCH
        priority=normalized_country_name(priority_country)
        priority_ov=_due_endpoints(priority,("openvpn",),min(5,ov_limit)) if priority else []
        priority_pool=_due_endpoints(priority,("softether","sstp","l2tp-ipsec"),min(3,pool_limit)) if priority else []
        selected_ov=[]; selected_pool=[]; seen=set()
        # Strict priority: while the requested/default country is below the
        # minimum usable reserve, NEVER spend this probe budget on other
        # countries. Only an explicitly completed/healthy priority country may
        # fall through to global rotation.
        if priority and not priority_ov and not priority_pool:
            snap = country_priority_snapshot(priority)
            if int(snap.get("available") or 0) < COUNTRY_AVAILABLE_TARGET:
                availability_engine_message = f"{priority} 优先检测未完成 · 可用 {int(snap.get('available') or 0)}/{COUNTRY_AVAILABLE_TARGET} · 暂不检测其它国家"
                set_state(availability_engine_running=False, availability_engine_message=availability_engine_message, availability_queue=0)
                return {"ok": True, "tested": 0, "priority_blocked": True, "country": priority}
        ov_source = priority_ov if priority else _due_endpoints("",("openvpn",),ov_limit)
        for ep in ov_source:
            eid=str(ep.get("endpoint_id") or "")
            if not eid or eid in seen: continue
            seen.add(eid); selected_ov.append(ep)
            if len(selected_ov)>=ov_limit: break
        seen=set()
        # Same strict priority rule for the non-OpenVPN protocols. If the
        # priority country has no due items but already satisfies the minimum,
        # global rotation is allowed.
        pool_source = priority_pool if priority else _due_endpoints("",("softether","sstp","l2tp-ipsec"),pool_limit)
        for ep in pool_source:
            eid=str(ep.get("endpoint_id") or "")
            if not eid or eid in seen: continue
            seen.add(eid); selected_pool.append(ep)
            if len(selected_pool)>=pool_limit: break
        availability_queue=len(selected_ov)+len(selected_pool)
        availability_new_pending=sum(1 for ep in selected_ov+selected_pool if str(ep.get("status") or "").upper()=="NEW")
        availability_engine_message=f"可用性检测中 · 新资源优先 · OpenVPN {len(selected_ov)} · 多协议 {len(selected_pool)} · 全球资源最长 4 小时复检"
        set_state(availability_engine_running=True,availability_engine_message=availability_engine_message,availability_queue=availability_queue,availability_new_pending=availability_new_pending)
        tested=0
        ids=[str((ep.get("metadata") or {}).get("node_id") or "") for ep in selected_ov]
        ids=[x for x in ids if x]
        if ids:
            try: tested+=len(test_multiple_nodes(ids))
            except Exception as exc: log_to_json("WARNING","Probe",f"V2 OpenVPN 批量检测失败: {exc}")
        if selected_pool:
            workers=min(8,len(selected_pool))
            def one(ep):
                eid=str(ep.get("endpoint_id") or "")
                return light_probe_endpoint_id(eid) if eid else {"ok":False}
            with concurrent.futures.ThreadPoolExecutor(max_workers=max(1,workers)) as ex:
                futs=[ex.submit(one,ep) for ep in selected_pool]
                for fut in concurrent.futures.as_completed(futs):
                    try:
                        if not fut.result().get("skipped"): tested+=1
                    except Exception as exc: log_to_json("WARNING","Probe",f"V2 多协议探测异常: {exc}")
        availability_tested_total+=tested
        if (not initial_bootstrap_active and not active_tunnel_running()
                and not (bool(get_state().get("proxy_ok")) and _tunnel_carrier_alive())
                and not manual_connection_active and bool(load_ui_config().get("connection_enabled", True))):
            threading.Thread(target=_ensure_active_client_v2, daemon=True).start()
        ov_due,pool_due=_due_counts()
        set_state(availability_engine_running=False,
                  availability_engine_message=f"本轮已检测 {tested} 个 · 待检测 OpenVPN {ov_due} / 多协议 {pool_due} · 后台继续运行",
                  availability_tested_total=availability_tested_total,availability_queue=ov_due+pool_due,availability_new_pending=0)
        if priority: _finish_priority_if_ready(priority)
        return {"ok":True,"tested":tested,"openvpn_due":ov_due,"protocol_due":pool_due}
    except Exception as exc:
        set_state(availability_engine_running=False,availability_engine_message=f"可用性检测异常：{exc}",availability_queue=0)
        log_to_json("ERROR","Probe",f"V2 可用性检测异常: {exc}")
        return {"ok":False,"error":str(exc)}
    finally:
        availability_engine_running=False
        availability_engine_lock.release()


def _empty_fetch_stats() -> dict[str, Any]:
    return {
        "inserted_servers": 0,
        "updated_servers": 0,
        "unchanged_servers": 0,
        "inserted_endpoints": 0,
        "updated_endpoints": 0,
        "recovered_endpoints": 0,
        "unchanged_endpoints": 0,
        "ip_changed_endpoints": 0,
        "new_endpoint_ids": [],
    }


def _merge_fetch_stats(total: dict[str, Any], part: dict[str, Any] | None) -> None:
    if not isinstance(part, dict):
        return
    for key in (
        "inserted_servers", "updated_servers", "unchanged_servers",
        "inserted_endpoints", "updated_endpoints", "recovered_endpoints",
        "unchanged_endpoints", "ip_changed_endpoints",
    ):
        total[key] = int(total.get(key) or 0) + int(part.get(key) or 0)
    seen = set(total.get("new_endpoint_ids") or [])
    for eid in part.get("new_endpoint_ids") or []:
        text = str(eid or "")
        if text and text not in seen:
            seen.add(text)
            total["new_endpoint_ids"].append(text)


def _load_resource_history() -> list[dict[str, Any]]:
    raw = read_json(RESOURCE_FETCH_HISTORY, [])
    if not isinstance(raw, list):
        return []
    return [item for item in raw if isinstance(item, dict)][-20:]


def _resource_next_interval(history: list[dict[str, Any]] | None = None) -> int:
    rows = list(history if history is not None else _load_resource_history())
    recent = [int(item.get("inserted_endpoints") or 0) for item in rows[-5:]]
    if recent and recent[-1] >= 50:
        interval = RESOURCE_COLLECTION_INTERVAL_SECONDS
    elif len(recent) < 5:
        interval = RESOURCE_COLLECTION_INTERVAL_SECONDS
    else:
        total = sum(recent)
        if total <= 0:
            interval = RESOURCE_COLLECTION_INTERVAL_MAX
        elif total <= 5:
            interval = 1800
        elif total <= 25:
            interval = 1200
        else:
            interval = RESOURCE_COLLECTION_INTERVAL_SECONDS
    total_kb, _avail_kb = _meminfo_kb()
    if 0 < total_kb < 700 * 1024:
        interval = max(interval, 6 * 3600)
    return interval


def _remember_resource_run(entry: dict[str, Any]) -> list[dict[str, Any]]:
    history = _load_resource_history()
    history.append(entry)
    history = history[-20:]
    try:
        write_json(RESOURCE_FETCH_HISTORY, history)
    except Exception:
        pass
    return history


def _probe_new_resource_ids(ids: list[str]) -> None:
    """Light-check only the endpoints this fetch inserted or whose IP changed."""
    pending = [str(eid) for eid in ids[:40] if str(eid or "")]
    if not pending:
        return
    if is_connecting or manual_connection_active or ui_command_plane.is_busy():
        return
    if active_tunnel_running() and proxy_server.proxy_forwarding_busy():
        return

    def one(eid: str) -> None:
        try:
            light_probe_endpoint_id(eid)
        except Exception as exc:
            log_to_json("WARNING", "Probe", f"新资源检测失败 {eid}: {exc}")

    workers = min(8, len(pending))
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        list(executor.map(one, pending))


def resource_collect_once(force=False, reason: str = "background", wait: bool = False):
    global resource_engine_running, resource_engine_message, resource_engine_last_at, _resource_last_result
    reason = str(reason or "background")
    if not force and reason == "background":
        pause_reason = _nano_library_pause_reason()
        if pause_reason:
            return {"ok": True, "skipped": True, "reason": pause_reason}
        if ui_query_active():
            return {"ok": True, "skipped": True, "busy": True, "reason": "页面正在读库，资源更新让路"}
    if not force:
        history = _load_resource_history()
        interval = _resource_next_interval(history)
        last_fetch = float(read_json(STATE_FILE, {}).get("last_fetch_at") or 0)
        if last_fetch and time.time() - last_fetch < interval:
            return {"ok": True, "skipped": True, "reason": "资源采集周期尚未到达", "next_interval": interval}
        if (
            proxy_server.proxy_forwarding_busy()
            or is_connecting
            or manual_connection_active
            or failover_lock.locked()
        ):
            return {"ok": True, "skipped": True, "busy": True, "reason": "当前正在转发或切换，资源更新延后"}
        if ui_command_plane.is_busy():
            return {"ok": True, "skipped": True, "busy": True, "reason": "用户正在执行前端指令"}
    if not resource_engine_lock.acquire(blocking=False):
        if not wait:
            return {"ok": True, "running": True, "reused": False}
        deadline = time.time() + 180
        while resource_engine_running and time.time() < deadline:
            time.sleep(0.25)
        reused = dict(_resource_last_result or {})
        reused["reused"] = True
        return reused or {"ok": True, "reused": True}
    started = time.time()
    resource_engine_running = True
    resource_engine_message = "正在更新全球资源库"
    set_state(resource_engine_running=True, resource_engine_message=resource_engine_message)
    stats = _empty_fetch_stats()
    sources_ok = 0
    sources_failed = 0
    fetched_servers = 0
    fetched_endpoints = 0
    try:
        openvpn_stats = _empty_fetch_stats()
        try:
            candidates = fetch_candidates()
            fetched_endpoints += len(candidates or [])
            sources_ok += 1
            openvpn_stats = dict(getattr(node_pool, "last_upsert_stats", {}) or {})
        except Exception as exc:
            candidates = []
            sources_failed += 1
            log_to_json("WARNING", "Main", f"V2 OpenVPN 资源采集失败: {exc}")
        _merge_fetch_stats(stats, openvpn_stats)
        catalog: dict[str, Any] = {}
        try:
            catalog = refresh_multi_protocol_catalog(force=True)
            if catalog.get("ok"):
                sources_ok += len(catalog.get("sources") or []) or 1
                fetched_servers += int(catalog.get("servers") or 0)
                _merge_fetch_stats(stats, catalog.get("upsert") or getattr(node_pool, "last_upsert_stats", {}) or {})
            else:
                sources_failed += 1
        except Exception as exc:
            sources_failed += 1
            log_to_json("WARNING", "Main", f"多协议资源采集失败: {exc}")
        duration_ms = int((time.time() - started) * 1000)
        inserted = int(stats.get("inserted_endpoints") or 0)
        recovered = int(stats.get("recovered_endpoints") or 0)
        changed = int(stats.get("ip_changed_endpoints") or 0)
        notify = list(stats.get("new_endpoint_ids") or [])
        message = (
            f"资源更新完成 · 耗时 {duration_ms / 1000:.1f} 秒 · "
            f"新增端点 {inserted} · 更新端点 {int(stats.get('updated_endpoints') or 0)} · "
            f"恢复 {recovered} · IP变更 {changed} · 无变化 {int(stats.get('unchanged_endpoints') or 0)} · "
            f"已通知检测 {len(notify)}"
        )
        if sources_failed:
            message += f" · {sources_ok} 个来源成功 / {sources_failed} 个失败"
        resource_engine_last_at = time.time()
        resource_engine_message = message
        history = _remember_resource_run({
            "timestamp": resource_engine_last_at,
            "duration_ms": duration_ms,
            "inserted_endpoints": inserted,
            "updated_endpoints": int(stats.get("updated_endpoints") or 0),
            "recovered_endpoints": recovered,
            "unchanged_endpoints": int(stats.get("unchanged_endpoints") or 0),
            "ip_changed_endpoints": changed,
            "sources_ok": sources_ok,
            "sources_failed": sources_failed,
            "reason": reason,
            "notified": len(notify),
        })
        next_interval = _resource_next_interval(history)
        set_state(
            resource_engine_running=False,
            resource_engine_message=message,
            resource_engine_last_at=resource_engine_last_at,
            last_fetch_at=resource_engine_last_at,
            last_fetch_status="ok" if sources_ok else "error",
            last_fetch_message=message,
            resource_fetch_duration_ms=duration_ms,
            resource_next_interval=next_interval,
        )
        log_to_json(
            "INFO", "Main",
            f"资源更新完成 耗时 {duration_ms}ms 原因 {reason} "
            f"拉取服务器 {fetched_servers} 端点 {fetched_endpoints} "
            f"新增服务器 {int(stats.get('inserted_servers') or 0)} 端点 {inserted} "
            f"更新服务器 {int(stats.get('updated_servers') or 0)} 端点 {int(stats.get('updated_endpoints') or 0)} "
            f"恢复 {recovered} IP变更 {changed} 无变化 {int(stats.get('unchanged_endpoints') or 0)} "
            f"已通知检测 {len(notify)} 下次 {next_interval}s",
        )
        if notify and reason == "background":
            threading.Thread(
                target=_probe_new_resource_ids, args=(notify,), daemon=True, name="new-resource-probe",
            ).start()
        result = {
            "ok": bool(sources_ok) or bool(node_pool.stats().get("endpoints")),
            "message": message,
            "added": inserted,
            "inserted_endpoints": inserted,
            "notified": len(notify),
            "duration_ms": duration_ms,
            "next_interval": next_interval,
            "sources_ok": sources_ok,
            "sources_failed": sources_failed,
            "endpoints": int(node_pool.stats().get("endpoints") or 0),
        }
        _resource_last_result = result
        return result
    except Exception as exc:
        resource_engine_message = f"资源采集异常：{exc}"
        set_state(resource_engine_running=False, resource_engine_message=resource_engine_message)
        log_to_json("ERROR", "Main", resource_engine_message)
        result = {"ok": False, "error": str(exc), "message": resource_engine_message}
        _resource_last_result = result
        return result
    finally:
        resource_engine_running = False
        resource_engine_lock.release()





def _switch_candidates_with_favorites_fallback(ui_cfg,exclude_endpoint_id="",limit=30):
    candidates=_legacy_unified_hot_pool_candidates_v2(ui_cfg,exclude_endpoint_id=exclude_endpoint_id,limit=limit)
    if candidates: return candidates,False
    if ui_cfg.get("routing_mode")=="favorites" and bool(ui_cfg.get("fav_fail_fallback",True)):
        fallback=dict(ui_cfg); fallback["routing_mode"]="auto"; fallback["favorite_node_ids"]=[]
        return _legacy_unified_hot_pool_candidates_v2(fallback,exclude_endpoint_id=exclude_endpoint_id,limit=limit),True
    return [],False


def _ensure_active_client_v2() -> bool:
    if active_tunnel_running() or manual_connection_active or failover_lock.locked() or is_connecting:
        return active_tunnel_running()
    ui_cfg=load_ui_config()
    if not bool(ui_cfg.get("connection_enabled",True)):
        return False
    if not bootstrap_connection_lock.acquire(blocking=False):
        return active_tunnel_running()
    try:
        if ui_cfg.get("routing_mode") == "fixed_ip":
            reconnect_fixed_node_if_needed(ui_cfg)
        else:
            apply_saved_scheme_now()
    except Exception as exc:
        log_to_json("WARNING","VPN",f"启动/恢复活动 VPN 失败: {exc}")
    finally:
        bootstrap_connection_lock.release()
    return active_tunnel_running()

def orphan_tunnel_reap_loop() -> None:
    """Catch SoftEther/L2TP sessions that a failed dial did not close.

    Startup already reaps once. This pass waits until nothing is dialing so it
    cannot delete a tunnel that is about to be promoted.
    """
    time.sleep(180)
    while True:
        try:
            probes_idle = getattr(protocol_probe_lock, "_value", None) == getattr(protocol_probe_lock, "_initial_value", None)
            if probes_idle and not is_connecting and not manual_connection_active and not failover_lock.locked():
                reap_orphan_protocol_tunnels()
        except Exception as exc:
            log_to_json("WARNING", "VPN", f"残留隧道清理失败: {exc}")
        time.sleep(600)


def reap_orphan_protocol_tunnels() -> None:
    """Disconnect SoftEther and L2TP sessions that are not the live exit or the hot standby.

    vpnclient and `ip netns` outlive this process. Leaving them up puts extra
    10.211.0.0/16 routes next to tun0 and burns the 512MB host.
    """
    keep_accounts: set[str] = set()
    keep_nics: set[str] = set()
    keep_ns: set[str] = set()

    def _keep(tunnel: tunnel_adapters.TunnelResult | None) -> None:
        if tunnel is None:
            return
        details = tunnel.details or {}
        account = str(details.get("account") or "")
        nic = str(details.get("nic") or "")
        namespace = str(tunnel.namespace or "")
        if account:
            keep_accounts.add(account)
        if nic:
            keep_nics.add(nic)
        if namespace:
            keep_ns.add(namespace)

    _keep(active_external_tunnel)
    try:
        _keep(standby_slot.get("tunnel"))
    except Exception:
        pass
    try:
        removed = tunnel_adapters.SoftEtherAdapter().reap_except(keep_accounts, keep_nics)
        if removed:
            log_to_json("INFO", "VPN", "已断开未接管的 SoftEther 会话: " + ", ".join(removed))
    except Exception as exc:
        log_to_json("WARNING", "VPN", f"清理 SoftEther 残留失败: {exc}")
    try:
        removed_ns = l2tp_adapter.reap_orphan_namespaces(keep_ns)
        if removed_ns:
            log_to_json("INFO", "VPN", "已删除未接管的 L2TP 网络命名空间: " + ", ".join(removed_ns))
    except Exception as exc:
        log_to_json("WARNING", "VPN", f"清理 L2TP 残留失败: {exc}")


def startup_recovery_loop():
    """One-shot boot recovery; a failed startup must not churn forever.

    A browser refresh does not restart this task. The old implementation ran
    every 15 seconds and could spend several minutes cycling through SoftEther/
    SSTP/L2TP candidates while the UI continuously showed a stale-looking
    "正在连接" state. Normal maintenance/failover loops remain responsible
    for later recovery.
    """
    try:
        # Previous process is gone, so nothing in memory owns the vpnclient
        # sessions or netns it left behind. Drop them before dialing again.
        reap_orphan_protocol_tunnels()
    except Exception as exc:
        log_to_json("WARNING", "VPN", f"启动清理残留隧道失败: {exc}")
    time.sleep(8)
    try:
        if initial_bootstrap_active:
            return
        ui_cfg = load_ui_config()
        if not bool(ui_cfg.get("connection_enabled", True)):
            return
        if global_pool_refresh_running or ui_command_plane.is_busy() or manual_connection_active or is_connecting or active_tunnel_running():
            return
        set_state(
            last_check_message="启动恢复：正在尝试一次已验证备用节点连接；失败后交给后台维护周期重试。"
        )
        connected = _ensure_active_client_v2()
        if connected:
            set_state(last_check_message="启动恢复完成：已建立可用 VPN 出口。")
        else:
            set_state(
                last_check_message="启动恢复未建立连接；不会循环占用检测，后台维护将在下一周期自动重试。"
            )
    except Exception as exc:
        log_to_json("WARNING", "VPN", f"启动恢复任务异常: {exc}")
        try:
            set_state(
                last_check_message=f"启动恢复未完成：{exc}；后台维护将在下一周期自动重试。"
            )
        except Exception:
            pass



def _initial_bootstrap_candidate(local_country):
    temp_cfg = {
        "routing_mode": "fixed_region",
        "force_country": str(local_country or "").strip(),
        "routing_ip_type": "all",
        "connection_enabled": True,
    }
    candidates = unified_hot_pool_candidates(temp_cfg, limit=100)
    target = normalized_country_name(local_country)
    if target:
        local = [x for x in candidates if normalized_country_name(x.get("country")) == target]
        if local:
            return local[0], "local_country"
    return (candidates[0], "global_fallback") if candidates else (None, "")

def initial_install_bootstrap_loop():
    global initial_bootstrap_active
    if not _first_install_bootstrap_needed():
        if not _read_bootstrap_state().get("completed"):
            _write_bootstrap_state(completed=True, completed_at=time.time(), mode="existing_install_detected")
        return
    initial_bootstrap_active = True
    detected = _detect_local_server_country()
    local_country = str(detected.get("country") or "").strip()
    _write_bootstrap_state(
        started_at=time.time(),
        completed=False,
        local_server_country=local_country,
        local_server_country_code=str(detected.get("country_code") or ""),
        local_server_public_ip=str(detected.get("public_ip") or ""),
        local_server_location=str(detected.get("location") or ""),
        local_server_owner=str(detected.get("owner") or ""),
        local_server_ip_type=str(detected.get("ip_type") or ""),
        local_server_identity_at=time.time() if detected.get("public_ip") else 0,
        detection_source=str(detected.get("source") or ""),
    )
    set_state(
        initial_bootstrap_running=True,
        initial_bootstrap_country=local_country,
        initial_bootstrap_public_ip=str(detected.get("public_ip") or ""),
        last_check_message=(
            f"首次安装初始化：正在获取资源并检测"
            + (f"，本机服务器位于 {local_country}" if local_country else "")
        ),
    )
    try:
        try:
            resource_collect_once(force=True)
        except Exception as exc:
            log_to_json("WARNING", "Bootstrap", f"首次安装资源获取启动失败: {exc}")
        try:
            if local_country:
                availability_sweep_once(local_country)
            else:
                availability_sweep_once("")
        except Exception as exc:
            log_to_json("WARNING", "Bootstrap", f"首次安装初始可用性检测失败: {exc}")

        deadline = time.time() + 15 * 60
        while time.time() < deadline and not active_tunnel_running():
            if not bool(load_ui_config().get("connection_enabled", True)):
                break
            candidate, reason = (None, "")
            try:
                candidate, reason = _initial_bootstrap_candidate(local_country)
            except Exception as exc:
                log_to_json("WARNING", "Bootstrap", f"首次安装候选节点选择失败: {exc}")
            if candidate:
                try:
                    set_state(
                        initial_bootstrap_running=True,
                        initial_bootstrap_country=local_country,
                        last_check_message=(
                            f"首次安装自动连接：优先 {local_country or '本机国家'}，"
                            f"正在连接最低延迟节点 {candidate.get('protocol','')} "
                            f"{candidate.get('current_ip') or candidate.get('hostname') or candidate.get('endpoint_id')}"
                        ),
                    )
                    connect_ranked_endpoint(candidate, manual=False)
                    _write_bootstrap_state(
                        completed=True,
                        completed_at=time.time(),
                        selected_endpoint=str(candidate.get("endpoint_id") or ""),
                        selected_country=str(candidate.get("country") or ""),
                        selection_reason=reason,
                    )
                    set_state(
                        initial_bootstrap_running=False,
                        initial_bootstrap_completed=True,
                        initial_bootstrap_country=local_country,
                        last_check_message=(
                            f"首次安装初始化完成：已自动连接 "
                            f"{candidate.get('country') or local_country or '最佳节点'}，"
                            "现在进入资源采集、可用性检测与 4 小时复检维护。"
                        ),
                    )
                    return
                except Exception as exc:
                    log_to_json("WARNING", "Bootstrap", f"首次安装自动连接失败: {candidate.get('endpoint_id')}: {exc}")
            time.sleep(5)

        _write_bootstrap_state(
            completed=True,
            completed_at=time.time(),
            selection_reason="no_verified_local_candidate",
        )
        set_state(
            initial_bootstrap_running=False,
            initial_bootstrap_completed=True,
            initial_bootstrap_country=local_country,
            last_check_message=(
                "首次安装初始化完成，但暂时没有经过验证的本国节点；"
                "后台资源与可用性检测将继续运行，获得可用节点后自动连接。"
            ),
        )
    except Exception as exc:
        log_to_json("ERROR", "Bootstrap", f"首次安装初始化异常: {exc}")
        _write_bootstrap_state(completed=True, completed_at=time.time(), selection_reason="bootstrap_exception")
        set_state(initial_bootstrap_running=False, initial_bootstrap_completed=True, last_check_message=f"首次安装初始化异常：{exc}")
    finally:
        initial_bootstrap_active = False



OPENVPN_LATENCY_MIGRATION_MARKER = DATA_DIR / "openvpn_latency_metrics_v2.json"


def migrate_openvpn_latency_metrics() -> None:
    """Remove persisted OpenVPN latency values that were not proven by a live tunnel."""
    try:
        marker = read_json(OPENVPN_LATENCY_MIGRATION_MARKER, {})
        marker_version = int(marker.get("version") or 0) if isinstance(marker, dict) else 0
        if marker_version >= 3:
            return

        reset_count = 0
        if marker_version < 2:
            reset_count = node_pool.reset_openvpn_latency_metrics()

        nodes = read_nodes()
        changed = 0
        for node in nodes:
            if str(node.get("protocol") or "openvpn").lower() != "openvpn":
                continue

            status = str(node.get("probe_status") or "not_checked").lower()
            # Any non-available OpenVPN row must never display or retain a latency.
            # In particular, failed AUTH/TLS attempts can have an elapsed duration,
            # but that duration is not a usable latency metric.
            if status != "available" and parse_int(node.get("latency_ms")) != 0:
                node["latency_ms"] = 0
                changed += 1

            # pool_rehydrated rows can carry the old Master-Pool latency into the UI.
            if node.get("pool_rehydrated") and status != "available":
                node["latency_ms"] = 0
                node["probe_message"] = "历史资源已重置，等待真实 OpenVPN 隧道测速"
                node["probed_at"] = 0

        if changed:
            write_json(NODES_FILE, sort_all_nodes(nodes))

        write_json(
            OPENVPN_LATENCY_MIGRATION_MARKER,
            {
                "version": 3,
                "completed_at": time.time(),
                "db_rows_reset": reset_count,
                "nodes_reset": changed,
            },
        )
        log_to_json(
            "INFO",
            "Main",
            f"已完成 OpenVPN 延迟可信度迁移：重置 {reset_count} 个 Master Pool 端点、清理 {changed} 个非可用节点的延迟值；后续延迟只采用真实隧道测速。",
        )
    except Exception as exc:
        log_to_json("ERROR", "Main", f"OpenVPN 延迟可信度迁移失败：{exc}")


def resume_web_certificate_if_needed() -> None:
    try:
        cfg = load_ui_config()
        domain = str(cfg.get("web_domain") or "").strip()
        if not domain:
            return
        cert = web_certificate.snapshot()
        status = str(cert.get("status") or "")
        cert_domain = str(cert.get("domain") or "").strip()
        should_resume = (
            status in ("issuing", "installing", "interrupted")
            or (status == "not_configured" and cert_domain != domain)
        )
        if not should_resume:
            return

        def resume() -> None:
            try:
                web_certificate.start(domain, resume=True)
            except Exception as exc:
                log_to_json("ERROR", "WebSSL", f"HTTPS 证书任务自动恢复失败：{domain} · {exc}")

        threading.Timer(1.5, resume).start()
        log_to_json("INFO", "WebSSL", f"已检测到 HTTPS 证书任务需要恢复：{domain}")
    except Exception as exc:
        log_to_json("ERROR", "WebSSL", f"HTTPS 证书启动检查失败：{exc}")


def main() -> None:
    ensure_dirs()
    try:
        repaired = node_pool.repair_data_integrity()
        log_to_json("INFO", "Main", f"Master Pool 数据完整性校正完成：servers={repaired.get('servers', 0)} endpoints={repaired.get('endpoints', 0)}")
    except Exception as exc:
        log_to_json("WARNING", "Main", f"Master Pool 数据完整性校正失败：{exc}")
    migrate_openvpn_latency_metrics()
    if not ISOLATED_INSTANCE:
        kill_existing_openvpn_processes()

    log_file = DATA_DIR / "vpngate.log"
    tee = Tee(str(log_file))
    sys.stdout = tee
    sys.stderr = tee

    write_json(
        STATE_FILE,
        {
            "api_url": API_URL,
            "target_valid_nodes": TARGET_VALID_NODES,
            "fetch_interval_seconds": FETCH_INTERVAL_SECONDS,
            "check_interval_seconds": CHECK_INTERVAL_SECONDS,
            "local_proxy": f"socks5://{'[' + LOCAL_PROXY_HOST + ']' if ':' in LOCAL_PROXY_HOST else LOCAL_PROXY_HOST}:{LOCAL_PROXY_PORT}",
            "active_openvpn_node_id": "",
            "last_fetch_status": "starting",
            "last_check_message": "服务已启动；后台连接状态由实际 VPN 隧道决定。",
            "is_connecting": False,
            "active_node_latency": "等待后台状态",
            "blacklisted_nodes": 0,
            "isolated_instance": ISOLATED_INSTANCE,
            "background_loops_disabled": DISABLE_BACKGROUND_LOOPS,
            "collector_loop_enabled": ENABLE_COLLECTOR_LOOP,
            "proxy_health_loop_enabled": ENABLE_PROXY_HEALTH_LOOP,
            "fast_liveness_loop_enabled": ENABLE_FAST_LIVENESS_LOOP,
            "fast_liveness_interval_seconds": FAST_LIVENESS_INTERVAL_SECONDS,
            "pinger_loop_enabled": ENABLE_PINGER_LOOP,
            "protocol_probe_loop_enabled": ENABLE_PROTOCOL_PROBE_LOOP,
            "active_route_table": ACTIVE_ROUTE_TABLE,
            "proxy_health_interval_seconds": PROXY_HEALTH_INTERVAL_SECONDS,
            "proxy_health_confirm_delay_seconds": PROXY_HEALTH_CONFIRM_DELAY_SECONDS,
            "failover_in_progress": False,
            "last_failover_ok": None,
            "last_failover_duration_ms": 0,
            "priority_country": "",
            "priority_inventory": 0,
            "priority_inventory_target": COUNTRY_INVENTORY_TARGET,
            "priority_available": 0,
            "priority_target": COUNTRY_AVAILABLE_TARGET,
            "priority_minimum": COUNTRY_AVAILABLE_MIN,
            "priority_running": False,
            "priority_message": "",
        },
    )
    """Run the 8500 relay in its own process so probes cannot stall packet copy."""
    pid_path = DATA_DIR / "proxy_gateway.pid"
    try:
        old_pid = int(pid_path.read_text(encoding="utf-8").strip() or "0")
    except (OSError, ValueError):
        old_pid = 0
    if old_pid > 0 and old_pid != os.getpid():
        try:
            os.kill(old_pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        except OSError:
            pass
        time.sleep(0.4)
    env = os.environ.copy()
    env["VPNGATE_DATA_DIR"] = str(DATA_DIR)
    env["LOCAL_PROXY_HOST"] = LOCAL_PROXY_HOST
    env["LOCAL_PROXY_PORT"] = str(LOCAL_PROXY_PORT)
    env.setdefault("MALLOC_ARENA_MAX", "2")
    proc = subprocess.Popen(
        [sys.executable, str(ROOT_DIR / "proxy_server.py")],
        cwd=str(ROOT_DIR),
        env=env,
    )
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    pid_path.write_text(str(proc.pid), encoding="utf-8")
    print(f"[网关] 8500 转发进程已启动 pid={proc.pid}", flush=True)

    # Wait for the gateway to officially start
    print("[网关] 正在启动代理网关...", flush=True)
    gateway_ready = False
    is_ipv6 = ":" in LOCAL_PROXY_HOST
    af = socket.AF_INET6 if is_ipv6 else socket.AF_INET
    for _ in range(30):
        s = None
        try:
            s = socket.socket(af, socket.SOCK_STREAM)
            s.settimeout(0.5)
            connect_host = LOCAL_PROXY_HOST
            if connect_host in ("::", "0.0.0.0", ""):
                connect_host = "::1" if is_ipv6 else "127.0.0.1"
            try:
                s.connect((connect_host, LOCAL_PROXY_PORT))
                gateway_ready = True
                break
            except Exception:
                if connect_host == "::1":
                    try:
                        s.close()
                        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        s.settimeout(0.5)
                        s.connect(("127.0.0.1", LOCAL_PROXY_PORT))
                        gateway_ready = True
                        break
                    except Exception:
                        pass
                raise
        except Exception:
            time.sleep(0.5)
        finally:
            if s is not None:
                try:
                    s.close()
                except Exception:
                    pass

    if gateway_ready:
        print("[网关] 代理网关已成功启动监听，启动同步与检测脚本...", flush=True)
    else:
        print("[警告] 代理网关启动超时，继续执行脚本...", flush=True)

    enabled_loops: list[str] = []
    if ENABLE_COLLECTOR_LOOP:
        threading.Thread(target=collector_loop, daemon=True).start()
        enabled_loops.append("collector")
    if ENABLE_RESOURCE_COLLECT_LOOP and not ISOLATED_INSTANCE:
        threading.Thread(target=resource_collect_loop, daemon=True).start()
        enabled_loops.append("resource-collector")
    if ENABLE_PROXY_HEALTH_LOOP:
        threading.Thread(target=background_proxy_checker, daemon=True).start()
        enabled_loops.append("proxy-health")
    if ENABLE_FAST_LIVENESS_LOOP:
        threading.Thread(target=fast_tunnel_liveness_loop, daemon=True).start()
        enabled_loops.append("fast-liveness")
    if ENABLE_PINGER_LOOP:
        threading.Thread(target=active_node_pinger, daemon=True).start()
        enabled_loops.append("pinger")
    if not ISOLATED_INSTANCE:
        threading.Thread(target=protocol_catalog_loop, daemon=True).start()
        enabled_loops.append("protocol-catalog")
        threading.Thread(target=resource_share_loop, daemon=True).start()
        enabled_loops.append("resource-share")
        threading.Thread(target=global_country_coverage_loop, daemon=True).start()
        enabled_loops.append("country-coverage")
    if ENABLE_PROTOCOL_PROBE_LOOP:
        threading.Thread(target=protocol_probe_loop, daemon=True).start()
        enabled_loops.append("protocol-probe")
    threading.Thread(target=memory_guard_loop, daemon=True, name="memory-guard").start()
    threading.Thread(target=orphan_tunnel_reap_loop, daemon=True, name="orphan-tunnel-reap").start()
    threading.Thread(target=warm_first_page_loop, daemon=True, name="warm-first-page").start()
    threading.Thread(target=warm_standby_loop, daemon=True, name="warm-standby").start()
    threading.Thread(target=cold_standby_loop, daemon=True, name="cold-standby").start()
    enabled_loops.append("warm-standby")

    threading.Thread(target=startup_recovery_loop, daemon=True, name="startup-recovery").start()
    enabled_loops.append("startup-recovery")
    threading.Thread(target=backfill_manual_speeds, daemon=True, name="manual-speed-backfill").start()

    # First installation is a one-time bootstrap only when the persistent pool
    # is empty. Existing installations keep their saved routing preferences.
    if _first_install_bootstrap_needed():
        threading.Thread(target=initial_install_bootstrap_loop, daemon=True, name="initial-bootstrap").start()
        enabled_loops.append("initial-bootstrap")
    elif not _read_bootstrap_state().get("completed"):
        _write_bootstrap_state(completed=True, completed_at=time.time(), mode="existing_install_detected")

    if ISOLATED_INSTANCE:
        print(f"[隔离实例] 已启用后台循环: {', '.join(enabled_loops) if enabled_loops else '无'}", flush=True)

    ui_cfg = load_ui_config()
    resume_web_certificate_if_needed()
    ui_host = ui_cfg.get("host", UI_HOST)
    ui_port = bounded_int(ui_cfg.get("port"), UI_PORT, 1, 65535)

    print(f"UI: http://{ui_host}:{ui_port}/", flush=True)
    print(f"Proxy: http://{LOCAL_PROXY_HOST}:{LOCAL_PROXY_PORT}", flush=True)
    DualStackHTTPServer((ui_host, ui_port), Handler).serve_forever()

if __name__ == "__main__":
    main()